typedef struct {
    // Add your MAC_COMMAND_PDU and MAC_DATA_PDU definitions here
} MAC_PDU;

MAC_PDU** pdus = NULL;
int size = 0, capacity = 2;

void pdus_init() {
    pdus = (MAC_PDU**)malloc(capacity * sizeof(MAC_PDU*));
}

int pdus_size() {
    return size;
}

void pdus_add(MAC_PDU* pdu) {
    if(size == capacity) {
        // Re-allocate memory when the array is full
        capacity *= 2;
        MAC_PDU** temp = (MAC_PDU**)realloc(pdus, capacity * sizeof(MAC_PDU*));
        pdus = temp;
    }

    pdus[size] = pdu;
    size++;
}

void pdus_update(int index, MAC_PDU* pdu) {
    if(index < 0 || index >= size)
        return; // Handle invalid indices

    pdus[index] = pdu;
}

MAC_PDU* pdus_get(int index) {
    if(index < 0 || index >= size)
        return NULL; // Handle invalid indices

    return pdus[index];
}

void pdus_free() {
    for(int i = 0; i < size; i++) {
        free(pdus[i]);
    }

    free(pdus);
}

int main() {
    pdus_init();

    // Example usage
    MAC_PDU* pdu1 = malloc(sizeof(MAC_PDU)); // Initialize and manage your PDU structures here
    MAC_PDU* pdu2 = malloc(sizeof(MAC_PDU));

    pdus_add(pdu1);
    pdus_add(pdu2);

    printf("Total entries: %d\n", pdus_size());

    pdus_update(0, pdu1); // Update the first entry

    MAC_PDU* retrievedPDU = pdus_get(0);

    if(retrievedPDU != NULL) {
        free(retrievedPDU);
    }

    pdus_free();

    return 0;
}
