#define MAX_RECORDS 1024
#define THRESHOLD 1000

typedef struct {
    int value;
} record_t;

int hash_func(int key) {
    return (key * 1103515245 + 12345) % (1 << 16);
}

record_t* init_records(int num_records, long* offsets, int* keys) {
    record_t* records = NULL;
    for (int i = 0; i < num_records; i++) {
        records = realloc(records, (i+1)*sizeof(record_t));
        records[i].value = hash_func(keys[i]);
    }
    return records;
}

void verify_init(record_t* records) {
    int i;
    for (i = 0; i < MAX_RECORDS; i++) {
        if (records[i].value == -1) {
            printf("Error: record %d not initialized.\n", i);
            exit(1);
        }
    }
}

int main() {
    int num_records, i;
    long* offsets = NULL;
    int* keys = NULL;

    // Initialize arrays
    offsets = (long*)malloc(MAX_RECORDS * sizeof(long));
    keys = (int*)malloc(MAX_RECORDS * sizeof(int));

    for (i = 0; i < MAX_RECORDS; i++) {
        offsets[i] = i;
        keys[i] = i;
    }

    num_records = rand() % MAX_RECORDS;

    record_t* records = init_records(num_records, offsets, keys);
    verify_init(records);

    // Use and free memory
    for (i = 0; i < num_records; i++) {
        printf("Record %d: value = %d\n", i, records[i].value);
    }

    free(records);
    free(offsets);
    free(keys);

    return 0;
}
