#include <unistd.h>
#include <stdbool.h>
#include <time.h>

#define LOG_FILE "log.txt"
#define DEFAULT_BUFFER_SIZE (1 << 20)

typedef enum {
    FLAG_HELP,
    FLAG_MANPAGE,
    FLAG_OUTPUT_FILE,
} flag_type;

typedef struct {
    int buffer_size;
    bool write_to_file;
    FILE* log_fp;
} config_t;

config_t config = {DEFAULT_BUFFER_SIZE, false, NULL};

void print_help() {
    printf("Usage: %s [options] <input_file>\n", "your_program");
    printf("Options:\n");
    printf("-h, --help     Show this help message\n");
    printf("-m, --manpage  Show man page\n");
    printf("-o, --output  Specify output file\n");
}

int main(int argc, char* argv[]) {
    int c;
    while ((c = getopt(argc, argv, "hm:o:")) != -1) {
        switch (c) {
            case 'h':
                print_help();
                exit(EXIT_SUCCESS);
            case 'm':
                config.write_to_file = false;
                break;
            case 'o':
                config.buffer_size = atoi(optarg);
                if (!strcmp(optarg, "-")) {
                    config.write_to_file = true;
                } else {
                    config.log_fp = fopen(optarg, "a+");
                    if (config.log_fp == NULL) {
                        perror("Failed to open log file");
                        exit(EXIT_FAILURE);
                    }
                }
                break;
            default:
                abort();
        }
    }

    int i;
    for (i = 1; i < argc; i++) {
        char* filename = argv[i];
        if (!strcmp(filename, "-")) {
            // Handle the case when user provides '-' as input file
        } else {
            FILE* fp = fopen(filename, "r");
            if (fp == NULL) {
                perror("Failed to open input file");
                exit(EXIT_FAILURE);
            }

            int line_count = 0;
            char buffer[config.buffer_size];
            size_t bytes_read;

            while ((bytes_read = fread(buffer, 1, config.buffer_size, fp)) > 0) {
                for (size_t i = 0; i < bytes_read; i++) {
                    if (buffer[i] == '\n') {
                        line_count++;
                    }
                }
            }

            fclose(fp);

            char timestamp[64];
            time_t now = time(NULL);
            strftime(timestamp, sizeof(timestamp), "%Y-%m-%d %H:%M:%S", localtime(&now));

            if (config.write_to_file) {
                fprintf(config.log_fp, "[%s] Processed file '%s' with %zu lines.\n", timestamp, filename, line_count);
            } else {
                printf("[%s] Processed file '%s' with %zu lines.\n", timestamp, filename, line_count);
            }
        }
    }

    if (config.log_fp) {
        fclose(config.log_fp);
    }

    return EXIT_SUCCESS;
}
