int configure_network(const char* configFile, const char* interfaceName, const char* ipAddress, int bringUp) {
    FILE* file = fopen(configFile, "r");
    if (file == NULL) {
        perror("Error opening configuration file");
        return 1;
    }

    struct ifaddrs* ifaddr = NULL;
    struct ifaddrs* temp = NULL;

    // Find the network interface
    getifaddrs(&temp);
    while (temp != NULL) {
        if (strcmp(temp->ifa_name, interfaceName) == 0) {
            ifaddr = temp;
            break;
        }
        temp = temp->ifa_next;
    }

    if (ifaddr == NULL) {
        perror("Network interface not found");
        return 1;
    }

    // Parse the configuration file
    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        // Remove newline character
        line[strcspn(line, "\n")] = '\0';

        // Parse IP address and subnet mask
        char* ipStart = strchr(line, ':');
        if (ipStart != NULL) {
            *ipStart++ = '\0';
            in_addr_t in;
            inet_pton(AF_INET, line, &in);
            int prefix = atoi(ipStart);

            // Check for valid IP address and subnet mask
            if (!validIP(in) || !validSubnet(prefix)) {
                perror("Invalid IP address or subnet mask");
                return 1;
            }

            // Apply the configuration to the network interface
            ifaddr->ifa_addr = in;
            ifaddr->ifa_netmask = prefix;

            // Bring up the network if requested
            if (bringUp) {
                system("ifconfig " + string(interfaceName) + " " + line);
            }
        }
    }

    fclose(file);

    return 0;
}

