#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <ifaddrs.h>
#include <arpa/inet.h>
#include <resolv.h>
#include <pthread.h>

#define CACHE_SIZE 1000
#define LOG_MAX_LENGTH 1024
#define LOG_VERBOSITY 2

typedef struct {
    char hostname[256];
    char ip_address[45]; // IPv6 address can be up to 46 characters long, but we leave room for the null terminator.
} CacheEntry;

CacheEntry *cache;
int cache_size = 0;
pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t cache_cond = PTHREAD_COND_INITIALIZER;

FILE *log_file;
int log_level = LOG_VERBOSITY;

u_char *resolve_dns(char *hostname) {
    struct hostent *host;
    struct in_addr ip4;
    struct in6_addr ip6;
    u_char *ip_address = NULL;

    // Perform DNS resolution
    host = gethostbyname(hostname);
    if (host == NULL)
        return "Error: Host not found";

    // Store the resolved IP address in cache
    pthread_mutex_lock(&cache_lock);
    for (int i = 0; i < cache_size; i++) {
        if (strcmp(cache[i].hostname, hostname) == 0) {
            ip_address = (u_char *)malloc(45); // IPv6 address can be up to 46 characters long
            strcpy((char *)ip_address, inet_ntop(AF_INET6, &host->h_addr_list[0], NULL));
            pthread_mutex_unlock(&cache_lock);
            return ip_address;
        }
    }

    // Add new entry to cache if it's not full
    if (cache_size < CACHE_SIZE) {
        CacheEntry new_entry;
        strcpy(new_entry.hostname, hostname);
        strcpy((char *)new_entry.ip_address, inet_ntop(AF_INET6, &host->h_addr_list[0], NULL));
        cache = (CacheEntry *)realloc(cache, sizeof(CacheEntry) * ++cache_size);
        pthread_mutex_unlock(&cache_lock);
    }

    // Close cache lock to prevent other threads from accessing it
    pthread_mutex_unlock(&cache_lock);

    return "Error: Host not found";
}

int main() {
    // Initialize the cache
    cache = (CacheEntry *)malloc(CACHE_SIZE * sizeof(CacheEntry));
    for (int i = 0; i < CACHE_SIZE; i++)
        cache[i].hostname[0] = '\0';

    // Initialize logging module
    log_file = fopen("dns_resolution.log", "a");
    if (log_file == NULL)
        return 1;

    // Perform DNS resolution and logging
    u_char *ip_address = resolve_dns("example.com");
    if (ip_address != NULL) {
        if (log_level > 0)
            fprintf(log_file, "%s: %s\n", "DNS Resolution", ip_address);
        free(ip_address);
    } else {
        if (log_level > 1)
            fprintf(log_file, "%s: %s\n", "Error: DNS Resolution", ip_address);
    }

    fclose(log_file);

    return 0;
}
