void processIntegers() {
    int maxCount = 10000;
    int* integers = (int*) malloc(maxCount * sizeof(int));

    int count = 0;
    int largest = INT_MIN;

    while (scanf("%d", &integers[count]) == 1 && ++count < maxCount) {
        if (integers[count] > largest)
            largest = integers[count];
    }

    if (scanf("%*c") != EOF && count >= maxCount) {
        printf("Error: Non-integer input detected. Terminating program.\n");
        free(integers);
        return;
    }

    for (int i = 0; i < count; ++i) {
        if (integers[i] > largest)
            largest = integers[i];
    }

    printf("Largest integer: %d\n", largest);

    free(integers);
}
