#include <stdio.h>
#include <stdarg.h>
#include <stdbool.h>
#include <stdlib.h>
#include <string.h>

#define LOG_MAX_LEVEL 4 // Debug:0, Info:1, Warning:2, Error:3
#define LOG_BUFFER_SIZE 1024
#define LOG_FILE_PATH "/path/to/log/file.log"
#define LOG_SYSLOG_PORT 514

typedef enum { DEBUG, INFO, WARNING, ERROR } LogLevel;

void log_message(LogLevel level, const char* format, ...) {
    if (level > LOG_MAX_LEVEL) return; // Ignore messages above max level

    static char buffer[LOG_BUFFER_SIZE];
    static int message_count = 0;
    va_list args;
    va_start(args, format);
    vsnprintf(buffer, LOG_BUFFER_SIZE, format, args);
    va_end(args);

    if (level >= ERROR) {
        // Write to error log file
        FILE* file = fopen(LOG_FILE_PATH, "a");
        if (file != NULL) {
            fwrite(buffer, strlen(buffer), 1, file);
            fclose(file);
        }

        // Send syslog message
        systemf("logger -p local0.info -t myapp %s", buffer);

        // Rate-limit logging to prevent excessive messages
        if (++message_count >= 10) {
            message_count = 0;
            usleep(100000); // 1/10 second delay
        }
    }
}
