import hashlib
import os

def calculate_md5_hash(file_path):
    md5 = hashlib.md5()
    chunk_size = 4096

    if not os.path.exists(file_path):
        return None, "File does not exist"

    try:
        with open(file_path, 'rb') as file:
            while True:
                chunk = file.read(chunk_size)
                if not chunk:
                    break
                md5.update(chunk)

            progress = 0
            total_chunks = os.path.getsize(file_path) // chunk_size

            def update_progress_bar():
                nonlocal progress
                while progress < total_chunks:
                    yield f"Hashing... {progress / total_chunks:.2%}"
                    progress += 1

            for message in update_progress_bar():
                print(message)

        return md5.hexdigest(), "MD5 hash calculated successfully"

    except OSError as e:
        return None, f"Error occurred while processing the file: {e}"
