EVP_CIPHER_CTX* validateOAuth2Token(char *tokenResponse) {
    json_object *jobj = json_object_from_string(tokenResponse);

    if (!jobj || !json_object_object_test(jobj, "access_token") ||
        !json_object_object_test(jobj, "expires_in") ||
        !json_object_object_test(jobj, "token_type")) {
        return NULL;
    }

    char *accessToken = json_object_get_string(jobj, "access_token");
    int expiresIn = json_object_get_int(jobj, "expires_in");
    char *tokenType = json_object_get_string(jobj, "token_type");
    char *refreshToken = json_object_get_string(jobj, "refresh_token");

    if (strlen(tokenType) != 6 || strcmp(tokenType, "Bearer") != 0)
        return NULL;

    if (expiresIn <= 0)
        return NULL;

    // Implement DES algorithm and its modes
    EVP_CIPHER_CTX *cipher = EVP_CIPHER_CTX_new();

    if (cipher && json_object_get_string(jobj, "cipher_mode")) {
        char *mode = json_object_get_string(jobj, "cipher_mode");
        if (strcmp(mode, "ECB") == 0)
            EVP_CipherInit_ex(cipher, EVP_des_cbc(), NULL, NULL, NULL);
        else if (strcmp(mode, "EDE") == 0)
            EVP_CipherInit_ex(cipher, EVP_des_ede_cfb64(), NULL, NULL, NULL);
        else if (strcmp(mode, "ED3") == 0)
            EVP_CipherInit_ex(cipher, EVP_des_ede3_cfb64(), NULL, NULL, NULL);
        else if (strcmp(mode, "CFB") == 0)
            EVP_CipherInit_ex(cipher, EVP_des_cfb64(), NULL, NULL, NULL);
    }

    return cipher;
}

