#include <signal.h>
#include <setjmp.h>
#include <stdlib.h>

void init_signal_set(int num_signals) {
    struct sigaction sa;
    int i;

    for (i = 0; i < num_signals; ++i) {
        sigemptyset(&sa.sa_mask);
        sa.sa_handler = signal_handler;
        sigaction(i, &sa, NULL);
    }
}

void* signal_handler(int signum) {
    jmp_buf* buf = (jmp_buf*)malloc(sizeof(jmp_setjmp));
    setjmp(buf);

    // Handle the signal
    printf("Signal %d received\n", signum);

    return NULL;
}

void cleanup() {
    int i;

    for (i = 0; i < num_signals; ++i) {
        sigemptyset(&sa.sa_mask);
        sa.sa_handler = SIG_DFL;
        sigaction(i, &sa, NULL);
    }

    free(buf);
}
