#include <boost/asio.hpp>
#include <boost/beast.hpp>
#include <iostream>
#include <thread>

class SandeshClient {
public:
    SandeshClient(boost::asio::io_context& io_context)
        : io_context_(io_context), resolver_(io_context), timeout_(5000) {}

    void start() {
        timer_.expires_after(std::chrono::milliseconds(timeout_));
        timer_.async_wait([this](boost::system::error_code ec) {
            if (!ec) {
                // Handle timeout
                std::cout << "Timeout occurred. Aborting." << std::endl;
                io_context_.stop();
            }
        });

        boost::asio::ip::tcp::resolver::results_type results = resolver_.resolve("localhost", "8080");
        stream_ = boost::make_shared<boost::beast::tcp_stream>(io_context_);
        stream_->set_option(boost::beast::socket_base::keep_alive(true));

        std::cout << "Sandesh client started." << std::endl;
    }

    void sendRequest(const boost::asio::ip::tcp::endpoint& endpoint, const std::string& method) {
        if (method == "GET") {
            // Handle GET request
            stream_->connect(endpoint);
            boost::beast::http::request<boost::beast::http::empty_body> req;
            req.version(11);
            req.target("/path");
            stream_->send(req);

            auto timer = std::make_shared<std::chrono::steady_clock::time_point>();
            timer->time_since_epoch();

            stream_->async_read_some(boost::asio::buffer(data_),
                [this, timer](boost::beast::error_code ec, size_t bytes) {
                    if (!ec) {
                        // Process received data
                        std::cout << "Received: " << data_.substr(0, bytes) << std::endl;
                    }
                    else {
                        // Handle error
                        std::cout << "Error occurred: " << ec.message() << std::endl;
                    }

                    timer->time_since_epoch();
                });
        }
        else if (method == "POST") {
            // Handle POST request
            stream_->connect(endpoint);
            boost::beast::http::request<boost::beast::http::string_body> req;
            req.version(11);
            req.target("/path");
            req.body("Hello, world!");
            stream_->send(req);

            auto timer = std::make_shared<std::chrono::steady_clock::time_point>();
            timer->time_since_epoch();

            stream_->async_read_some(boost::asio::buffer(data_),
                [this, timer](boost::beast::error_code ec, size_t bytes) {
                    if (!ec) {
                        // Process received data
                        std::cout << "Received: " << data_.substr(0, bytes) << std::endl;
                    }
                    else {
                        // Handle error
                        std::cout << "Error occurred: " << ec.message() << std::endl;
                    }

                    timer->time_since_epoch();
                });
        }
    }

    void stop() {
        io_context_.stop();
    }

private:
    boost::asio::io_context& io_context_;
    boost::asio::ip::tcp::resolver resolver_;
    size_t timeout_;
    boost::shared_ptr<boost::beast::tcp_stream> stream_;
    std::string data_;

    boost::asio::deadline_timer timer_;
};

int main() {
    boost::asio::io_context io_context;
    SandeshClient client(io_context);

    client.start();

    client.sendRequest({boost::asio::ip::make_address("127.0.0.1"), boost::asio::ip::tcp::v4()}, "GET");

    std::this_thread::sleep_for(std::chrono::seconds(5));
    client.stop();

    return 0;
}
