using System;
using System.Collections.Generic;
using System.Data;
using System.Data.SqlClient;
using System.Threading.Tasks;

public async Task<List<T>> ExecuteStoredProcedureAsync<T>(SqlConnection connection, string storedProcedureName, Dictionary<string, object> parameters) where T : new()
{
    using (var cmd = new SqlCommand(storedProcedureName, connection))
    {
        cmd.CommandType = CommandType.StoredProcedure;

        foreach (var pair in parameters)
        {
            cmd.Parameters.AddWithValue(pair.Key, pair.Value);
        }

        using (var da = new SqlDataAdapter(cmd))
        {
            var ds = new DataSet();
            await da.FillAsync(ds);

            if (ds.Tables.Count > 0)
            {
                var result = new List<T>();

                foreach (DataTable table in ds.Tables)
                {
                    var properties = typeof(T).GetProperties();
                    var dataRow = table.NewRow();

                    foreach (DataColumn column in table.Columns)
                    {
                        var propertyInfo = properties.Find(p => p.Name.ToLower() == column.ColumnName.ToLower());
                        if (propertyInfo != null)
                        {
                            dataRow[propertyInfo.Name] = column["Value"];
                        }
                    }

                    result.Add((T)table.Rows.Add(dataRow).Field<T>(0));
                }

                return result;
            }
            else
            {
                return new List<T>();
            }
        }
    }
}
