using System;
using System.Xml;
using System.Xml.XPath;

public class XmlParser
{
    public static IEnumerable<XmlMatch> Parse(XmlDocument xml, string xpathExpression, string[] namespaceUris)
    {
        var manager = new XmlNamespaceManager(xml.NameTable);
        foreach (var nsUri in namespaceUris)
        {
            manager.AddNamespace("", nsUri);
        }

        var navigator = xml.CreateNavigator();
        navigator.XPathNavigator.NamespaceManager = manager;

        var result = navigator.Select(xpathExpression).GetEnumerator();

        while (result.MoveNext())
        {
            yield return new XmlMatch(result.Current, ((IXPathNavigable)result.Current).GetAttributes());
        }
    }
}

public class XmlMatch
{
    public XPathNodeIterator Node { get; set; }
    public XmlAttributeCollection Attributes { get; set; }

    public XmlMatch(XPathNodeIterator node, XmlAttributeCollection attributes)
    {
        Node = node;
        Attributes = attributes;
    }
}
