import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;

public class Main {
    private static final int MAX_STRING_LENGTH = 1024;
    private static final int MAX_CACHE_SIZE = 1000;
    private static volatile boolean isCacheEnabled = true;
    private static Object cacheLock = new Object();
    private static volatile long[] cache = new long[MAX_CACHE_SIZE];

    public static String getMd5Hash(String input) {
        if (input == null || input.isEmpty()) {
            throw new NullPointerException("Input string cannot be null or empty");
        }
        if (input.length() > MAX_STRING_LENGTH) {
            throw new RuntimeException("Input string length exceeds the maximum allowed");
        }

        long hash;
        synchronized (cacheLock) {
            for (int i = 0; i < cache.length; i++) {
                if (cache[i] == getHash(input)) {
                    return Long.toHexString(cache[i]);
                }
            }
            if (!isCacheEnabled || isFull()) {
                MessageDigest md = getMessageDigest();
                byte[] hashBytes;
                try {
                    hashBytes = md.digest(input.getBytes());
                    hash = getLongFromByteArray(hashBytes);
                    cache[getAvailableSlot()] = hash;
                } catch (NoSuchAlgorithmException e) {
                    throw new RuntimeException("Error creating MD5 message digest", e);
                }
            } else {
                MessageDigest md = getMessageDigest();
                byte[] hashBytes;
                try {
                    hashBytes = md.digest(input.getBytes());
                    hash = getLongFromByteArray(hashBytes);
                } catch (NoSuchAlgorithmException e) {
                    throw new RuntimeException("Error creating MD5 message digest", e);
                }
            }
        }

        return Long.toHexString(hash);
    }

    private static MessageDigest getMessageDigest() {
        try {
            return MessageDigest.getInstance("MD5");
        } catch (NoSuchAlgorithmException e) {
            throw new RuntimeException("Error getting MD5 message digest", e);
        }
    }

    private static long getLongFromByteArray(byte[] bytes) {
        long result = 0;
        for (int i = 0; i < bytes.length; i++) {
            int value = bytes[i] & 0xFF;
            result = (result << 8) | value;
        }
        return result;
    }

    private static boolean isFull() {
        for (int i = 0; i < cache.length; i++) {
            if (cache[i] == 0) {
                return false;
            }
        }
        return true;
    }

    private static int getAvailableSlot() {
        for (int i = 0; i < cache.length; i++) {
            if (cache[i] == 0) {
                return i;
            }
        }
        throw new RuntimeException("Cache is full and cannot be expanded");
    }
}
