function handle_user_request() {
    $request = $_REQUEST;
    if (!isset($request['sub_action'])) {
        $request['sub_action'] = 'create';
    }

    switch ($request['sub_action']) {
        case 'create':
            return create_or_update_user($request);
        case 'update':
            return create_or_update_user($request);
        case 'delete':
            return delete_user($request);
        default:
            return json_encode(['message' => 'error', 'details' => ['status' => 'failure', 'reason' => 'unknown sub_action']]);
    }
}

function create_or_update_user($request) {
    $validator = new Validator();
    if (!$validator->validate($request)) {
        return json_encode(['message' => 'error', 'details' => ['status' => 'failure', 'reason' => 'invalid request data']]);
    }

    try {
        if (isset($request['id'])) {
            $user = User::find($request['id']);
            if (!$user) {
                return json_encode(['message' => 'error', 'details' => ['status' => 'failure', 'reason' => 'user not found']]);
            }
            $save_result = Save::update_user($user, $request);
        } else {
            $user = new User();
            $save_result = Save::create_user($user, $request);
        }

        if ($save_result) {
            return json_encode(['message' => 'success', 'details' => ['status' => 'success']]);
        }
    } catch (Exception $e) {
        return json_encode(['message' => 'error', 'details' => ['status' => 'failure', 'reason' => $e->getMessage()]]);
    }

    return json_encode(['message' => 'error', 'details' => ['status' => 'failure', 'reason' => 'unknown error']]);
}

function delete_user($request) {
    try {
        if (isset($request['id'])) {
            User::delete($request['id']);
            return json_encode(['message' => 'success', 'details' => ['status' => 'success']]);
        } else {
            return json_encode(['message' => 'error', 'details' => ['status' => 'failure', 'reason' => 'no user ID provided']]);
        }
    } catch (Exception $e) {
        return json_encode(['message' => 'error', 'details' => ['status' => 'failure', 'reason' => $e->getMessage()]]);
    }
}
