async function mergeFiles(directoryPath) {
  try {
    const filePromises = [];
    const fs = require('fs');
    const path = require('path');

    for (const filename of await fs.readdir(directoryPath)) {
      if (!filename.endsWith('.txt')) continue; // filter by extension
      const filePath = path.join(directoryPath, filename);
      filePromises.push(fs.promises.readFile(filePath, 'utf8'));
    }

    const fileContents = await Promise.all(filePromises);

    let mergedString = '';
    for (const content of fileContents) {
      mergedString += content;
    }

    return mergedString;

  } catch (err) {
    console.error('Error merging files:', err);
    throw err;
  }
}
