["```
function extractBibleReferences(text) {
  const bibleBooks = ['Genesis', 'Exodus', 'Leviticus', 'Numbers', 'Deuteronomy', 'Joshua', 'Judges', 'Ruth', '1Samuel', '2Samuel', '1Kings', '2Kings', '1Chronicles', '2Chronicles', 'Ezra', 'Nehemiah', 'Esther', 'Job', 'Psalms', 'Proverbs', 'Ecclesiastes', 'SongOfSolomon', 'Isaiah', 'Jeremiah', 'Lamentations', 'Ezekiel', 'Daniel', 'Hosea', 'Joel', 'Amos', 'Obadiah', 'Jonah', 'Micah', 'Nahum', 'Habakkuk', 'Zephaniah', 'Haggai', 'Zechariah', 'Malachi'];
  const verseReferenceRegex = /\b(\w+)\s*\d+:\d+\b/g;
  const bookRegex = /\b(\w+)\b/gi;

  let books = {};
  let references = {};

  text.toLowerCase().replace(/[^\w\s]/g, '').split(/\W+/).forEach(word => {
    if (bookRegex.test(word)) {
      if (!books[word]) books[word] = 0;
      books[word]++;
    } else if (verseReferenceRegex.test(word)) {
      let match = verseReferenceRegex.exec(word);
      if (!references[match[1]]) references[match[1]] = {};
      if (!references[match[1]][match[2]]) references[match[1]][match[2]] = 0;
      references[match[1]][match[2]]++;
    }
  });

  return { books, references };
}"]

['```
function generateNavigationBar(menuItems) {
  let navHTML = '<nav>';
  for (let item of menuItems) {
    navHTML += `<a href="${item.url}" target="_blank">${item.label}</a>`;
    if (Array.isArray(item.submenu)) {
      navHTML += `
        <ul>
          ${item.submenu.map(subItem => `<li><a href="${subItem.url}" target="_blank">${subItem.label}</a></li>`).join('')}
        </ul>
      `;
    }
  }
  navHTML += '</nav>';
  return navHTML;
}']

