function StreamManager() {
  this.data = [];
  let paused = false;
  this.graph = {};

  StreamManager.prototype.collectData = function* (stream) {
    for await (const chunk of stream) {
      if (!paused) {
        this.data.push(chunk);
      }
    }
  };

  StreamManager.prototype.pause = function() {
    paused = true;
  };

  StreamManager.prototype.resume = function() {
    paused = false;
