['```
function copyBytes(dataChunks, bytesToCopy) {
  const totalSize = dataChunks.reduce((acc, chunk) => acc + chunk.length, 0);
  if (bytesToCopy > totalSize) throw new Error("Invalid input size");

  const outputBuffer = Buffer.alloc(bytesToCopy);
  let writeIndex = 0;
  for (const chunk of dataChunks) {
    const chunkLength = chunk.length;
    const bytesInChunk = Math.min(chunkLength, bytesToCopy - writeIndex);
    chunk.copy(outputBuffer, writeIndex, writeIndex + bytesInChunk);
    writeIndex += bytesInChunk;
  }
  return outputBuffer;
}
