['function traverseDOM(filter) {
  const queue = [];
  const result = [];

  function processNode(node) {
    if (node.nodeType === 1) { // element node
      for (let child of node.children) {
        queue.push(child);
      }
    } else if (node.nodeType === 3 && filter(node.textContent)) { // text node with matching content
      result.push({ node, match: true });
    } else if (node.hasChildNodes()) {
      processNode(node.firstChild);
    }

    if (!queue.length) {
      queue = [];
    }
  }

  function asyncTraverse() {
    return new Promise((resolve, reject) => {
      if (!queue.length) {
        resolve();
      }

      const node = queue.shift();
      processNode(node).then(() => {
        asyncTraverse().then(resolve);
      }).catch(reject);
    });
  }

  async function traverse() {
    await asyncTraverse();
    return result;
  }

  return traverse();']

