class ModuleLoader {
  constructor() {
    this.modules = {};
    this.loadQueue = [];
  }

  async loadModule(url) {
    if (!this.modules[url]) {
      try {
        const module = await import(url);
        this.modules[url] = module;
      } catch (error) {
        console.error(`Failed to load module ${url}: ${error}`);
      }
    }
    return this.modules[url];
  }

  async loadModules(urls) {
    for (const url of urls) {
      this.loadQueue.push({ url, loaded: false });
    }
    while (this.loadQueue.length > 0) {
      const queueItem = this.loadQueue.shift();
      try {
        await this.loadModule(queueItem.url);
        queueItem.loaded = true;
      } catch (error) {
        console.error(`Failed to load module ${queueItem.url}: ${error}`);
      }
    }
  }

  async executeModules(modules) {
    for (const moduleName in modules) {
      try {
        await modules[moduleName].default();
      } catch (error) {
        console.error(`Failed to execute module ${moduleName}: ${error}`);
      }
    }
  }

  async run() {
    const urls = [...new Set(this.loadQueue.map(item => item.url))];
    await this.loadModules(urls);
    const loadedModules = {};
    for (const url of urls) {
      if (this.modules[url]) {
        loadedModules[url] = this.modules[url];
      }
    }
    await this.executeModules(loadedModules);
  }
}

// Example usage:
const loader = new ModuleLoader();
loader.loadQueue.push({ url: 'module1.js', loaded: false });
loader.loadQueue.push({ url: 'module2.js', loaded: false });
loader.run();

