import java.io.File;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.ConcurrentHashMap;

public class FileProcessor {

    private static final long ONE_DAY_MILLIS = 24 * 60 * 60 * 1000;

    public MapReport processFilePaths(List<String> filePaths, ConcurrentHashMap<String, Long> cache) {
        MapReport report = new MapReport();
        long startTime = System.currentTimeMillis();

        for (String filePath : filePaths) {
            if (!cache.containsKey(filePath)) {
                File file = new File(filePath);
                long lastModified = file.lastModified();

                if (lastModified > startTime - ONE_DAY_MILLIS) {
                    report.addFile(filePath, lastModified);
                }

                cache.put(filePath, System.currentTimeMillis());
            }
        }

        long endTime = System.currentTimeMillis();
        report.setTimeTaken(endTime - startTime);

        return report;
    }
}

class MapReport {

    private List<String> files;
    private long timeTaken;

    public MapReport() {
        this.files = new ArrayList<>();
        this.timeTaken = 0;
    }

    public void addFile(String file, long lastModified) {
        this.files.add(file + " (modified: " + new Date(lastModified).toString() + ")");
    }

    public List<String> getFiles() {
        return files;
    }

    public long getTimeTaken() {
        return timeTaken;
    }
}
