                        // Process the secure connection
                    } catch (IOException e) {
                        // Handle connection errors and timeouts
                    }
                });
            } catch (IOException e) {
                if (i <= MAX_RETRIES) { // backoff strategy: retry up to maxRetries times
                    try {
                        Thread.sleep(RETRY_DELAY);
                    } catch (InterruptedException ie) {
                        // handle interrupt
