        Scanner scanner = new Scanner(System.in);
        int maxIntegersToRead = 10000;

        if (args.length > 0) {
            try {
                maxIntegersToRead = Integer.parseInt(args[0]);
            } catch (NumberFormatException e) {
                System.out.println("Invalid input. Using default value of 10,000.");
            }
        }

        int[] integers = new int[maxIntegersToRead];
        int count = 0;

        while (scanner.hasNext() && count < maxIntegersToRead) {
            String input = scanner.next();

            try {
                integers[count] = Integer.parseInt(input);
                count++;
            } catch (NumberFormatException e) {
                System.out.println("Error: Non-integer input. Terminating program.");
                return;
            }
        }

        if (count > 0) {
            int maxInteger = Arrays.stream(integers).max().getAsInt();
            System.out.println("Largest integer: " + maxInteger);
        } else {
            System.out.println("No integers read.");
        }

        // Start and stop service with random delay
        for (int i = 0; i < count; i++) {
            try {
                Thread.sleep((long) Math.random() * 10000);
                System.out.println("Service started.");

                // Simulate sending a message to messaging system
                System.out.println("Sending message to messaging system...");

                System.out.println("Service stopped.");
            } catch (InterruptedException e) {
                System.out.println("Error: Interrupted while starting or stopping service.");
            }
        }

        // Free memory allocated for array
        integers = null;
    }
