<?php
class UserAPI {
    private $apiUrl = 'https://api.example.com/users';
    private $apiKey = 'your_api_key';
    private $cacheFile = 'user_data_cache.json';
    private $rateLimit = 5; // requests per minute
    private $lastRequestTime;

    public function getUserData($userId) {
        $userData = $this->getCachedUserData($userId);
        if ($userData !== null) return $userData;

        $response = json_decode($this->makeApiRequest($userId), true);
        if (isset($response['error'])) {
            error_log('Error fetching user data: ' . $response['error']);
            return null;
        }

        $this->cacheUserData($response, $userId);
        return $response;
    }

    private function makeApiRequest($userId) {
        $timestamp = date('U');
        if (!isset($this->lastRequestTime) || ($timestamp - $this->lastRequestTime) > 60) {
            $this->lastRequestTime = $timestamp;
        } elseif (count(explode(',', json_decode($this->getRateLimitCache(), true)['requests'])) >= $this->rateLimit) {
            error_log('Rate limit exceeded');
            return null;
        }

        $ch = curl_init();
        curl_setopt($ch, CURLOPT_URL, $this->apiUrl . '/' . $userId);
        curl_setopt($ch, CURLOPT_RETURNTRANSFER, 1);
        curl_setopt($ch, CURLOPT_HTTPHEADER, array('Authorization: Bearer ' . $this->apiKey));
        $response = json_decode(curl_exec($ch), true);
        curl_close($ch);

        if (isset($response['error'])) {
            error_log('Error fetching user data: ' . $response['error']);
            return null;
        }

        return $response;
    }

    private function cacheUserData($userData, $userId) {
        file_put_contents($this->cacheFile, json_encode(array_merge(json_decode(file_get_contents($this->cacheFile), true), array("{$userId}" => $userData))), FILE_APPEND);
    }

    private function getCachedUserData($userId) {
        if (!file_exists($this->cacheFile)) return null;
        $data = json_decode(file_get_contents($this->cacheFile), true);
        if (!isset($data[$userId])) return null;

        return $data[$userId];
    }

    private function getRateLimitCache() {
        if (!file_exists('rate_limit_cache.json')) file_put_contents('rate_limit_cache.json', json_encode(array()));
        return json_decode(file_get_contents('rate_limit_cache.json'), true);
    }
}']

['```rust
use reqwest::blocking::{ClientBuilder, RequestBuilder};
use reqwest::{header, redirect};
use std::time::Duration;

pub struct HttpClient {
    client: reqwest::blocking::Client,
}

impl HttpClient {
    pub fn new(url: &str) -> Self {
        let client = ClientBuilder::new(reqwest::blocking::default_client())
            .timeout(Duration::from_millis(10000))
            .build()?;

        if let Some(disable_cert_validation) = url.parse::<bool>() {
            if disable_cert_validation {
                client = client.danger_accept_invalid_certs(true);
            }
        }

        Self { client }
    }

    pub fn set_custom_headers(&self, headers: Vec<(&str, &str)>) -> RequestBuilder {
        let mut rb = self.client.get(url).unwrap();
        for (key, value) in headers {
            rb.header(header::Authorization, format!("{}: {}", key, value));
        }
        rb
    }

    pub fn set_retries(&self, max_retries: u16, retry_delay_ms: u32) -> RequestBuilder {
        let mut rb = self.client.get(url).unwrap();
        if max_retries > 0 {
            rb.redirect(retry::Method::Get);
            rb.retry(max_retries as i32, Duration::from_millis(retry_delay_ms));
        }
        rb
    }

    pub fn set_token_auth(&self, token: &str) -> RequestBuilder {
        let mut rb = self.client.get(url).unwrap();
        rb.header("Authorization", format!("Bearer {}", token));
        rb
    }
}
