    $randomString = '';
    for ($i = 0; $i < $length; $i++) {
        $randomString .= substr($characterSet, rand(0, strlen($characterSet) - 1), 1);
    }
    return $randomString;
}

function hashInputString($inputString, $algorithm = 'SHA256') {
    if (!is_string($inputString)) {
        throw new InvalidArgumentException('Input string must be a string');
    }

    $hash = hash($algorithm, $inputString);
    return bin2hex($hash);
}

