    public UserPasswordDAO(Connection conn, Logger log) {
        this.connection = conn;
        this.logger = log;
    }

    public boolean updatePassword(int userId, String oldPassword, String newPassword) throws Exception {

        // Validate the new password strength
        if (!validatePasswordStrength(newPassword)) {
            throw new Exception("New password does not meet the minimum requirements");
        }

        try (PreparedStatement stmt = connection.prepareStatement("SELECT * FROM users WHERE user_id=? AND password=?")) {
            stmt.setInt(1, userId);
            stmt.setString(2, oldPassword);

            try (ResultSet result = stmt.executeQuery()) {
                if (!result.next()) {
                    throw new Exception("Invalid old password");
                }

                // Validate the concurrent access
                String currentLockValue = result.getString("lock_value");

                try (PreparedStatement updateStmt = connection.prepareStatement("UPDATE users SET lock_value=?, password=? WHERE user_id=?")) {
                    updateStmt.setString(1, generateRandomLockValue());
                    updateStmt.setString(2, newPassword);
                    updateStmt.setInt(3, userId);

                    // Ensure data consistency across all services
                    if (!updateStmt.execute()) {
                        throw new Exception("Failed to update the password");
                    }
                } catch (Exception e) {
                    logger.error("Error updating password: " + e.getMessage());
                    return false;
                } finally {
                    // Release the lock value
                    try (PreparedStatement releaseStmt = connection.prepareStatement("UPDATE users SET lock_value=null WHERE user_id=?")) {
                        releaseStmt.setInt(1, userId);
                        releaseStmt.execute();
                    }
                }

                return true;
            } catch (Exception e) {
                logger.error("Error updating password: " + e.getMessage());
                return false;
            }
        } catch (Exception e) {
            logger.error("Error updating password: " + e.getMessage());
            return false;
        }
