#include <stdlib.h>
#include <stdio.h>

struct FSA {
    int **transitions;
    int current_state;
    int final_reached;
};

struct StateNode {
    int state;
    struct StateNode *next;
};

struct StateNode* process_states(int *initial_states, int n_states, struct FSA* fsa, int last_state_index, int* head) {
    // Create a linked list to store the processed states
    struct StateNode* current = NULL;
    struct StateNode** tail = &current;

    for (int i = 0; i < n_states && i <= last_state_index; i++) {
        if (fsa->transitions[i] == NULL) { // Edge case: no further transitions beyond last_state_index
            return NULL;
        }

        int state = initial_states[i];
        struct StateNode* node = (struct StateNode*) malloc(sizeof(struct StateNode));
        node->state = state;
        node->next = NULL;

        if (*tail != NULL) {
            (*tail)->next = node;
            *tail = node;
        } else {
            *head = node;
            *tail = node;
        }
    }

    return *head;
}
