#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define TRANSACTION_THRESHOLD 1000
#define TRANSACTION_AGE_THRESHOLD 30
#define TRANSACTION_ID_INTERVAL 5
#define TRANSACTION_AMOUNT_THRESHOLD 10000
#define ROLLING_AVERAGE_WINDOW 60
#define HIGH_PRIORITY_METADATA "high-priority"

typedef struct {
    time_t timestamp;
    int transaction_id;
    double amount;
    char* metadata;
} Transaction;

typedef struct {
    double total_amount;
    int max_transaction_id;
    time_t last_transaction_timestamp;
    double rolling_average;
    int threshold_count;
} Cache;

Cache cache = {0, 0, 0, 0, 0};

void process_transactions(Transaction** transactions, int num_transactions) {
    pthread_mutex_lock(&cache.lock);
    for (int i = 0; i < num_transactions; i++) {
        Transaction* transaction = &transactions[i];
        time_t current_time = time(NULL);
        if ((current_time - transaction->timestamp) < TRANSACTION_AGE_THRESHOLD &&
            !cache_last_transaction_seen(transaction->transaction_id, TRANSACTION_ID_INTERVAL) &&
            transaction->amount <= TRANSACTION_AMOUNT_THRESHOLD &&
            strcmp(transaction->metadata, HIGH_PRIORITY_METADATA) == 0) {
            cache_total_amount(&cache, transaction->amount);
            cache_max_transaction_id(&cache, transaction->transaction_id);
            cache_last_transaction_timestamp(&cache, current_time);
        }
    }
    pthread_mutex_unlock(&cache.lock);

    double rolling_average = cache_rolling_average(&cache);
    int max_transaction_id = cache_max_transaction_id;
    time_t last_transaction_timestamp = cache_last_transaction_timestamp;

    if (num_transactions > 0) {
        // Update threshold count
        int threshold_count = num_transactions / TRANSACTION_THRESHOLD;
        if (threshold_count < 1)
            threshold_count = 1;
        else if (threshold_count > 5)
            threshold_count = 5;

        // Detect and log unusual patterns in transaction frequency or amounts
        if (num_transactions > 1000 || rolling_average > 50000) {
            printf("Unusual pattern detected: %d transactions in the last second, average amount is %.2f\n", num_transactions, rolling_average);
        }
    }

    printf("Rolling average of transaction amounts over the last 60 seconds: %.2f\n", rolling_average);
    printf("Maximum accepted transaction amount and corresponding transaction ID: %d\n", max_transaction_id);

    return;
}

int main() {
    // Initialize cache
    pthread_mutex_init(&cache.lock, NULL);
    cache_total_amount = &cache->total_amount;
    cache_max_transaction_id = &cache->max_transaction_id;
    cache_last_transaction_timestamp = &cache->last_transaction_timestamp;

    // Process transactions
    Transaction* transactions[1000];
    process_transactions(transactions, 1000);

    return 0;
}
