#include <iostream>
#include <thread>
#include <chrono>

class Attack {
public:
    enum Type { ATTACK1, ATTACK2 };
    Attack(Type type) : type_(type), cooldownTime_(0) {}

    void execute() {
        if (cooldownTime_ > 0) {
            std::cout << "Attack on cooldown! (" << cooldownTime_ << " seconds remaining)\n";
            return;
        }

        // Code to handle attack execution goes here
        std::cout << "Executing " << (type_ == ATTACK1 ? "Attack 1" : "Attack 2") << "\n";

        cooldownTime_ = 9; // Set cooldown timer to 9 seconds

        auto start = std::chrono::steady_clock::now();
        while (cooldownTime_ > 0) {
            auto now = std::chrono::steady_clock::now();
            if (std::chrono::duration_cast<std::chrono::seconds>(now - start).count() >= cooldownTime_) {
                cooldownTime_ = 0;
                break;
            }
            std::this_thread::sleep_for(std::chrono::milliseconds(100));
        }

        std::cout << "Cooldown over!\n";
    }

private:
    Type type_;
    int cooldownTime_;
};

void selectAndExecuteAttack(int attackSelection) {
    Attack* attacks[] = { new Attack(Attack::ATTACK1), new Attack(Attack::ATTACK2) };

    if (attackSelection < 0 || attackSelection >= sizeof(attacks) / sizeof(attacks[0])) {
        std::cout << "Invalid attack selection. Defaulting to ATTACK1.\n";
        attacks[0]->execute();
        return;
    }

    attacks[attackSelection]->execute();

    // Clean up deleted objects
    for (Attack* attack : attacks) {
        delete attack;
    }
}

int main() {
    int attackSelection = 0; // Default selection is ATTACK1

    while (true) {
        std::cout << "Select an attack (0-1): ";
        std::cin >> attackSelection;

        selectAndExecuteAttack(attackSelection);
    }

    return 0;
}
