using System;
using System.Collections.Generic;

public class RandomValueGenerator
{
    private List<Range> ranges = new List<Range>();
    private Random random;

    public void AddRange(int min, int max, bool inclusiveMin, bool inclusiveMax)
    {
        if (min > max)
        {
            throw new ArgumentException("Minimum value cannot be greater than maximum value");
        }

        ranges.Add(new Range(min, max, inclusiveMin, inclusiveMax));
    }

    public float GenerateFloat()
    {
        for (int i = 0; i < ranges.Count; i++)
        {
            random = new Random();
            if (random.NextDouble() < (ranges[i].Maximum - ranges[i].Minimum) / (float)(ranges[i].ExclusiveMin ? ranges[i].Minimum + 1 : ranges[i].Minimum)
               && random.NextDouble() < ((ranges[i].ExclusiveMax ? ranges[i].Maximum - 1 : ranges[i].Maximum) - ranges[i].Minimum) / (float)(ranges[i].ExclusiveMin ? ranges[i].Minimum + 1 : ranges[i].Minimum))
            {
                return (random.NextDouble() * (ranges[i].ExclusiveMax ? ranges[i].Maximum - 1 : ranges[i].Maximum)
                       + (ranges[i].ExclusiveMin ? ranges[i].Minimum + 1 : ranges[i].Minimum));
            }
        }

        throw new Exception("No valid range found");
    }

    public int GenerateInt()
    {
        for (int i = 0; i < ranges.Count; i++)
        {
            random = new Random();
            if (random.NextDouble() < (ranges[i].Maximum - ranges[i].Minimum) / (float)(ranges[i].ExclusiveMin ? ranges[i].Minimum + 1 : ranges[i].Minimum)
               && random.NextDouble() < ((ranges[i].ExclusiveMax ? ranges[i].Maximum - 1 : ranges[i].Maximum) - ranges[i].Minimum) / (float)(ranges[i].ExclusiveMin ? ranges[i].Minimum + 1 : ranges[i].Minimum))
            {
                return random.Next((int)((ranges[i].ExclusiveMax ? ranges[i].Maximum - 1 : ranges[i].Maximum) - (ranges[i].ExclusiveMin ? ranges[i].Minimum + 1 : ranges[i].Minimum))) +
                       (int)(random.NextDouble() * (ranges[i].ExclusiveMax ? ranges[i].Maximum - 1 : ranges[i].Maximum)
                          + (ranges[i].ExclusiveMin ? ranges[i].Minimum + 1 : ranges[i].Minimum));
            }
        }

        throw new Exception("No valid range found");
    }

    public override string ToString()
    {
        StringBuilder sb = new StringBuilder();
        foreach (var range in ranges)
        {
            sb.AppendLine($"Range {range.Minimum} to {range.Maximum}, Inclusive Min: {range.InclusiveMin}, Exclusive Max: {range.ExclusiveMax}");
        }
        return sb.ToString();
    }

    private class Range
    {
        public int Minimum { get; set; }
        public int Maximum { get; set; }
        public bool InclusiveMin { get; set; }
        public bool ExclusiveMax { get; set; }

        public Range(int min, int max, bool inclusiveMin, bool exclusiveMax)
        {
            Minimum = min;
            Maximum = max;
            InclusiveMin = inclusiveMin;
            ExclusiveMax = exclusiveMax;
        }
    }
}
