async function asyncReduce(arr, initialValue, callback) {
  let result = initialValue;
  const promises = arr.map((num, index) => {
    return new Promise((resolve, reject) => {
      setTimeout(() => {
        try {
          const validatedNum = validateNumber(num);
          result = callback(result, validatedNum);
          resolve();
        } catch (error) {
          reject(error);
        }
      }, Math.random() * 1000); // simulate random delay
    });
  });

  await Promise.all(promises);

  return result;
}

async function validateNumber(number) {
  // Simulate external service call to validate the number
  return new Promise((resolve, reject) => {
    setTimeout(() => {
      if (Math.random() < 0.5) { // simulate occasional failure
        reject(new Error("Validation failed"));
      } else {
        resolve(number);
      }
    }, Math.random() * 500); // simulate random delay
  });
}
