#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <stdbool.h>

#define MAX_ITEM_NAME 256
#define MAX_ITEM_VALUE 1024

typedef struct {
    int id;
    char name[MAX_ITEM_NAME];
    char value[MAX_ITEM_VALUE];
} Item;

typedef struct {
    int total_items;
    Item* items;
    char* error_message;
} Bundle;

Bundle* load_resource_bundle(const char* file_path) {
    FILE* file = fopen(file_path, "r");
    if (!file) {
        return create_error_bundle("Failed to open file");
    }

    Bundle* bundle = (Bundle*)malloc(sizeof(Bundle));
    bundle->total_items = 0;
    bundle->items = NULL;

    char line[1024];
    while (fgets(line, sizeof(line), file)) {
        Item* item = (Item*)malloc(sizeof(Item));

        // Parse the item from the line
        sscanf(line, "%d:%s:%s", &item->id, item->name, item->value);

        bundle->total_items++;
        if (!bundle->items) {
            bundle->items = (Item*)malloc((bundle->total_items + 1)*sizeof(Item));
        }
        bundle->items[bundle->total_items - 1] = item;

        // Log the successful loading of the item
        printf("Loaded item %d: '%s' = '%s'\n", item->id, item->name, item->value);
    }

    fclose(file);

    return bundle;
}

Bundle* create_error_bundle(const char* error_message) {
    Bundle* bundle = (Bundle*)malloc(sizeof(Bundle));
    bundle->total_items = -1;
    bundle->items = NULL;
    bundle->error_message = strdup(error_message);
    return bundle;
}
