struct config {
    int append_star;
    int insert_space;
};

char* process_string(char* str, size_t limit, struct config cfg) {
    if (strlen(str) > limit) return NULL;

    char* result = malloc(limit + 2);
    if (!result) return NULL; // Handle memory allocation error

    strcpy(result, str);

    if (strnlen(result, limit) < limit && !cfg.insert_space) {
        strcat(result, "/");
    } else if (strnlen(result, limit) < limit && cfg.insert_space) {
        char* temp = malloc(strlen(result) + 2);
        strcpy(temp, result);
        free(result);
        result = temp;
        strcat(result, " ");
        strcat(result, "/");
    }

    if (cfg.append_star && strnlen(result, limit) < limit) {
        strcat(result, "*");
    }

    return result;
}
