#define MAX_LINE_LENGTH 1024
#define AVERAGE_WINDOW 3

void process_line(char *line) {
    int values[AVERAGE_WINDOW];
    int count = 0;
    char *token = strtok(line, " ");
    while (token != NULL && count < AVERAGE_WINDOW) {
        values[count] = atoi(token);
        token = strtok(NULL, " ");
        count++;
    }

    double sum = 0.0;
    for (int i = 0; i < count; i++) {
        sum += values[i];
    }

    int avg = (count > 0) ? (int)(sum / count) : -1;

    // Append the average as the last field
    char *new_line = malloc(MAX_LINE_LENGTH + 10);
    strcpy(new_line, line);
    if (avg >= 0) {
        sprintf(&new_line[strlen(line)], ", %d", avg);
    } else {
        strcat(new_line, ", -1");
    }

    printf("%s\n", new_line);

    free(new_line);
}

int main() {
    FILE *file = fopen("input.txt", "r");
    if (file == NULL) {
        return 0;
    }

    char *line = malloc(MAX_LINE_LENGTH);
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        process_line(line);
    }

    free(line);
    fclose(file);

    return 0;
}
