const char* modify_filename(const char* filename) {
    int num_vowels = 0;
    for (int i = strlen(filename) - 1; i >= 0; --i) {
        if (strchr("aeiouAEIOU", filename[i])) {
            ++num_vowels;
        }
        else if (filename[i] == '.') {
            break;
        }
    }

    char* new_filename = strdup(filename);
    char* ptr = strrchr(new_filename, '.');
    if (!ptr) {
        *ptr++ = '0';
    } else {
        int digits = num_vowels > 0 ? (int)ceil(log10(num_vowels + 1)) : 0;
        sprintf(ptr, "%d%c", num_vowels, ptr[1]);
    }

    return new_filename;
}
