#include <openssl/aes.h>
#include <openssl/err.h>
#include <openssl/pbkdf2.h>
#include <openssl/rand.h>
#include <uuid/uuid.h>

// Cipher structure to hold the encryption context
typedef struct {
    EVP_CIPHER_CTX *ctx;
    unsigned char iv[AES_BLOCK_SIZE];
} cipher_ctx;

// Function to initialize and set up an AES-256-CBC cipher
cipher_ctx* aes_init_cipher(const char* password, const char* salt) {
    // Derive the encryption key from the password using PBKDF2-HMAC-SHA256
    unsigned char key[EVP_MAX_KEY_LENGTH];
    int key_len;
    if (!PBKDF2_HMAC_SHA256(password, strlen(password), salt, 16, key, &key_len, 10000)) {
        return NULL; // Failure to derive the encryption key
    }

    // Generate a random initialization vector (IV)
    RAND_bytes(key + key_len, AES_BLOCK_SIZE);

    // Initialize the cipher context
    cipher_ctx* ctx = malloc(sizeof(cipher_ctx));
    if (!ctx) {
        return NULL; // Memory allocation failure
    }
    ctx->ctx = EVP_CIPHER_CTX_new();
    if (!ctx->ctx) {
        free(ctx);
        return NULL; // Memory allocation failure
    }

    // Set the encryption key, IV, and block size for AES-256-CBC
    EVP_CipherInit(ctx->ctx, EVP_aes_256_cbc(), key, key_len, key + key_len, AES_BLOCK_SIZE);

    return ctx;
}

// Function to securely clean up and disable a cipher context
void aes_clean_cipher(cipher_ctx* ctx) {
    if (!ctx) {
        return; // Invalid cipher context
    }

    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx); // Free the memory allocated for the cipher context

    return;
}

// Function to generate multiple ciphers with different passwords, storing them in a linked list
typedef struct {
    uuid_t id;
    cipher_ctx* ctx;
    struct node* next;
} node;

node* aes_init_cipher_list() {
    node* head = malloc(sizeof(node));
    if (!head) {
        return NULL; // Memory allocation failure
    }
    head->id = uuid_generate();
    head->ctx = aes_init_cipher("your_password", "your_salt");
    head->next = NULL;
    return head;
}

// Function to securely clean up and disable all cipher contexts in a linked list
void aes_clean_cipher_list(node* head) {
    node* current = head;
    while (current != NULL) {
        if (current->ctx) {
            aes_clean_cipher(current->ctx);
        }
        node* next = current->next;
        free(current); // Free the memory allocated for each cipher context
        current = next;
    }

    return;
}
