#include <fcntl.h>
#include <unistd.h>

int organize_files(const char *input_str, const char *dest_dir, const char **extensions) {
    DIR *dir;
    struct dirent *ent;
    int i, count = 0;
    const char *sep = ".";

    // Create destination directory if it doesn't exist
    if (access(dest_dir, F_OK) != 0) {
        mkdir(dest_dir, S_IRWXU);
    }

    for (i = 0; extensions[i]; i++) {
        count++;
        char *dir_path = alloca(strlen(dest_dir) + strlen(extensions[i]) + 2);
        sprintf(dir_path, "%s/%s", dest_dir, extensions[i]);

        // Create directory if it doesn't exist
        if (access(dir_path, F_OK) != 0) {
            mkdir(dir_path, S_IRWXU);
        }

        dir = opendir(dest_dir);
        if (dir == NULL) {
            return 1;
        }

        while ((ent = readdir(dir)) != NULL) {
            if (strcmp(ent->d_name, "." || strcmp(ent->d_name, "..")) == 0) continue;

            char *file_path = alloca(strlen(input_str) + strlen(extensions[i]) + strlen(sep));
            sprintf(file_path, "%s/%s.%s", input_str, ent->d_name, extensions[i]);

            if (access(file_path, F_OK) == 0) {
                char *dst_file_path = alloca(strlen(dest_dir) + strlen(extensions[i]) + strlen(ent->d_name) + 2);
                sprintf(dst_file_path, "%s/%s.%s", dest_dir, extensions[i], ent->d_name);

                if (rename(file_path, dst_file_path) != 0) {
                    closedir(dir);
                    return 1;
                }
            }

            free(ent);
        }

        closedir(dir);
    }

    return 0;
}
