#include <stdio.h>
#include <stdlib.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/wait.h>

void run_command(char* cmd) {
    pid_t pid = fork();

    if (pid == -1) {
        perror("fork");
        return;
    } else if (pid > 0) { // parent process
        int status;
        waitpid(pid, &status, 0);

        if (!WIFEXITED(status)) {
            printf("Command '%s' timed out.\n", cmd);
        } else if (WEXITSTATUS(status) != 0) {
            printf("Command '%s' failed with exit code %d.\n", cmd, WEXITSTATUS(status));
        } else {
            printf("Command '%s' succeeded.\n", cmd);
        }
    } else { // child process
        dup2(STDOUT_FILENO, STDOUT_FILENO);

        if (execlp(cmd, cmd, NULL) == -1) {
            perror("execlp");
            exit(EXIT_FAILURE);
        }

        printf("Command '%s' timed out.\n", cmd);
    }
}

int main() {
    int i;

    char* commands[] = {"command1", "command2", "command3"};

    for (i = 0; i < sizeof(commands) / sizeof(commands[0]); i++) {
        run_command(commands[i]);

        // Add a timeout if needed
        sleep(2);
    }

    return EXIT_SUCCESS;
}

