import java.io.BufferedReader;
import java.io.BufferedWriter;
import java.io.File;
import java.io.FileReader;
import java.io.FileWriter;
import java.io.IOException;
import java.io.InputStreamReader;
import java.io.OutputStream;
import java.util.Arrays;
import java.util.concurrent.TimeUnit;

public class CommandExecutor {

    private static final int TIMEOUT_SECONDS = 30; // adjust the timeout duration as needed

    public void executeCommand(String[] args) {
        try {
            String command = constructCommand(args);
            File fileToDelete = new File("toBeDeleted.txt"); // specify the file name
            if (fileToDelete.exists()) {
                deleteFile(fileToDelete);
            }

            Process process = Runtime.getRuntime().exec(command);

            // Set timeout for command execution
            process.waitFor(TIMEOUT_SECONDS, TimeUnit.SECONDS);

            // Capture standard output and error streams
            try (BufferedReader stdOut = new BufferedReader(new InputStreamReader(process.getInputStream()));
                 BufferedReader stdErr = new BufferedReader(new InputStreamReader(process.getErrorStream()))) {

                String outLine;
                String errLine;

                // Write standard output to log file
                try (FileWriter logFileOut = new FileWriter("command_output.log", true)) {
                    while ((outLine = stdOut.readLine()) != null) {
                        logFileOut.write(outLine);
                        logFileOut.newLine();
                    }
                }

                // Write error output to log file
                try (FileWriter logFileErr = new FileWriter("command_error.log", true)) {
                    while ((errLine = stdErr.readLine()) != null) {
                        logFileErr.write(errLine);
                        logFileErr.newLine();
                    }
                }

            } catch (IOException e) {
                // Handle IO exceptions
                System.err.println("Error reading output or error streams: " + e.getMessage());
            }

        } catch (InterruptedException | IOException e) {
            // Handle timeouts and other exceptions
            System.err.println("Command execution timed out or an unexpected error occurred: " + e.getMessage());
        }
    }

    private String constructCommand(String[] args) {
        StringBuilder command = new StringBuilder();
        for (String arg : args) {
            command.append(arg).append(" ");
        }
        return command.toString().trim();
    }

    private void deleteFile(File fileToDelete) {
        if (fileToDelete.delete()) {
            System.out.println("File deleted successfully.");
        } else {
            System.out.println("Failed to delete the file. It may still exist.");
        }
    }
}
