#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* access_token;
    int expires_in;
    char* token_type;
    char* refresh_token;
} OAuth2Token;

int validate_json(char* json_string, OAuth2Token* token) {
    if (json_string == NULL || *json_string == '\0') return 0; // empty or null string

    if (!json_valid(json_string)) return 0; // malformed JSON

    if ((token->access_token = json_get_string(json_string, "access_token")) == NULL ||
        strlen(token->access_token) == 0) return 0; // invalid access token

    int expires_in = json_get_int(json_string, "expires_in");
    if (expires_in <= 0) return 0; // invalid expires_in

    char* token_type = json_get_string(json_string, "token_type");
    if (strcmp(token_type, "Bearer") != 0) return 0; // invalid token_type

    if ((token->refresh_token = json_get_string(json_string, "refresh_token")) != NULL &&
        strlen(token->refresh_token) == 0) {
        free(token->refresh_token);
        token->refresh_token = NULL;
    }

    return 1; // valid JSON
}

int main() {
    char* json_string = "{\"access_token\":\"some_access_token\",\"expires_in\":123,\"token_type\":\"Bearer\"}";
    OAuth2Token token;
    if (validate_json(json_string, &token)) {
        printf("JSON is valid\n");
    } else {
        printf("JSON is invalid\n");
    }
    return 0;
}

