    public async Task<string> ProcessByteArray(byte[] byteData)
    {
        if (byteData == null || byteData.Length == 0) return string.Empty;

        // Upload the byte array to cloud storage
        var uploadTask = _cloudStorage.UploadFileAsync("original", byteData);
        await uploadTask;

        // Generate the thumbnail
        using (var thumbnailStream = await _thumbnailGenerator.GenerateThumbnailAsync(uploadTask.Result))
        {
            // Upload the thumbnail to cloud storage
            var thumbnailUploadTask = _cloudStorage.UploadFileAsync("thumbnail", thumbnailStream);
            await thumbnailUploadTask;
        }

        // Delete the original file from cloud storage
        await _cloudStorage.DeleteFileAsync("original");

        return thumbnailUploadTask.Result;
    }
