using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class FileHasher
{
    public static (string, string) DecryptAndCalculateHash(string base64Message, string filePath)
    {
        // Initialize DES triple encryption algorithm with the given key and IV.
        TripleDESCryptoServiceProvider des = new TripleDESCryptoServiceProvider();
        des.Key = ASCIIEncoding.ASCII.GetBytes("your-key");
        des.IV = ASCIIEncoding.ASCII.GetBytes("your-IV");

        // Decrypt the base64 message.
        byte[] base64Bytes = Convert.FromBase64String(base64Message);
        byte[] decryptedBytes;
        using (MemoryStream ms = new MemoryStream())
        {
            CryptoStream cryptoStream = new CryptoStream(ms, des.CreateDecryptor());
            cryptoStream.Write(base64Bytes, 0, base64Bytes.Length);
            cryptoStream.FlushFinalBlock();
            decryptedBytes = ms.ToArray();
        }

        // Convert the decrypted bytes back to a string.
        string decryptedMessage = Encoding.ASCII.GetString(decryptedBytes);

        // Calculate MD5 hash of the file in chunks for efficient memory usage.
        byte[] fileHash;
        using (FileStream fs = new FileStream(filePath, FileMode.Open))
        {
            MD5CryptoServiceProvider md5 = new MD5CryptoServiceProvider();
            int bytesRead;
            using (MemoryStream ms = new MemoryStream())
            {
                while ((readBytes = fs.Read(ms.ToArray(), 0, (int)fs.Length)) > 0)
                {
                    byte[] hashBytes = md5.ComputeHash(ms.ToArray());
                    ms.SetLength(0);
                    ms.Write(hashBytes, 0, hashBytes.Length);
                }
                fileHash = ms.ToArray();
            }
        }

        return (decryptedMessage, BitConverter.ToString(fileHash));
    }
}
