using System;
using System.Security.Cryptography;
using System.Text;

public class Md5HashGenerator
{
    public async Task<string> GenerateMd5HashAsync(string input)
    {
        if (string.IsNullOrEmpty(input))
            return string.Empty;

        using var md5 = MD5.Create();
        var buffer = Encoding.UTF8.GetBytes(input);
        var hashBytes = await GetHashBytesAsync(md5, buffer);

        return BitConverter.ToString(hashBytes).Replace("-", "").ToLower();
    }

    private async Task<byte[]> GetHashBytesAsync(MD5 md5, byte[] buffer)
    {
        using var ms = new MemoryStream();
        await md5.TransformFinalBlockAsync(buffer, 0, buffer.Length, ms);
        await ms.FlushAsync();

        return ms.ToArray();
    }
}
