using System;
using System.IO;
using System.Linq;
using System.Text;
using System.Threading;
using System.Collections.Concurrent;

public class DataDeserializer
{
    private readonly ConcurrentDictionary<string, object> _cache = new ConcurrentDictionary<string, object>();

    public T Deserialize<T>(string filename) where T : class
    {
        if (!_cache.TryGetValue(filename, out var cached))
            cached = LoadAndDeserialize(filename);

        return (T)cached;
    }

    private object LoadAndDeserialize(string filename)
    {
        using (var stream = File.OpenRead(filename))
        {
            using (var gzipStream = new GZipStream(stream, CompressionMode.Decompress))
            {
                using (var memoryStream = new MemoryStream())
                {
                    gzipStream.CopyTo(memoryStream);
                    memoryStream.Position = 0;
                    return Serialize<T>(memoryStream);
                }
            }
        }
    }

    public object Serialize<T>(MemoryStream stream) where T : class
    {
        var formatter = new BinaryFormatter();
        return formatter.Deserialize(stream);
    }
}
