class Config {
public:
    bool appendStar;
    bool insertSpace;
};

std::string* deserializeAndProcessString(unsigned char* byteArray, int sizeLimit, const Config& config) {
    std::istringstream stream(byteArray, 0, sizeLimit);
    ObjectInputStream objStream(&stream);

    try {
        std::string* str = static_cast<std::string*>(objStream.readObject());
        if (str->length() > sizeLimit) {
            return NULL;
        }

        if (config.appendStar) {
            *str += "/";
            *str += "*";
        } else if (config.insertSpace) {
            *str += " /";
        } else {
            *str += "/";
        }

        return str;
    } catch (const BadStream& e) {
        throw std::runtime_error("Error deserializing object");
    } catch (const ExceptionInObjectInputStream& e) {
        throw std::runtime_error("Class not found during deserialization");
    }
}
