const axios = require('axios');
const Winston = require('winston');

async function uploadFile(url, config) {
  try {
    const { storageService, apiKey, timeout, headers } = config || {};

    // Validate URL
    if (!url.startsWith('https://') && !url.startsWith('http://')) throw new Error('Invalid URL format');

    // Initialize axios instance with API key and timeout
    const client = axios.create({
      baseURL: storageService === 'AWS' ? 'aws-s3-url.com' : 'google-cloud-storage-url.com',
      headers: { 'Authorization': `Bearer ${apiKey}` },
      timeout: config.timeout || 5000
    });

    // Upload file using axios
    return await client.put(url, {}, {
      maxRedirects: 5,
      maxContentLength: 1024 * 1024 * 10, // 10MB limit
      headers: { ...headers }
    })
    .then((response) => response.request.res.responseURL)
    .catch((error) => Promise.reject({ message: error.message }));

  } catch (err) {
    const log = Winston.log;

    // Log errors with request ID and timestamped metadata
    log.error({
      level: 'error',
      message: err.message,
      requestId: Date.now().toString(),
      timestamp: new Date().toISOString()
    });

    // Reject promise with error message if upload fails
    return Promise.reject({ message: err.message });
  }
}
