  // implementation of session token validation
}

function cacheShellCommandResults(pageSectionId) {
  const results = {};

  fs.readdir(`shell-command-results/`, (err, files) => {
    if (err) return;

    files.forEach((file) => {
      if (!file.includes(pageSectionId)) return;

      const contents = fs.readFileSync(`shell-command-results/${file}`, 'utf8');
      results[pageSectionId] = { result: contents };
    });
  });

  return results[pageSectionId];
}
