      try {
        const vertexId = await graphql(`
          MATCH (n:Vertex {name: "V${i}"}) RETURN n.id AS id
        `);
        const propKey = `prop_${Math.floor(Math.random() * 10000)}`;
        await graphql(`
          MATCH (n:Vertex {id: ${vertexId}}) 
          SET n += { ${propKey}: "${Math.random().toString()}" }
        `);
