      } catch (error) {
        console.error(error);
      }
    }

    for (let i = 0; i < num; i++) {
      try {
        const fromId = await graphql(`
          MATCH (n:Vertex {name: "V${i}"}) RETURN n.id AS id
        `);
        const toId = Math.floor(Math.random() * num);
        const propKey = `prop_${Math.floor(Math.random() * 10000)}`;
        await graphql(`
          MATCH (from:Vertex {id: ${fromId}}), 
                 (to:Vertex) WHERE to.id = ${toId} 
          SET from-[:RELATION]->to += { ${propKey}: "${Math.random().toString()}" }
        `);
        console.log(`Added property ${propKey} to edge between V${i} and V${toId}`);
      } catch (error) {
        console.error(error);
      }
    }
  }

  async function executeShellCommands(num) {
    for (let i = 0; i < num; i++) {
      try {
        const output = await exec(`echo "Hello World! ${i}"`);
        process.stdout.write(output.toString());
      } catch (error) {
        console.error(error);
      }
    }
  }

  async function main() {
    const numVerticesAndEdges = Math.floor(Math.random() * 100);
    await addVerticesAndEdges(numVerticesAndEdges);
    await addProperties(numVerticesAndEdges);
