use actix_web::{web, App, HttpResponse, HttpServer, Responder};
use log::info;
use std::collections::HashMap;

async fn index() -> HttpResponse {
    HttpResponse::Ok().body("Welcome to Actix-web!")
}

async fn handle_request(req: web::Request) -> HttpResponse {
    info!("Received request: {:?}", req);

    let duration = actix_web::http::timeout(std::time::Duration::from_millis(10)).await;
    info!("Response time: {}ms", duration.as_millis());

    let response = match req.match_info().get("name") {
        Some(name) => format!("Hello, {}!", name),
        None => "Hello, world!".to_string(),
    };

    HttpResponse::Ok().body(response)
}

#[actix_web_macros::main]
async fn main() -> std::io::Result<()> {
    env_logger::init_from_env("LOG_TARGET=info");

    let mut config = HashMap::new();
    config.insert("server.port", "8080");
    config.insert("logging.level", "INFO");

    let server = HttpServer::new(|| {
        App::new()
            .service(web::route().to(index))
            .service(web::resource("/api").to(handle_request))
            .configure(|builder| {
                builder.app_data(config.clone())
                    .service(web::resource("/static/{file:.+}")
                        .to(static_files))
            })
    });

    server.bind("127.0.0.1:8080")?.run().await
}

async fn static_files(req: web::Request) -> Result<HttpResponse, actix_web::error::Error> {
    let file_path = req.match_info().get("file").unwrap();
    let mut response = match fs::read_file(file_path) {
        Ok(contents) => HttpResponse::Ok().body(contents),
        Err(_) => HttpResponse::NotFound().finish(),
    };

    response.headers_mut().insert(
        "Content-Type",
        format!("{}; charset=utf-8", mime_guess::from_path(file_path).first().unwrap()),
    );

    Ok(response)
}
