use std::env;
use std::fs::{create_dir_all, remove_dir_all};
use std::io;
use std::path::Path;
use chrono::{DateTime, Utc};

pub fn manage_logs(service_name: &str) -> io::Result<()> {
    let current_date = DateTime::<Utc>::now().format("%Y-%m-%d").to_string();
    let log_dir = format!("logs/{}/{}", current_date, service_name);

    if env::var("LOG_DIR").is_ok() {
        let old_log_dir = env::var("LOG_DIR")?.clone();

        create_dir_all(&log_dir)?;
        env::set_var("LOG_DIR", &log_dir)?;

        // Archive old logs
        archive_logs(old_log_dir.clone(), 30)?;
    } else {
        create_dir_all(&log_dir)?;
        env::set_var("LOG_DIR", &log_dir)?;
    }

    Ok(())
}

pub fn archive_logs(log_dir: String, days_to_keep: u32) -> io::Result<()> {
    let mut dir_iter = std::fs::read_dir(&log_dir)?;

    while let Some(entry) = dir_iter.next() {
        match entry {
            Ok(dir_entry) => {
                let path = dir_entry.path();
                if path.is_dir() && Path::new(&path).file_name().unwrap().to_string_lossy().to_string().contains("old") {
                    remove_dir_all(path)?;
                }
            },
