from threading import Lock

class ConfigRegistry:
    def __init__(self):
        self.factories = {}
        self.lock = Lock()

    def register_factory(self, id, factory):
        with self.lock:
            if id in self.factories:
                raise ValueError(f"Factory ID '{id}' already registered")
            self.factories[id] = factory

    def get_factory(self, id):
        with self.lock:
            return self.factories.get(id)

