    unsigned char key[32];
    unsigned char iv[16];
    uuid_t uuid;
} CipherContext;

// Function to initialize an AES-256-CBC cipher with a given password
CipherContext* init_cipher(const char* password, int iterations) {
    CipherContext* ctx = (CipherContext*)malloc(sizeof(CipherContext));

    // Derive the encryption key from the password using PBKDF2-HMAC-SHA256
    unsigned char key[32];
    int key_len = 32;
    if (!PBKDF2_hmac_sha256(password, strlen(password), key, &key_len, iterations)) {
        free(ctx);
        return NULL;
    }

    // Generate a random initialization vector (IV)
    if (!RAND_bytes(ctx->iv, 16)) {
        free(ctx);
        return NULL;
    }

    // Set the key length to 32 bytes for AES-256
    ctx->ctx = EVP_CIPHER_CTX_new();
    EVP_EncryptInit_ex(ctx->ctx, EVP_aes_256_cbc(), NULL, key, ctx->iv);

    // Generate a UUID for the cipher context
    uuid_generate_random(&ctx->uuid);

    return ctx;
}

// Function to encrypt or decrypt data using an AES-256-CBC cipher
int cipher_operation(CipherContext* ctx, unsigned char* data, int data_len, int mode) {
    int len = 0;
    if (mode == EVP_ENCRYPT)
        len = EVP_EncryptUpdate(ctx->ctx, data, &data_len, data, data_len);
    else if (mode == EVP_DECRYPT)
        len = EVP_DecryptUpdate(ctx->ctx, data, &data_len, data, data_len);

    // Check for errors
    if (!ERR_error_string(ERR_get_error(), NULL)) {
        return -1;
    }

    return len;
}

// Function to securely clean up and disable an AES-256-CBC cipher
int destroy_cipher(CipherContext* ctx) {
    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx);
    return 0;
}

// Function to generate multiple ciphers with different passwords, storing them in a linked list for later use
CipherContext* init_ciphers(int num_ciphers) {
    CipherContext* ciphers = (CipherContext*)calloc(num_ciphers, sizeof(CipherContext));

    // Initialize each cipher context
    for (int i = 0; i < num_ciphers; i++) {
        const char* password = get_password(i); // Replace with your own password retrieval function
        int iterations = get_iterations(); // Replace with your own iteration configuration function
        ciphers[i] = init_cipher(password, iterations);
    }

    return ciphers;
}

// Function to securely clean up and free a linked list of cipher contexts
int destroy_ciphers(CipherContext* ciphers, int num_ciphers) {
    for (int i = 0; i < num_ciphers; i++) {
        CipherContext* ctx = &ciphers[i];
        if (!destroy_cipher(ctx)) {
            return -1;
        }
    }

    free(ciphers);
    return 0;
}
