typedef struct {
    uint16_t source_port;
    uint16_t destination_port;
    uint32_t sequence_number;
    uint32_t acknowledgement_number;
    uint8_t flags;
    uint16_t window_size;
} TcpHeader;

typedef struct {
    TcpHeader header;
    char payload[];
} TcpSegment;

TcpSegment* tcp_segments = NULL;
size_t segment_count = 0;
uint32_t cumulative_checksum = 0;

TcpSegment* add_segment(TcpHeader* header, size_t payload_length) {
    TcpSegment* new_segment = (TcpSegment*)malloc(sizeof(TcpSegment) + payload_length);
    if (!new_segment) {
        return NULL; // Handle memory allocation failure
    }

    new_segment->header = *header;
    new_segment->payload = (char*)&new_segment->header + sizeof(TcpHeader);

    if (segment_count == 0 || cumulative_checksum != 0) {
        cumulative_checksum = 0; // Reset checksum for first segment or after a sequence break
    }

    for (size_t i = 0; i < payload_length; i++) {
        cumulative_checksum += new_segment->payload[i];
    }

    if (segment_count > 0) {
        TcpSegment* last_segment = tcp_segments + (segment_count - 1);
        cumulative_checksum += ((uint32_t*)(&last_segment->header))[2]; // Add previous segment's checksum
    }

    segment_count++;

    // Update the dynamic array of segments
    if (segment_count > 0) {
        TcpSegment* new_array = (TcpSegment*)malloc(sizeof(TcpSegment) * segment_count);
        if (!new_array) {
            return NULL; // Handle memory allocation failure
        }

        memcpy(new_array, tcp_segments, sizeof(TcpSegment) * segment_count);
        free(tcp_segments);
        tcp_segments = new_array;
    } else {
        tcp_segments = (TcpSegment*)malloc(sizeof(TcpSegment));
        if (!tcp_segments) {
            return NULL; // Handle memory allocation failure
        }
    }

    return new_segment;
}

void update_segment(size_t index, TcpHeader* header) {
    if (index >= segment_count || !tcp_segments) {
        return; // Index out of bounds or no segments available
    }

    tcp_segments[index].header = *header;

    for (size_t i = 0; i < strlen((char*)tcp_segments[index].payload); i++) {
        cumulative_checksum += ((uint8_t*)tcp_segments[index].payload)[i];
    }
}

TcpSegment* get_segment(size_t index) {
    if (index >= segment_count || !tcp_segments) {
        return NULL; // Index out of bounds or no segments available
    }

    return &tcp_segments[index];
}

size_t get_segment_count() {
    return segment_count;
}

uint32_t get_cumulative_checksum() {
    return cumulative_checksum;
}
