#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/socket.h>
#include <arpa/inet.h>
#include <ifaddrs.h>
#include <unistd.h>
#include <time.h>

#define MAX_CONFIG_FILE 1024
#define MAX_INTERFACE_NAME 64
#define MAX_IP_ADDRESS 32
#define MAX_SUBNET_MASK 32
#define MAX_GATEWAY 32

void configure_interface(const char* config_file, const char* interface_name, const char* ip_address, int bring_up);
char* generate_random_string(int length, const char* charset);

int main(int argc, char* argv[]) {
    if (argc != 5) {
        printf("Usage: %s <config_file> <interface_name> <ip_address> <bring_up>\n", argv[0]);
        return 1;
    }

    configure_interface(argv[1], argv[2], argv[3], atoi(argv[4]));

    return 0;
}

void configure_interface(const char* config_file, const char* interface_name, const char* ip_address, int bring_up) {
    FILE* file = fopen(config_file, "r");
    if (!file) {
        perror("Error opening configuration file");
        exit(1);
    }

    struct ifaddrs* ifaddr;
    struct ifaddrs* ifa_iter = NULL;

    getifaddrs(&ifa_iter);

    while (ifa_iter != NULL) {
        if (ifa_iter->ifa_addr->sa_family == AF_INET && strcmp(ifa_iter->ifa_name, interface_name) == 0) {
            // Apply settings to the network interface
            int sock_fd = socket(AF_INET, SOCK_DGRAM, 0);
            if (sock_fd < 0) {
                perror("Error creating socket");
                exit(1);
            }

            struct sockaddr_in* addr = (struct sockaddr_in*)ifa_iter->ifa_addr;
            inet_pton(AF_INET, ip_address, &addr->sin_addr);

            // Bring up the network interface
            if (bring_up && setsockopt(sock_fd, IFF_UP, "1") < 0) {
                perror("Error bringing up network interface");
                exit(1);
            }

            close(sock_fd);
        }

        ifa_iter = ifa_iter->ifa_next;
    }

    freeifaddrs(ifa_iter);

    fclose(file);
}

char* generate_random_string(int length, const char* charset) {
    static char random_string[MAX_INTERFACE_NAME];
    srand(time(NULL));

    for (int i = 0; i < length; i++) {
        int index = rand() % strlen(charset);
        random_string[i] = charset[index];
    }

    return random_string;
}
