    if (sscanf(buffer, "%d", &n) != 1 || n < 0) {
        printf("Invalid input. Using default limit of %d.\n", n);
    }
    int *arr = (int *)malloc(n * sizeof(int));
    for (int i = 0; i < n; i++) {
        if (fgets(buffer, sizeof(buffer), stdin) == NULL || sscanf(buffer, "%d", &arr[i]) != 1) {
            printf("Error: Invalid input. Terminating program.\n");
            free(arr);
            exit(1);
        }
