import java.io.*;
import java.security.MessageDigest;
import java.util.*;

public class Main {
    private static Map<String, Tuple> cache = new HashMap<>();
    private static final int MAX_FILE_SIZE = 1048576;

    public static Tuple processTextFile(String filePath) throws Exception {
        if (filePath == null || filePath.isEmpty()) {
            return new Tuple(null, "Invalid file path");
        }

        File file = new File(filePath);
        if (!file.exists() || !file.isFile()) {
            return new Tuple(null, "File not found or not a file");
        }

        byte[] content;
        try (BufferedInputStream bis = new BufferedInputStream(new FileInputStream(file))) {
            content = new byte[MAX_FILE_SIZE];
            int bytesRead = bis.read(content);
            if (bytesRead < 0) {
                return new Tuple(null, "Error reading the file");
            }
            if (bytesRead > MAX_FILE_SIZE) {
                return new Tuple(null, "File size exceeds the limit");
            }
        } catch (IOException e) {
            return new Tuple(null, "Error reading the file: " + e.getMessage());
        }

        String fileHash;
        try {
            MessageDigest md = MessageDigest.getInstance("MD5");
            byte[] hashBytes = md.digest(content);
            StringBuilder sb = new StringBuilder();
            for (byte b : hashBytes) {
                sb.append(String.format("%02x", b));
            }
            fileHash = sb.toString();
        } catch (Exception e) {
            return new Tuple(null, "Error computing the MD5 hash: " + e.getMessage());
        }

        String sequenceNumber;
        try (BufferedReader br = new BufferedReader(new InputStreamReader(new FileInputStream(file)))) {
            StringBuilder lines = new StringBuilder();
            for (String line; (line = br.readLine()) != null;) {
                lines.append(line);
                if (!line.trim().endsWith("SequenceNumber:")) {
                    continue;
                }
                sequenceNumber = line.substring(line.indexOf(":") + 1).trim();
                break;
            }
        } catch (IOException e) {
            return new Tuple(null, "Error reading the file: " + e.getMessage());
        }

        if (sequenceNumber == null || sequenceNumber.isEmpty()) {
            return new Tuple(fileHash, "Sequence number not found in the file");
        }

        Tuple result = cache.computeIfAbsent(filePath, k -> new Tuple(fileHash, sequenceNumber));
        return result;
    }
}

class Tuple {
    public String md5Hash;
    public String sequenceNumber;

    public Tuple(String md5Hash, String sequenceNumber) {
        this.md5Hash = md5Hash;
        this.sequenceNumber = sequenceNumber;
    }

    @Override
    public String toString() {
        return "MD5 Hash: " + md5Hash + ", Sequence Number: " + sequenceNumber;
    }
}
