import os
import hashlib
import logging
from threading import Thread
from queue import Queue

def process_and_reformat_files(directory):
    log_level = logging.INFO
    logging.basicConfig(level=log_level)

    def process_file(file_path):
        try:
            file_hash = hashlib.md5(open(file_path, 'rb').read()).hexdigest()
            base_name, extension = os.path.splitext(os.path.basename(file_path))
            new_file_name = f"{base_name}_{file_hash}{extension}"
            os.rename(file_path, new_file_name)
        except Exception as e:
            logging.error(f"Error processing file {file_path}: {str(e)}")

    def process_files(directory):
        queue = Queue()
        num_threads = 4
        threads = []

        for i in range(num_threads):
            thread = Thread(target=process_queue, args=(queue,))
            thread.start()
            threads.append(thread)

        for root, dirs, files in os.walk(directory):
            for file in files:
                file_path = os.path.join(root, file)
                queue.put(file_path)

        for thread in threads:
            thread.join()

    def process_queue(queue):
        while True:
            file_path = queue.get()
            if file_path is None:
                break
            process_file(file_path)
            queue.task_done()

    try:
        process_files(directory)
    except Exception as e:
        logging.error(f"Error processing files in directory {directory}: {str(e)}")

if __name__ == "__main__":
    directory = "/path/to/files"
    process_and_reformat_files(directory)
