import hashlib
import os
import time
from multiprocessing import Pool
from ftplib import FTP
from urllib.request import urlretrieve
import logging

def get_file_hash(file_path, algorithm='md5', verify=False, reference_hash=None):
    if not os.path.exists(file_path):
        raise FileNotFoundError(f"File {file_path} not found")

    file_size = os.path.getsize(file_path)
    chunk_size = 1024 * 1024  # 1MB chunks for performance

    def hash_file_chunks(file_path, algorithm):
        md5 = hashlib.md5()
        with open(file_path, 'rb') as f:
            while True:
                chunk = f.read(chunk_size)
                if not chunk:
                    break
                md5.update(chunk)
        return md5.hexdigest()

    if algorithm.lower() == 'md5':
        hash_func = hashlib.md5
    elif algorithm.lower() == 'sha-256':
        hash_func = hashlib.sha256
    elif algorithm.lower() == 'sha-512':
        hash_func = hashlib.sha512
    else:
        raise ValueError("Invalid algorithm")

    start_time = time.time()
    progress_indicator = 0

    while True:
        if not os.path.exists(file_path):
            raise FileNotFoundError(f"File {file_path} not found")
        if not os.path.isfile(file_path):
            raise TypeError(f"{file_path} is not a file")
        chunk = file_size - progress_indicator * chunk_size
        if chunk <= 0:
            break

        with open(file_path, 'rb') as f:
            f.seek(progress_indicator * chunk_size)
            chunk_data = f.read(chunk_size)

        hash_func().update(chunk_data)
        progress_indicator += 1
        print(f"{progress_indicator / (file_size // chunk_size) * 100:.2f}%")
        time.sleep(1)

    end_time = time.time()
    elapsed_time = end_time - start_time

    if verify and reference_hash:
        calculated_hash = hash_func().hexdigest()
        if calculated_hash != reference_hash:
            raise ValueError("Hash verification failed")

    return {
        'file_path': file_path,
        'algorithm': algorithm.lower(),
        'hash_value': hash_func().hexdigest(),
        'elapsed_time': elapsed_time
    }

def parallelize_file_chunks(file_path, chunk_size):
    pool = Pool()
    with open(file_path, 'rb') as f:
        while True:
            chunk = f.read(chunk_size)
            if not chunk:
                break
            yield chunk

def log_progress(current, total, message=None):
    print(f"\r{current / total * 100:.2f}% {'' if message is None else message}", end='')

def get_file_hash_parallel(file_path, algorithm='md5'):
    def parallelize_chunks(file_path, chunk_size):
        pool = Pool()
        with open(file_path, 'rb') as f:
            while True:
                chunk = f.read(chunk_size)
                if not chunk:
                    break
                yield chunk

    file_size = os.path.getsize(file_path)

    if algorithm.lower() == 'md5':
        hash_func = hashlib.md5()
    elif algorithm.lower() == 'sha-256':
        hash_func = hashlib.sha256()
    elif algorithm.lower() == 'sha-512':
        hash_func = hashlib.sha512()
    else:
        raise ValueError("Invalid algorithm")

    start_time = time.time()
    progress_indicator = 0

    for chunk in parallelize_chunks(file_path, file_size // 10):
        hash_func.update(chunk)
        log_progress(progress_indicator + 1, file_size // 10, "Processing...")
        progress_indicator += 1
        if progress_indicator % (file_size // 100) == 0:
            print(f"{progress_indicator / (file_size // 10) * 100:.2f}%")
    end_time = time.time()
    elapsed_time = end_time - start_time

    return {
        'file_path': file_path,
        'algorithm': algorithm.lower(),
        'hash_value': hash_func.hexdigest(),
        'elapsed_time': elapsed_time
    }
