#include <openssl/aes.h>
#include <openssl/err.h>
#include <openssl/sha.h>
#include <openssl/hmac.h>

struct cipher_ctx {
    EVP_CIPHER_CTX *ctx;
    unsigned char *key;
    unsigned char *iv;
};

cipher_ctx* aes256_cbc_init(const char* password, int password_len) {
    // Initialize SHA-1 for deriving the key
    SHA_CTX sha_ctx;
    SHA1_Init(&sha_ctx);
    SHA1_Update(&sha_ctx, password, password_len);
    unsigned char hash[SHA_DIGEST_LENGTH];
    SHA1_Final(hash, &sha_ctx);

    // Initialize PBKDF2 to derive the key from the password and hash
    EVP_PBE_CTX *pbe_ctx = NULL;
    const EVP_MD *md = EVP_sha256();
    int iterations = 1000;

    if (PBKDF2_create(&pbe_ctx, password, password_len, md, &iterations) != 1) {
        // Handle error: failed to create PBKDF2 context
        return NULL;
    }

    unsigned char derived_key[EVP_MAX_KEY_LENGTH];
    int key_len = PBKDF2(pbe_ctx, hash, SHA_DIGEST_LENGTH, derived_key, EVP_MAX_KEY_LENGTH);

    if (key_len <= 0) {
        // Handle error: failed to derive the key
        return NULL;
    }

    // Initialize AES-256-CBC with the derived key and a fixed IV length
    unsigned char iv[AES_BLOCK_SIZE];
    for (int i = 0; i < AES_BLOCK_SIZE; i++) {
        iv[i] = (unsigned char)i;
    }

    cipher_ctx *ctx = malloc(sizeof(cipher_ctx));
    ctx->ctx = EVP_CipherInit(EVP_aes_256_cbc(), derived_key, iv, 1);
    if (!ctx->ctx) {
        // Handle error: failed to initialize AES-256-CBC
        return NULL;
    }

    ctx->key = derived_key;
    ctx->iv = iv;

    return ctx;
}

void aes256_cbc_cleanup(cipher_ctx *ctx) {
    EVP_Cipher_CTX_free(ctx->ctx);
    OPENSSL_cleanse(ctx->key, EVP_MAX_KEY_LENGTH);
    OPENSSL_cleanse(ctx->iv, AES_BLOCK_SIZE);
    free(ctx);
}
