using System;
using System.Collections.Generic;
using System.Linq;

public class DataQualityMonitor
{
    private readonly List<DataCheck> _checks = new();
    private readonly Dictionary<string, Func<object, bool>> _validators = new();

    public void AddCheck(string checkName, string dataType, params (string Rule, object Value)[] rules)
    {
        var dataCheck = new DataCheck(checkName, dataType);
        foreach ((var rule, var value) in rules)
        {
            switch (dataType.ToLower())
            {
                case "numerical":
                    _validators.Add($"{checkName}_{rule}", x => IsNumericalValid(x, value));
                    break;
                case "categorical":
                    _validators.Add($"{checkName}_{rule}", x => IsCategoricalValid(x, value));
                    break;
            }
        }
        _checks.Add(dataCheck);
    }

    public void Validate(object[] dataBatch)
    {
        foreach (var check in _checks)
        {
            if (!ValidateCheck(check, dataBatch))
            {
                Console.WriteLine($"Validation failed for check '{check.Name}'");
            }
        }
    }

    private bool ValidateCheck(DataCheck check, object[] dataBatch)
    {
        var isValid = true;
        foreach (var validator in _validators.Values)
        {
            if (!dataBatch.All(validator))
            {
                isValid = false;
                break;
            }
        }
        return isValid;
    }

    private bool IsNumericalValid(object value, (string Rule, object Value) rule)
    {
        var threshold = Convert.ToDouble(rule.Value);
        switch (rule.Rule.ToLower())
        {
            case "greaterthan":
                return (value is double num && num > threshold);
            case "lessthan":
                return (value is double num && num < threshold);
            default:
                throw new ArgumentException("Invalid rule for numerical data");
        }
    }

    private bool IsCategoricalValid(object value, (string Rule, object Value) rule)
    {
        var expectedValue = rule.Value.ToString();
        switch (rule.Rule.ToLower())
        {
            case "equal":
                return (value is string && ((string)value).Equals(expectedValue, StringComparison.OrdinalIgnoreCase));
            default:
                throw new ArgumentException("Invalid rule for categorical data");
        }
    }

    public override string ToString()
    {
        var result = $"Managed checks: {_checks.Count}\n";
        foreach (var check in _checks)
        {
            result += $"{check.Name} ({check.DataType}): {string.Join(", ", _validators.Keys.Where(k => k.StartsWith(check.Name)))}\n";
        }
        return result.Trim();
    }

    public class DataCheck
    {
        public string Name { get; }
        public string DataType { get; }

