void read_integers(int *max_count) {
    int count = 0;
    int *arr = NULL;
    char c;

    while ((c = getchar()) != '\n' && count < *max_count) {
        if (c >= '0' && c <= '9') {
            // Add the digit to the array
            arr[count] = c - '0';
            count++;
        } else if (c == '-') {
            // Handle negative numbers
            int temp;
            do {
                c = getchar();
                if (c >= '0' && c <= '9') {
                    temp = c - '0';
                    break;
                }
            } while (1);
            arr[count] = -temp;
            count++;
        } else {
            // Invalid input, terminate the function
            printf("Error: Only integers are allowed.\n");
            if (arr != NULL) free(arr);
            exit(1);
        }
    }

    // Determine and print the largest integer
    int max_int = arr[0];
    for (int i = 1; i < count; i++) {
        if (arr[i] > max_int) max_int = arr[i];
    }
    printf("The largest integer is: %d\n", max_int);

    // Free the memory
    free(arr);
}

void resolve_dns(char *hostname, u_char *ip) {
    struct hostent *host;
    int len;

    host = gethostbyname(hostname);
    if (host == NULL) {
        // Handle errors
        printf("Error: DNS resolution failed.\n");
        return;
    }

    // Copy the IP address to the buffer
    for (len = 0; len < IN_ADDRLEN && len < sizeof(*ip); len++) {
        ip[len] = ((struct in_addr *)host->h_addr)->s_addr >> 24;
        ip[len++] = ((struct in_addr *)host->h_addr)->s_addr >> 16 & 0xFF;
        ip[len++] = ((struct in_addr *)host->h_addr)->s_addr >> 8 & 0xFF;
        ip[len] = ((struct in_addr *)host->h_addr)->s_addr & 0xFF;
    }
}

int main() {
    int max_count = 50000; // Default maximum count
    int *arr;

    read_integers(&max_count);

    char hostname[] = "example.com";
    u_char ip[16];

    resolve_dns(hostname, ip);

    return 0;
}
