import java.io.*;
import java.nio.file.Files;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;

public class LogAnalyzer {
    private static final int MAX_FILE_SIZE = 5242880; // 5 MB in bytes
    private static final String CACHE_KEY = "log-hash-response";
    private static Map<String, Tuple> cache = new ConcurrentHashMap<>();

    public Tuple parseAndAnalyzeLogs(String filePath) throws Exception {
        if (filePath == null || filePath.isEmpty()) {
            throw new NullPointerException("File path is empty or null");
        }

        File file = new File(filePath);
        long fileSize = Files.size(file.toPath());

        if (fileSize > MAX_FILE_SIZE) {
            throw new IOException("File size exceeds the maximum allowed (5 MB)");
        }

        try (BufferedReader reader = new BufferedReader(new FileReader(file))) {
            int entryCount = 0;
            List<String> logEntries = new ArrayList<>();
            long totalResponseTime = 0;

            for (String line; (line = reader.readLine()) != null; ) {
                if (!line.isEmpty()) {
                    logEntries.add(line);
                    String[] parts = line.split(":");
                    int responseTime = Integer.parseInt(parts[1].trim());
                    totalResponseTime += responseTime;
                    entryCount++;
                }
            }

            if (entryCount < 10) {
                return new Tuple("Insufficient data for analysis. Less than 10 entries found.");
            }

            double averageResponseTime = totalResponseTime / entryCount;

            Map<String, Integer> errorCodes = new HashMap<>();

            for (String logEntry : logEntries) {
                String[] parts = logEntry.split(":");
                if (parts.length > 2 && parts[2].startsWith("Error:")) {
                    int errorCode = Integer.parseInt(parts[2].substring(6));
                    errorCodes.put(String.valueOf(errorCode), null);
                }
            }

            Set<String> uniqueErrorCodes = new HashSet<>(errorCodes.keySet());

            String fileContentHash;
            Tuple cacheEntry = cache.get(CACHE_KEY + filePath);

            if (cacheEntry != null) {
                return cacheEntry;
            } else {
                MessageDigest md = MessageDigest.getInstance("SHA-256");
                try (InputStream inputStream = Files.newInputStream(file.toPath())) {
                    byte[] buffer = new byte[8192];
                    int bytesRead;

                    while ((bytesRead = inputStream.read(buffer)) != -1) {
                        md.update(buffer, 0, bytesRead);
                    }

                    fileContentHash = bytesToHex(md.digest());
                } catch (IOException e) {
                    throw new Exception("Error reading file content", e);
                }

                cache.put(CACHE_KEY + filePath, new Tuple(fileContentHash, new Double averageResponseTime), uniqueErrorCodes.size()));

                return new Tuple(fileContentHash, averageResponseTime, uniqueErrorCodes.size());
            }
        } catch (IOException | NullPointerException e) {
            throw new Exception("Error parsing log file", e);
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder sb = new StringBuilder();

        for (byte b : bytes) {
            sb.append(String.format("%02x", b));
        }

        return sb.toString();
    }

    public static class Tuple {
        public final String hash;
        public final double averageResponseTime;
        public final int uniqueErrorCodes;

        public Tuple(String hash, double averageResponseTime, int uniqueErrorCodes) {
            this.hash = hash;
            this.averageResponseTime = averageResponseTime;
            this.uniqueErrorCodes = uniqueErrorCodes;
        }

        public Tuple(String message) {
            this.hash = null;
            this.averageResponseTime = 0.0d;
            this.uniqueErrorCodes = 0;
        }
    }
}']

