    char* name;
    int id;
    void (*func)(const char*);
    char* desc;
} TextProcessingUtility;

// Define the function to dynamically load and return the list of available utilities
TextProcessingUtility** getAvailableUtilities() {
    // Initialize an empty list
    TextProcessingUtility** utilities = NULL;
    int utilityCount = 0;

    // Load the shared library for text processing utilities
    void* libHandle = dlopen("text_processing_utilities.so", RTLD_LAZY);
    if (!libHandle) {
        fprintf(stderr, "Failed to load shared library: %s\n", dlerror());
        return NULL;
    }

    // Iterate through the symbols in the loaded library and load each utility
    for (char* symbol = dlsym(libHandle, "get_utility_"); symbol; symbol = dlsym(libHandle, symbol + 1)) {
        TextProcessingUtility* utility = malloc(sizeof(TextProcessingUtility));

        // Load the utility's name, ID, function pointer, and description
        strcpy(utility->name, symbol);
        utility->id = atoi(strrchr(symbol, '_') + 1);
        utility->func = dlsym(libHandle, symbol);
        utility->desc = strdup(dlsym(libHandle, symbol));

        // Add the utility to the list
        utilities = realloc(utilities, sizeof(TextProcessingUtility*) * (utilityCount + 1));
        utilities[utilityCount++] = utility;
    }

    dlclose(libHandle); // Close the shared library

    return utilities;
}

