#include <stdio.h>
#include <string.h>
#include <openssl/pbkdf2.h>
#include <openssl/aes.h>
#include <openssl/rand.h>
#include <uuid/uuid.h>

#define PBKDF2_ITERATIONS 1000000
#define AES_KEY_LENGTH 32
#define IV_LENGTH 16

typedef struct {
    unsigned char key[AES_KEY_LENGTH];
    unsigned char iv[IV_LENGTH];
    int enabled;
} CipherContext;

CipherContext* cipher_init(const char* password) {
    CipherContext* ctx = malloc(sizeof(CipherContext));
    if (ctx == NULL) {
        return NULL; // Memory allocation failed
    }

    ctx->enabled = 1;

    unsigned char key[AES_KEY_LENGTH];
    int ret = PBKDF2_hmac_sha256(password, strlen(password), NULL, 0, key, AES_KEY_LENGTH, PBKDF2_ITERATIONS);
    if (ret != 1) {
        free(ctx);
        return NULL; // Password derivation failed
    }

    unsigned char* iv = malloc(IV_LENGTH);
    if (iv == NULL) {
        free(ctx);
        return NULL; // Memory allocation failed
    }
    ret = RAND_bytes(iv, IV_LENGTH);
    if (ret != 1) {
        free(iv);
        free(ctx);
        return NULL; // Random number generation failed
    }

    ctx->key = key;
    ctx->iv = iv;

    return ctx;
}

void cipher_free(CipherContext* ctx) {
    if (ctx == NULL)
        return;
    if (ctx->enabled) {
        // Perform any necessary operations to clean up and disable the cipher
        ctx->enabled = 0;
    }
    free(ctx->iv);
    free(ctx->key);
    free(ctx);
}

int cipher_encrypt(CipherContext* ctx, unsigned char* plaintext, int len, unsigned char** ciphertext) {
    if (ctx == NULL || ctx->enabled == 0)
        return -1; // Cipher not initialized or disabled

    AES_KEY key;
    memcpy(&key.key, ctx->key, AES_KEY_LENGTH);

    unsigned char* iv = ctx->iv;
    int ret = AES_cbc_encrypt(plaintext, ciphertext, len, &key, iv, 1);
    if (ret != 1) {
        return -1; // Encryption failed
    }

    return 0;
}

int cipher_decrypt(CipherContext* ctx, unsigned char* ciphertext, int len, unsigned char** plaintext) {
    if (ctx == NULL || ctx->enabled == 0)
        return -1; // Cipher not initialized or disabled

    AES_KEY key;
    memcpy(&key.key, ctx->key, AES_KEY_LENGTH);

    unsigned char* iv = ctx->iv;
    int ret = AES_cbc_encrypt(ciphertext, plaintext, len, &key, iv, 0);
    if (ret != 1) {
        return -1; // Decryption failed
    }

    return 0;
}

// Implement cipher_update_password and cipher_export_import functions as per the task requirements.

int main() {
    CipherContext* ctx = cipher_init("my_secret_password");
    if (ctx == NULL)
        printf("Cipher initialization failed\n");
    else {
        // Use the cipher for encryption and decryption
        unsigned char plaintext[] = "Hello, World!";
        int len = strlen((char*)plaintext);
        unsigned char* ciphertext;
        int ret = cipher_encrypt(ctx, plaintext, len, &ciphertext);
        if (ret == 0)
            printf("Encrypted data: %s\n", (char*)ciphertext);

        // Clean up the cipher
        cipher_free(ctx);
    }

    return 0;
}
