import hashlib
import os
from time import sleep
from threading import Lock

class Hasher:
    def __init__(self):
        self.lock = Lock()
        self.chunk_size = 1024 * 1024  # 1MB chunks default
        self.md5_hash = hashlib.md5()

    def _read_file(self, file_path):
        try:
            with open(file_path, 'rb') as f:
                chunk = f.read(self.chunk_size)
                while chunk:
                    self._hash_chunk(chunk)
                    chunk = f.read(self.chunk_size)
        except IOError as e:
            print(f"Error reading file: {e}")

    def _hash_chunk(self, chunk):
        if not isinstance(chunk, bytes):
            raise ValueError("Invalid chunk type")
        self.md5_hash.update(chunk)

    def get_md5_hash(self):
        return self.md5_hash.hexdigest()

    def hash_file(self, file_path):
        try:
            with self.lock:
                self._read_file(file_path)
        except Exception as e:
            print(f"Error hashing file: {e}")
        finally:
            report = f"File '{file_path}' hashed successfully. MD5 Hash: {self.get_md5_hash()}"
            print(report)

    def hash_files(self, file_paths):
        for file_path in file_paths:
            self.hash_file(file_path)
            sleep(1)  # update progress every second

if __name__ == "__main__":
    hasher = Hasher()
    files_to_hash = ["path/to/file1.txt", "path/to/file2.zip"]
    hasher.hash_files(files_to_hash)
