// Define the cache size and its contents
#define CACHE_SIZE 1024
char* cache[CACHE_SIZE];
int cache_index = 0;

void cache_insert(const char* str) {
    if (cache_index >= CACHE_SIZE)
        return; // Cache full, ignore this string

    cache[cache_index++] = strdup(str);
}

char* cache_get(const char* str) {
    for (int i = 0; i < cache_index; i++) {
        if (!strcmp(cache[i], str))
            return cache[i];
    }
    return NULL;
}

// Define the function
void process_string(char** out, const char* input, int size_limit,
                     int allow_special_char, CustomMutex* mutex) {
    // 1. Validate the string length
    if (strlen(input) > size_limit) {
        *out = NULL;
        return;
    }

    // 2. Append a slash and special character (if allowed)
    char* temp = malloc(size_limit + 2);
    strcpy(temp, input);
    if (!allow_special_char && !strncasecmp(input, "suffix", size_limit)) {
        free(temp);
        *out = NULL;
        return;
    }
    strcat(temp, "/");

    // 3. Insert a space and append the slash (if allowed)
    char* processed = malloc(size_limit + 4);
    if (!allow_special_char || !strncasecmp(input, "suffix", size_limit))
        strcpy(processed, temp);
    else {
        strcat(temp, " ");
        strcpy(processed, temp);
    }

    // 4. Perform additional processing (e.g., URL encoding)
    // ...

    // Cache the processed string
    if (!cache_get(processed)) {
        cache_insert(processed);
    }
    *out = processed;
}

