#define MAX_LINE_LENGTH 1024

int main() {
    // Initialize JSON parser
    JSON_C_VERSION;
    json_t *root = json_object();
    FILE *file = fopen("large_json_file.json", "r");

    if (!file) {
        fprintf(stderr, "Error opening file\n");
        return -1;
    }

    char line[MAX_LINE_LENGTH];
    while (fgets(line, MAX_LINE_LENGTH, file)) {
        // Parse JSON entry
        json_t *entry = json_loads(line, JSON_ENCODE_INTERNALS);

        if (!entry) {
            fprintf(stderr, "Error parsing JSON\n");
            continue;
        }

        int has_access_token = 0;
        int has_expires_in = 0;
        int has_token_type = 0;
        int has_refresh_token = 0;

        json_t *access_token = json_object_get(entry, "access_token");
        if (access_token) {
            has_access_token = 1;

            // Extract numerical values from access_token
            size_t count = 0;
            const char *value = json_string_value(access_token);
            for (const char *p = value; *p; p++) {
                if (*p >= '0' && *p <= '9') {
                    count++;
                } else if (!has_refresh_token) {
                    has_refresh_token = 1;
                    break;
                }
            }

            // Check token_type
            json_t *token_type = json_object_get(entry, "token_type");
            if (!token_type || json_string_value(token_type) != "Bearer") {
                continue;
            }

            // Check expires_in
            json_t *expires_in = json_object_get(entry, "expires_in");
            if (!expires_in || !json_is_integer(expires_in)) {
                continue;
            } else {
                int expires_in_val = json_integer_value(expires_in);
                if (expires_in_val <= 0) {
                    continue;
                }

                has_expires_in = 1;
            }
        }

        // Compute average of last three numerical values
        double avg = 0.0;
        size_t i = 0;
        for (; i < count; i++) {
            if (i >= 3) {
                break;
            }
            avg += (double)(value[i] - '0');
        }

        // Append average to entry
        json_object_set_new(entry, "average", json_real(avg));

        // Print modified entry in comma-separated format
        printf("%s,", json_dumpf(entry, JSON_COMPACT));
        puts("");

        // Free JSON objects
        json_decref(access_token);
        json_decref(token_type);
        json_decref(expires_in);
        json_decref(entry);
    }

    fclose(file);
    json_decref(root);

    return 0;
}
