        }

        function expandTree($node, $featureSize, $numLeafNodes, $dataCapacity) {
            if ($numLeafNodes <= 0 || $dataCapacity <= 0) return;
            if (count($node->children) >= $numLeafNodes) {
                // Node is full, split it
                $newPrefix = $node->prefix . str_pad('', floor(($featureSize - 1) / 2), ' ');
                $this->expandTree(new OctreeNode($newPrefix, []), $featureSize, $numLeafNodes, $dataCapacity);
            } else {
                // Node is not full, recursively expand children
                for ($i = 0; i < count($node->children); $i++) {
                    if (!isset($node->children[$i]->children)) {
