typedef struct {
    char *filename;
    float value;
} record_t;

void organize_files(const char *input_string, const char *destination_directory, char **file_extensions) {
    // Create a directory for each file extension
    DIR *dir;
    struct dirent *ent;
    for (int i = 0; file_extensions[i]; i++) {
        char dir_path[256];
        sprintf(dir_path, "%s/%s", destination_directory, file_extensions[i]);
        mkdir(dir_path, S_IRWXU | S_IRWXG | S_IROTH | S_IWOTH);

        // Load the existing records from disk
        record_t **records = load_records(dir_path);

        // Organize files into subdirectories
        for (ent = readdir(dir); ent; ent = readdir(dir)) {
            if (!strcmp(ent->d_name, ".") || !strcmp(ent->d_name, "..")) continue;
            char file_path[256];
            sprintf(file_path, "%s/%s", destination_directory, file_extensions[i], ent->d_name);
            for (int j = 0; records[j]; j++) {
                if (!strcmp(records[j]->filename, ent->d_name)) break;
            }
        }

        // Save the organized records back to disk
        save_records(dir_path, records);
    }
}

record_t **load_records(const char *directory) {
    // Load existing records from disk
    record_t **records = (record_t **)malloc(sizeof(record_t *) * 1024);
    for (int i = 0; ; i++) {
        char file_path[256];
        sprintf(file_path, "%s/record_%d.dat", directory, i);
        FILE *file = fopen(file_path, "rb");
        if (!file) break;
        record_t *record = malloc(sizeof(record_t));
        fread(&record->filename, sizeof(char), strlen(input_string), file);
        fread(&record->value, sizeof(float), 1, file);
        records[i] = record;
    }
    return records;
}

void save_records(const char *directory, record_t **records) {
    // Save the organized records back to disk
    for (int i = 0; ; i++) {
        char file_path[256];
        sprintf(file_path, "%s/record_%d.dat", directory, i);
        FILE *file = fopen(file_path, "wb");
        if (!file) break;
        fwrite(records[i]->filename, sizeof(char), strlen(input_string), file);
        fwrite(&records[i]->value, sizeof(float), 1, file);
    }
}
