void organizeFiles(char** files, int fileCount, char* destDir) {
    FileType* fileTypes = (FileType*)malloc(sizeof(FileType));
    for (int i = 0; i < fileCount; i++) {
        const char* extension = strrchr(files[i], '.');
        char* fileExtension = strndup(extension, strlen(extension) - 1);
        FileType fileType;
        fileType.id = 1; // default type id
        fileType.fileExtension = fileExtension;
        fileTypes[i] = fileType;
    }
    for (int i = 0; i < fileCount; i++) {
        const char* filename = files[i];
        char* fileExtension = fileTypes[i].fileExtension;
        char* destFileDir = strncat(destDir, "/", 2);
        destFileDir = strncat(destFileDir, fileExtension, strlen(fileExtension));
        printf("Moving %s to %s\n", filename, destFileDir);
    }
}

int main(int argc, char** argv) {
    // Call the organizeFiles function
