void process_log_files(char *dir_path, char *timestamp_range, int min_size_threshold, int max_size_threshold, 
                        int include_metadata, char *report_prefix, char *character_set, int random_string_length) {
    DIR *dp = opendir(dir_path);
    if (dp == NULL) {
        perror("Error opening directory");
        return;
    }

    struct dirent *ent;
    while ((ent = readdir(dp)) != NULL) {
        // Filter for JSON files
        if (strcmp(ent->d_name, ".") == 0 || strcmp(ent->d_name, "..") == 0 || 
            strstr(ent->d_name, ".json") == NULL)
            continue;

        FILE *file = fopen(ent->d_name, "r");
        if (file == NULL) {
            perror("Error opening log file");
            continue;
        }

        json_object *log_data = json_object_from_file(file);
        fclose(file);

        // Parse and validate JSON events
        int event_count = 0;
        double total_duration = 0.0;
        char **event_types = NULL;
        int event_type_count = 0;

        for (json_object_iter iter = json_object_iter_first(log_data); 
             iter != NULL; 
             iter = json_object_iter_next(iter)) {
            // Filter events by timestamp range and size threshold
            if (!validate_event(iter->value, timestamp_range, min_size_threshold, max_size_threshold))
                continue;

            event_count++;
            total_duration += get_event_duration(iter->value);
            char *event_type = get_event_type(iter->value);
            int found = 0;
            for (int i = 0; i < event_type_count; i++) {
                if (strcmp(event_types[i], event_type) == 0)
                    found = 1;
                    break;
            }
            if (!found) {
                event_types = realloc(event_types, sizeof(char *) * (event_type_count + 1));
                event_types[event_type_count++] = strdup(event_type);
            }
        }

        // Generate report
        FILE *report_file = fopen(strcat(report_prefix, ".csv"), "w");
        fprintf(report_file, "Event Type,Count,Average Duration\n");
        for (int i = 0; i < event_type_count; i++) {
            fprintf(report_file, "%s,%d,%.2f\n", event_types[i], event_count, total_duration / event_count);
        }
        fclose(report_file);

        // Generate random string and hash input string
