import java.io.*;
import java.nio.file.Files;
import java.nio.file.Path;
import java.nio.file.Paths;
import java.security.MessageDigest;
import java.security.NoSuchAlgorithmException;
import java.util.*;
import com.google.common.cache.CacheBuilder;
import com.google.common.cache.CacheLoader;
import com.google.common.collect.Ordering;

public class MetricsProcessor {

    private static final int MAX_FILE_SIZE = 10485760;
    private static final int LATENCY_WINDOW_SIZE = 50;
    private static final long ONE_HOUR_IN_MILLISECONDS = 3600000L;

    private Map<String, String> fileHashCache = CacheBuilder
            .newCache()
            .build(CacheLoader.from(key -> processAndAggregateMetrics((String) key)));

    public Tuple processAndAggregateMetrics(String filePath) {
        try {
            if (filePath == null || filePath.isEmpty()) {
                return new Tuple("Invalid input file path", null, null, null);
            }

            Path path = Paths.get(filePath);
            byte[] fileContent = Files.readAllBytes(path);

            if (fileContent.length > MAX_FILE_SIZE) {
                return new Tuple("File size exceeds the maximum limit", null, null, null);
            }

            MessageDigest md = MessageDigest.getInstance("SHA-256");
            String fileHash = bytesToHex(md.digest(fileContent));

            List<Metric> metrics = parseMetrics(filePath);

            if (metrics.size() < LATENCY_WINDOW_SIZE) {
                return new Tuple("Insufficient data for analysis", null, null, null);
            }

            int cumulativeThroughput = calculateCumulativeThroughput(metrics);
            Map<String, Long> requestTypeDistribution = calculateRequestTypeDistribution(metrics);

            return new Tuple(fileHash, getMedianLatency(metrics), cumulativeThroughput, requestTypeDistribution);
        } catch (IOException | NoSuchAlgorithmException e) {
            return new Tuple("Error processing file", null, null, null);
        }
    }

    private String bytesToHex(byte[] bytes) {
        StringBuilder result = new StringBuilder();
        for (byte b : bytes) {
            final String hex = Integer.toHexString(0xff & b);
            result.append(hex);
        }
        return result.toString();
    }

    private List<Metric> parseMetrics(String filePath) {
        // Implement your logic to parse the metrics file
        // For demonstration purposes, assume a simple list of Metric objects
        return Arrays.asList(new Metric("10ms"), new Metric("20ms"), ...);
    }

    private int calculateCumulativeThroughput(List<Metric> metrics) {
        // Calculate cumulative throughput based on the last hour's data
        long lastHourStart = System.currentTimeMillis() - ONE_HOUR_IN_MILLISECONDS;
        int throughput = 0;

        for (Metric metric : metrics) {
            if (metric.getTimeStamp() >= lastHourStart) {
                throughput++;
            }
        }

        return throughput;
    }

    private Map<String, Long> calculateRequestTypeDistribution(List<Metric> metrics) {
        // Calculate the distribution of request types
        Map<String, Long> distribution = new HashMap<>();

        for (Metric metric : metrics) {
            String requestType = metric.getRequestType();
            distribution.put(requestType, distribution.getOrDefault(requestType, 0L) + 1);
        }

        return distribution;
    }

    private Double getMedianLatency(List<Metric> metrics) {
        // Calculate the median latency
        List<Double> latencies = new ArrayList<>();

        for (Metric metric : metrics) {
            double latency = Double.parseDouble(metric.getLatency());
            latencies.add(latency);
        }

        Ordering.DoubleOrdering ordering = Ordering.natural().reverse();
        return ordering.median(latencies);
    }
}

class Metric {
    private String requestType;
    private String latency;

    public Metric(String requestType, String latency) {
        this.requestType = requestType;
        this.latency = latency;
    }

    public String getRequestType() {
        return requestType;
    }

    public String getLatency() {
        return latency;
    }
}

class Tuple {
    private Object[] values;

    public Tuple(Object... values) {
        this.values = values;
    }

    public Object getValue(int index) {
        return values[index];
    }
}
