    char* output_str = malloc(size_limit + 2);
    strcpy(output_str, input_str);

    if (append_slash) {
        output_str[strlen(output_str)] = '/';
        if (append_star) output_str[strlen(output_str) + 1] = '*';
    }

    if (!add_processing || !config->require_space_before_slash) return output_str;

    for (int i = 0; i < strlen(input_str); i++) {
        if (i == strlen(input_str) - 1 && strcasecmp(&input_str[i], config->suffix)) continue;
        output_str = realloc(output_str, size_limit + 3);
