typedef struct {
    MAC_COMMAND_PDU command;
    MAC_DATA_PDU data;
} MAC_PDU;

typedef struct {
    int size;
    MAC_PDU* pdus;
    pthread_mutex_t mutex;
} PDU_Array;

PDU_Array* pdu_array_init() {
    PDU_Array* array = (PDU_Array*)malloc(sizeof(PDU_Array));
    array->size = 0;
    array->pdus = NULL;
    if(pthread_mutex_init(&array->mutex, NULL) != 0) {
        free(array);
        return NULL;
    }
    return array;
}

void pdu_array_free(PDU_Array* array) {
    for(int i = 0; i < array->size; i++) {
        free(array->pdus[i].command.command_data);
        free(array->pdus[i].data.data);
    }
    free(array->pdus);
    pthread_mutex_destroy(&array->mutex);
    free(array);
}

int pdu_array_add(PDU_Array* array, MAC_PDU pdu) {
    if(array == NULL) return -1;

    MAC_PDU* new_pdu = (MAC_PDU*)malloc(sizeof(MAC_PDU));
    *new_pdu = pdu;

    int i;
    for(i = 0; i < array->size; i++) {
        if(new_pdu->command.command_type == array->pdus[i]->command.command_type &&
           new_pdu->data.data_type == array->pdus[i]->data.data_type) {
            // Update existing PDU
            free(array->pdus[i].command.command_data);
            free(array->pdus[i].data.data);
            *array->pdus[i] = pdu;
            return i;
        }
    }

    MAC_PDU** new_pdus = (MAC_PDU**)realloc(array->pdus, sizeof(MAC_PDU*)*(array->size + 1));
    if(new_pdus == NULL) return -2;

    array->pdus = new_pdus;
    array->pdus[array->size] = new_pdu;
    array->size++;

    return array->size - 1;
}

int pdu_array_get_size(PDU_Array* array) {
    pthread_mutex_lock(&array->mutex);
    int size = array->size;
    pthread_mutex_unlock(&array->mutex);
    return size;
}
