int mac_pdu_array_manager() {
    // Initialize variables for the function
    int size = 0;  // Current size of the array
    int capacity = 1;  // Initial capacity of the array
    Node** pdus = (Node**)malloc(capacity * sizeof(Node*));  // Dynamic array to store PDU pairs

