    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Function to handle adding new PDU pairs
    void add_pdu(MAC_PDU pdu) {
        Node* node = (Node*)malloc(sizeof(Node));
        node->pdu = pdu;
        node->next = NULL;

        if(size == capacity) {
            // Reallocate memory with double the capacity when full
            capacity *= 2;
            pdus = (Node**)realloc(pdus, capacity * sizeof(Node*));
        }

        pdus[size++] = node;
    }

