        free(key);
        free(ctx->iv);
        free(ctx->password);
        free(ctx);
        return NULL;
    }

    return ctx;
}

void cipher_cleanup(CipherContext* ctx) {
    if (!ctx) {
        return;
    }

    EVP_CIPHER_CTX_free(ctx->ctx);
    free(ctx->password);
    free(ctx->iv);
    free(ctx);
}

