// Define the maximum allowed buffer size
#define MAX_BUFFER_SIZE (2 * 1024 * 1024)

int main(int argc, char* argv[]) {
    // Initialize variables
    bool helpRequested = false;
    char* delimiter = ",";
    char* outputFile = NULL;
    int bufferSize = MAX_BUFFER_SIZE;

    // Parse command line arguments
    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "--help") == 0) {
            helpRequested = true;
        } else if (strcmp(argv[i], "-d") == 0 && i + 1 < argc) {
            delimiter = argv[i + 1];
            i++;
        } else if (strcmp(argv[i], "-o") == 0 && i + 1 < argc) {
            outputFile = argv[i + 1];
            i++;
        } else if (strncmp(argv[i], "-bs", 3) == 0) {
            bufferSize = atoi(argv[i] + 3);
        }
    }

    // Check for help request and print usage information
    if (helpRequested || argc < 2) {
        printf("Usage: %s [-d delimiter] [-o output_file] [input_file]\n", argv[0]);
        return 0;
    }

    // Open the input file
    FILE* inputFile = fopen(argv[argc - 1], "r");
    if (inputFile == NULL) {
        fprintf(stderr, "Error opening input file: %s\n", argv[argc - 1]);
        return 1;
    }

    // Initialize variables to track line count and average line length
    long int lineCount = 0;
    long long int totalLineLength = 0;

    // Read the input file in chunks
    char buffer[MAX_BUFFER_SIZE];
    while (fgets(buffer, sizeof(buffer), inputFile)) {
        // Process each chunk of lines
        size_t bytesRead = strlen(buffer);
        char* line = buffer;
        do {
            // Count the number of lines and calculate average line length
            lineCount++;
            totalLineLength += bytesRead;
            bytesRead = strcspn(line, delimiter) - 1; // Adjust for null terminator

            // Read the next chunk
            bytesRead = fread(buffer, 1, sizeof(buffer), inputFile);
        } while (bytesRead > 0);

        // Close the input file
        fclose(inputFile);
    }

    // Calculate and print the average line length
    printf("Lines: %ld\n", lineCount);
    if (lineCount > 0) {
        printf("Average line length: %.2f\n", (double)totalLineLength / lineCount);
    } else {
        printf("No lines processed.\n");
    }

    // Close the output file, if specified
    if (outputFile != NULL) {
        FILE* outputFileHandle = fopen(outputFile, "w");
        if (outputFileHandle == NULL) {
            fprintf(stderr, "Error opening output file: %s\n", outputFile);
        } else {
            fprintf(outputFileHandle, "%ld\n", lineCount);
            fclose(outputFileHandle);
        }
    }

    return 0;
}
