#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <openssl/err.h>
#include <openssl/aes.h>
#include <openssl/pbkdf2.h>
#include <uuid/uuid.h>

// Structure to represent a cipher context
typedef struct {
    AES_CTX* aes_ctx;
    EVP_CIPHER_CTX* cipher_ctx;
    unsigned char iv[AES_BLOCK_SIZE];
    UUID uuid;
} CipherContext;

// Function to initialize and configure each cipher context
CipherContext* init_cipher_context(const char* password, const char* salt) {
    CipherContext* ctx = malloc(sizeof(CipherContext));
    if (!ctx) return NULL;

    // Initialize AES context
    if (!(ctx->aes_ctx = AES_new())) {
        free(ctx);
        return NULL;
    }

    // Derive key using PBKDF2-HMAC-SHA256
    unsigned char key[32];
    int ret = PBKDF2_HMAC_SHA256(password, strlen(password), salt, 8, key, 32, 10000);
    if (ret != 1) {
        AES_free(ctx->aes_ctx);
        free(ctx);
        return NULL;
    }

    // Initialize cipher context
    if (!(ctx->cipher_ctx = EVP_CIPHER_CTX_new())) {
        AES_free(ctx->aes_ctx);
        free(ctx);
        return NULL;
    }

    // Set up AES-256-CBC encryption
    if (!EVP_EncryptInit_ex(ctx->cipher_ctx, ctx->aes_ctx, key)) {
        EVP_CIPHER_CTX_free(ctx->cipher_ctx);
        AES_free(ctx->aes_ctx);
        free(ctx);
        return NULL;
    }

    // Generate random initialization vector (IV)
    RAND_bytes(ctx->iv, AES_BLOCK_SIZE);

    // Initialize UUID
    uuid_generate(ctx->uuid);

    return ctx;
}

// Function to encrypt data using a cipher context
int encrypt_data(CipherContext* ctx, const unsigned char* data, size_t data_len, unsigned char** encrypted_data) {
    int ret = EVP_EncryptUpdate(ctx->cipher_ctx, *encrypted_data, &data_len, data, data_len);
    if (ret != 1) return -1;
    return 0;
}

// Function to decrypt data using a cipher context
int decrypt_data(CipherContext* ctx, const unsigned char* encrypted_data, size_t data_len, unsigned char** decrypted_data) {
    int ret = EVP_DecryptUpdate(ctx->cipher_ctx, *decrypted_data, &data_len, encrypted_data, data_len);
    if (ret != 1) return -1;
    return 0;
}

// Function to store multiple cipher contexts in a linked list
typedef struct {
    CipherContext* ctx;
    struct LinkNode* next;
} LinkNode;

LinkNode* add_cipher_context(LinkNode* head, CipherContext* ctx) {
    LinkNode* new_node = malloc(sizeof(LinkNode));
    if (!new_node) return NULL;

    new_node->ctx = ctx;
    new_node->next = head;
    return new_node;
}

// Function to securely clean up and disable cipher contexts
void cleanup_cipher_context(CipherContext* ctx) {
    EVP_CIPHER_CTX_free(ctx->cipher_ctx);
    AES_free(ctx->aes_ctx);
    free(ctx);
}
