// Define a struct to hold log context information
typedef struct {
    uuid_t id; // Unique identifier (UUID) for the logging context
    int level; // Log level (DEBUG, INFO, WARNING, ERROR)
    char* filename; // Output file name or NULL if console output
    int sockfd; // Socket for network output or -1 if not applicable
} log_ctx_t;

// Initialize and configure a new logging context
log_ctx_t* log_ctx_new(const uuid_t id, int level, const char* filename, int sockfd) {
    log_ctx_t* ctx = (log_ctx_t*)malloc(sizeof(log_ctx_t));
    ctx->id = *id;
    ctx->level = level;
    ctx->filename = (filename != NULL) ? strdup(filename) : NULL;
    ctx->sockfd = sockfd;
    return ctx;
}

// Free resources associated with a logging context
void log_ctx_free(log_ctx_t* ctx) {
    if (ctx->filename != NULL)
        free(ctx->filename);
    free(ctx);
}

// Store multiple logging contexts in a linked list structure
typedef struct node {
    log_ctx_t* ctx;
    struct node* next;
} log_ctx_list_node;

log_ctx_list_node* log_ctx_list_new(log_ctx_t* ctx) {
    log_ctx_list_node* node = (log_ctx_list_node*)malloc(sizeof(log_ctx_list_node));
    node->ctx = ctx;
    node->next = NULL;
    return node;
}

// Store multiple logging contexts in a linked list structure
void log_ctx_list_free(log_ctx_list_node* head) {
    while (head != NULL) {
        log_ctx_list_node* temp = head;
        head = head->next;
        free(temp);
    }
}

// Implement error handling mechanism to track frequency and nature of errors
typedef struct {
    int count; // Error count
    char* msg; // Last error message
} error_info_t;

error_info_t* error_info_new() {
