    info->count = 0;
    info->msg = NULL;
    return info;
}

void error_info_free(error_info_t* info) {
    if (info->msg != NULL)
        free(info->msg);
    free(info);
}

// Support concurrent access by multiple threads
pthread_mutex_t log_ctx_list_lock = PTHREAD_MUTEX_INITIALIZER;

log_ctx_list_node* log_ctx_list_search(log_ctx_list_node* head, uuid_t id) {
    pthread_mutex_lock(&log_ctx_list_lock);
    log_ctx_list_node* curr = head;
    while (curr != NULL && memcmp(curr->ctx->id, id, 16) != 0)
        curr = curr->next;
    pthread_mutex_unlock(&log_ctx_list_lock);
    return curr;
}

// Securely clean up and disable logging contexts
void log_ctx_disable(log_ctx_t* ctx) {
    // Implement cleanup strategy here
}

