typedef struct {
    MAC_COMMAND_PDU command;
    MAC_DATA_PDU data;
} MAC_PDU;

int pdu_array_size = 0;
MAC_PDU** pdus = NULL;

void* pdus_lock = (void*)1; // dummy lock for demonstration purposes

void add_pdu(MAC_PDU* pdu) {
    pthread_mutex_lock((pthread_mutex_t*)pdus_lock);
    if (pdu_array_size == 0 || pdus[pdu_array_size-1]->data.size > pdu->data.size) {
        MAC_PDU** new_pdus = realloc(pdus, sizeof(MAC_PDU*) * (pdu_array_size + 2));
        if (!new_pdus) {
            // handle memory allocation failure
            printf("Memory allocation failed\n");
            pthread_mutex_unlock((pthread_mutex_t*)pdus_lock);
            return;
        }
        new_pdus[pdu_array_size] = pdu;
        pdus = new_pdus;
        pdu_array_size++;
    } else {
        // reallocate to maintain contiguous memory
        MAC_PDU** new_pdus = realloc(pdus, sizeof(MAC_PDU*) * (pdu_array_size + 1));
        if (!new_pdus) {
            // handle memory allocation failure
            printf("Memory allocation failed\n");
            pthread_mutex_unlock((pthread_mutex_t*)pdus_lock);
            return;
        }
        pdus = new_pdus;
    }
    pthread_mutex_unlock((pthread_mutex_t*)pdus_lock);
}

int get_pdu_count() {
    int count = 0;
    for (int i = 0; i < pdu_array_size; i++) {
        count++;
    }
    return count;
}

void update_pdu(int index, MAC_PDU* pdu) {
    pthread_mutex_lock((pthread_mutex_t*)pdus_lock);
    if (index >= 0 && index < pdu_array_size) {
        pdus[index] = pdu;
    } else {
        // handle invalid index
        printf("Invalid index\n");
    }
    pthread_mutex_unlock((pthread_mutex_t*)pdus_lock);
}

void free_pdus() {
    for (int i = 0; i < pdu_array_size; i++) {
        if (pdus[i]) {
            free(pdus[i]);
        }
    }
    free(pdus);
}

int main() {
    // initialize data structure
    pdus = malloc(sizeof(MAC_PDU*) * 2);
    pdu_array_size = 0;

    // add PDUs
    MAC_PDU* pdu1 = malloc(sizeof(MAC_PDU));
    // ... initialize pdu1 ...
    add_pdu(pdu1);

    MAC_PDU* pdu2 = malloc(sizeof(MAC_PDU));
    // ... initialize pdu2 ...
    add_pdu(pdu2);

    // retrieve PDU count
    int count = get_pdu_count();
    printf("Total PDUs: %d\n", count);

    // update PDU at index 0
    MAC_PDU* updated_pdu = malloc(sizeof(MAC_PDU));
    // ... initialize updated_pdu ...
    update_pdu(0, updated_pdu);

    free_pdus();

    return 0;
}

