typedef struct {
    char* metadata;
    char* payload;
    int timestamp;
} Packet;

Packet** packets = NULL;
int packet_count = 0;
int max_packets = 10; // initial capacity

void init_packet_array() {
    packets = (Packet**)malloc(max_packets * sizeof(Packet*));
}

void update_packet(int index, char* new_metadata, char* new_payload, int new_timestamp) {
    Packet* packet = &packets[index];
    free(packet->metadata);
    free(packet->payload);
    packet->metadata = malloc(strlen(new_metadata) + 1);
    strcpy(packet->metadata, new_metadata);
    packet->payload = malloc(strlen(new_payload) + 1);
    strcpy(packet->payload, new_payload);
    packet->timestamp = new_timestamp;
}

void add_packet(char* metadata, char* payload, int timestamp) {
    if (packet_count >= max_packets) {
        max_packets *= 2; // double the capacity
        packets = (Packet**)realloc(packets, max_packets * sizeof(Packet*));
    }
    Packet* packet = &packets[packet_count];
    packet->metadata = malloc(strlen(metadata) + 1);
    strcpy(packet->metadata, metadata);
    packet->payload = malloc(strlen(payload) + 1);
    strcpy(packet->payload, payload);
    packet->timestamp = timestamp;
    packet_count++;
}

int get_packet_count() {
    return packet_count;
}
