    int addSession(int userId, const std::string& username, const std::vector<std::string>& permissions) {
        if (userId <= 0) return -1; // Invalid user ID
        sessions[userId] = Session(userId, username);
        sessions[userId].permissions = permissions;
        sessions[userId].lastActive = std::time(nullptr);
        return userId;
    }

    void updateSession(int userId, const std::string& username, const std::vector<std::string>& permissions) {
        if (sessions.find(userId) == sessions.end()) return; // Session not found
        sessions[userId].username = username;
        sessions[userId].permissions = permissions;
        sessions[userId].lastActive = std::time(nullptr);
    }

    int getActiveSessionCount() {
        int count = 0;
        for (const auto& session : sessions) {
            if (session.second.lastActive > 0) count++;
        }
        return count;
    }

