    if(context->file == NULL) {
        printf("File opening failed\n");
        free(context);
        return NULL;
    }
    return context;
}

// Function to clean up a logging context and its associated resources
void cleanup_logging_context(LoggingContext* context) {
    fclose(context->file); // Close the log file
    free(context); // Free the memory allocated for the logging context
}

// Function to write logs to the file
void write_log(LoggingContext* context, const char* message) {
    if(context->log_level <= 1) { // Only write logs with level 0 or 1
        fprintf(context->file, "%s\n", message);
    }
}

