    LoggingContext* context = init_logging_context();
    if(context == NULL) {
        printf("Initialization failed\n");
        return -1;
    }

    for(int i = 0; i < 5; i++) {
        write_log(context, "This is a log message");
    }

    cleanup_logging_context(context);

    return 0;
}
