    void (*function)(void);
    void* params;
} CryptoAlgorithm;

CryptoAlgorithm* getAvailableAlgorithms() {
    CryptoAlgorithm* algorithms = NULL;
    // Get system's cryptographic capabilities dynamically
    int numHashFunctions = 0, numBlockCiphers = 0;
    // Initialize structures and populate arrays with available hash functions and block ciphers

    // Hash Functions
    char** hashFunctionNames = {"SHA1", "SHA256", "MD5"};
    void (**hashFunctions)[void] = {(void*)&hashFunctionImpl, (void*)&anotherHashFunction, (void*)&yetAnotherHashFunction};
    for (int i = 0; i < numHashFunctions; i++) {
        CryptoAlgorithm* algorithm = malloc(sizeof(CryptoAlgorithm));
        algorithm->name = strdup(hashFunctionNames[i]);
        algorithm->function = hashFunctions[i];
        algorithm->params = NULL;
        algorithms = realloc(algorithms, sizeof(CryptoAlgorithm*) * (i + 1));
        algorithms[i] = algorithm;
    }

    // Block Ciphers
    char** blockCipherNames = {"AES", "DES", "Blowfish"};
    void (**blockCiphers)[void] = {(void*)&aesImpl, (void*)&desImpl, (void*)&blowfishImpl};
    for (int i = numHashFunctions; i < numHashFunctions + numBlockCiphers; i++) {
        CryptoAlgorithm* algorithm = malloc(sizeof(CryptoAlgorithm));
        algorithm->name = strdup(blockCipherNames[i - numHashFunctions]);
        algorithm->function = blockCiphers[i - numHashFunctions];
        algorithm->params = NULL;
        algorithms = realloc(algorithms, sizeof(CryptoAlgorithm*) * (i + 1));
        algorithms[i] = algorithm;
    }

    return algorithms;
}

