    if ($length < 1 || !is_string($chars)) {
        return 'Invalid input';
    }
    $result = '';
    for ($i = 0; $i < $length; $i++) {
        $result .= $chars[mt_rand(0, strlen($chars) - 1)];
    }
    return $result;
}

function generateSalt() {
    return generateRandomString(16, 'abcdefghijklmnopqrstuvwxyzABCDEFGHIJKLMNOPQRSTUVWXYZ0123456789');
}

function hashPassword($password) {
    if (!is_string($password)) {
        return 'Invalid input';
    }
    $salt = generateSalt();
    $hash = password_hash($password . $salt, PASSWORD_DEFAULT);
    return array('hashed_password' => $hash, 'salt' => $salt);
}

function checkEntropy($string) {
    if (strlen($string) < 16) {
        return false;
    }
    for ($i = 0; $i < strlen($string); $i++) {
        if (!preg_match('/[a-zA-Z0-9]/', $string[$i])) {
            return false;
        }
    }
    return true;
}

function main() {
    $password = 'mysecretpassword';
    $result = hashPassword($password);
    var_dump($result);
}

main();

