    DIR* dir = opendir(dir_path);
    if (dir == NULL) {
        perror("Failed to open directory");
        return;
    }

    struct dirent* entry;
    while ((entry = readdir(dir)) != NULL) {
        if (!strcmp(entry->d_name, ".")) continue; // Ignore current and parent directories
        if (!strcmp(entry->d_name, "..")) continue;

        for (int i = 0; extensions[i]; i++) {
            if (strrchr(entry->d_name, '.') && strcmp(strrchr(entry->d_name, '.'), extensions[i])) continue;
            // Move the file to its corresponding subdirectory
            char* new_dir_path = malloc(strlen(dir_path) + strlen(extensions[i]) + 2);
            sprintf(new_dir_path, "%s/%s", dir_path, extensions[i]);
            if (rename(entry->d_name, new_dir_path) != 0) {
                perror("Failed to move file");
            }
            free(new_dir_path);
        }
    }

    closedir(dir);
}
