#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Session state structure
typedef struct {
    int id;
    char metadata[256];
    int64_t bytes_sent;
    int64_t packets_received;
} session_state;

// Hash table for storing sessions (using a combination of hash and linked list)
typedef struct {
    pthread_mutex_t lock; // Mutex for concurrent access
    size_t capacity; // Capacity of the hash table
    size_t count; // Number of active sessions
    session_state** states; // Array of session state pointers
} session_manager;

// Initialize session manager with given capacity and concurrency level
session_manager* init_session_manager(size_t capacity) {
    session_manager* manager = malloc(sizeof(session_manager));
    pthread_mutex_init(&manager->lock, NULL);
    manager->capacity = capacity;
    manager->count = 0;
    manager->states = calloc(capacity, sizeof(session_state*));
    return manager;
}

// Add a new session state to the hash table
int add_session(session_manager* manager, int id, const char* metadata) {
    pthread_mutex_lock(&manager->lock);
    size_t index = id % manager->capacity; // Hash function using modulo operation
    if (manager->states[index] == NULL || strcmp(manager->states[index]->metadata, metadata) != 0) {
        session_state* state = malloc(sizeof(session_state));
        state->id = id;
        strcpy(state->metadata, metadata);
        state->bytes_sent = 0;
        state->packets_received = 0;
        manager->states[index] = state;
    }
    pthread_mutex_unlock(&manager->lock);
    return 1; // Success
}

// Update the statistics for an existing session
int update_session(session_manager* manager, int id, int64_t bytes_sent, int64_t packets_received) {
    pthread_mutex_lock(&manager->lock);
    size_t index = id % manager->capacity;
    if (manager->states[index] != NULL && manager->states[index]->id == id) {
        manager->states[index]->bytes_sent += bytes_sent;
        manager->states[index]->packets_received += packets_received;
    }
    pthread_mutex_unlock(&manager->lock);
    return 1; // Success
}

// Get the total number of active sessions
int get_session_count(session_manager* manager) {
    pthread_mutex_lock(&manager->lock);
    int count = 0;
    for (size_t i = 0; i < manager->capacity; i++) {
        if (manager->states[i] != NULL)
            count++;
    }
    pthread_mutex_unlock(&manager->lock);
    return count;
}

// Clean up and free resources
void cleanup_session_manager(session_manager* manager) {
    for (size_t i = 0; i < manager->capacity; i++) {
        if (manager->states[i] != NULL)
            free(manager->states[i]);
    }
    free(manager->states);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}

int main() {
    // Initialize the session manager with a capacity of 1000
    session_manager* manager = init_session_manager(1000);

    // Add some sample sessions
    add_session(manager, 1, "Session 1");
    add_session(manager, 2, "Session 2");
    add_session(manager, 3, "Session 3");

    // Update the statistics for an existing session
    update_session(manager, 1, 1000, 500);

    // Get the total number of active sessions
    int count = get_session_count(manager);
    printf("Total active sessions: %d\n", count);

    // Clean up and free resources
    cleanup_session_manager(manager);

    return 0;
}
