    float traffic_statistics[100];
} SessionState;

SessionState* sessions = NULL;
int num_sessions = 0;
int capacity = 10; // initial capacity
pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

void add_session(SessionState* new_session) {
    pthread_mutex_lock(&lock);

    if (num_sessions >= capacity) {
        // handle memory allocation failure
        printf("Memory full. Cannot add new session.\n");
        return;
    }

    sessions[num_sessions] = *new_session;
    num_sessions++;

    pthread_mutex_unlock(&lock);
}

SessionState* get_session(int index) {
    pthread_mutex_lock(&lock);

    if (index >= num_sessions || index < 0) {
        // handle out-of-bounds access
        printf("Invalid session index.\n");
        return NULL;
    }

    SessionState* result = &sessions[index];
    pthread_mutex_unlock(&lock);

    return result;
}

int get_num_active_sessions() {
    pthread_mutex_lock(&lock);

    int result = num_sessions;
    pthread_mutex_unlock(&lock);

    return result;
}

void update_session(int index, SessionState* new_state) {
    pthread_mutex_lock(&lock);

    if (index >= num_sessions || index < 0) {
        // handle out-of-bounds access
        printf("Invalid session index.\n");
        return;
    }

    sessions[index] = *new_state;

    pthread_mutex_unlock(&lock);
}

void release_session(int index) {
    pthread_mutex_lock(&lock);

    if (index >= num_sessions || index < 0) {
        // handle out-of-bounds access
        printf("Invalid session index.\n");
        return;
    }

    for (int i = index; i < num_sessions - 1; i++) {
        sessions[i] = sessions[i + 1];
    }

    num_sessions--;

    pthread_mutex_unlock(&lock);
}

void* thread_func(void* arg) {
    int session_index = *(int*)arg;

    // simulate some work
    printf("Thread %d is working on session %d...\n", pthread_self(), session_index);

    return NULL;
}

