typedef struct {
    MAC_COMMAND_PDU command;
    MAC_DATA_PDU data;
} MAC_PDU;

typedef struct {
    size_t size;
    MAC_PDU* pdus;
    pthread_mutex_t lock;
} PDU_Array;

PDU_Array* pdu_array_init() {
    PDU_Array* array = malloc(sizeof(PDU_Array));
    if (!array) {
        return NULL;  // Handle memory allocation failure
    }
    array->size = 0;
    array->pdus = NULL;
    pthread_mutex_init(&array->lock, NULL);
    return array;
}

int pdu_array_add(PDU_Array* array, MAC_PDU* pdus) {
    size_t new_size = array->size + 1;
    MAC_PDU** new_pdus = realloc(array->pdus, sizeof(MAC_PDU*) * new_size);
    if (!new_pdus) {
        return -1;  // Handle memory allocation failure
    }
    array->pdus = new_pdus;
    pthread_mutex_lock(&array->lock);
    array->pdus[array->size] = pdus;
    array->size = new_size;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int pdu_array_update(PDU_Array* array, size_t index, MAC_PDU* pdus) {
    if (index >= array->size) {
        return -1;  // Index out of bounds
    }
    pthread_mutex_lock(&array->lock);
    array->pdus[index] = pdus;
    pthread_mutex_unlock(&array->lock);
    return 0;
}

int pdu_array_size(PDU_Array* array) {
    return array->size;
}
