    def __init__(self):
        if not self._generator:
            self._generator = random.Random(self.MersenneTwister())

    @staticmethod
    def MersenneTwister():
        return random.mtrand.TwistGen(19937)

    def get_random_number(self, min_val=0, max_val=1000):
        return int(self._generator.uniform(min_val, max_val))

def distributed_processing_pipeline(num_tasks):
    logging.basicConfig(level=logging.INFO)
    logger = logging.getLogger(__name__)

    # Create a pool of worker processes
    with Pool(processes=num_tasks) as pool:
        results = [pool.apply_async(process_task, args=(task_id,))
                   for task_id in range(num_tasks)]

        # Monitor the progress and check for failures
        while any(not result.ready() for result in results):
            time.sleep(1)
            logger.info(f"Processing {num_tasks} tasks... ({results.count(None)}/{len(results)} complete)")

        # Collect the results
        results = [result.get() if result.ready() else None
                   for result in results]

    return results

def process_task(task_id):
    try:
        # Simulate task processing
        random_number = RandomGenerator().get_random_number()
        time.sleep(random_number)
        logger.info(f"Task {task_id} completed successfully")
        return f"Task {task_id} succeeded"
    except Exception as e:
        logger.error(f"Error occurred while processing Task {task_id}: {str(e)}")
        return None

if __name__ == "__main__":
    num_tasks = 10
    results = distributed_processing_pipeline(num_tasks)
    for result in results:
        if result:
            print(result)

