#include <string.h>

typedef struct {
    uint32_t teid;
    uint32_t pdpContextId;
    uint8_t epsMobilityHeader[20];
} GTPv2CMESSAGE;

void manageGTPv2CMessages(int numMessages, GTPv2CMESSAGE* messages) {
    // Initialize sequence number and message type
    int seqNumber = 0;
    char messageType = 'A';

    for (int i = 0; i < numMessages; i++) {
        // Generate TEID, PDP Context ID, and EPS Mobility Header
        uint32_t teid = rand() % (1 << 24);
        uint32_t pdpContextId = rand() % (1 << 16);
        char epsMobilityHeader[20];

        for (int j = 0; j < 20; j++) {
            epsMobilityHeader[j] = (char)rand() % 256;
        }

        // Determine sequence number based on time and message type
        seqNumber++;
        if (seqNumber > 10) {
            messageType = 'B';
            seqNumber = 1;
        }

        messages[i].teid = teid;
        messages[i].pdpContextId = pdpContextId;
        memcpy(messages[i].epsMobilityHeader, epsMobilityHeader, 20);
    }
}

int main() {
    int numMessages = 10;
    GTPv2CMESSAGE* messages = (GTPv2CMESSAGE*)malloc(numMessages * sizeof(GTPv2CMESSAGE));

    manageGTPv2CMessages(numMessages, messages);

    for (int i = 0; i < numMessages; i++) {
        printf("TEID: %d\nPDP Context ID: %d\nEPS Mobility Header: ", messages[i].teid, messages[i].pdpContextId);
        for (int j = 0; j < 20; j++) {
            printf("%02x", messages[i].epsMobilityHeader[j]);
        }
        printf("\n");
    }

    free(messages);

    return 0;
}
