    for (int i = 0; i < N; i++) {
        if (messages[i].message_type != (i % 2 == 0) ? MESSAGE_TYPE_T(1) : MESSAGE_TYPE_T(2)) {
            printf("[MESSAGE %d: Message type mismatch]\n", i);
            return -1;
        }

        if (messages[i].mme_id != i) {
            printf("[MESSAGE %d: MME ID mismatch]\n", i);
            return -1;
        }

        if (!check_encryption(compression_flag)) {
            printf("[MESSAGE %d: Encryption failed]\n", i);
            return -1;
