// Function to calculate MD5 hash of a large file given its path
#include <md5.h>

char* calculate_md5_hash(const char* file_path) {
    FILE *file = fopen(file_path, "rb");
    if (file == NULL) {
        printf("Error opening file.\n");
        return NULL;
    }

    MD5_CTX ctx;
    unsigned char hash[16];
    unsigned char chunk[1024];

    // Initialize the MD5 context
    MD5_Init(&ctx);

    int64_t fileSize = ftell(file);
    fseek(file, 0, SEEK_SET);

    for (int i = 0; i < fileSize; i += 1024) {
        if ((fseek(file, i, SEEK_SET)) || (fread(chunk, 1, 1024, file) != 1024)) {
            printf("Error reading file.\n");
            fclose(file);
            return NULL;
        }

        MD5_Update(&ctx, chunk, 1024);
    }

    MD5_Final(&ctx, hash);

    char* md5_hash = (char*)malloc(33);
    for(int i = 0; i < 16; i++) {
        sprintf(md5_hash + (i * 2), "%02x", hash[i]);
    }
    fclose(file);
    return md5_hash;
}

// Function to generate a report summarizing the hashing process
void generate_report(const char* file_path, int64_t fileSize, float chunkSize, int errorCount) {
    printf("File Path: %s\n", file_path);
    printf("File Size: %lld bytes\n", fileSize);
    printf("Chunk Size: %.2f MB\n", (float)chunkSize / 1024 / 1024);
    printf("Error Count: %d\n", errorCount);

    if(errorCount > 0) {
        printf("Warning: File corruption detected.\n");
    }
}

int main() {
    // Example usage
    int num_messages = 10;
    bool encrypt = true;
    bool compress = false;

    LTE_MME_MESSAGE_T* messages = manage_messages(num_messages, encrypt, compress);

    for(int i = 0; i < num_messages; i++) {
        printf("Message Type: %d\n", messages[i].message_type);
        printf("MME ID: %s\n", messages[i].mme_id);
        printf("Mobile ID: %d\n", messages[i].mobile_id);
    }

    char* md5_hash = calculate_md5_hash("path/to/large/file.txt");

    if(md5_hash != NULL) {
        printf("MD5 Hash: %s\n", md5_hash);

        // Generate report summarizing the hashing process
        int64_t fileSize = 1024 * 1024 * 100; // 100 MB file size
        float chunkSize = (float)1024;
        int errorCount = 0;

        generate_report("path/to/large/file.txt", fileSize, chunkSize, errorCount);
    }

    return 0;
}
