void create_pdu_list(int N) {
    int i, j;
    LTE_ENB_INTERFACE_MME_PDU_T* p = NULL;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    // Initialize pool with available ENB IDs
    for (i = 0; i < ENB_ID_POOL_SIZE; i++) {
        enb_id_pool[i] = (void*)i;
    }

    for (i = 0; i < N; i++) {
        pthread_mutex_lock(&lock);

        // Generate MME ID and allocate PDU structure
        p = (LTE_ENB_INTERFACE_MME_PDU_T*)malloc(sizeof(LTE_ENB_INTERFACE_MME_PDU_T));
        if (p == NULL) {
            // Handle out-of-memory condition
            log_failure("Out of memory");
            pthread_mutex_unlock(&lock);
            return;
        }

        // Generate ENB ID and MME ID
        p->ENB_ID = *(uint32_t*)enb_id_pool[i % ENB_ID_POOL_SIZE];
        p->MME_ID = (uint32_t)i;

        // Randomly set CRCFLAG in MESSAGE_TYPE
        for (j = 0; j < CRCFLAG_SIZE; j++) {
            p->MESSAGE_TYPE[j] = rand() & 1;
        }

        pthread_mutex_unlock(&lock);
    }
}
