typedef enum {
    ESTABLISHED,
    CLOSED,
    TIME_WAIT,
} CONNECTION_STATUS;

typedef struct TCP_CONNECTION_STATE {
    unsigned long long CLIENT_ID;
    int SERVER_ID;
    CONNECTION_STATUS CONN_STATUS;
    int CRCFLAG;
    struct TCP_CONNECTION_STATE* next;
} TCP_CONNECTION_STATE;

TCP_CONNECTION_STATE* create_connection_states(int N) {
    srand(time(NULL));

    // Create a list of available server IDs
    int num_server_ids = 100; // Assuming at least this many potential server IDs are available
    int* server_ids = (int*)malloc(num_server_ids * sizeof(int));
    for (int i = 0; i < num_server_ids; i++) {
        server_ids[i] = i;
    }

    TCP_CONNECTION_STATE* head = NULL;
    TCP_CONNECTION_STATE** tail = &head;

    for (int i = 0; i < N; i++) {
        int client_id = rand() % ((1 << 64) - 1);
        int server_id_idx = rand() % num_server_ids;

        // Ensure the requested number of connection states does not exceed available server IDs
        if (i >= num_server_ids) {
            printf("Not enough server IDs to fulfill request. Skipping remaining connections.\n");
            break;
        }

        TCP_CONNECTION_STATE* new_state = (TCP_CONNECTION_STATE*)malloc(sizeof(TCP_CONNECTION_STATE));
        new_state->CLIENT_ID = client_id;
        new_state->SERVER_ID = server_ids[server_id_idx];
        new_state->CONN_STATUS = (CONNECTION_STATUS)(rand() % 3); // Randomly set CRCFLAG
        new_state->CRCFLAG = rand() & 1; // Randomly set CRCFLAG

        if (*tail) {
            (*tail)->next = new_state;
        } else {
            head = new_state;
        }

        *tail = &new_state->next;
    }

    // Validate connection states
    TCP_CONNECTION_STATE* current = head;
    while (current) {
        printf("Client ID: %llu, Server ID: %d, Status: %s, CRCFLAG: %d\n",
               current->CLIENT_ID, current->SERVER_ID,
               (current->CONN_STATUS == ESTABLISHED ? "ESTABLISHED" : 
                (current->CONN_STATUS == CLOSED ? "CLOSED" : "TIME_WAIT")),
               current->CRCFLAG);

        if (!current->next) {
            break;
        }
        current = current->next;
    }

    // Log any failures or discrepancies
    printf("Initialization complete. %d connection states created.\n", N - (i < 0 ? i : 0));

    return head;
}
