void init_pdu_list(struct pdu_list* list) {
    list->size = 0;
    pthread_mutex_init(&list->mutex, NULL);
}

int add_pdu(struct pdu_list* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->mutex);
    if (list->size >= MAX_PDU) {
        pthread_mutex_unlock(&list->mutex);
        return -1;
    }
    pdus[list->size] = pdu;
    list->size++;
    pthread_mutex_unlock(&list->mutex);
}

int update_pdu(struct pdu_list* list, int rnti, uint8_t crc_indication_rel8_tag) {
    pthread_mutex_lock(&list->mutex);
    for (int i = 0; i < list->size; i++) {
        if (pdus[i]->rnti == rnti) {
            pdus[i]->crc_indication_rel8_tag = crc_indication_rel8_tag;
            pthread_mutex_unlock(&list->mutex);
            return 1;
        }
    }
    pthread_mutex_unlock(&list->mutex);
    return -1;
}

int get_pdu_count(struct pdu_list* list) {
    pthread_mutex_lock(&list->mutex);
    int count = list->size;
    pthread_mutex_unlock(&list->mutex);
    return count;
}

void pause_and_resume(struct pdu_list* list, int pause) {
    if (pause) {
        // pause data collection
    } else {
        // resume data collection
    }
}
