} USER_ACTIVITY_LOG;

// Function to generate a random 64-bit integer
unsigned long long int generateRandomId() {
    return rand() * (RAND_MAX + 1ULL);
}

// Function to create the user activity log
void createActivityLog(int M, time_t startTimestamp, time_t endTimestamp) {
    // Initialize the linked list for storing activity logs
    USER_ACTIVITY_LOG* head = NULL;
    USER_ACTIVITY_LOG* tail = NULL;

    int i;
    for (i = 0; i < M; i++) {
        // Generate a random user ID and set the CRC flag randomly
        unsigned long long int userId = generateRandomId();
        int crcFlag = rand() % 2;

        // Set the session start time within the given timestamp range
        time_t sessionStartTime = (startTimestamp + (rand() % (endTimestamp - startTimestamp))) / 1000;
        if (sessionStartTime < startTimestamp) {
            sessionStartTime = startTimestamp;
        } else if (sessionStartTime > endTimestamp) {
            sessionStartTime = endTimestamp;
        }

        // Set the activity type randomly
        char* activityType = "LOGIN";
        if (rand() % 2) {
            activityType = "LOGOUT";
        } else {
            if (rand() % 3) {
                activityType = "PASSWORD_CHANGE";
            } else {
                activityType = "DATA_ACCESS";
            }
        }

        // Create a new user activity log and append it to the linked list
        USER_ACTIVITY_LOG* newNode = (USER_ACTIVITY_LOG*)malloc(sizeof(USER_ACTIVITY_LOG));
        newNode->userId = userId;
        newNode->sessionStartTime = sessionStartTime;
        strcpy(newNode->activityType, activityType);
        newNode->crcFlag = crcFlag;

        if (head == NULL) {
            head = newNode;
            tail = newNode;
        } else {
            tail->next = newNode;
            tail = newNode;
        }
    }

    // Validate the integrity of the created activity logs
    int i;
    for (i = 0; i < M; i++) {
        if (head == NULL || head->next == NULL) {
            printf("Error: Activity log creation failed.\n");
            return;
        } else {
