        USER_ACTIVITY_LOG* node = head;
        while (node) {
            printf("User ID: %llu, Session Start Time: %lu, Activity Type: %s, CRC Flag: %d\n", node->userId, node->sessionStartTime, node->activityType, node->crcFlag);
            node = node->next;
        }
    }
}

// Function to calculate the MD5 hash of a large file
int calculateMd5Hash(const char* filePath) {
    // Open the file in read mode
    FILE* file = fopen(filePath, "rb");
    if (file == NULL) {
        printf("Error: Unable to open file.\n");
        return -1;
    }

    // Calculate the MD5 hash of the file
    unsigned char md5Hash[16];
    FILE* ftemp = tmpfile();
    while (1) {
        char buffer[1024 * 8]; // Read in chunks
        int bytesRead = fread(buffer, 1, sizeof(buffer), file);
        if (ferror(file)) {
            printf("Error: Unable to read from file.\n");
            fclose(file);
            return -1;
        }
        if (!fseek(ftemp, ftell(ftemp), SEEK_END)) {
            fwrite(buffer, 1, bytesRead, ftemp);
        } else {
            printf("Error: Unable to seek to end of temporary file.\n");
            fclose(file);
            return -1;
        }
    }

    // Calculate the MD5 hash
    unsigned char* buffer = (unsigned char*)malloc(1024 * 8); // Read in chunks
    int bytesRead;
    while ((bytesRead = fread(buffer, 1, sizeof(buffer), ftemp)) > 0) {
        SHA256_CTX ctx;
        SHA256_Init(&ctx);
        for (int i = 0; i < bytesRead; i++) {
            SHA256_Update(&ctx, buffer + i, 1);
        }
        SHA256_Final(md5Hash, &ctx);
    }

    // Close the files and free memory
    fclose(file);
    fclose(ftemp);
    free(buffer);

    // Print the MD5 hash
    printf("MD5 Hash: ");
    int j;
    for (j = 0; j < 16; j++) {
        printf("%02x", md5Hash[j]);
    }
    printf("\n");

    return 0;
}

