#define NFAPI_CRC_INDICATION_PDU_T \
    struct { \
        uint16_t RX_UE_INFORMATION_TAG; \
        uint16_t RNTI; \
        uint8_t CRC_INDICATION_REL8_TAG[3]; \
    }

void init_crc_indication_pdus(int N, uint16_t* ue_identifiers, NFAPI_CRC_INDICATION_PDU_T** pdus) {
    if (!ue_identifiers || N <= 0) return;

    int unique_UEs = 0;
    for (int i = 0; i < N && i < sizeof(ue_identifiers) / sizeof(ue_identifiers[0]); i++) {
        uint16_t ue_id = ue_identifiers[i];
        if (!unique_UEs || memcmp(&ue_id, &ue_identifiers[unique_UEs - 1], sizeof(uint16_t)) != 0)
            unique_UEs++;
    }

    *pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < N && i < unique_UEs; i++) {
        (*pdus)[i].RX_UE_INFORMATION_TAG = i;
        (*pdus)[i].RNTI = ue_identifiers[i % unique_UEs];
        for (int j = 0; j < sizeof((*pdus)[i].CRC_INDICATION_REL8_TAG) / sizeof((*pdus)[i].CRC_INDICATION_REL8_TAG[0]); j++)
            (*pdus)[i].CRC_INDICATION_REL8_TAG[j] = (uint8_t)(rand() % 256);
    }

    if (N > unique_UEs) {
        printf("Warning: Not enough UE identifiers available for all PDUs.\n");
        N = unique_UEs;
    }

    // Validate integrity
    for (int i = 0; i < N; i++) {
        if (!(*pdus)[i].RX_UE_INFORMATION_TAG || !(*pdus)[i].RNTI) {
            printf("Error: PDU %d has uninitialized fields.\n", i);
            return;
        }
    }

    // Check for consistent data integrity
    uint16_t prev_RNTI = 0;
    for (int i = 0; i < N; i++) {
        if ((*pdus)[i].RNTI == prev_RNTI) {
            printf("Error: Duplicate RNTI found at PDU %d.\n", i);
            return;
        }
        prev_RNTI = (*pdus)[i].RNTI;
    }

    // Validate CRCFLAG
    for (int i = 0; i < N; i++) {
        uint8_t crcflag_sum = 0;
        for (int j = 0; j < sizeof((*pdus)[i].CRC_INDICATION_REL8_TAG) / sizeof((*pdus)[i].CRC_INDICATION_REL8_TAG[0]); j++)
            crcflag_sum += (*pdus)[i].CRC_INDICATION_REL8_TAG[j];
        if (crcflag_sum != rand()) {
            printf("Error: CRCFLAG at PDU %d is invalid.\n", i);
            return;
        }
    }
}

int main() {
    int N = 10;
    uint16_t ue_identifiers[] = {1, 2, 3, 4, 5};
    NFAPI_CRC_INDICATION_PDU_T* pdus;
    init_crc_indication_pdus(N, ue_identifiers, &pdus);
    // Use the created PDUs here
