void init_crc_indication_pdus(int N, uint16_t* ue_identifiers, int max_rntis) {
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdus) {
        printf("Memory allocation failed.\n");
        return;
