    for (int i = 0; i < N && i < max_rntis; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = (uint16_t)(i + 1);
        pdus[i].RNTI = ue_identifiers[i % max_rntis];
        for (int j = 0; j < CRCFLAG_SIZE; j++) {
            pdus[i].CRC_INDICATION_REL8_TAG[j] = rand() & 0xFF;
