Session_Context* initialize_session_context(int session_id, char *client_ip, char *server_ip, int port, int max_connections, int timeout_ms, int log_file) {
    Session_Context* session = (Session_Context*)malloc(sizeof(Session_Context));

    if (!session) return NULL; // Handle memory allocation error

    session->session_id = session_id;
    session->client_ip = client_ip;
    session->server_ip = server_ip;
    session->port = port;
    session->max_connections = max_connections;
    session->timeout_ms = timeout_ms;
    session->log_file = log_file;

    // Initialize connections array with NULL elements
    session->connections = (Connection_T**)malloc(max_connections * sizeof(Connection_T*));
    if (!session->connections) {
        free(session);
        return NULL; // Handle memory allocation error
    }
    for (int i = 0; i < max_connections; i++) {
        session->connections[i] = (Connection_T*)malloc(sizeof(Connection_T));
        if (!session->connections[i]) {
            for (int j = 0; j <= i; j++) {
                free(session->connections[j]);
            }
            free(session->connections);
            free(session);
            return NULL; // Handle memory allocation error
        }
    }

    session->connection_count = 0;
    session->last_connection_time = time(NULL);
    session->total_bandwidth_usage = 0;

    return session;
}
