    NR_RACH_PREAMBLE_REQUEST_T* rach_preambles = (NR_RACH_PREAMBLE_REQUEST_T*)malloc(sizeof(NR_RACH_PREAMBLE_REQUEST_T) * threshold);
    GTP_MESSAGE_T* gtp_messages = (GTP_MESSAGE_T*)malloc(sizeof(GTP_MESSAGE_T) * threshold);

    while (1) {
