            // Flush current list and initiate a new one
            flush_and_reinit();
            continue;
        }

        // Process incoming data packets
        process_packets();

        for (int i = 0; i < current_entry_count; i++) {
            rach_preambles[i].PRACH_CONFIG_INDEX = get_prach_config_index();
            rach_preambles[i].PREAMBLE_SEQUENCE = generate_preamble_sequence();
            rach_preambles[i].SRS资源配置 = allocate_srs_resources();

            gtp_messages[i].TEID = generate_teid();
            gtp_messages[i].PDP_Context_ID = get_pdp_context_id();
            gtp_messages[i].EPS_Mobility_Header = generate_eps_mobility_header();
        }

        // Ensure message integrity and reliability
        for (int i = 0; i < current_entry_count; i++) {
            if (!validate_gtp_message(gtp_messages[i])) {
                retry_limit--;
                if (retry_limit <= 0) {
                    handle_error_and_log("GTP message validation failed");
                    break;
                }
                continue;
