        }

        // Detect and handle duplicate messages
        for (int i = 0; i < current_entry_count; i++) {
            if (detect_duplicate_message(gtp_messages[i])) {
                handle_duplicate_message();
            }
        }

        // Process gtp messages
        process_gtp_messages(gtp_messages, current_entry_count);

        free(rach_preambles);
        free(gtp_messages);
    }
}

