function createRLCPDUs(N, PDCP_SN_array, config, transmissionDirection, performanceTuningFlag, timeoutValue) {
  const rlcPduList = new LinkedList();
  let pdcpsnIndex = 0;
  let pduCount = 0;

  for (let i = 0; i < N; i++) {
    const pdcpSn = PDCP_SN_array[pdcpsnIndex];
    if (!pdcpSn) {
      // handle edge case where PDCP_SN array is exhausted
      break;
    }

    pdcpsnIndex++;

    let pdu;
    if (transmissionDirection) {
      // downlink transmission
      pdu = new RLC_AM_ACK_PDU(pdcpSn, generateAckSequenceNumber(), generateRandomPayload());
    } else {
      // uplink transmission
      pdu = new RLC_AM_DATA_PDU(pdcpSn, generateRandomPayload());
    }

    rlcPduList.append(pdu);
    pduCount++;
  }

  return { rlcPduList, pduCount };
}

function extractBibleBookNames(text) {
  const BOOK_NAME_REGEXP = /\b(Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1Samuel|2Samuel|1Kings|2Kings|1Chronicles|2Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|SongOfSolomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Zephaniah|Haggai|Zechariah|Malachi)\b/gi;
  const CHAPTER_NAME_REGEXP = /\b(Genesis|Exodus|Leviticus|Numbers|Deuteronomy|Joshua|Judges|Ruth|1Samuel|2Samuel|1Kings|2Kings|1Chronicles|2Chronicles|Ezra|Nehemiah|Esther|Job|Psalms|Proverbs|Ecclesiastes|SongOfSolomon|Isaiah|Jeremiah|Lamentations|Ezekiel|Daniel|Hosea|Joel|Amos|Obadiah|Jonah|Micah|Zephaniah|Haggai|Zechariah|Malachi)\.?\s*(\d+|\*)/g;

  let bookNames = [];
  let chapterMatches = CHAPTER_NAME_REGEXP.exec(text);
  while (chapterMatches) {
    const chapterName = chapterMatches[1];
    const bookName = BOOK_NAME_REGEXP.exec(chapterName)[1];
    if (!bookNames.includes(bookName)) {
      bookNames.push(bookName);
    }
    chapterMatches = CHAPTER_NAME_REGEXP.exec(text);
  }

  return bookNames;
}
