void create_pdu_list(int N, LTE_ENB_INTERFACE_MME_PDU_T** list) {
    if (N <= 0) return; // Handle edge case where N is zero
    if (!list || !*list) *list = NULL; // Initialize list pointer

    int available_entities = 10; // Example of a limited set of ENB_ID identifiers
    int* enb_ids = (int*)malloc(sizeof(int) * available_entities);
    for (int i = 0; i < available_entities; ++i) {
        enb_ids[i] = i;
    }

    *list = (LTE_ENB_INTERFACE_MME_PDU_T*)calloc(N, sizeof(LTE_ENB_INTERFACE_MME_PDU_T));
    if (!*list) return;

    for (int i = 0; i < N; ++i) {
        (*list)[i].MME_ID = rand() % 4294967296; // Randomly generate MME_ID
        int enb_id = rand() % available_entities;
        while (enb_ids[enb_id] == 0 || i > 0 && enb_ids[enb_id] != (*list)[i-1].ENB_ID) {
            enb_id = rand() % available_entities; // Re-roll for unavailable or duplicate IDs
        }
        (*list)[i].ENB_ID = enb_ids[enb_id];
        srand(time(NULL)); // Reset random seed for each PDU
        (*list)[i].MESSAGE_TYPE = (int)rand() & 0x7fffffff; // Randomly set MESSAGE_TYPE with CRCFLAG
    }
}

