int create_pdu_list(int N, LTE_ENB_INTERFACE_MME_PDU_T** pdux, size_t n_entites[]) {
    if (N < 0) return -1; // Invalid input
    if (!n_entites || !n_entites[0]) return -2; // Invalid input

    srand(time(NULL)); // Seed random number generator

    LTE_ENB_INTERFACE_MME_PDU_T* pdu_list = NULL;
    int remaining_entities = N;

    for (int i = 0; i < N && i < n_entites[0]; i++) {
        LTE_ENB_INTERFACE_MME_PDU_T* pdux_new = 
            (LTE_ENB_INTERFACE_MME_PDU_T*)malloc(sizeof(LTE_ENB_INTERFACE_MME_PDU_T));

        if (!pdux_new) {
            log_failure("Memory allocation failed", __LINE__);
            return -3; // Memory allocation failure
        }

        pdux_new->MME_ID = (unsigned int)i;
        pdux_new->ENB_ID = n_entites[i % n_entites[0]];
        pdux_new->MESSAGE_TYPE = rand() % 3;

        if (pdu_list) {
            pdux_new->next = pdu_list;
        } else {
            pdux_new->next = NULL;
        }

        pdu_list = pdux_new;

        remaining_entities--;
    }

    *pdux = pdu_list;
    return N - remaining_entities; // Number of PDUs actually created
}

void* log_failure(const char* message, int line) {
    // Implement logging mechanism here
    printf("[ERROR] %s at line %d\n", message, line);
    return NULL;
