    uint8_t MESSAGE_TYPE;
    uint32_t MOBILE_ID;
} LTE_MME_MESSAGE_T;

// Function to generate random MOBILE_ID
uint32_t generate_mobile_id(uint32_t *id_list, int list_size) {
    // Randomly select a unique MOBILE_ID from the provided list
    int i = rand() % list_size;
    return id_list[i];
}

// Function to create collections of LTE_ENB_INTERFACE_MME_PDU_T and LTE_MME_MESSAGE_T structures
LTE_ENB_INTERFACE_MME_PDU_T* generate_pdu_collection(int pdu_count, uint32_t *id_list, int list_size) {
    LTE_ENB_INTERFACE_MME_PDU_T *pdus = (LTE_ENB_INTERFACE_MME_PDU_T*)malloc(pdu_count * sizeof(LTE_ENB_INTERFACE_MME_PDU_T));

    // Initialize and randomize CRCFLAG in each MESSAGE_TYPE
    for(int i = 0; i < pdu_count; i++) {
        pdus[i].MESSAGE_TYPE.CRCFLAG = rand() % 2;
    }

    return pdus;
}

LTE_MME_MESSAGE_T* generate_message_collection(int message_count, uint32_t *id_list, int list_size) {
    LTE_MME_MESSAGE_T *messages = (LTE_MME_MESSAGE_T*)malloc(message_count * sizeof(LTE_MME_MESSAGE_T));

    // Randomly select MOBILE_ID from the provided list
    for(int i = 0; i < message_count; i++) {
        messages[i].MOBILE_ID = generate_mobile_id(id_list, list_size);
    }

    return messages;
}

// Function to manage concurrent operations and logging
