// Function to calculate the MD5 hash of a file
void md5_hash_file(char* filename, char* output_filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) {
        printf("Error: unable to open file '%s'\n", filename);
        return;
    }

    // Calculate MD5 hash in chunks to minimize memory usage
    unsigned char buffer[16384];
    int chunk_size;
    FILE* output_file = fopen(output_filename, "wb");
    if (output_file == NULL) {
        printf("Error: unable to open file '%s'\n", output_filename);
        fclose(file);
        return;
    }

    while ((chunk_size = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        // Calculate MD5 hash for the chunk
        unsigned char* hash_bytes = (unsigned char*)malloc(16);
        // ...
        fwrite(hash_bytes, 1, 16, output_file); // Write the hash to the output file
    }

    fclose(file);
    fclose(output_file);
}

