#include <time.h>

typedef struct {
    uint32_t MME_ID;
    uint16_t ENB_ID;
    uint8_t MESSAGE_TYPE[CRCFLAG_SIZE];
} LTE_ENB_INTERFACE_MME_PDU_T;

// Custom CRC calculation function
uint8_t crc_calc(uint8_t* data, size_t len) {
    uint8_t crc = 0xFF;
    for (size_t i = 0; i < len; i++) {
        crc = (crc >> 4) ^ (crc & 1);
        crc ^= data[i];
    }
    return crc;
}

void create_pdu_list(int N, int E, LTE_ENB_INTERFACE_MME_PDU_T** pdu_list) {
    // Initialize available ENB_ID identifiers
    uint16_t* enb_ids = (uint16_t*)malloc(E * sizeof(uint16_t));
    for (int i = 0; i < E; i++) {
        enb_ids[i] = i;
    }

    // Create and populate the list of PDUs
    int pdu_count = N;
    int max_enb_id_index = -1;
    LTE_ENB_INTERFACE_MME_PDU_T** puds = (LTE_ENB_INTERFACE_MME_PDU_T**)malloc(pdu_count * sizeof(LTE_ENB_INTERFACE_MME_PDU_T*));
    for (int i = 0; i < pdu_count && max_enb_id_index < E - 1; i++) {
        // Generate MME_ID and ENB_ID
        uint32_t mme_id = rand() % ((1 << 32) - 1);
        int enb_id_index;
        do {
            enb_id_index = rand() % E;
            max_enb_id_index = (int)(rand() % (E - enb_id_index - 1));
            if (enb_id_index + max_enb_id_index < E) break;
        } while (1);
        uint16_t enb_id = enb_ids[enb_id_index];
        for (int j = 0; j < max_enb_id_index; j++) {
            enb_ids[j] = enb_ids[j + 1];
        }

        // Initialize MESSAGE_TYPE with CRCFLAG
        LTE_ENB_INTERFACE_MME_PDU_T* pdu = (LTE_ENB_INTERFACE_MME_PDU_T*)malloc(sizeof(LTE_ENB_INTERFACE_MME_PDU_T));
        pdu->MME_ID = mme_id;
        pdu->ENB_ID = enb_id;
        for (int j = 0; j < CRCFLAG_SIZE; j++) {
            pdu->MESSAGE_TYPE[j] = crc_calc((uint8_t*)&pdu->MME_ID, sizeof(uint32_t));
        }

        puds[i] = pdu;
    }

    *pdu_list = puds;
}
