typedef struct {
    uint16_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    struct {
        uint8_t CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void init_PDUs(int N, int *RNTI_list_size, unsigned short **RNTI_list, int prioritize_speed, FILE *log_file) {
    NFAPI_CRC_INDICATION_PDU_T *pdus = NULL;

    if (N < 0) {
        fprintf(log_file, "Error: Invalid number of PDUs. Returning 0.\n");
        return;
    }

    pdus = malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdus && N > 0) {
        fprintf(log_file, "Error: Memory allocation failed for %d PDUs.\n", N);
        return;
    }

    // Initialize PDUs
    for (int i = 0; i < N; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = (uint16_t)rand();

        if (*RNTI_list_size <= 0) {
            fprintf(log_file, "Warning: No RNTI list available. Skipping RNTI initialization for PDU %d.\n", i);
            pdus[i].RNTI = 0;
        } else {
            int idx = rand() % *RNTI_list_size;
            pdus[i].RNTI = (*RNTI_list)[idx];

            // Remove used RNTI from the list
            for (int j = idx; j < *RNTI_list_size - 1; j++) {
                (*RNTI_list)[j] = (*RNTI_list)[j + 1];
            }
            (*RNTI_list_size)--;
        }

        pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (uint8_t)rand() & 0x01; // Randomly set CRCFLAG

        if (prioritize_speed) {
            // Perform minimal validation for speed optimization
            if (!pdus[i].RX_UE_INFORMATION_TAG || !pdus[i].RNTI || pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG > 1) {
                fprintf(log_file, "Error: PDU %d initialization failed. Returning NULL.\n", i);
                return;
            }
        } else {
            // Perform extensive validation for memory efficiency
            if (!pdus[i].RX_UE_INFORMATION_TAG || pdus[i].RNTI > 0xFFFF || pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG > 1) {
                fprintf(log_file, "Error: PDU %d initialization failed. Returning NULL.\n", i);
                return;
            }
        }
    }

    if (prioritize_speed) {
        // Record timestamp and number of PDUs for logging
        time_t now = time(NULL);
        fprintf(log_file, "PDU initialization completed in %.2fs with %d PDUs.\n", difftime(now, start_time), N);
    } else {
        // Validate entire array to ensure integrity
        for (int i = 0; i < N; i++) {
            if (!pdus[i].RX_UE_INFORMATION_TAG || !pdus[i].RNTI || pdus[i].CRC_INDICATION_REL8_TAG.CRCFLAG > 1) {
                fprintf(log_file, "Error: PDU %d initialization failed. Returning NULL.\n", i);
                return;
            }
        }

        // Record timestamp and number of PDUs for logging
        time_t now = time(NULL);
        fprintf(log_file, "PDU initialization completed in %.2fs with %d PDUs.\n", difftime(now, start_time), N);
    }

    free(pdus);
}

int main() {
    // Example usage:
    int RNTI_list[] = {1, 2, 3, 4, 5};
    int RNTI_list_size = sizeof(RNTI_list) / sizeof(RNTI_list[0]);
    FILE *log_file = fopen("pdu_log.txt", "w");

    init_PDUs(10, &RNTI_list_size, &RNTI_list, 1, log_file);

    return 0;
}
