int lteUplinkTxFrameInfo_AddChannel(LTE_Uplink_TxFrameInfo_T* info, LTE_TransportChannelConfig_T* channel) {
    int i = 0;
    if (!info->transportChannels) {
        info->transportChannels = (struct LTE_TransportChannelConfig_T**)malloc(sizeof(struct LTE_TransportChannelConfig_T*) * 1);
        info->transportChannels[0] = channel;
    } else {
        while (i < info->ueIndex && i < sizeof(info->transportChannels) / sizeof(*info->transportChannels)) {
            if (!info->transportChannels[i]) {
                info->transportChannels[i] = channel;
                return 1;
            }
            i++;
        }
    }
    return 0;
}

int lteUplinkTxFrameInfo_Update(LTE_Uplink_TxFrameInfo_T* info, int ueIndex, float preambleRsrp) {
    if (ueIndex >= 0 && ueIndex < info->ueIndex) {
        info->transportChannels[ueIndex] = NULL;
        return 1;
    }
    info->ueIndex = ueIndex;
    info->preambleRsrp = preambleRsrp;
    return 0;
}

void lteUplinkTxFrameInfo_Free(LTE_Uplink_TxFrameInfo_T* info) {
    int i = 0;
    while (i < info->ueIndex) {
        if (info->transportChannels[i]) {
            free(info->transportChannels[i]);
        }
        i++;
    }
    free(info->transportChannels);
