#include <stdio.h>
#include <stdlib.h>
#include <string.h>

// Define the LTE_Uplink_TxFrameInfo_T structure
typedef struct {
    int UE_INDEX;
    int PREAMBLE_RSRP;
    struct LTE_TransportChannelConfig_T** channels;
} LTE_Uplink_TxFrameInfo_T;

// Define the LTE_TransportChannelConfig_T structure (assuming this is provided)
typedef struct {
    // fields...
} LTE_TransportChannelConfig_T;

// Structure to hold collection of LTE_Uplink_TxFrameInfo_T
typedef struct {
    int size;
    LTE_Uplink_TxFrameInfo_T* frames;
    pthread_mutex_t mutex;
} LTE_Uplink_FrameCollection_T;

// Initialize and manage the LTE_Uplink_FrameCollection_T
LTE_Uplink_FrameCollection_T* initUplinkFrameCollection() {
    LTE_Uplink_FrameCollection_T* collection = (LTE_Uplink_FrameCollection_T*) malloc(sizeof(LTE_Uplink_FrameCollection_T));
    if (!collection) return NULL;
    pthread_mutex_init(&collection->mutex, NULL);
    collection->size = 0;
    collection->frames = NULL;
    return collection;
}

// Add a new entry to the LTE_Uplink_FrameCollection_T
int addUplinkFrame(LTE_Uplink_FrameCollection_T* collection, int UE_INDEX, int PREAMBLE_RSRP) {
    if (!collection) return -1;

    // dynamically allocate memory for channels array
    int num_channels = 0; // assume default number of channels
    LTE_TransportChannelConfig_T** channels = (LTE_TransportChannelConfig_T**) malloc(num_channels * sizeof(LTE_TransportChannelConfig_T*));
    if (!channels) return -1;

    // initialize new frame entry
    LTE_Uplink_TxFrameInfo_T* new_frame = (LTE_Uplink_TxFrameInfo_T*) malloc(sizeof(LTE_Uplink_TxFrameInfo_T));
    if (!new_frame) {
        free(channels);
        return -1;
    }
    new_frame->UE_INDEX = UE_INDEX;
    new_frame->PREAMBLE_RSRP = PREAMBLE_RSRP;

    // add the new frame to the collection
    pthread_mutex_lock(&collection->mutex);
    if (collection->size == 0) {
        collection->frames = (LTE_Uplink_TxFrameInfo_T*) malloc(sizeof(LTE_Uplink_TxFrameInfo_T));
        if (!collection->frames) {
            pthread_mutex_unlock(&collection->mutex);
            return -1;
        }
        collection->frames[0] = *new_frame;
        collection->size++;
    } else {
        LTE_Uplink_TxFrameInfo_T* frames = (LTE_Uplink_TxFrameInfo_T*) realloc(collection->frames, (collection->size + 1) * sizeof(LTE_Uplink_TxFrameInfo_T));
        if (!frames) {
            pthread_mutex_unlock(&collection->mutex);
            return -1;
        }
        frames[collection->size] = *new_frame;
        collection->frames = frames;
        collection->size++;
    }

    // update channels array for new frame
    if (num_channels == 0) num_channels++; // always at least one channel

    pthread_mutex_unlock(&collection->mutex);
    return 0;
}

// Update an existing entry in the LTE_Uplink_FrameCollection_T
int updateUplinkFrame(LTE_Uplink_FrameCollection_T* collection, int UE_INDEX, int PREAMBLE_RSRP) {
    if (!collection) return -1;

    pthread_mutex_lock(&collection->mutex);
    for (int i = 0; i < collection->size; i++) {
        if (collection->frames[i].UE_INDEX == UE_INDEX) {
            // update the frame entry
            collection->frames[i].PREAMBLE_RSRP = PREAMBLE_RSRP;
            pthread_mutex_unlock(&collection->mutex);
            return 0;
        }
    }

    pthread_mutex_unlock(&collection->mutex);
    return -1; // not found
}

// Free the LTE_Uplink_FrameCollection_T resources when destroyed
void freeUplinkFrameCollection(LTE_Uplink_FrameCollection_T* collection) {
    if (!collection) return;

    pthread_mutex_lock(&collection->mutex);
    for (int i = 0; i < collection->size; i++) {
        // free channels array and frame entry
        for (int j = 0; j < num_channels; j++) {
            free(collection->frames[i].channels[j]);
        }
        free(collection->frames[i].channels);
        free(collection->frames[i]);
    }
    pthread_mutex_unlock(&collection->mutex);

    // free collection itself
    free(collection->frames);
    free(collection);
}

// Get the total number of frames in the LTE_Uplink_FrameCollection_T
int getUplinkFrameCount(LTE_Uplink_FrameCollection_T* collection) {
    if (!collection) return -1;
    pthread_mutex_lock(&collection->mutex);
    int count = collection->size;
    pthread_mutex_unlock(&collection->mutex);
    return count;
}
