// Initialize the collection and its management structures
void* manageLTEFrames() {
    // Create a thread-safe data structure to hold all frames
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;
    int totalFrames = 0;
    LTE_Uplink_TxFrameInfo_T** frames = NULL;

    return (void*) (&frames);
}

// Add a new frame with given details to the collection
int addLTEFrame(LTE_Uplink_TxFrameInfo_T* frame) {
    pthread_mutex_lock(&mutex);
    // Create a new entry for the frame and add it to the collection
    LTE_Uplink_TxFrameInfo_T** newFrames = (LTE_Uplink_TxFrameInfo_T**) realloc(frames, sizeof(LTE_Uplink_TxFrameInfo_T*) * (totalFrames + 1));
    newFrames[totalFrames] = frame;
    frames = newFrames;
    totalFrames++;
    pthread_mutex_unlock(&mutex);
}

// Update an existing frame in the collection
int updateLTEFrame(int UE_INDEX, float PREAMBLE_RSRP) {
    pthread_mutex_lock(&mutex);
    for (int i = 0; i < totalFrames; i++) {
        if (frames[i]->UE_INDEX == UE_INDEX) {
            frames[i]->PREAMBLE_RSRP = PREAMBLE_RSRP;
            break;
        }
    }
    pthread_mutex_unlock(&mutex);
}

// Free resources when the collection is destroyed
void freeLTEFrames() {
    for (int i = 0; i < totalFrames; i++) {
        // Dynamically allocated arrays should be freed here
        free(frames[i]->transportChannels);
        free(frames[i]);
    }
    free(frames);
}

// Get the current number of frames in the collection
int getLTEFrameCount() {
    return totalFrames;
}
