LTE_ENB_INTERFACE_MME_PDU_T* create_PDUs(int N, int E, int L, int MAX_MEMORY_USAGE) {
    // Calculate memory needed for PDUs
    int total_memory_needed = sizeof(LTE_ENB_INTERFACE_MME_PDU_T) * N;

    if (total_memory_needed > MAX_MEMORY_USAGE * 1024) {
        printf("Error: Requested PDUs exceed maximum allowed memory usage.\n");
        return NULL;
    }

    // Create array of PDUs
    LTE_ENB_INTERFACE_MME_PDU_T* pdus = malloc(total_memory_needed);
    if (pdus == NULL) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    // Initialize ENB_ID list
    uint16_t* enb_ids = malloc(E * sizeof(uint16_t));
    for (int i = 0; i < E; i++) {
        enb_ids[i] = rand() % (1 << 15);
    }

    int available_enb_ids = E;

    // Create PDUs
    for (int i = 0; i < N && available_enb_ids > 0; i++) {
        pdus[i].MME_ID = rand() % (1 << 31);
        pdus[i].ENB_ID = enb_ids[rand() % available_enb_ids];
        available_enb_ids--;

        // Set CRCFLAG randomly
        srand((unsigned)time(NULL));
        pdus[i].CRCFLAG = rand() % 256;

        // Initialize MESSAGE_TYPE
        char* message_type = malloc(L);
        for (int j = 0; j < L - 1; j++) {
            message_type[j] = 'A' + rand() % 26;
        }
        message_type[L - 1] = '\0';

        pdus[i].MESSAGE_TYPE = message_type;
    }

    free(enb_ids);

    return pdus;
}

void validate_PDUs(LTE_ENB_INTERFACE_MME_PDU_T* pdus, int N) {
    for (int i = 0; i < N; i++) {
        if (!pdus[i].MESSAGE_TYPE || strlen(pdus[i].MESSAGE_TYPE) > L - 1) {
            printf("Error: PDU %d has invalid MESSAGE_TYPE.\n", i);
        }

        // Check CRCFLAG
        if (pdus[i].CRCFLAG < 0 || pdus[i].CRCFLAG > 255) {
            printf("Error: PDU %d has invalid CRCFLAG.\n", i);
        }
    }
}

// Custom CRC calculation function
uint8_t crc_calculate(uint8_t* data, int length) {
    uint8_t crc = 0;

    for (int i = 0; i < length; i++) {
        crc = (crc << 1) | (data[i] & 1);

        if (data[i] & 2) {
            crc ^= 0x07;
        }

        if (i > 0 && (i % 4 == 3 || i == length - 1)) {
            crc = (crc >> 4) ^ (crc << 4);

            if ((crc & 0xF000) == 0) {
                crc |= 0x100;
            }
        }
    }

    return crc;
}

int main() {
    int N = 10, E = 100, L = 1024, MAX_MEMORY_USAGE = 2048;

    LTE_ENB_INTERFACE_MME_PDU_T* pdus = create_PDUs(N, E, L, MAX_MEMORY_USAGE);

    if (pdus == NULL) {
        return 1;
    }

    validate_PDUs(pdus, N);

    free(pdus);

    return 0;
}
