```c
#include <stdio.h>
#include <stdlib.h>
#include <stdint.h>

typedef struct LTE_ENB_INTERFACE_MME_PDU_T {
    uint32_t MME_ID;
    uint16_t ENB_ID;
    uint8_t MESSAGE_TYPE;
    uint8_t QoS_CLASS_IDENTIFIER;
} PDU_T;

uint16_t custom_CRC(uint8_t* data, int len) {
    uint16_t crc = 0xFFFF;
    for (int i = 0; i < len; i++) {
        crc = (crc >> 4) ^ ((crc & 0xF) << 12 | (data[i] >> 4));
        crc ^= data[i];
    }
    return crc;
}

void manage_PDU_list(int N, int E, int M, int Q, PDU_T** list, int* len) {
    if (N > E || N > M || Q < 0x00 || Q > 0xFF) {
        printf("Invalid input. Exiting.\n");
        return;
    }

    *len = N;

    for (int i = 0; i < N; i++) {
        PDU_T* pdu = (PDU_T*)malloc(sizeof(PDU_T));

        if (i >= M) {
            pdu->MME_ID = (uint32_t)-1;
        } else {
            pdu->MME_ID = (uint32_t)(rand() % ((1 << 31) - 1));
        }

        pdu->ENB_ID = rand() % E;

        if (pdu->ENB_ID == 0) {
            // Handle duplicate ENB_ID
            for (int j = i; j >= 0; j--) {
                if (list[j]->ENB_ID != 0) {
                    pdu->ENB_ID = list[j]->ENB_ID;
                    break;
                }
            }
        }

        pdu->MESSAGE_TYPE = (uint8_t)(rand() % ((1 << 7) - 1));
        pdu->QoS_CLASS_IDENTIFIER = Q;

        pdu->CRCFLAG = custom_CRC((uint8_t*)&pdu, sizeof(PDU_T));

        list[i] = pdu;
    }
}

int main() {
    int N = 10; // Number of PDUs
    int E = 256; // Maximum number of unique ENB_ID identifiers
    int M = 32; // Maximum number of MME entities supported
    int Q = 0x20; // Minimum QoS class identifier required

    PDU_T* list = (PDU_T*)malloc(N * sizeof(PDU_T));
    int len;

