    }

    // Initialize the list of created PDUs and its count
    LTE_ENB_INTERFACE_MME_PDU_T **pdus_list_head = NULL;
    int current_pdu_count = 0;

    // Create the requested number of PDUs
    for (int i = 0; i < N; i++) {
        if (current_pdu_count >= *pdu_count) break;

        LTE_ENB_INTERFACE_MME_PDU_T *new_pdu;
        if (!pdus_list_head) {
            new_pdu = (LTE_ENB_INTERFACE_MME_PDU_T *)malloc(sizeof(LTE_ENB_INTERFACE_MME_PDU_T));
            pdus_list_head = &new_pdu;
