// Function to perform DNS resolution and caching
char* dns_resolution(const char* hostname) {
    // Initialize cache and node IDs
    static uint32_t node_id = 0;
    static pthread_mutex_t cache_lock = PTHREAD_MUTEX_INITIALIZER;

    // Perform DNS lookup using standard library functions
    struct hostent* host_entry = gethostbyname(hostname);
    if (!host_entry) {
        // Handle error and return NULL for non-existent hostname
        return NULL;
    }

    // Extract IP address from host entry
    char* ip_address = (char*)malloc(strlen((char*)host_entry->h_addr) + 1);
    strcpy(ip_address, (char*)host_entry->h_addr);

    // Cache the resolved IP address and node ID for future lookups
    pthread_mutex_lock(&cache_lock);
    static uint64_t cache[256] = {0};
    cache[node_id % 256] = (uint64_t)ip_address;
    pthread_mutex_unlock(&cache_lock);

    return ip_address;
}

// Function to integrate OpenSSL library for cryptographic operations
void* crypto_operation(const char* input, int option) {
    // Initialize OpenSSL library
    EVP_CIPHER_CTX* ctx = EVP_CIPHER_CTX_new();
    if (!ctx) {
        // Handle error and return NULL on failure
        return NULL;
    }

    // Perform specified operation based on command-line option
    switch (option) {
        case 1:
            // Encrypt input string using AES-256-CBC
            unsigned char* encrypted = (unsigned char*)malloc(strlen(input) + 16);
            AES_cbc_encrypt((const unsigned char*)input, encrypted, strlen(input), EVP_aes_256_cbc(), NULL, 0);
            break;
        case 2:
            // Decrypt input string using AES-256-CBC
            unsigned char* decrypted = (unsigned char*)malloc(strlen(input) + 16);
