XmlElement* parse_xml(xmlDoc *doc, const char *xpath_expression) {
    XmlElement *element = malloc(sizeof(XmlElement));
    element->doc = doc;
    element->node = xmlXPathEval(doc, xpath_expression);
    if (element->node == NULL || xmlNodeGetChildren(element->node) == NULL) {
        free(element);
        return NULL;
    }
