    int num_pdis = (N <= RNTI_POOL_SIZE) ? N : RNTI_POOL_SIZE;
    NFAPI_CRC_INDICATION_PDU_T* pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_pdis * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize the PDUs
    for (int i = 0; i < num_pdis; i++) {
        pdus[i].RX_UE_INFORMATION_TAG = generate_random_tag();
        pdus[i].RNTI = rnti_pool[i % RNTI_POOL_SIZE]; // ensure unique and recycled RNTIs
        pdus[i].CRC_INDICATION_REL8_TAG = (uint32_t)(rand() % 256); // simulate random CRC flags
    }

    return pdus;
}

// Validate the initialized PDUs
bool validate_pdu_array(NFAPI_CRC_INDICATION_PDU_T* pdus) {
    for (int i = 0; i < N; i++) {
        if (!pdus[i].RX_UE_INFORMATION_TAG || !pdus[i].RNTI || pdus[i].CRCFLAG != CRCFLAG_MASK) {
            return false;
        }
    }
    return true;
}
