void init_tcp_segments(int N, SN_POOL* sn_pool, uint8_t* buffer, int timeout_ms, int mss, uint8_t cid) {
    // Initialize TCP header structure
    tcp_header_t* headers = (tcp_header_t*)malloc(N * sizeof(tcp_header_t));

    for (int i = 0; i < N; i++) {
        headers[i].src_port = cid;
        headers[i].dst_port = cid + i % 2;
        // Reuse SNs if pool exhausted
        uint32_t sn = sn_pool->sn_list[sn_pool->available_sn_index++ % sn_pool->num_sns];
        while (sn == headers[i-1].seq_num && i > 0) {
            sn = sn_pool->sn_list[(sn_pool->available_sn_index++) % sn_pool->num_sns];
        }
        headers[i].seq_num = sn;
        headers[i].ack_num = 0;
        headers[i].flags = 0x02; // SYN
        headers[i].window_size = mss - sizeof(tcp_header_t) - sizeof(uint8_t);
        headers[i].checksum = 0;
        headers[i].urg_ptr = 0;

