// Custom memory pool for allocating structures
void* struc_pool = NULL;
size_t struc_pool_size = 0;

// Periodic garbage collection interval (seconds)
int gc_interval = 10;

// Backoff strategy for retrying resource allocation attempts
int backoff = 1;

void init_struc_pool(size_t size) {
    if (!struc_pool && size > 0) {
        struc_pool = malloc(size);
        if (struc_pool) {
            struc_pool_size = size;
        } else {
            printf("Failed to allocate memory for structure pool.\n");
        }
    }
}

void free_struc_pool() {
