    if (struc_refcount[0] < MAX_STRUCTURES) {
        // Ensure uniqueness of CRC flag using hash table
        int crc_index = 0;
        while (crc_flags[crc_index] != 0) {
            crc_index++;
        }
        struc->CRCFLAG = crc_index;

        // Allocate memory for the structure using custom pool
        void* ptr = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!ptr) {
            printf("Failed to allocate memory for structure.\n");
        } else {
            memcpy(ptr, struc, sizeof(NFAPI_CRC_INDICATION_PDU_T));

            // Update reference count and add structure to the list
            struc_refcount[0]++;
            pthread_spin_lock(&spin_lock);
            log_head = (log_head + 1) % 1024;
            sprintf(log_buffer[log_head], "Added structure with CRC flag %d.\n", struc->CRCFLAG);
            pthread_spin_unlock(&spin_lock);
