    } else {
        printf("Maximum number of structures exceeded.\n");
    }
    pthread_mutex_unlock(&lock);
}

void remove_structure(NFAPI_CRC_INDICATION_PDU_T* struc) {
    pthread_mutex_lock(&lock);
    // Update reference count and remove structure from the list
    struc_refcount[0]--;
    if (struc_refcount[0] == 0) {
        free(struc);
    }
    pthread_mutex_unlock(&lock);
}

void gc_thread(void* arg) {
    while (1) {
        sleep(gc_interval);
        pthread_mutex_lock(&lock);
        // Periodic garbage collection
        for (int i = 0; i < MAX_STRUCTURES; i++) {
            if (struc_refcount[i] == 0) {
                free((void*)i);
            }
        }
        pthread_mutex_unlock(&lock);
