            struc.CRCFLAG = crc_index;
        }

        // Validate and add structure to the list
        if (!validate_structure(&struc)) {
            printf("Validation error. Retrying...\n");
            sleep(backoff);
            backoff *= 2; // Increase backoff factor on retry
        } else {
            add_structure(&struc);
            backoff = 1; // Reset backoff factor
        }
    }

