        printf("User ID: %llu, Session Start Time: %lu, Activity Type: %s, CRC Indication Rel 8 Tag: %d, CRC Flag: %d\n", 
               activity_log[i].user_id, activity_log[i].session_start_time, activity_log[i].activity_type, activity_log[i].crcindicationrel8tag, activity_log[i].crcflag);
    }
}

// Function to save the activity logs to a database
void save_activity_logs(USER_ACTIVITY_LOG* activity_log, int M) {
    MYSQL *conn;
    MYSQL_RES *res;
    MYSQL_ROW row;

    // Establish connection to database
    conn = mysql_init(NULL);
