        printf("Error: Unable to connect to the database.\n");
        return;  // Return on failure
    }

    // Prepare SQL query for inserting activity logs into the database
    char* sql_query = "INSERT INTO activity_logs (user_id, session_start_time, activity_type, crcindicationrel8tag, crcflag) VALUES (?, ?, ?, ?, ?)";
    if (!mysql_prepare_statement(conn, sql_query)) {
        printf("Error: Unable to prepare SQL query.\n");
        return;  // Return on failure
    }

    // Execute the prepared SQL query for each log entry
    for (int i = 0; i < M; i++) {
        if (!mysql_bind_param(conn, sql_query, &activity_log[i].user_id, &activity_log[i].session_start_time, 
                              activity_log[i].activity_type, &activity_log[i].crcindicationrel8tag, &activity_log[i].crcflag)) {
            printf("Error: Unable to bind parameters for the SQL query.\n");
            return;  // Return on failure
        }

        if (!mysql_execute_query(conn, sql_query)) {
            printf("Error: Unable to execute the SQL query.\n");
            return;  // Return on failure
        }
    }

    // Close database connection and free allocated memory
    mysql_close(conn);
    free(activity_log);
}

// Function to calculate the MD5 hash of a large file given its path
void calculate_md5_hash(const char* file_path) {
    // Initialize variables for hashing
    unsigned char buffer[1048576];  // Chunk size: 1 MB
    int bytes_read;
    FILE* file = fopen(file_path, "rb");

    if (file == NULL) {
        printf("Error: Unable to open the file.\n");
        return;  // Return on failure
    }

    MD5_CTX ctx;
    unsigned char hash[16];

    while ((bytes_read = fread(buffer, 1, sizeof(buffer), file)) > 0) {
        MD5Update(&ctx, buffer, bytes_read);

        if (ferror(file) != 0) {
            printf("Error: Unable to read the file.\n");
            fclose(file);  // Close file on failure
            return;  // Return on failure
        }
    }

    // Calculate and store the MD5 hash
    MD5Final(&ctx, hash);
    fclose(file);  // Close file

    printf("MD5 Hash: ");
    for (int i = 0; i < 16; i++) {
        printf("%02x", hash[i]);
    }
    printf("\n");
}

// Function to generate a report summarizing the hashing process
void generate_report(const char* file_path) {
    // Initialize variables for reporting
    time_t start_time, end_time;
    int bytes_processed = 0;

    start_time = time(NULL);
    calculate_md5_hash(file_path);
    end_time = time(NULL);

    printf("File Path: %s\n", file_path);
    printf("Start Time: %lu\n", start_time);
    printf("End Time: %lu\n", end_time);
    printf("Bytes Processed: %d\n", bytes_processed);
}

int main() {
