import os
import hashlib

def md5_hash_file(path):
    # Open the file for reading
    with open(path, 'rb') as file:
        chunk_size = 8192
        hash = hashlib.md5()
        while True:
            chunk = file.read(chunk_size)
            if not chunk:
                break
            hash.update(chunk)

    return hash.hexdigest()

def report_md5_hashing(hash):
    print(f"MD5 Hash: {hash}")
