import hashlib
import os

def calculate_md5_hash(file_path):
    md5 = hashlib.md5()

    with open(file_path, 'rb') as f:
        while True:
            chunk = f.read(4096)
            if not chunk:
                break
            md5.update(chunk)

    # generate report summarizing hashing process
    print(f"Hashing {file_path}...")
    print(f"Start time: {os.getcwd()}")
    print(f"End time: {os.getcwd()}")
    print(f"Chunk sizes processed: 4096 bytes each")
    if md5.hexdigest():
        print(f"MD5 hash: {md5.hexdigest()}")

    return md5.hexdigest()

if __name__ == "__main__":
    file_path = "path/to/large/file.txt"
    print(calculate_md5_hash(file_path))
