typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
} NFAPI_CRC_INDICATION_PDU_T;

int main() {
    // Define the number of structures to create
    int N = 10;

    // Create a list of NFAPI_CRC_INDICATION_PDU_T structures
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdu_list) {
        printf("Memory allocation failed.\n");
        return -1;
    }

    // Initialize a random seed
    srand(time(NULL));

    int crc_flag = 0;
    for (int i = 0; i < N; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = i;
        pdu_list[i].RNTI = i * 10;

        // Generate a unique CRCFLAG
        while (1) {
            crc_flag = rand() % 256;
            int flag_exists = 0;
            for (int j = 0; j < i; j++) {
                if (pdu_list[j].CRC_INDICATION_REL8_TAG == crc_flag) {
                    flag_exists = 1;
                    break;
                }
            }
            if (!flag_exists) {
                pdu_list[i].CRC_INDICATION_REL8_TAG = crc_flag;
                break;
            }
        }
    }

    // Log the creation process
    printf("Created %d NFAPI_CRC_INDICATION_PDU_T structures.\n", N);

    // Serialize the list to a file in a specific format
    FILE* f = fopen("pdu_list.bin", "wb");
