        available_ids++;
    }

    int max_pdu_count = (available_ids > N) ? N : available_ids;

    LTE_ENB_INTERFACE_MME_PDU_T* pdu_list = (LTE_ENB_INTERFACE_MME_PDU_T*)malloc(max_pdu_count * sizeof(LTE_ENB_INTERFACE_MME_PDU_T));
