        return NULL;

    for (int i = 0; i < max_pdu_count; i++) {
        pdu_list[i].MME_ID = i;
        pdu_list[i].ENB_ID = ids[i];
        // Randomly set MESSAGE_TYPE
        srand(time(NULL));
        int random_type = rand() % 3;
        pdu_list[i].MESSAGE_TYPE = (random_type == 0) ? MSG_TYPE_UNKNOWN : (random_type == 1) ? MSG_TYPE_REGISTRAR_REQUEST : MSG_TYPE_REGISTRAR_RESPONSE;

        // Initialize RX_UE_INFORMATION_TAG and RNTI
        // ...

        // Set CRCFLAG using custom CRC calculation function
        // ...
    }

    free(ids);

    return pdu_list;
}

void serialize_list(LTE_ENB_INTERFACE_MME_PDU_T* list, int size) {
    FILE *file = fopen("pdu_data.bin", "wb");
    if (!file)
        return;

    fwrite(&size, sizeof(int), 1, file);
    for (int i = 0; i < size; i++) {
        LTE_ENB_INTERFACE_MME_PDU_T pdu = list[i];
        fwrite(&pdu.MME_ID, sizeof(uint32_t), 1, file);
