                strcpy(msg_type_str, "UNKNOWN");
                break;
            case MSG_TYPE_REGISTRAR_REQUEST:
                strcpy(msg_type_str, "REGISTRAR_REQUEST");
                break;
            case MSG_TYPE_REGISTRAR_RESPONSE:
                strcpy(msg_type_str, "REGISTRAR_RESPONSE");
                break;
        }
        fwrite(msg_type_str, sizeof(char), strlen(msg_type_str) + 1, file);

