} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_list(int n) {
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Track uniqueness of CRCFLAG
    int crcflag = 0;
    for(int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list[i];

        // Randomly set CRCFLAG
        srand(time(NULL) + i);
        pdu->CRCFLAG = rand();

        while(crcflag == pdu->CRCFLAG) {
            pdu->CRCFLAG = rand();
        }

        crcflag = pdu->CRCFLAG;

        strcpy(pdu->RX_UE_INFORMATION_TAG, "RX_UE_INFO_TAG");
        pdu->RNTI = i;
        strcpy(pdu->CRC_INDICATION_REL8_TAG, "CRC_INDICATION_REL8_TAG");
    }

    return list;
}

void serialize_crc_indication_list(NFAPI_CRC_INDICATION_PDU_T* list, int n) {
    FILE* file = fopen("crc_indications.txt", "w");

    if(file == NULL) {
        printf("Error: Unable to open file.\n");
        return;
    }

    for(int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list[i];

        fprintf(file, "%s %d %s\n", pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRC_INDICATION_REL8_TAG);
