#include <stdlib.h>
#include <stdio.h>
#include <pthread.h>

#define MAX_SIZE 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_CRC_INDICATION_PDU_T* elements;
    int size;
    pthread_mutex_t lock;
} DynamicList;

DynamicList* dynamic_list_create() {
    DynamicList* list = (DynamicList*)malloc(sizeof(DynamicList));
    if (!list) return NULL;
    list->elements = (NFAPI_CRC_INDICATION_PDU_T*)calloc(MAX_SIZE, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!list->elements) {
        free(list);
        return NULL;
    }
    list->size = 0;
    pthread_mutex_init(&list->lock, NULL);
    return list;
}

void dynamic_list_destroy(DynamicList* list) {
    if (!list) return;
    for (int i = 0; i < list->size; i++) free(&list->elements[i]);
    free(list->elements);
    free(list);
    pthread_mutex_destroy(&list->lock);
}

int dynamic_list_add(DynamicList* list, NFAPI_CRC_INDICATION_PDU_T new_element) {
    if (list->size >= MAX_SIZE) return -1;
    pthread_mutex_lock(&list->lock);
    list->elements[list->size] = new_element;
    (list->size)++;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

int dynamic_list_remove(DynamicList* list, int index) {
    if (index >= list->size) return -1;
    pthread_mutex_lock(&list->lock);
    for (int i = index; i < list->size - 1; i++) {
        list->elements[i] = list->elements[i + 1];
    }
    (list->size)--;
    pthread_mutex_unlock(&list->lock);
    return 0;
}

NFAPI_CRC_INDICATION_PDU_T* dynamic_list_get(DynamicList* list, int index) {
    if (index >= list->size) return NULL;
    pthread_mutex_lock(&list->lock);
    NFAPI_CRC_INDICATION_PDU_T* element = &list->elements[index];
    pthread_mutex_unlock(&list->lock);
    return element;
}

void print_list(DynamicList* list) {
    for (int i = 0; i < list->size; i++) {
        printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRCFLAG: %d\n", list->elements[i].RX_UE_INFORMATION_TAG, list->elements[i].RNTI, list->elements[i].CRCFLAG);
    }
}
