RLC_STATUS_PDU *rlc_list = NULL;
int rlc_size = 0;
int lock = 0; // mutex for thread safety

void add_rlcpdu(RLC_STATUS_PDU* new_pdu) {
    if (rlc_size >= MAX_SIZE) {
        printf("Maximum size reached. Cannot add more.\n");
        return;
    }

    RLC_STATUS_PDU *new_list = realloc(rlc_list, sizeof(RLC_STATUS_PDU *) * (rlc_size + 1));
    if (!new_list) {
        printf("Memory allocation failed. Cannot add more.\n");
        return;
    }

    new_list[rlc_size] = new_pdu;
    rlc_list = new_list;
    rlc_size++;
}

void remove_rlcpdu(int index) {
    if (index < 0 || index >= rlc_size) {
        printf("Invalid index. Cannot remove.\n");
        return;
    }

    RLC_STATUS_PDU **temp = &rlc_list[index];
    memmove(temp, temp + 1, sizeof(RLC_STATUS_PDU *) * (rlc_size - index));
    rlc_size--;
}

RLC_STATUS_PDU* get_rlcpdu(int index) {
    if (index < 0 || index >= rlc_size) {
        printf("Invalid index. Cannot retrieve.\n");
        return NULL;
    }

    return &rlc_list[index]->tx_status;
}

void update_buffer_status(RLC_STATUS_PDU* pdu, struct TX_RLC_BUFFER_STATUS new_tx_status, struct RX_RLC_BUFFER_STATUS new_rx_status) {
    if (pdu) {
        pdu->tx_status = new_tx_status;
        pdu->rx_status = new_rx_status;
    }
}

void flush_rlcpdus() {
    for (int i = 0; i < rlc_size; i++) {
        free(&rlc_list[i]);
    }

    free(rlc_list);
    rlc_list = NULL;
    rlc_size = 0;
}
