import asyncio
import json
from websockets import WebSocketServerProtocol

class WebSocketService:
    def __init__(self):
        self.clients = set()

    async def handle_connection(self, client: WebSocketServerProtocol) -> None:
        try:
            while True:
                message = await client.recv()
                if message == "disconnect":
                    break
                await self.propagate_event(message)
        finally:
            self.clients.remove(client)

    async def propagate_event(self, event_data):
        for client in self.clients.copy():
            try:
                await client.send(json.dumps(event_data))
            except asyncio.CancelledError:
                self.clients.remove(client)

    async def broadcast_event(self, event_data: dict) -> None:
        if not self.clients:
            return
        await asyncio.wait([client.send(json.dumps(event_data)) for client in self.clients])

    async def start_server(self):
        server = await websockets.serve(self.handle_connection, "localhost", 8765)
        print("Server started on port 8765")
        try:
            await server.wait_closed()
        finally:
            server.close()

    async def run_client(self, user_id: str, session_token: str) -> None:
        async with websockets.connect("ws://localhost:8765") as websocket:
            try:
                await websocket.send(json.dumps({"event_type": "connect", "user_id": user_id, "session_token": session_token}))
                while True:
                    message = await websocket.recv()
                    if message == "disconnect":
                        break
                    await self.propagate_event(message)
            except asyncio.CancelledError:
                pass

    def start(self):
        asyncio.run(self.start_server())

    def run_client_loop(self, user_id: str, session_token: str) -> None:
        while True:
            try:
                await self.run_client(user_id, session_token)
            except Exception as e:
                print(f"Error in client loop: {e}")
