import asyncio
import json

class WebSocketHandler:
    def __init__(self, user_id, session_token):
        self.user_id = user_id
        self.session_token = session_token
        self.websocket_connections = {}

    async def handle_connection(self, reader, writer):
        while True:
            try:
                data = await reader.read(1024)
                if not data:
                    break

                # process incoming message
                event_type = json.loads(data.decode()).get('event_type')

                if event_type == 'new_message':
                    # propagate events to connected clients
                    for ws in self.websocket_connections.values():
                        await ws.send(data)
            except ConnectionResetError as e:
                print(f"Connection reset: {e}")
                break

            except Exception as e:
                print(f"Unexpected error: {e}")
                break

        writer.close()

    async def start_server(self, host='0.0.0.0', port=8080):
        server = await asyncio.start_server(self.handle_connection, host, port)
        async with server:
            await server.serve_forever()

if __name__ == "__main__":
    user_id = 1
    session_token = "your_session_token"
    ws_handler = WebSocketHandler(user_id, session_token)
    asyncio.run(ws_handler.start_server())
