#define MAX_SESSIONS 1000
#define BUFFER_SIZE 1024
#define COMPRESS_THRESHOLD 5000

typedef struct {
    int id;
    char data[20];
} ConnectionStatistics;

ConnectionStatistics* sessions[MAX_SESSIONS];
int num_sessions = 0;

pthread_mutex_t session_lock = PTHREAD_MUTEX_INITIALIZER;
pthread_cond_t session_cond = PTHREAD_COND_INITIALIZER;

void* thread_func(void* arg) {
    while(1) {
        pthread_mutex_lock(&session_lock);
        if(num_sessions < MAX_SESSIONS && sessions[num_sessions] == NULL) {
            int i;
            for(i = 0; i < COMPRESS_THRESHOLD; i++) {
                ConnectionStatistics* new_session = malloc(sizeof(ConnectionStatistics));
                new_session->id = num_sessions + i;
                strcpy(new_session->data, "Some data");
                sessions[num_sessions++] = new_session;
            }
        }
        pthread_mutex_unlock(&session_lock);

        // Periodic compression and sending to central server
        if(num_sessions > COMPRESS_THRESHOLD) {
            FILE* file = fopen("central_server.log", "a+");
            if(file) {
                for(int i = 0; i < num_sessions; i++) {
                    fwrite(&sessions[i]->id, sizeof(int), 1, file);
                    fwrite(sessions[i]->data, strlen(sessions[i]->data), 1, file);
                }
                fclose(file);
            }
        }

        // Periodic compression and sending to central server
        sleep(5); 
    }
}

int main() {
    pthread_t thread;

    // Initialize the logging framework
    FILE* log_file = fopen("log.log", "w+");
    if(log_file) {
        setvbuf(log_file, NULL, _IONLY, BUFFER_SIZE);
    }

    // Start the thread
    pthread_create(&thread, NULL, thread_func, NULL);

    // Main loop
    while(1) {
        sleep(10); 
    }

    return 0;
}
