// Structure to represent an NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Hash table to store unique CRCFLAG values
typedef struct {
    size_t size;
    unsigned long* keys;
    unsigned long* values;
} hash_table_t;

// Initialize the hash table with a specified size
hash_table_t* init_hash_table(size_t size) {
    hash_table_t* ht = (hash_table_t*)malloc(sizeof(hash_table_t));
    ht->size = size;
    ht->keys = (unsigned long*)calloc(size, sizeof(unsigned long));
    ht->values = (unsigned long*)calloc(size, sizeof(unsigned long));
    return ht;
}

// Insert a key-value pair into the hash table
void insert_hash_table(hash_table_t* ht, unsigned long key, bool value) {
    size_t i = 0;
    while (i < ht->size && ht->keys[i] != key) {
        i++;
    }
    if (i == ht->size) {
        // Handle hash table full condition
        printf("Hash table is full. Cannot insert.\n");
        return;
    }
    ht->values[i] = value;
}

// Delete a key-value pair from the hash table
void delete_hash_table(hash_table_t* ht, unsigned long key) {
    size_t i = 0;
    while (i < ht->size && ht->keys[i] != key) {
        i++;
    }
    if (i == ht->size) {
        // Handle key not found condition
        printf("Key not found in hash table. Cannot delete.\n");
        return;
    }
    ht->values[i] = false;  // Mark as deleted
}

// Function to manage the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
void manage_list(hash_table_t* ht, int* RX_UE_INFORMATION_TAG, int* RNTI) {
    static NFAPI_CRC_INDICATION_PDU_T list[1000];
    static size_t list_size = 0;
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Acquire the lock
    pthread_mutex_lock(&mutex);

    // Check if the list is full
    if (list_size >= sizeof(list) / sizeof(*list)) {
        printf("List is full. Cannot add more elements.\n");
        return;
    }

    // Generate a random RX_UE_INFORMATION_TAG and RNTI value
    *RX_UE_INFORMATION_TAG = rand() % 1000;
    *RNTI = rand() % 1000;

    // Insert the new structure into the list
    list[list_size].RX_UE_INFORMATION_TAG = *RX_UE_INFORMATION_TAG;
    list[list_size].RNTI = *RNTI;
    list[list_size].CRCFLAG = false;  // Initialize CRCFLAG as false

    // Add the new structure to the hash table
    insert_hash_table(ht, (unsigned long)list_size, true);

    list_size++;

    // Release the lock
    pthread_mutex_unlock(&mutex);
}

// Function to process a byte array input and generate a random string of a specified length using a configurable character set
string ProcessInput(byte[] input, int length)
{
