import subprocess
import random
import json
from structpy import Structure
import os

class NFAPI_CRC_INDICATION_PDU_T(Structure):
    fields = [
        ('RX_UE_INFORMATION_TAG', '16s'),
        ('RNTI', '32s'),
        ('CRC_INDICATION_REL8_TAG', {
            'CRCFLAG': 'B'
        })
    ]

def generate_random_crcflag():
    return random.randint(0, 1)

def replace_placeholders(config_file, placeholders):
    try:
        output = subprocess.check_output(['sed', '-E', '-i', f"s/{re.escape(key)}/{value}/g", config_file] for key, value in placeholders.items())
    except subprocess.CalledProcessError as e:
        raise Exception(f"Failed to replace placeholders: {e}")

def generate_structures(num_structures):
    structures = []
    for _ in range(num_structures):
        struct = NFAPI_CRC_INDICATION_PDU_T()
        struct.RX_UE_INFORMATION_TAG = os.urandom(16)
        struct.RNTI = os.urandom(4)
        struct.CRC_INDICATION_REL8_TAG['CRCFLAG'] = generate_random_crcflag()
        structures.append(struct.pack())

    return b''.join(structures)

def main(config_file, placeholders):
    try:
        replace_placeholders(config_file, placeholders)
    except Exception as e:
        raise

    try:
        with open(config_file + '.mod', 'wb') as f:
            f.write(open(config_file).read().encode())
            f.write(generate_structures(len(placeholders)).encode())
    except Exception as e:
        raise
