import os
import random
import subprocess
from Crypto.Cipher import AES
from Crypto.Util.Padding import pad, unpad
import hashlib
import re

def generate_crcflag():
    crcflag = bytes([random.randint(0x00, 0xff) for _ in range(4)])
    return crcflag.hex()

def validate_password(password):
    if len(password) < 8:
        raise ValueError("Password must be at least 8 characters long")
    if not re.match(r"^[a-zA-Z0-9_]+$", password):
        raise ValueError("Password can only contain letters, numbers and underscores")

def generate_structures(num_structures):
    structures = []
    rnti_sum = 0
    crcflag = generate_crcflag()
    for _ in range(num_structures):
        rx_ue_info_tag = f"RX_UE_INFORMATION_TAG_{rnti_sum + 1}"
        rnti = hashlib.sha256(str(rnti_sum).encode()).hexdigest()[:8]
        structures.append({"RX_UE_INFORMATION_TAG": rx_ue_info_tag, "RNTI": rnti, "CRC_INDICATION_REL8_TAG": crcflag})
        rnti_sum += 1
    return structures

def encrypt_password(password):
    key = b"your_secret_key_here"
    cipher = AES.new(key, AES.MODE_ECB)
    padded_password = pad(password.encode(), AES.block_size)
    encrypted_password = cipher.encrypt(padded_password)
    decrypted_password = unpad(cipher.decrypt(encrypted_password), AES.block_size).decode()
    return decrypted_password

def modify_config(config_file, placeholders, actual_values):
    try:
        with open(config_file, "r+") as file:
            contents = file.read()
            for placeholder, value in actual_values.items():
                if f"${{{placeholder}}}" not in contents:
                    raise ValueError(f"Missing placeholder {placeholder}")
                new_contents = contents.replace(f"${{{placeholder}}}", str(value))
            file.seek(0)
            file.write(new_contents)
    except Exception as e:
        log_error(e)
        return False
    return True

def add_password(config_file, password):
    try:
        with open(config_file, "a") as file:
            file.write("\n" + password)
    except Exception as e:
        log_error(e)
        return False
    return True

def generate_config(actual_values):
    config_file = "modified_config.cfg"
    placeholders = list(actual_values.keys())
    retry_count = 0
    while True:
        try:
            subprocess.check_call(f"sed -i 's|{re.escape(placeholders[0])}|{actual_values[placeholders[0]]}|g' {config_file}", shell=True)
            break
        except subprocess.CalledProcessError as e:
            if retry_count < 3:
                log_error(e)
                retry_count += 1
                continue
            raise

    for placeholder in placeholders[1:]:
        while True:
            try:
                subprocess.check_call(f"sed -i 's|{re.escape(placeholder)}|{actual_values[placeholder]}|g' {config_file}", shell=True)
                break
            except subprocess.CalledProcessError as e:
                if retry_count < 3:
                    log_error(e)
                    retry_count += 1
                    continue
                raise

    password = encrypt_password(input("Enter the new password: "))
    validate_password(password)
    while True:
        try:
            add_password(config_file, password)
            break
        except Exception as e:
            if retry_count < 3:
                log_error(e)
                retry_count += 1
                continue
            raise

    structures = generate_structures(10)  # default number of structures
    with open(config_file, "a") as file:
        for structure in structures:
            file.write(f"{{\n"
                      f"RX_UE_INFORMATION_TAG: {structure['RX_UE_INFORMATION_TAG']},\n"
                      f"RNTI: {structure['RNTI']},\n"
                      f"CRC_INDICATION_REL8_TAG: {{CRCFLAG: {structure['CRC_INDICATION_REL8_TAG']}}}\n"
                      "}},")
