public void HandleHttpPostRequest(int userId, string sessionToken, int pageSectionId, int elementId, string htmlContent, CacheControlDirective cacheControl)
{
    if (!ValidateSessionToken(sessionToken))
    {
        // Unauthorized access
        throw new SecurityException("Invalid or expired session token");
    }

    var section = GetPageSection(pageSectionId);
    if (section == null || !IsEditable(section))
    {
        // Page section not found or not editable
        throw new HttpException("Page section not found or not editable", 404);
    }

    if (!ValidateElement(elementId, pageSectionId))
    {
        // Element not found or not in this page section
        throw new HttpException("Element not found or not in this page section", 404);
    }

    using (var service = GetService())
    {
        try
        {
            service.UpdateElement(elementId, htmlContent);
        }
        catch (Exception ex)
        {
            // Log the error
            Console.WriteLine(ex.Message);
            throw;
        }
    }

    if (!ShouldRefreshPage(cacheControl))
    {
        return;
    }

    // Refresh the page
    var cache = GetCache();
    cache.SetExpirationTime(TimeSpan.FromMinutes(30)); // Example expiration time
    cache.Invalidate(pageSectionId); // Invalidate this page section's cache
}
