#include <string.h>
#include <errno.h>

int convert_jpg_to_pdf(const char *input_file_name, const char *output_file_name, int compression_level, int encryption_settings, const char *metadata_string) {
    int tries = 0;
    int success = 0;

    while (tries < 3 && !success) {
        FILE *input_file = fopen(input_file_name, "rb");
        if (!input_file) {
            perror("Error opening input file");
            return 1;
        }

        FILE *output_file = fopen(output_file_name, "wb");
        if (!output_file) {
            perror("Error opening output file");
            fclose(input_file);
            return 1;
        }

        // Call third-party tool to convert JPEG to PDF
        system("converter --compression-level=3 --encryption-settings=2 --metadata-string=\"MetadataString\" input_file_name output_file_name");

        if (ferror(output_file)) {
            perror("Error writing to output file");
            fclose(input_file);
            fclose(output_file);
            return 1;
        }

        success = 1;
    }

    if (!success) {
        // Log failure
        printf("Conversion failed after %d tries. Error: %s\n", tries, strerror(errno));
    } else {
        // Log success
        printf("Conversion successful!\n");
    }

    fclose(input_file);
    fclose(output_file);

    return success ? 0 : 1;
}
