#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <syslog.h>
#include <pthread.h>

#define MAX_LOG_LEVEL 4 // debug: 0, info: 1, warning: 2, error: 3
#define MAX_BUFFER_SIZE 10240
#define LOG_FILE_PATH "log_file.log"
#define LOG_SYSD_BUG FALSE

typedef struct {
    char* buffer;
    size_t len;
} log_entry;

pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;
log_entry* log_buffer = NULL;
size_t log_buffer_len = 0;
int max_log_level = 2; // default: warning
FILE* log_file = NULL;

void log_message(int level, const char* message) {
    if (level > max_log_level)
        return;

    pthread_mutex_lock(&lock);
    log_entry* new_entry = (log_entry*)malloc(sizeof(log_entry));
    new_entry->buffer = (char*)malloc(MAX_BUFFER_SIZE);
    strcpy(new_entry->buffer, message);
    new_entry->len = strlen(message);

    if (log_buffer_len >= MAX_BUFFER_SIZE / 2) {
        // resize log buffer
        size_t new_size = max(log_buffer_len * 2, MAX_BUFFER_SIZE);
        log_entry* temp = (log_entry*)malloc(new_size * sizeof(log_entry));
        memcpy(temp, log_buffer, log_buffer_len * sizeof(log_entry));
        free(log_buffer);
        log_buffer = temp;
    }

    if (log_buffer_len >= MAX_BUFFER_SIZE) {
        // rotate log file
        rename(LOG_FILE_PATH, LOG_FILE_PATH ".old");
        log_file = fopen(LOG_FILE_PATH, "w");
        if (!log_file) {
            syslog(LOG_ERR, "Failed to open log file for writing.");
        }
    }

    log_buffer[log_buffer_len++] = *new_entry;
    pthread_mutex_unlock(&lock);

    // write to file and syslog
    fprintf(log_file, "%s\n", new_entry->buffer);
    syslog(level, "%s", new_entry->buffer);

    free(new_entry->buffer);
    free(new_entry);
}

void init_log() {
    log_buffer = (log_entry*)malloc(MAX_BUFFER_SIZE / 2 * sizeof(log_entry));
    log_buffer_len = 0;
    max_log_level = MAX_LOG_LEVEL;
    log_file = fopen(LOG_FILE_PATH, "w");
    if (!log_file) {
        syslog(LOG_ERR, "Failed to open log file for writing.");
    }
}

void destroy_log() {
    pthread_mutex_lock(&lock);
    for (int i = 0; i < log_buffer_len; i++) {
        free(log_buffer[i].buffer);
    }
    free(log_buffer);
    pthread_mutex_unlock(&lock);
}
