void init_dynamic_array(struct dynamic_array* array, size_t initial_capacity) {
    array->size = 0;
    array->capacity = initial_capacity;
    array->pdus = (MAC_PDU*)malloc(array->capacity * sizeof(MAC_PDU));
    pthread_mutex_init(&array->mutex, NULL);
}

void add_pdu(struct dynamic_array* array, MAC_PDU pdu) {
    pthread_mutex_lock(&array->mutex);
    if (array->size >= array->capacity) {
        array->capacity *= 2;
        array->pdus = (MAC_PDU*)realloc(array->pdus, array->capacity * sizeof(MAC_PDU));
    }
    array->pdus[array->size] = pdu;
    array->size++;
    pthread_mutex_unlock(&array->mutex);
}

void update_pdu(struct dynamic_array* array, int index, MAC_PDU pdu) {
    pthread_mutex_lock(&array->mutex);
    if (index >= 0 && index < array->size) {
        array->pdus[index] = pdu;
    }
    pthread_mutex_unlock(&array->mutex);
}

int get_pdu_count(struct dynamic_array* array) {
    int count = 0;
    pthread_mutex_lock(&array->mutex);
    for (int i = 0; i < array->size; i++) {
        count++;
