import asyncio
import logging

class Product:
    def __init__(self, product_id: int, priority_level: str, update_frequency: int):
        self.product_id = product_id
        self.priority_level = priority_level
        self.update_frequency = update_frequency

class TaskScheduler:
    def __init__(self):
        self.tasks = []
        self.service_class = None

    async def schedule_task(self, product: Product):
        # Validate product details for correctness and completeness
        if not product.product_id or not product.priority_level or not product.update_frequency:
            raise ValueError("Invalid product details")

        # Propagate task to workers using the service class
        await self.service_class.run_task(product)

    def start(self, service_class: object):
        self.service_class = service_class

    async def run(self):
        while True:
            try:
                task = await asyncio.wait_for(self.schedule_task(), timeout=1)
                # Manage task backpressure to avoid overload
                if len(self.tasks) > 100:
                    await asyncio.sleep(0.5)

            except asyncio.TimeoutError:
                logging.warning("Task timed out")

    def add_task(self, product: Product):
        self.tasks.append(product)

    async def retry_failed_tasks(self):
        while True:
            failed_tasks = [task for task in self.tasks if task.status == "failed"]
            for task in failed_tasks:
                await self.schedule_task(task)
            await asyncio.sleep(1)

class Task:
    def __init__(self, product: Product, priority_level: str):
        self.product = product
        self.priority_level = priority_level
        self.status = "pending"

    async def run(self):
        # Simulate task execution
        await asyncio.sleep(2)
        if random.random() < 0.5:
            self.status = "failed"
        else:
            self.status = "success"

class TaskWorker:
    def __init__(self, service_class: object):
        self.service_class = service_class

    async def run_task(self, product: Product):
        # Simulate task execution
        await asyncio.sleep(1)
        print(f"Task worker {product.product_id} executed successfully")

async def main():
    scheduler = TaskScheduler()
    service_class = ServiceClass()

    # Schedule tasks and start the scheduler
    for _ in range(10):
        product = Product(_ + 1, "high", 2)
        await scheduler.schedule_task(product)

    await scheduler.run()

