#include <getopt.h>

int signal_set = 0;
FILE* input_file = NULL;

void init_signal_set(int signal) {
    signal_set = signal;
}

void cleanup() {
    if (input_file != NULL) {
        fclose(input_file);
    }
}

SIGSET_T get_signal_set() {
    return (SIGSET_T)(signal_set);
}

int main(int argc, char* argv[]) {
    int c;
    static struct option long_options[] = {
        {"manpage", 0, 0, 'm'},
        {"cs",     0, 0, 'c'},
        {"output", 1, 0, 'o'}
    };
    while ((c = getopt_long(argc, argv, "mc:o:", long_options, NULL)) != -1) {
        switch (c) {
            case 'm':
                printf("This is the manpage\n");
                break;
            case 'c':
                init_signal_set(SIGINT);
                break;
            case 'o':
                input_file = fopen(optarg, "r");
                if (input_file == NULL) {
                    fprintf(stderr, "Failed to open file %s\n", optarg);
                    return 1;
                }
                break;
        }
    }

    if (optind < argc) {
        printf("Usage: %s [options]\nOptions:\n"
               "-m     Print this manpage.\n"
               "-c     Initialize signal set with SIGINT.\n"
               "-o output_file  Read input from file and write to output_file.\n\n",
               argv[0]);
    } else {
        int line_count = 0;
        char buffer[1024];
        while (fgets(buffer, sizeof(buffer), input_file)) {
            line_count++;
        }
        fclose(input_file);
        printf("Number of lines: %d\n", line_count);
    }

    cleanup();
    return 0;
}
