use std::path::{Path, PathBuf};
use std::fs::File;
use std::io::{Read, Write};
use llvm::{LLVMContext, LLVMModule, LLVMBuilder};
use lexer::{Lexer, LexerError};
use parser::{Parser, ParserError};
use optimizer::{Optimizer, OptimizationPass};

#[derive(Debug)]
pub enum Mode {
    Sync,
    Async,
}

impl generate_llvm_ir {
    pub fn new() -> Self {
        // Initialize logging and debugging
        let log_level = // determine log level based on environment variables or configuration file
        Self { log_level }
    }

    pub fn generate_llvm_ir(&self, file_path: &str, mode: Mode) -> String {
        let mut file = match File::open(PathBuf::from(file_path)) {
            Ok(file) => file,
            Err(err) => {
                // handle file I/O error
                panic!("Error opening file: {}", err);
            }
        };

        let mut buffer = String::new();
        match file.read_to_string(&mut buffer) {
            Ok(_) => {}
            Err(err) => {
                // handle file reading error
                panic!("Error reading file: {}", err);
            }
        }

        let lexer = Lexer::new(&buffer);
        match lexer.tokenize() {
            Ok(tokens) => {
                let mut parser = Parser::new(lexer);
                match parser.parse() {
                    Ok(ast) => {
                        // optimize and generate LLVM IR
                        let optimizer = Optimizer::new();
                        let module = optimizer.optimize(&ast);

                        let builder = LLVMBuilder::new(LLVMContext::new());
                        let llvmmodule = module.to_llvm_module(builder);
                        let llvmsource = format!("{:?}", llvmmodule);

                        // print parsed nodes and generated LLVM IR code
                        println!("Parsed AST: {:?}", ast);
                        println!("Generated LLVM IR: {}", llvmsource);

                        return llvmsource;
                    }
                    Err(err) => {
                        // handle parser error
                        panic!("Error parsing file: {}", err);
                    }
                }
            }
            Err(err) => {
                // handle lexer error
                panic!("Error tokenizing file: {}", err);
            }
        }

        "".to_string()
    }
}
