int* modifyStateList(std::vector<int>& states, int targetState, int replacementState, struct State* fsa) {
    for (auto it = states.begin(); it != states.end(); ++it) {
        if (*it == targetState) {
            *it = replacementState;
            break;
        }
    }

    if (std::find(states.begin(), states.end(), targetState) == states.end()) {
        states.push_back(replacementState);
    }

    return &states[0];
}

