            foreach (var parameter in parameters)
            {
                command.Parameters.AddWithValue(parameter.Key, parameter.Value);
            }

            using (SqlDataReader reader = await command.ExecuteReaderAsync())
            {
                while (await reader.ReadAsync())
                {
                    MyClass obj = new MyClass();
                    // Map the result set to the specified class structure
                    obj.Id = (int)reader["Id"];
                    obj.Name = (string)reader["Name"];

                    // Make API call and merge results
                    MyApiResponse apiResult = await MakeApiClientCallAsync();
                    obj.ApiData = apiResult.Data;

