using System;
using System.Xml;
using System.Xml.XPath;

public static class XmlParser
{
    public static XElement ParseXml(string xmlString, string nodeName, string[] attributeOrder)
    {
        XmlDocument xmlDoc = new XmlDocument();
        try
        {
            xmlDoc.LoadXml(xmlString);
        }
        catch (Exception ex)
        {
            // Log error and return null if XML parsing fails
            Console.WriteLine($"Error parsing XML: {ex.Message}");
            return null;
        }

        XPathNavigator navigator = xmlDoc.CreateNavigator();
        XPathExpression expression = navigator.Compile($"/{nodeName}");

        try
        {
            XPathNodeIterator nodes = navigator.Select(expression);
            if (!nodes.MoveNext())
            {
                // Log warning and return null if no matching node found
                Console.WriteLine($"Warning: No element found with name '{nodeName}'");
                return null;
            }

            XPathNavigator selectedNode = nodes.Current;
            foreach (string attributeName in attributeOrder)
            {
                XPathExpression childExpression = navigator.Compile($"{attributeName}");
                XPathNodeIterator childNodes = selectedNode.Select(childExpression);
                if (!childNodes.MoveNext())
                {
                    // Heuristically choose the first node with non-empty attribute
                    return selectedNode.SelectSingleNode($".//{childExpression.Name}");
                }
            }

            return selectedNode;
        }
        catch (Exception ex)
        {
            // Log error and return null if XPath query fails
            Console.WriteLine($"Error parsing XML using XPath: {ex.Message}");
            return null;
        }
    }
}
