```csharp
using System;
using System.Xml;
using System.Collections.Generic;

public class XmlParser
{
    private readonly XmlDocument _xmlDoc;
    private readonly XPathNavigator _xpathNav;
    private readonly List<HTTP_RESPONSE_PDU_T> _httpResponseList = new();

    public XmlParser(string xmlString, string[] namespaceUris)
    {
        _xmlDoc = new XmlDocument();
        _xmlDoc.LoadXml(xmlString);
        _xpathNav = _xmlDoc.CreateNavigator();
        foreach (var nsUri in namespaceUris)
        {
            _xpathNav.AddNamespace(nsUri, nsUri);
        }
    }

    public List<HTTP_RESPONSE_PDU_T> ParseXml(string elementName, string[] attributeNames, Predicate<HTTP_RESPONSE_PDU_T> filter)
    {
        var matchingElements = new List<XPathNodeIterator>();
        try
        {
            var expr = _xpathNav.Compile("/" + elementName);
            XPathNodeIterator iterator = expr.Select();
            while (iterator.MoveNext())
            {
                HTTP_RESPONSE_PDU_T pdu;
                try
                {
                    pdu = new HTTP_RESPONSE_PDU_T(iterator.Current.GetAttribute(attributeNames[0], ""));
                    _httpResponseList.Add(pdu);
                }
                catch (Exception ex)
                {
                    throw new Exception("Failed to parse XML", ex);
                }
            }
        }
        catch (Exception ex)
        {
            throw new Exception("Failed to parse XPath", ex);
        }

        if (_httpResponseList.Count == 0)
            throw new Exception("No element found with name " + elementName);

        return _httpResponseList.Where(filter).ToList();
    }
}

public class HTTP_RESPONSE_PDU_T
{
    public int TransactionId { get; set; }
    public string HttpHeader { get; set; }
    public int StatusCode { get; set; }
    public string Payload { get; set; }

    public HTTP_RESPONSE_PDU_T(string payload, int statusCode)
    {
        this.Payload = payload;
        this.StatusCode = statusCode;
    }
}
