                            $authToken = $auth->authenticate($request['service'], $request['auth_token']);
                            if ($authToken) {
                                return json_encode(array('message' => 'success', 'details' => array('status' => 'success')));
                            } else {
                                return json_encode(array('message' => 'error', 'details' => array('status' => 'failure', 'reason' => 'Authentication failed')));
