                        }
                    } else {
                        return json_encode(array('message' => 'error', 'details' => array('status' => 'failure', 'reason' => 'Password does not meet complexity requirements')));
                    }
                } else {
                    return json_encode(array('message' => 'error', 'details' => array('status' => 'failure', 'reason' => 'Invalid data')));
                }
                break;
            case 'update':
