                            $save->updateUser($user, $data);
                            return json_encode(array('message' => 'success', 'details' => array('status' => 'success')));
                        } else {
                            return json_encode(array('message' => 'error', 'details' => array('status' => 'failure', 'reason' => 'No data to update')));
                        }
                    } else {
                        return json_encode(array('message' => 'error', 'details' => array('status' => 'failure', 'reason' => 'User not found')));
                    }
                } else {
                    return json_encode(array('message' => 'error', 'details' => array('status' => 'failure', 'reason' => 'Invalid operation')));
                }
                break;
            case 'delete':
                if (!empty($request['id'])) {
                    $user = $save->getUser($request['id']);
                    if ($user) {
                        $authToken = $auth->authenticate($request['service'], $request['auth_token']);
