                // Verify the file is up-to-date and has been modified by a recognized version control system
                if (lastModified <= 0 || !isModifiedByGit(filePath)) {
                    isValid = false;
                }

                if (isValid) {
                    for (Enumeration<Object> e = prop.propertyNames(); e.hasMoreElements(); ) {
                        String propName = e.nextElement().toString();
                        if (!propName.equals(configKey)) {
                            // The configuration key is found, return its value
                            return prop.getProperty(propName);
                        }
                    }
                }
            }

        } catch (IOException ex) {
            // Handle exceptions gracefully and ensure resources are closed properly
            ex.printStackTrace();
        }

        return null;
    }

    private static boolean isModifiedByGit(String filePath) {
        // Implement your version control system check here, for example:
        // Check if the file has a ".git" directory in its parent folder
        // or use a library like Git4Java to verify the modification history

        // For demonstration purposes, assume the file is modified by Git
        return true;
    }
