["```javascript
const fs = require('fs');
const path = require('path');
const { promisify } = require('util');

// Promisify the fs.readFile function
const readFileAsync = promisify(fs.readFile);

async function mergeFiles(directory, pattern = '', maxBytesPerRead = 1024 * 1024, concurrencyLevel = 5) {
  const regex = new RegExp(pattern);
  const files = await fs.readdir(directory);
  const filteredFiles = files.filter(file => regex.test(path.basename(file)));

  // Set up a queue to manage file reading and merging
  let currentFileIndex = 0;
  let maxFileCount = filteredFiles.length;
  const fileQueue = [];
  for (let i = 0; i < concurrencyLevel; i++) {
    fileQueue.push({
      file: null,
      bytesRead: 0
    });
  }

  // Read files in parallel
  function processFiles() {
    return new Promise((resolve, reject) => {
      async function readNextFile() {
        if (currentFileIndex >= maxFileCount) {
          resolve();
          return;
        }

        const file = filteredFiles[currentFileIndex++];
        fileQueue.forEach(queueItem => {
          if (!queueItem.file || queueItem.file === file) {
            queueItem.file = file;
            break;
          }
        });

        // Read the next file
        async function readNextChunk() {
          if (currentFileIndex >= maxFileCount) {
            resolve();
            return;
          }

          const chunkSize = Math.min(maxBytesPerRead, fs.statSync(path.join(directory, file)).size - queueItem.bytesRead);
          try {
            const fileContent = await readFileAsync(path.join(directory, file), 'utf8', null, chunkSize);
            queueItem.file = null; // Reset the file pointer
            queueItem.bytesRead += chunkSize;

            // Merge the file content
            let mergedString = '';
            if (mergedString.length + fileContent.length > maxBytesPerRead) {
              await processFiles(); // Process other files before processing this chunk
              return readNextChunk();
            }
            mergedString += fileContent;
          } catch (err) {
            reject(err);
            return;
          }

          // Continue reading the next file chunk
          setTimeout(() => {
            readNextChunk();
          }, 0);
        }

        readNextChunk();
      }

      readNextFile();
    });
  }

  // Start processing files
  await processFiles();
}
