function testModules(labels, modules, f) {
  const maxConcurrency = 100;
  const queue = [];
  let activeTests = 0;

  labels.forEach((label) => {
    if (!modules[label]) {
      console.error(`Module '${label}' not found`);
      return;
    }
    const module = modules[label];
    if (module.dependencies) {
      const deps = new Set(module.dependencies);
      for (const dep of deps) {
        if (!modules[dep]) {
          console.error(`Dependency '${dep}' not found`);
          return;
        }
      }
    }
    queue.push({ label, module });
  });

  async function runTest() {
    while (queue.length > 0) {
      const { label, module } = queue.shift();
      try {
        await f(label);
        console.log(`Module '${label}' - Test passed`);
      } catch (error) {
        console.error(`Module '${label}' - Test failed: ${error}`);
      }
    }
  }

  runTest();
}
