typedef struct {
  int connection_id;
  int client_port;
  enum { IDLE, ESTABLISHED, CLOSED } state;
  time_t last_active_time;
} Connection_T;

void initialize_session_context(char* session_id, char* client_ip, char* server_ip, int port, int max_connections, int timeout_ms) {
  SessionContext* context = malloc(sizeof(SessionContext));
  context->session_id = session_id;
  context->client_ip = client_ip;
  context->server_ip = server_ip;
  context->port = port;
  context->max_connections = max_connections;
  context->timeout_ms = timeout_ms;

  int num_connections = 0;
  for (int i = 0; i < max_connections; i++) {
    Connection_T* connection = &context->connections[i];
    connection->connection_id = i;
    connection->client_port = port;
    connection->state = IDLE;
    connection->last_active_time = time(NULL);
    num_connections++;
  }

  if (num_connections > max_connections) {
    printf("Warning: maximum connections reached. Cannot accept further connections.\n");
  }
}
