["```
class RealTimeDataCollector {
  constructor({
    graphDatabaseUrl,
    batchSize = 100,
    persistenceIntervalMs = 1000,
    retryDelayMs = 30000,
    rateLimitWindowMs = 60000
  }) {
    this.graphDatabaseUrl = graphDatabaseUrl;
    this.batchSize = batchSize;
    this.persistenceIntervalMs = persistenceIntervalMs;
    this.retryDelayMs = retryDelayMs;
    this.rateLimitWindowMs = rateLimitWindowMs;
    this.paused = false;
    this.dataBuffer = [];
    this.lastPersistenceTimestamp = 0;
  }

  start() {
    this.paused = false;
    setInterval(() => this.persistenceLoop(), this.persistenceIntervalMs);
  }

  pause() {
    this.paused = true;
  }

  resume() {
    this.paused = false;
  }

  addVertex(id, data) {
    if (this.paused) return;

    const vertex = { id, data };
    this.dataBuffer.push(vertex);

    if (this.dataBuffer.length >= this.batchSize) {
      this.persistenceLoop();
    }
  }

  addEdge(srcId, destId, data) {
    if (this.paused) return;

    const edge = { srcId, destId, data };
    this.dataBuffer.push(edge);

    if (this.dataBuffer.length >= this.batchSize) {
      this.persistenceLoop();
    }
  }

  persistenceLoop() {
    while (this.dataBuffer.length > 0 && !this.paused) {
      const batch = this.dataBuffer.slice(0, this.batchSize);
      this.dataBuffer.splice(0, this.batchSize);

      try {
        this.sendToGraphDatabase(batch);
      } catch (error) {
        if (!this.handleRetry(error)) {
          console.error('Failed to persist data:', error);
          return;
        }
      }

      this.lastPersistenceTimestamp = Date.now();
    }
  }

  sendToGraphDatabase(dataBatch) {
    const url = `${this.graphDatabaseUrl}/vertices`;
    const requests = dataBatch.map((data) => {
      if (typeof data === 'object') {
        return { method: 'POST', body: JSON.stringify(data) };
      } else {
        return { method: 'PUT', body: JSON.stringify({ id: data }) };
      }
    });

    const responses = await Promise.all(requests.map((request) => this.rateLimitedRequest(request)));

    if (!responses.every((response) => response.ok)) {
      throw new Error('Failed to persist some data');
    }
  }

  rateLimitedRequest(request) {
    return new Promise((resolve, reject) => {
      const deadline = Date.now() + this.rateLimitWindowMs;

      (async () => {
        while (Date.now() < deadline) {
          try {
            await fetch(request.url, request);
            resolve();
            break;
          } catch (error) {
            if (!this.handleRetry(error)) {
              reject(error);
              return;
            }
          }

          await new Promise((resolve) => setTimeout(resolve, 100));
        }

        reject(new Error('Rate limit exceeded'));
      })();
    });
  }

  handleRetry(error) {
    const retryDelay = this.retryDelayMs;

    if (error.code === 'ECONNREFUSED' || error.name === 'TimeoutError') {
      setTimeout(() => this.persistenceLoop(), retryDelay);
      return true;
    }

    return false;
  }
}
