import json
from collections import defaultdict
from heapq import heapify, heappop

def aggregate_json_streams(streams):
    aggregated_data = defaultdict(dict)
    seen_keys = set()
    stream_heap = [(stream, 0) for stream in streams]
    heapify(stream_heap)

    while stream_heap:
        stream, pos = heappop(stream_heap)
        try:
            event = json.loads(stream[pos:])
        except json.JSONDecodeError:
            continue

        if isinstance(event, dict):
            for key, value in event.items():
                if key in seen_keys and aggregated_data[key]:
                    aggregated_data[key].update(value)
                else:
                    aggregated_data[key][pos] = value
                seen_keys.add(key)

    return {key: list(values.values()) for key, values in aggregated_data.items()}

