const { parallel } = require('async');
const axios = require('axios');
const cache = require('memory-cache');

function traverseDOM(domTree, filterFunction) {
  const nodeQueue = [];
  const batchResults = [];

  async function processBatch(batchSize) {
    const nodesInThisBatch = await new Promise((resolve) => {
      for (let i = 0; i < batchSize; i++) {
        if (!nodeQueue.length) {
          resolve([]);
        }
        const node = nodeQueue.shift();
        resolve([node]);
      }
    });

    // Process nodes in this batch
    const batchResultsInThisBatch = await parallel(
      nodesInThisBatch.map((node) => async (cb) => {
        // Fetch metadata from external service if necessary
        let metaData;
        if (!cache.get(node.id)) {
          try {
            metaData = await axios.get(`https://example.com/metadata/${node.id}`);
            cache.put(node.id, metaData.data);
          } catch (err) {
            console.error('Error fetching metadata:', err);
          }
        }

        // Apply filter function
        const filteredNode = filterFunction(node, metaData);

        // Add node to batch results and node queue if not filtered out
        if (filteredNode) {
          batchResultsInThisBatch.push(filteredNode);
          nodeQueue.push(...node.children);
        }

        cb();
      })
    );

    return batchResultsInThisBatch;
  }

  async function traverse() {
    while (nodeQueue.length > 0 || batchResults.length > 0) {
      const batchSize = Math.min(nodeQueue.length, 100); // Adjust this value based on performance requirements
      const batchResultsInThisBatch = await processBatch(batchSize);
      batchResults.push(...batchResultsInThisBatch);

      // Print metrics for this batch
      console.log(`Batch processed: ${batchResultsInThisBatch.length} nodes`);
      console.log(`Memory usage: ${process.memoryUsage().rss / 1024 / 1024} MB`);
    }

    return batchResults;
  }

  nodeQueue.push(...domTree.children);
  return traverse();
}
