    for (const moduleName in loadedModules) {
      try {
        await loadedModules[moduleName].init();
        executedModules[moduleName] = loadedModules[moduleName];
      } catch (error) {
        console.error(`Error executing module ${moduleName}:`, error);
      }
    }
    return executedModules;
  }

  async function main() {
    const modules = ['module1', 'module2', 'module3'];
