import java.io.IOException;
import java.net.InetSocketAddress;
import java.nio.channels.SelectionKey;
import java.nio.channels.Selector;
import java.nio.channels.ServerSocketChannel;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.atomic.AtomicInteger;

public class ConnectionManager {

    private static final int PORT = 8080;
    private static final int TIMEOUT_MILLIS = 30000; // 30 seconds
    private static final int MAX_CONNECTIONS = 100;
    private static final AtomicInteger activeConnections = new AtomicInteger(0);

    private List<ServerSocketChannel> availableChannels = new ArrayList<>();
    private Selector selector;

    public ConnectionManager() throws IOException {
        this.selector = Selector.open();
    }

    public void startListening() throws IOException {
        ServerSocketChannel channel = ServerSocketChannel.open();
        channel.socket().bind(new InetSocketAddress(PORT));
        channel.configureBlocking(false);
        channel.register(selector, SelectionKey.OP_ACCEPT);
        availableChannels.add(channel);

        new Thread(() -> listenForConnections()).start();
    }

    private void listenForConnections() {
        while (true) {
            try {
                selector.select(TIMEOUT_MILLIS);
                for (SelectionKey key : selector.selectedKeys()) {
                    ServerSocketChannel channel = (ServerSocketChannel) key.channel();
                    channel.configureBlocking(false);

                    channel.register(selector, SelectionKey.OP_ACCEPT);

                    if (!channel.isOpen()) {
                        continue;
                    }

                    try {
                        SocketChannel socketChannel = channel.accept();
                        handleConnection(socketChannel);
                    } catch (IOException e) {
                        // Handle IO exception
                    }
                }
                selector.selectedKeys().clear();
            } catch (IOException | InterruptedException e) {
                // Handle exceptions
            }
        }
    }

    private void handleConnection(SocketChannel socketChannel) throws IOException {
        try {
            socketChannel.configureBlocking(false);
            socketChannel.register(selector, SelectionKey.OP_READ);

            int bytesRead = 0;
            while ((bytesRead = socketChannel.read(new byte[1024])) > 0) {
                // Handle incoming data
            }

            if (socketChannel.isOpen()) {
                socketChannel.close();
            }
        } finally {
            if (!socketChannel.isOpen()) {
                return;
            }

            try {
                socketChannel.close();
            } catch (IOException e) {
                // Handle IO exception
            }
        }
    }

    public void stopListening() throws IOException {
        selector.wakeup();
        availableChannels.forEach(ServerSocketChannel::close);
        availableChannels.clear();
        selector.close();
    }

    public int getActiveConnections() {
        return activeConnections.get();
    }

    public void logConnectionActivity(String message) {
        // Log connection activity
    }
}
