@app.before_request
def before_request():
    # Check if session token is expired and invalidate it if necessary
    if 'session_token' in session:
        if datetime.datetime.strptime(session['session_token'], '%Y-%m-%d %H:%M:%S') < datetime.datetime.now() - datetime.timedelta(minutes=30):
            session.clear()
            return jsonify({'error': 'Session token has expired'}), 401

    # Verify and set user's preferred locale
    if 'locale' not in session:
        session['locale'] = 'en-US'

@app.after_request
def after_request(response):
    # Log all session-related activities
    logging.info(f"Session activity: {request.method} {request.path}")

    return response

@app.route('/refresh_token', methods=['POST'])
def refresh_token():
    if request.method == 'POST':
        try:
            # Verify and decode the token using JWT
            decoded_token = jwt.decode(session['session_token'], app.config['SECRET_KEY'], algorithms=['HS256'])

            # Refresh token with the external authentication service
            new_token = authenticate_service().refresh_token(decoded_token['user_id'])

            # Update session token
            session['session_token'] = datetime.datetime.now().strftime('%Y-%m-%d %H:%M:%S')
            r.set('session_token', session['session_token'])
        except jwt.ExpiredSignatureError:
            return jsonify({'error': 'Token has expired'}), 401

    return jsonify({'message': 'Token refreshed successfully'})

@app.route('/update_locale', methods=['POST'])
def update_locale():
    if request.method == 'POST':
        try:
            # Verify and decode the token using JWT
            decoded_token = jwt.decode(session['session_token'], app.config['SECRET_KEY'], algorithms=['HS256'])

            # Update user's preferred locale
            session['locale'] = request.get_json()['locale']

            # Log the update
            logging.info(f"User {decoded_token['user_id']} updated their locale to {session['locale']}")

        except jwt.ExpiredSignatureError:
            return jsonify({'error': 'Token has expired'}), 401

    return jsonify({'message': 'Locale updated successfully'})

@app.route('/update_user_data', methods=['POST'])
def update_user_data():
    if request.method == 'POST':
        try:
            # Verify and decode the token using JWT
            decoded_token = jwt.decode(session['session_token'], app.config['SECRET_KEY'], algorithms=['HS256'])

            # Update user's data (e.g., name, email)
            session['user_data'] = request.get_json()

            # Log the update
            logging.info(f"User {decoded_token['user_id']} updated their data")

        except jwt.ExpiredSignatureError:
            return jsonify({'error': 'Token has expired'}), 401

    return jsonify({'message': 'Data updated successfully'})

@app.route('/validate_session', methods=['GET'])
def validate_session():
    try:
        # Verify and decode the token using JWT
        decoded_token = jwt.decode(session['session_token'], app.config['SECRET_KEY'], algorithms=['HS256'])

        # Check if user's session is still valid
        if datetime.datetime.strptime(session['session_token'], '%Y-%m-%d %H:%M:%S') < datetime.datetime.now() - datetime.timedelta(minutes=30):
            return jsonify({'error': 'Session token has expired'}), 401

    except jwt.ExpiredSignatureError:
        return jsonify({'error': 'Token has expired'}), 401

    # Session is valid, return the user's data
    return jsonify(session['user_data'])

if __name__ == '__main__':
    app.run(debug=True)
