use std::process::{Command, Output};
use std::time::{Instant, Duration};
use std::fs;
use crossbeam_channel::bounded;

struct ResourceUsageProfiler {
    cpu_usage: f64,
    memory_usage: f64,
}

impl ResourceUsageProfiler {
    fn new() -> Self {
        Self { cpu_usage: 0.0, memory_usage: 0.0 }
    }

    fn update(&mut self, cpu_percent: f64, mem_percent: f64) {
        if cpu_percent > self.cpu_usage {
            self.cpu_usage = cpu_percent;
        }
        if mem_percent > self.memory_usage {
            self.memory_usage = mem_percent;
        }
    }

    fn peak_usage(&self) -> (&f64, &f64) {
        (&&self.cpu_usage, &&self.memory_usage)
    }
}

struct DiskUsageMonitor {
    disk_usage: fs::Metadata,
}

impl DiskUsageMonitor {
    fn new(path: &str) -> Self {
        Self { disk_usage: fs::metadata(path)? }
    }

    fn update(&mut self, path: &str) {
        if let Ok(metadata) = fs::metadata(path) {
            *self = DiskUsageMonitor { disk_usage: metadata };
        }
    }

    fn usage_diff(&self, other: &DiskUsageMonitor) -> (f64, f64) {
        (
            ((other.disk_usage.len() - self.disk_usage.len()) as f64) / 1024.0,
            ((other.disk_usage.len() - self.disk_usage.len()) as f64) * 8.0,
        )
    }
}

struct CommandExecutor {
    commands: Vec<Command>,
    profiler: ResourceUsageProfiler,
    disk_monitor: DiskUsageMonitor,
    signal_handler: Option<std::thread::JoinHandle<()>>,
}

impl CommandExecutor {
    fn new() -> Self {
        Self {
            commands: Vec::new(),
            profiler: ResourceUsageProfiler::new(),
            disk_monitor: DiskUsageMonitor::new("/"),
            signal_handler: None,
        }
    }

    fn run_command(&mut self, command: String) -> Result<Output, Box<dyn std::error::Error>> {
        let start = Instant::now();
        let output = Command::new("your_custom_tool")
            .arg("any_args")
            .output()
            .map_err(|e| format!("Command execution failed: {}", e))?;
        self.profiler.update(output.stdout_count as f64, output.stderr_count as f64);
        let end = Instant::now();
        println!("Command executed in {:.2?}", end - start, command);

        Ok(output)
    }

    fn monitor_disk_usage(&mut self) -> (f64, f64) {
        let usage_diff = self.disk_monitor.usage_diff(&DiskUsageMonitor::new("/"));
        println!("Disk usage: {}/{},", usage_diff.0, usage_diff.1);
        usage_diff
    }
}

fn main() {
    // Initialize the command executor and signal handler
    let mut cmd_executor = CommandExecutor::new();
    let signal_handler = std::thread::spawn(move || {
        // Handle signals here
        // ...
    });
    cmd_executor.signal_handler = Some(signal_handler);

    // Run commands concurrently, limit maximum concurrency to prevent overload
    const MAX_CONCURRENCY: usize = 5;
    let (tx, rx) = crossbeam_channel::bounded(MAX_CONCURRENCY);
    for _ in 0..10 {
        tx.send("your_custom_tool".to_string()).unwrap();
    }
    while let Ok(cmd) = rx.recv() {
        match cmd_executor.run_command(cmd) {
            Ok(output) => {
                // Handle command output
                // ...
            }
            Err(err) => {
                eprintln!("Error running command: {}", err);
                // Exit cleanly
                std::process::exit(1);
            }
        }
    }
}
