    while (old_logs != NULL) {
        USER_ACTIVITY_LOG* log = old_logs->data;
        // Compress the log using zlib
        deflateInit2(&zstream, Z_DEFAULT_COMPRESSION);
        compress_log(log, &zstream);
        deflateEnd(&zstream);

        // Write the compressed log to the file
        fwrite(zstream.next_in, 1, zstream.total_out, compressed_file);

        old_logs = old_logs->next;
    }
    fclose(compressed_file);

    // Archive the compressed logs
    system("tar -czf archived_logs.tar.gz compressed_logs.bin");
}
