import os
import hashlib

def rename_files_based_on_content_hash(directory):
    # Iterate over files in the directory
    for filename in os.listdir(directory):
        filepath = os.path.join(directory, filename)

        if os.path.isfile(filepath):  # Check if it's a file
            with open(filepath, 'rb') as f:
                # Calculate MD5 hash of the file contents
                md5_hash = hashlib.md5(f.read()).hexdigest()

                # Rename the file by appending a unique identifier derived from its content hash
                new_filename = f"{md5_hash[:8]}_{filename}"
                os.rename(filepath, os.path.join(directory, new_filename))

        elif os.path.isdir(filepath):  # Check if it's a directory
            rename_files_based_on_content_hash(filepath)  # Recursively call the function

    print("Files renamed successfully.")
```

Here is the code block for calculating the MD5 hash of a large file given its path:

```python
import hashlib

def calculate_file_md5_hash(file_path):
    # Initialize MD5 hash object
    md5_hash = hashlib.md5()

    # Open the file in binary mode
    with open(file_path, 'rb') as f:
        # Read the file contents in chunks to minimize memory usage
        chunk_size = 65536
        while True:
            chunk = f.read(chunk_size)

            if not chunk:  # Check for end of file
                break

            md5_hash.update(chunk)

    return md5_hash.hexdigest()
