        time_t creationTime = fileStat.st_ctime;
        time_t modificationTime = fileStat.st_mtime;

        uint32_t checksum = 0;
        // Calculate the checksum using a suitable algorithm (e.g., Adler-32 or CRC-32)

        pthread_mutex_lock(&metadataMutex);
        metadataCache[i].fileSize = fileSize;
        metadataCache[i].creationTime = creationTime;
        metadataCache[i].modificationTime = modificationTime;
        metadataCache[i].checksum = checksum;

        strcpy(metadataCache[i].filename, entry->d_name);

        i++;
        if (i >= MAX_METADATA_CACHE_SIZE) {
            pthread_mutex_unlock(&metadataMutex);
            break;
        }

        pthread_mutex_unlock(&metadataMutex);

        close(fd);
    }
