using System;
using System.Collections.Generic;
using System.Linq;
using System.Xml.XPath;
using System.Threading;
using System.Threading.Tasks;

public class HttpPduManager
{
    private List<HttpPdu> _pdus = new List<HttpPdu>();

    public void ParseXml(string xmlDocument, string xpathQuery)
    {
        XPathNavigator navigator = XPathDocument.Load(xmlDocument).CreateNavigator();
        XPathNodeIterator iterator = navigator.Select(xpathQuery);

        foreach (XPathNavigator node in iterator)
        {
            HttpPdu pdu = new HttpPdu();
            pdu.TransactionId = Guid.NewGuid().ToString();

            foreach (XmlNode child in node.Descendants())
            {
                if (child.Name == "HTTP_HEADER")
                {
                    pdu.Headers.Add(new Header(child["Name"].Value, child["Value"].Value));
                }
                else if (child.Name == "STATUS_CODE")
                {
                    pdu.StatusCode = int.Parse(child.Value);
                }
                else if (child.Name == "PAYLOAD")
                {
                    pdu.Payload = child.InnerText;
                }
            }

            _pdus.Add(pdu);
        }
    }

    public List<HttpPdu> GetPdus()
    {
        return _pdus;
    }

    public void SerializePdus(string filePath)
    {
        using (FileStream stream = new FileStream(filePath, FileMode.Create))
        {
            BinaryFormatter formatter = new BinaryFormatter();
            PduMessage message = new PduMessage(_pdus.ToArray());

            formatter.Serialize(stream, message);
        }
    }

    public List<HttpPdu> DeserializePdus(string filePath)
    {
        using (FileStream stream = new FileStream(filePath, FileMode.Open))
        {
            BinaryFormatter formatter = new BinaryFormatter();
            PduMessage message = (PduMessage)formatter.Deserialize(stream);

            return message.GetData();
        }
    }

    public void AdjustPduCount()
    {
        int availableResources = GetAvailableResources();
        int pduCount = _pdus.Count;

        if (pduCount > availableResources)
        {
            _pdus.Clear();
        }
        else if (pduCount < availableResources * 0.75f)
        {
            // dynamically adjust pdu count
            _pdus.AddRange(Enumerable.Repeat(new HttpPdu(), availableResources - pduCount));
        }
    }

    public void LogCreationProcess()
    {
        Console.WriteLine("Created PDU list with {0} elements.", _pdus.Count);
    }
}

public class PduMessage : ISerializable
{
    private byte[] _data;

    public PduMessage(byte[] data)
    {
        _data = data;
    }

    public List<HttpPdu> GetData()
    {
        List<HttpPdu> pdus = new List<HttpPdu>();

        using (MemoryStream stream = new MemoryStream(_data))
        {
            BinaryFormatter formatter = new BinaryFormatter();
            HttpPdu[] pduArray = (HttpPdu[])formatter.Deserialize(stream);

            foreach (HttpPdu pdu in pduArray)
            {
                pdus.Add(pdu);
            }
        }

        return pdus;
    }
}

public class HttpPdu
{
    public Guid TransactionId { get; set; }
    public List<Header> Headers { get; set; }
    public int StatusCode { get; set; }
    public string Payload { get; set; }
}

public class Header
{
    public string Name { get; set; }
    public string Value { get; set; }

    public Header(string name, string value)
    {
        Name = name;
        Value = value;
    }
}
