import com.fasterxml.jackson.databind.JsonNode;
import com.fasterxml.jackson.databind.ObjectMapper;
import com.fasterxml.jackson.databind.node.ObjectNode;
import com.fasterxml.jackson.module.jsonSchema.FastJackson2Module;
import org.apache.commons.lang3.tuple.Pair;

public class OrderItemProcessor {
    public static List<ORDER_ITEM_T> processLargeJSONDocument(String jsonFile, String schemaFile) throws Exception {
        ObjectMapper mapper = new ObjectMapper();
        mapper.registerModule(new FastJackson2Module());

        // Load JSON document
        JsonNode rootNode = mapper.readTree(jsonFile);

        // Validate JSON schema
        JsonNode schemaRoot = mapper.readTree(schemaFile);
        if (!schemaRoot.equals(rootNode)) {
            throw new Exception("JSON does not match the specified schema");
        }

        // Filter elements based on key-path pattern
        List<ORDER_ITEM_T> orderItems = new ArrayList<>();
        String keyPathPattern = "path.to.element";
        for (JsonNode element : rootNode) {
            if (element.get(keyPathPattern).isTextual()) {
                ORDER_ITEM_T orderItem = new ORDER_ITEM_T();
                // Set values from JSON node
                orderItem.setProductID(element.get("product_id").asInt());
                orderItem.setQuantity(element.get("quantity").asInt());
                orderItem.setPrice(element.get("price").asDouble());
                orderItem.setCustomerInfo(element.get("customer_info").toString());
                orderItems.add(orderItem);
            }
        }

        if (orderItems.isEmpty()) {
            throw new Exception("No element found for key-path pattern: " + keyPathPattern);
        }

        return orderItems;
    }
}
