void dynamic_list_init(DynamicList* list) {
    pthread_mutex_init(&list->mutex, NULL);
    list->data = (NR_API_RLC_STATUS_PDU_T*)malloc(BUFFER_SIZE);
    list->size = 0;
    list->capacity = MAX_SIZE;
}

int dynamic_list_add(DynamicList* list, NR_API_RLC_STATUS_PDU_T* element) {
    if (list->size >= list->capacity) {
        // Handle memory allocation failure gracefully
        printf("Dynamic list is full. Cannot add new elements.\n");
        return -1;
    }

    pthread_mutex_lock(&list->mutex);
    list->data[list->size] = *element;
    list->size++;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

int dynamic_list_remove(DynamicList* list, int index) {
    if (index >= list->size || index < 0) {
        printf("Invalid index. Cannot remove element.\n");
        return -1;
    }

    pthread_mutex_lock(&list->mutex);
    for (int i = index; i < list->size - 1; i++) {
        list->data[i] = list->data[i + 1];
    }
    list->size--;
    pthread_mutex_unlock(&list->mutex);

    return 0;
}

NR_API_RLC_STATUS_PDU_T* dynamic_list_get(DynamicList* list, int index) {
    if (index >= list->size || index < 0) {
        printf("Invalid index. Cannot retrieve element.\n");
        return NULL;
    }

    pthread_mutex_lock(&list->mutex);
    NR_API_RLC_STATUS_PDU_T* element = &list->data[index];
    pthread_mutex_unlock(&list->mutex);

    return element;
}

void dynamic_list_flush(DynamicList* list) {
    pthread_mutex_lock(&list->mutex);
    free(list->data);
    list->size = 0;
    pthread_mutex_unlock(&list->mutex);
