typedef struct {
    char* password;
    struct connection {
        char* title;
        char* network_interface_name;
    } connection;
    void (*callback)(void);
} structure_t;

int calculateMD5Hash(char* file_path, structure_t* strcture) {
    int fd = open(file_path, O_RDONLY);
    if (fd < 0) {
        return -1; // Error opening the file
    }

    MD5_CTX ctx;
    unsigned char md5[16];
    MD5_Init(&ctx);

    struct stat sb;
    fstat(fd, &sb);

    off_t offset = 0;
    size_t chunk_size = 1024 * 1024; // 1MB chunks for large files
    while (offset < sb.st_size) {
        char* buffer = malloc(chunk_size);
        if (!buffer) {
            return -2; // Error allocating memory
        }

        ssize_t read_size = pread(fd, buffer, chunk_size, offset);
        if (read_size < 0) {
            return -3; // Error reading from the file
        }

        MD5_Update(&ctx, buffer, read_size);

        free(buffer);
        offset += read_size;
    }

    MD5_Final(md5, &ctx);

    close(fd);

    printf("MD5 Hash: ");
    for (int i = 0; i < 16; i++) {
        printf("%02x", md5[i]);
    }
    printf("\n");

    return 0; // Success
}
