    size_t totalFrames = 0;

    // Implement robust error handling and retry logic for I/O operations
    FILE* file = fopen(filePath, "rb");
    if (!file) {
        printf("Error opening file: %s\n", filePath);
        return -1;
    }

    int bytesRead;
    while ((bytesRead = fread(buffer, 1, chunkSize, file)) > 0) {
        // Process audio frames
        for (size_t i = 0; i < bytesRead; i++) {
            totalFrames++;
            // Handle decoding and re-sampling on-the-fly
            int decodedFrame = buffer[i];
            // Provide checksums for detecting data corruption
            if (decodedFrame != (int)(buffer[i] & 0xFF)) {
                printf("Error: Data corruption detected\n");
                return -1;
            }
