            fscanf(file, "%d %s %f %s %d\n", &transaction.transaction_id, transaction.timestamp, &transaction.amount, transaction.currency, &transaction.merchant_id);

            // Validate the transaction against predefined business rules
            if (validateTransaction(&transaction)) {
                // Allocate memory for a new node
                NODE* node = (NODE*)malloc(sizeof(NODE));

                if (!node) {
                    printf("Memory allocation failed\n");
                    return;
                }

                node->record = transaction;
                node->next = processed_transactions;
                processed_transactions = node;
            } else {
                // Log the rejected transaction
                logTransaction(&transaction, "REJECTED");
            }

            num_transactions++;
        }

        fclose(file);
    }

    // Close and free memory for processed transactions
    NODE* current = processed_transactions;

    while (current) {
        NODE* next = current->next;
        free(current);
        current = next;
    }
}

int validateTransaction(TRANSACTION_RECORD* transaction) {
    // Validate the transaction against predefined business rules
    if (/* validation criteria */) {
        return 1;  // Approved
    } else {
        return 0;  // Declined or requires further review
    }
}

void logTransaction(TRANSACTION_RECORD* transaction, char status[10]) {
    // Log the transaction
    printf("Last modified timestamp: %s, Transaction ID: %d, Session ID: %s, Status: %s\n", transaction->timestamp, transaction->transaction_id, /* session ID */, status);
}

int main() {
    processTransactionData();
    return 0;
}
