// Define the structure for MAC_PDU
typedef struct {
    // Other fields...
    MAC_COMMAND_PDU command_pdu;
    MAC_DATA_PDU data_pdu;
} MAC_PDU;

// Define the structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    RX_UE_INFORMATION_TAG rx_ue_info_tag;
    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication_rel8_tag;
    int crc_flag;
} NFAPI_CRC_INDICATION_PDU_T;

// Define the dynamic array of MAC_PDU structures
typedef struct {
    size_t capacity;
    size_t size;
    MAC_PDU* arr;
    pthread_mutex_t mutex;
} PDU_ARRAY;

// Function to initialize the PDU array
PDU_ARRAY* pdu_array_init(size_t initial_capacity) {
    PDU_ARRAY* array = (PDU_ARRAY*)malloc(sizeof(PDU_ARRAY));
    array->capacity = initial_capacity;
    array->size = 0;
    array->arr = (MAC_PDU*)calloc(initial_capacity, sizeof(MAC_PDU));
    pthread_mutex_init(&array->mutex, NULL);
    return array;
}

// Function to add a new PDU pair
void pdu_array_add(PDU_ARRAY* array, MAC_PDU* new_pdu) {
    pthread_mutex_lock(&array->mutex);

    if (array->size == array->capacity) {
        // Double the capacity and reallocate memory
        size_t new_capacity = array->capacity * 2;
        array->arr = (MAC_PDU*)realloc(array->arr, sizeof(MAC_PDU) * new_capacity);
        array->capacity = new_capacity;
    }

    array->arr[array->size] = *new_pdu;
    array->size++;

    pthread_mutex_unlock(&array->mutex);
}

// Function to update an existing PDU pair
void pdu_array_update(PDU_ARRAY* array, size_t index, MAC_PDU* updated_pdu) {
    pthread_mutex_lock(&array->mutex);

    if (index >= array->size || index < 0) {
        // Handle out-of-range error
        pthread_mutex_unlock(&array->mutex);
        return;
    }

    array->arr[index] = *updated_pdu;

    pthread_mutex_unlock(&array->mutex);
}

// Function to get the total number of entries
size_t pdu_array_size(PDU_ARRAY* array) {
    pthread_mutex_lock(&array->mutex);

    size_t result = array->size;

    pthread_mutex_unlock(&array->mutex);

    return result;
}

// Function to pause and resume data collection
void pdu_array_pause_resume(PDU_ARRAY* array, int paused) {
    pthread_mutex_lock(&array->mutex);

    if (paused) {
        // Pause data collection
        array->size = 0; // Reset the size to avoid data corruption
    } else {
        // Resume data collection
        // No need to reset the size as it was saved before pausing
    }

    pthread_mutex_unlock(&array->mutex);
}

// Function to handle asynchronous events related to external services
void pdu_array_handle_events(PDU_ARRAY* array, ...) {
    // Handle events related to external services...
}
