void generate_list(NFAPI_CRC_INDICATION_PDU_T* list, int n) {
    srand(time(NULL));
    int rnti_count = 0; // count of unique RNTI values
    for(int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;
        strcpy(pdu.RX_UE_INFORMATION_TAG, "RX_UE_INFORMATION_TAG");
        pdu.RNTI = (i + rnti_count) % M; // ensure uniqueness and reuse
        pdu.CRCFLAG = rand() & 1; // set CRCFLAG randomly

        list[i] = pdu;

        if(i > 0 && list[i].RNTI == list[i-1].RNTI) {
            i--; // backtrack to try a different RNTI value
            rnti_count = (rnti_count + 1) % M; // increment and wrap around
        }
    }
}

int serialize_list(const NFAPI_CRC_INDICATION_PDU_T* list, const char* filename, int n) {
    FILE* file = fopen(filename, "wb");
    if(file == NULL) {
        printf("Error opening file for writing.\n");
        return 1;
    }

