uint8_t errorFlag = 0;

typedef struct {
    uint16_t rx_ue_info_tag;
    uint16_t rnti;
    uint32_t crc_indication_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

void* allocatePduArray(uint16_t N, uint16_t seed) {
    if (N > MAX_PDU_COUNT) {
        printf("Error: Maximum pdu count exceeded.\n");
        errorFlag = 1;
        return NULL;
    }

    std::random_device rd;
    std::mt19937 gen(rd());
    std::uniform_int_distribution<uint16_t> distribution(0, (1 << 15) - 1);

    NFAPI_CRC_INDICATION_PDU_T* pduArray = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pduArray) {
        errorFlag = 1;
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    uint16_t uniqueTags[2] = {0};
    for (uint16_t i = 0; i < N; i++) {
        pduArray[i].rx_ue_info_tag = distribution(gen);
        while (std::find(uniqueTags, uniqueTags + 2, pduArray[i].rx_ue_info_tag) != uniqueTags + 2)
            pduArray[i].rx_ue_info_tag = distribution(gen);

        pduArray[i].rnti = distribution(gen);

        if (i % 2 == 0)
            pduArray[i].crc_indication_rel8_tag = i;
        else
            pduArray[i].crc_indication_rel8_tag = i + 1;

        pduArray[i].crcflag = ((i & 1) == 1) ? 1 : 0;

        uniqueTags[0] = pduArray[i].rx_ue_info_tag;
        uniqueTags[1] = pduArray[i].rnti;
    }

    uint16_t crcIndicationsWithFlag = 0;
    for (uint16_t i = 0; i < N; i++)
        if (pduArray[i].crcflag == 1)
            crcIndicationsWithFlag++;

    return pduArray;
}
