#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <unistd.h>
#include <sys/types.h>
#include <sys/stat.h>
#include <fcntl.h>

typedef struct {
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* create_list(int M, int N) {
    // initialize variables
    int unique_RNTIs = 0;
    int current_RNTI = rand() % M; // start with a random RNTI value
    int rnti_count[M] = {0}; // keep track of used RNTIs

    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for(int i = 0; i < N; i++) {
        if(rnti_count[current_RNTI]++ >= M) {
            // restart RNTI counter from the beginning
            current_RNTI = (current_RNTI + 1) % M;
        }

        list[i].RNTI = current_RNTI;
        list[i].CRCFLAG = rand() & 0xFF; // random CRC flag

        if(unique_RNTIs++ >= M) {
            break; // reached maximum RNTI count
        }
    }

    return list;
}

