        indications[i].crc_indication_rel8_tag.crcflag = rand() % 2;

        // Add more structure fields as needed
    }

    return indications;
}

uint32_t computeMD5Hash(const char* input) {
    MD5_CTX ctx;
    unsigned char hash[16];

    MD5_Init(&ctx);
    MD5_Update(&ctx, input, strlen(input));
    MD5_Final(hash, &ctx);

    uint32_t result = 0;

    for (int i = 0; i < 4; i++) {
        result |= ((uint32_t)hash[i * 4]) << (i * 8);
    }

    return result;
}
