void read_file_and_populate_structures(int n, int m) {
    FILE *file = fopen("input.txt", "r");
    if (file == NULL) {
        printf("Error opening file.\n");
        return;
    }

    srand(time(NULL));

    NFAPI_CRC_INDICATION_PDU_T *list = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int *rti_count = calloc(m, sizeof(int));
    int current_rnti = -1;
    int last_rnti = -1;

