void insert(struct list_node** head_ref, NFAPI_CRC_INDICATION_PDU_T data) {
    struct list_node* new_node = (struct list_node*)malloc(sizeof(struct list_node));
    new_node->data = data;
    pthread_mutex_lock(&list_mutex);
    if (*head_ref == NULL) {
        *head_ref = new_node;
    } else {
        new_node->next = *head_ref;
        *head_ref = new_node;
    }
    pthread_mutex_unlock(&list_mutex);
}

void* serialize(void*) {
