typedef struct {
    char RX_UE_INFORMATION_TAG[20];
    int RNTI;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to populate the list
void* create_list(int n, int m) {
    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) return NULL;

    int unique_rnti_count = 0;
    int rnti_values[10000]; // assuming max m is 10,000
    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!data) return NULL;

        // Generate random RNTI
        int rnti = rand() % m;
        while (rnti_values[rnti] > 0 && unique_rnti_count < m) {
            rnti = (rnti + 1) % m;
        }
        if (unique_rnti_count >= m) {
            int recycle_index = rnti - (rnti % m);
            while (rnti_values[recycle_index] > 0 && unique_rnti_count < m) {
                recycle_index = (recycle_index + 1) % m;
            }
            if (unique_rnti_count >= m) {
                free(data); // recycle the RNTI
                return NULL; // failed to create list
            }
        }

        data->RNTI = rnti_values[rnti] = i + 1;
        strcpy(data->RX_UE_INFORMATION_TAG, "Random Tag");
        data->CRCFLAG = rand() % 2;

        if (list[i]) free(list[i]);
        list[i] = data;

        unique_rnti_count++;
    }

    return list;
}

// Function to serialize the list
int serialize_list(NFAPI_CRC_INDICATION_PDU_T** list, int n) {
    int fd = open("output.bin", O_CREAT | O_RDWR, 0644);
    if (fd < 0) return -1;

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* data = list[i];
        if (!data) break;
        write(fd, &data->RNTI, sizeof(int));
        write(fd, data->RX_UE_INFORMATION_TAG, strlen(data->RX_UE_INFORMATION_TAG) + 1);
        write(fd, &data->CRCFLAG, sizeof(uint8_t));

        free(data);
    }

    close(fd);
    return 0;
}

// Function to deserialize the list
NFAPI_CRC_INDICATION_PDU_T** deserialize_list(int n) {
    NFAPI_CRC_INDICATION_PDU_T** list = (NFAPI_CRC_INDICATION_PDU_T**)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!list) return NULL;

    int fd = open("output.bin", O_RDONLY);
    if (fd < 0) return NULL;

    for (int i = 0; i < n; i++) {
        NFAPI_CRC_INDICATION_PDU_T* data = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        read(fd, &data->RNTI, sizeof(int));
        char tag[21]; // to account for null terminator
        read(fd, tag, 20);
        tag[20] = '\0';
        data->RX_UE_INFORMATION_TAG = (char*)malloc(strlen(tag) + 1);
        strcpy(data->RX_UE_INFORMATION_TAG, tag);

        read(fd, &data->CRCFLAG, sizeof(uint8_t));

        list[i] = data;
    }

    close(fd);
    return list;
}
