int read_binary_file(const char* filename, List* list) {
    int fd = open(filename, O_RDONLY);
    if (fd < 0) {
        perror("open");
        return -1;
    }

    struct stat sb;
    fstat(fd, &sb);

    void* buffer = mmap(NULL, sb.st_size, PROT_READ, MAP_SHARED, fd, 0);
    if (buffer == MAP_FAILED) {
        perror("mmap");
        close(fd);
        return -1;
