            printf("Duplicate cell ID found. Skipping.\n");
            return;
        }
    }
    *array = realloc(*array, (size + 1) * sizeof(LTE_PHY_STATS_PDU_T));
    (*array)[size].phy_layer_status = rand() % 100;
    (*array)[size].cell_id = cell_id;
    (*array)[size].tx_power_level = tx_power_level;
}

int find_cell_id(LTE_PHY_STATS_PDU_T** array, int size, int target_cell_id) {
    for (int i = 0; i < size; i++) {
        if ((*array)[i].cell_id == target_cell_id) {
            return i;
        }
    }
    return -1; // cell ID not found
}

void update_tx_power_level(LTE_PHY_STATS_PDU_T** array, int size, int cell_id, int new_tx_power_level) {
