    }
}

int serialize_array(LTE_PHY_STATS_PDU_T** array, int size, FILE* file) {
    int bytes_written = 0;
    for (int i = 0; i < size; i++) {
        fwrite(&((*array)[i].phy_layer_status), sizeof(int), 1, file);
        fwrite(&((*array)[i].cell_id), sizeof(int), 1, file);
        fwrite(&((*array)[i].tx_power_level), sizeof(int), 1, file);
        bytes_written += 3 * sizeof(int);
    }
    return bytes_written;
}

int deserialize_array(LTE_PHY_STATS_PDU_T*** deserialized_array_ptr, FILE* file) {
