    int bytes_read = 0;
    while (fread(&size, sizeof(int), 1, file) == 1) {
        *deserialized_array_ptr = realloc(*deserialized_array_ptr, (size + 1) * sizeof(LTE_PHY_STATS_PDU_T));
        for (int i = 0; i < size; i++) {
