    LTE_PHY_STATS_PDU_T* new_element = (LTE_PHY_STATS_PDU_T*)malloc(sizeof(LTE_PHY_STATS_PDU_T));
    new_element->PHY_LAYER_STATUS = phy_layer_status;
    new_element->CELL_ID = cell_id;
    new_element->TX_POWER_LEVEL = tx_power_level;

    if (array_size == 0 || !duplicate_cell_id(new_element->CELL_ID)) {
        lte_phy_stats_pdu_array = realloc(lte_phy_stats_pdu_array, (array_size + 1) * sizeof(LTE_PHY_STATS_PDU_T*));
        lte_phy_stats_pdu_array[array_size++] = new_element;
    } else {
        free(new_element);
    }
}

int duplicate_cell_id(int cell_id) {
    for (int i = 0; i < array_size; i++) {
        if (lte_phy_stats_pdu_array[i]->CELL_ID == cell_id) {
            return 1;
        }
    }
    return 0;
}

