void deserialize_from_file(char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) {
        printf("Error opening file for reading.\n");
        return;
    }

    int serialized_size;
    fread(&serialized_size, sizeof(int), 1, file);

    lte_phy_stats_pdu_array = (LTE_PHY_STATS_PDU_T*)malloc(serialized_size * sizeof(LTE_PHY_STATS_PDU_T));
    fread(lte_phy_stats_pdu_array, sizeof(LTE_PHY_STATS_PDU_T), serialized_size, file);

    fclose(file);
}

void update_tx_power_level(int cell_id, int new_tx_power_level) {
    for (int i = 0; i < array_size; i++) {
        if (lte_phy_stats_pdu_array[i]->CELL_ID == cell_id) {
            lte_phy_stats_pdu_array[i]->TX_POWER_LEVEL = new_tx_power_level;
