int add_element(LTE_PHY_STATS_PDU_T** arr, uint32_t* size, uint16_t new_cell_id) {
    *size += 1;
    (*arr) = (LTE_PHY_STATS_PDU_T**) realloc((*arr), sizeof(LTE_PHY_STATS_PDU_T*) * (*size));

    for(int i = 0; i < *size - 1; i++) {
        if((*arr)[i]->cell_id == new_cell_id) return -1;
    }

    (*arr)[*size - 1] = malloc(sizeof(LTE_PHY_STATS_PDU_T));
    (*arr)[*size - 1]->phy_layer_status = rand() % 100; 
    (*arr)[*size - 1]->cell_id = new_cell_id;
    (*arr)[*size - 1]->tx_power_level = rand() % 10;

