    for(int i = 0; i < size; i++) {
        fwrite(&((*arr)[i]->phy_layer_status), sizeof(int), 1, file);
        fwrite(&((*arr)[i]->cell_id), sizeof(uint16_t), 1, file);
        fwrite(&((*arr)[i]->tx_power_level), sizeof(int), 1, file);
    }

    return 0;
}

