NFAPI_CRC_INDICATION_PDU_T** get_array() {
    static struct array_handler handler = {0};
    if (!handler.array) {
        handler.array = (NFAPI_CRC_INDICATION_PDU_T**)malloc((MAX_ELEMENTS+1)*sizeof(NFAPI_CRC_INDICATION_PDU_T*));
        handler.size = 0;
        pthread_mutex_init(&handler.mutex, NULL);
    }
    return &handler.array;
}

int add_element(int rnti) {
