    pthread_mutex_lock(&array->mutex);
    if (array->size >= MAX_ELEMENTS) {
        printf("Array is full. Cannot add more elements.\n");
        pthread_mutex_unlock(&array->mutex);
        return -1;
    }
    NFAPI_CRC_INDICATION_PDU_T* element = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    // Initialize your CRCFLAG here with a random value between 0 and CRCFLAG_MAX_VALUE
    element->crc_indication_rel8_tag.crcflag = rand() % CRCFLAG_MAX_VALUE;
    array->array[array->size] = element;
    array->size++;
