        printf("Invalid index. Cannot retrieve element.\n");
        pthread_mutex_unlock(&array->mutex);
        return NULL;
    }
    NFAPI_CRC_INDICATION_PDU_T* element = array->array[index];
    pthread_mutex_unlock(&array->mutex);
    return element;
}

int clear_array() {
    NFAPI_CRC_INDICATION_PDU_T** array = get_array();
    pthread_mutex_lock(&array->mutex);
    for (int i = 0; i < array->size; i++) {
        free(array->array[i]);
    }
    free(array->array);
    array->size = 0;
    pthread_mutex_unlock(&array->mutex);
    return 0;
}

void print_array() {
