// Function to manage a dynamic array of LTE_PHY_STATS_PDU_T structures
int manage_phy_stats_array(int *phy_stats_array, int *array_size) {
    // Create a new array with double the size if it overflows
    if (*array_size == 0 || (*array_size << 1) > *array_size) {
        *array_size <<= 1;
        phy_stats_array = realloc(phy_stats_array, sizeof(LTE_PHY_STATS_PDU_T) * *array_size);
    }

    // Generate random values for new array elements
    for (int i = 0; i < *array_size; i++) {
        LTE_PHY_STATS_PDU_T* current_pdu = &phy_stats_array[i];
        current_pdu->phy_layer_status = rand() % 100;
        current_pdu->cell_id = rand() % 10000;
        current_pdu->tx_power_level = rand() % 20 + 1;
    }

    return 0;
}

// Function to serialize the array to a file
int serialize_phy_stats_array(const LTE_PHY_STATS_PDU_T* phy_stats_array, int array_size, const char* filename) {
    FILE *file = fopen(filename, "wb");
    if (file == NULL) {
        return -1; // Error opening file
    }

    fwrite(&array_size, sizeof(int), 1, file);
    for (int i = 0; i < array_size; i++) {
        LTE_PHY_STATS_PDU_T pdu = phy_stats_array[i];
        fwrite(&pdu.phy_layer_status, sizeof(int), 1, file);
        fwrite(&pdu.cell_id, sizeof(int), 1, file);
        fwrite(&pdu.tx_power_level, sizeof(int), 1, file);
    }

    fclose(file);
    return 0;
}

// Function to deserialize the array from a file
int deserialize_phy_stats_array(LTE_PHY_STATS_PDU_T** phy_stats_array, int* array_size, const char* filename) {
    FILE *file = fopen(filename, "rb");
    if (file == NULL) {
        return -1; // Error opening file
    }

    fread(array_size, sizeof(int), 1, file);
    *phy_stats_array = malloc(sizeof(LTE_PHY_STATS_PDU_T) * *array_size);

    for (int i = 0; i < *array_size; i++) {
        LTE_PHY_STATS_PDU_T* current_pdu = &(*phy_stats_array)[i];
        fread(&current_pdu->phy_layer_status, sizeof(int), 1, file);
        fread(&current_pdu->cell_id, sizeof(int), 1, file);
        fread(&current_pdu->tx_power_level, sizeof(int), 1, file);
    }

    fclose(file);
    return 0;
}

// Function to update the TX power level for a specific cell ID
int update_tx_power_level(LTE_PHY_STATS_PDU_T* phy_stats_array, int array_size, int cell_id, int new_tx_power_level) {
    for (int i = 0; i < array_size; i++) {
        if (phy_stats_array[i].cell_id == cell_id) {
            phy_stats_array[i].tx_power_level = new_tx_power_level;
            return 0;
        }
    }

    return -1; // Cell ID not found
}

int main() {
    int array_size = 10;

    LTE_PHY_STATS_PDU_T* phy_stats_array = malloc(sizeof(LTE_PHY_STATS_PDU_T) * array_size);
    if (phy_stats_array == NULL) {
        return -1;
    }

    manage_phy_stats_array(&phy_stats_array, &array_size);

    // Serialize the array to a file
    serialize_phy_stats_array(phy_stats_array, array_size, "phy_stats.bin");

    free(phy_stats_array);

    return 0;
}

