#include <string.h>

typedef struct {
    char ip_address[16];
    uint16_t port_number;
    time_t last_seen_timestamp;
    int conn_state;
} TCP_CONNECTION_INFO_T;

typedef struct {
    TCP_CONNECTION_INFO_T* connections;
    size_t num_connections;
    size_t capacity;
} CONNECTION_LIST_T;

CONNECTION_LIST_T create_connection_list(size_t initial_capacity) {
    CONNECTION_LIST_T list = (CONNECTION_LIST_T)malloc(sizeof(struct));
    list->connections = (TCP_CONNECTION_INFO_T*)calloc(initial_capacity, sizeof(TCP_CONNECTION_INFO_T));
    list->num_connections = 0;
    list->capacity = initial_capacity;
    return list;
}

int add_connection(CONNECTION_LIST_T* list, TCP_CONNECTION_INFO_T connection) {
    if (list->num_connections >= list->capacity) {
        size_t new_capacity = list->capacity * 2 + 1;
        list->connections = (TCP_CONNECTION_INFO_T*)realloc(list->connections, new_capacity * sizeof(TCP_CONNECTION_INFO_T));
        list->capacity = new_capacity;
    }
    strcpy(list->connections[list->num_connections].ip_address, connection.ip_address);
    list->connections[list->num_connections].port_number = connection.port_number;
    list->connections[list->num_connections].last_seen_timestamp = connection.last_seen_timestamp;
    list->connections[list->num_connections].conn_state = connection.conn_state;
    (*list).num_connections++;
    return 0;
}

int serialize_connection_list(CONNECTION_LIST_T* list, FILE* file) {
    size_t i;
    for (i = 0; i < list->num_connections; i++) {
        fwrite(&list->connections[i], sizeof(TCP_CONNECTION_INFO_T), 1, file);
    }
    return 0;
}

int deserialize_connection_list(CONNECTION_LIST_T* list, FILE* file) {
    TCP_CONNECTION_INFO_T connection;
    size_t i;
    for (i = 0; i < list->num_connections; i++) {
        fread(&connection, sizeof(TCP_CONNECTION_INFO_T), 1, file);
        if (connection.port_number == 0) break; // Check for end of file
        add_connection(list, connection);
    }
    return 0;
}

int update_last_seen_timestamp(CONNECTION_LIST_T* list, TCP_CONNECTION_INFO_T connection) {
    size_t i;
    for (i = 0; i < list->num_connections; i++) {
        if (strcmp(list->connections[i].ip_address, connection.ip_address) == 0 && list->connections[i].port_number == connection.port_number) {
            list->connections[i].last_seen_timestamp = connection.last_seen_timestamp;
            return 0;
        }
    }
    return -1; // Connection not found
}

int main() {
    CONNECTION_LIST_T list = create_connection_list(10);

    // Add connections, serialize and deserialize the list

    FILE* file = fopen("connection_list.bin", "wb");
    serialize_connection_list(&list, file);
    fclose(file);

    file = fopen("connection_list.bin", "rb");
    deserialize_connection_list(&list, file);
    fclose(file);

    return 0;
}
