import os
import hashlib

def rename_files_based_on_content_hash(directory_path):
    # Initialize the list of files with varying extensions and sizes
    file_list = []

    # Iterate through the directory and its contents
    for root, dirs, files in os.walk(directory_path):
        for file in files:
            file_path = os.path.join(root, file)

            # Calculate the content hash of each file
            with open(file_path, 'rb') as f:
                file_hash = hashlib.sha256(f.read()).hexdigest()

            # Rename each file by appending a unique identifier derived from its content hash
            new_file_name = f"{file_path}.{file_hash[:8]}"

            try:
                os.rename(file_path, new_file_name)
            except OSError as e:
                if e.errno == 18:  # File too large error
                    retry_count = 0
                    while retry_count < 3:
                        try:
                            os.rename(file_path, new_file_name)
                            break
                        except OSError as e:
                            if e.errno != 18:
                                raise
                            retry_count += 1
                    else:
                        print(f"Failed to rename {file_path} after 3 retries")
                else:
                    raise
            else:
                print(f"Renamed {file_path} to {new_file_name}")
