    // Initialize buffer for aggregated data
    int buffer_size = 1024;
    float* buffer = (float*)malloc(buffer_size * sizeof(float));
    int buffer_index = 0;

    // Initialize flags for data integrity and anomalies
    int data_integrity_issues = 0;
    int anomalies_detected = 0;

    // Process sensor data packets
    for (int i = 0; i < packet_count; i++) {
        SENSOR_DATA_PACKET_T* packet = packets[i];

        // Validate packet integrity
        if (packet->timestamp <= 0 || packet->sensor_id <= 0) {
            printf("Invalid packet: %ld, %d\n", packet->timestamp, packet->sensor_id);
            continue;
        }

        // Add packet value to buffer
        if (buffer_index >= buffer_size) {
            // Resize buffer if necessary
            buffer_size *= 2;
            float* new_buffer = (float*)realloc(buffer, buffer_size * sizeof(float));
            buffer = new_buffer;
        }
        buffer[buffer_index++] = packet->value;

        // Detect anomalies
        if (packet->value > 10.0 || packet->value < -10.0) {
            printf("Anomaly detected: %f at timestamp %ld\n", packet->value, packet->timestamp);
            anomalies_detected++;
        }
    }

    // Validate data integrity
    for (int i = 1; i < buffer_index; i++) {
        if (buffer[i] - buffer[i-1] > 5.0 || buffer[i] - buffer[i-1] < -5.0) {
            printf("Data integrity issue: value mismatch at timestamp %ld\n", packets[0]->timestamp);
            data_integrity_issues++;
        }
    }

    // Print final statistics
    printf("Anomalies detected: %d\n", anomalies_detected);
    printf("Data integrity issues: %d\n", data_integrity_issues);

    free(buffer);
}

int main() {
    SENSOR_DATA_PACKET_T* packets[5];
    int packet_count = 5;

    // Initialize sensor data packets
    for (int i = 0; i < packet_count; i++) {
        packets[i] = (SENSOR_DATA_PACKET_T*)malloc(sizeof(SENSOR_DATA_PACKET_T));
        packets[i]->timestamp = i;
        packets[i]->sensor_id = i + 1;
        packets[i]->value = (float)(i * i);
        packets[i]->metadata = "Metadata for packet";
    }

    process_sensor_data_stream_and_notify_anomalies(packets, packet_count);

    // Free sensor data packets
    for (int i = 0; i < packet_count; i++) {
        free(packets[i]);
    }

    return 0;
}

