        pdu->RX_UE_INFORMATION_TAG = rand() % 100;
        pdu->RNTI = rand() % 1000;
        pdu->CRC_INDICATION_REL8_TAG = rand() % 100;
        pdu->CRCFLAG = rand() % 2;

