            }
        }

        pdu_array[i] = *pdu;
    }

    // Log CRCFLAG values
    FILE* log_file = fopen("crc_log.txt", "a");
    for (int i = 0; i < N; i++) {
        fprintf(log_file, "%d\n", pdu_array[i].CRCFLAG);
