typedef struct {
    char RX_UE_INFORMATION_TAG[256];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[256];
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* allocate_structure(int RNTI) {
    NFAPI_CRC_INDICATION_PDU_T* structure = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!structure) return NULL;
    strcpy(structure->RX_UE_INFORMATION_TAG, "Valid RX UE Information Tag");
    structure->RNTI = RNTI;
    strcpy(structure->CRC_INDICATION_REL8_TAG, "Valid CRC Indication Rel8 Tag");
    int random_CRCFLAG = rand() % 2; // Randomly generate CRCFLAG value
    structure->CRCFLAG = random_CRCFLAG;
    return structure;
}

void populate_array(int N, NFAPI_CRC_INDICATION_PDU_T** array) {
    for (int i = 0; i < N; i++) {
        int RNTI = rand() % 1000; // Generate a unique RNTI value
        NFAPI_CRC_INDICATION_PDU_T* structure = allocate_structure(RNTI);
        if (!structure) break;
        array[i] = structure;
    }
}

void filter_array(NFAPI_CRC_INDICATION_PDU_T** array, int N, int target_RNTI) {
    for (int i = 0; i < N; i++) {
        if (array[i]->RNTI == target_RNTI) {
            printf("Found matching RNTI value: %d\n", array[i]->RNTI);
        }
    }
}

void serialize_array(NFAPI_CRC_INDICATION_PDU_T** array, int N, char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return;
    for (int i = 0; i < N; i++) {
        fwrite(array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    fclose(file);
}

void deserialize_array(char* filename, NFAPI_CRC_INDICATION_PDU_T** array) {
    FILE* file = fopen(filename, "rb");
    if (!file) return;
    for (int i = 0; i < MAX_STRUCTURE; i++) {
        fread(array[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
    }
    fclose(file);
}

void log_CRCFLAG(NFAPI_CRC_INDICATION_PDU_T* structure) {
    printf("CRC FLAG: %d\n", structure->CRCFLAG);
}

void process_structures(int N, NFAPI_CRC_INDICATION_PDU_T** array) {
    for (int i = 0; i < N; i++) {
        log_CRCFLAG(array[i]);
    }
}

// Function to check if there is a collision in the RNTI values
int check_collision(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    int i;
    for (i = 0; i < N - 1; i++) {
        for (int j = i + 1; j < N; j++) {
            if (array[i]->RNTI == array[j]->RNTI) {
                return 1;
            }
        }
    }
    return 0;
}

// Function to handle the case where memory allocation fails
void* my_malloc(size_t size) {
    void* ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed\n");
    }
    return ptr;
}

int main() {
    int N = 1000; // Number of structures to create
    srand(time(NULL)); // Seed the random number generator

    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(MAX_STRUCTURE * sizeof(NFAPI_CRC_INDICATION_PDU_T*));
    if (!array) return 1;
    populate_array(N, array);

    int target_RNTI = rand() % 1000; // Generate a unique RNTI value for filtering
    filter_array(array, N, target_RNTI);

    char filename[] = "output.bin"; // File to serialize the array
    serialize_array(array, N, filename);

    deserialize_array(filename, array); // Deserialize the array

    process_structures(N, array);

    free(array); // Free the allocated memory

    return 0;
}
