    NFAPI_CRC_INDICATION_PDU_T* array = NULL;
    pthread_mutex_t lock = PTHREAD_MUTEX_INITIALIZER;

    struct timeval start, end;
    int i, crcflag;
    unsigned char rnti;

    if ((array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T))) == NULL) {
