        array[i].CRC_INDICATION_REL8_TAG = crcflag;

        pthread_mutex_lock(&lock);
        gettimeofday(&start, NULL);

        printf("CRCFLAG: %d, RNTI: %hhx\n", crcflag, array[i].RNTI);

        gettimeofday(&end, NULL);
        pthread_mutex_unlock(&lock);

        if ((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec) > ALERT_THRESHOLD) {
            fprintf(stderr, "Alert: Structure creation took %d microseconds\n", (int)((end.tv_sec - start.tv_sec) * 1000000 + (end.tv_usec - start.tv_usec)));
        }
    }

    return array;
}

void free_array(NFAPI_CRC_INDICATION_PDU_T* array, int N) {
    if (array != NULL)
        free(array);
}
