#define M 1000
#define MAX_CONNECTIONS M
#define CONNECTION_STATUS_ACTIVE 1
#define CONNECTION_STATUS_INACTIVE 0
#define LOGGING_BUFFER_SIZE 2048

typedef struct {
    int id;
    char ip[16];
    uint16_t port;
    int status;
} CONN_MANAGER_T;

static pthread_mutex_t conn_mgr_lock = PTHREAD_MUTEX_INITIALIZER;
static pthread_cond_t conn_avail = PTHREAD_COND_INITIALIZER;
static CONN_MANAGER_T connections[MAX_CONNECTIONS];
static int num_connections = 0;
static pthread_t performance_monitor_thread;

void* log_performance(void* arg) {
    while (1) {
        sleep(1);
        double avg_setup_time = 0.0;
        for (int i = 0; i < num_connections; i++) {
            CONN_MANAGER_T* conn = &connections[i];
            if (conn->status == CONNECTION_STATUS_ACTIVE) {
                // Calculate average setup time
                avg_setup_time += (double)(conn->setup_time);
            }
        }
        avg_setup_time /= num_connections;
        if (avg_setup_time > 0.015) {
            printf("Connection setup time exceeded threshold! Average: %.6f microseconds.\n", avg_setup_time * 1e6);
        }
    }
}

CONN_MANAGER_T* create_connection() {
    CONN_MANAGER_T* conn = NULL;
    pthread_mutex_lock(&conn_mgr_lock);
    if (num_connections < MAX_CONNECTIONS) {
        conn = &connections[num_connections];
        num_connections++;
    } else {
        printf("Connection pool is full! Cannot create new connection.\n");
    }
    pthread_mutex_unlock(&conn_mgr_lock);
    return conn;
}

void destroy_connection(CONN_MANAGER_T* conn) {
    if (conn != NULL) {
        pthread_mutex_lock(&conn_mgr_lock);
        for (int i = 0; i < num_connections; i++) {
            if (&connections[i] == conn) {
                connections[i].status = CONNECTION_STATUS_INACTIVE;
                memmove(conn, &connections[i + 1], sizeof(CONN_MANAGER_T) * (num_connections - i - 1));
                num_connections--;
                break;
            }
        }
        pthread_mutex_unlock(&conn_mgr_lock);
    }
}

int main() {
    int ret = pthread_create(&performance_monitor_thread, NULL, log_performance, NULL);
    if (ret != 0) {
        printf("Error creating performance monitor thread! Code: %d\n", ret);
    }
    return 0;
}
