int main() {
    // Initialize VM list and type count
    int* current_id = 0;
    int** vm_list = NULL;
    int vm_count = 0;
    int unique_type_count = 0;

    manage_vm_list(&current_id, &vm_list, &vm_count);
}

void manage_vm_list(int* current_id, int** vm_list, int max_types) {
    while (1) {
        // Create a new VM instance
        VM* new_vm = create_vm_instance();

        if (new_vm->type[0] == '\0') {
            printf("Error: Out of instance types.\n");
            return;
        }

        // Update the current ID and count of VMs
        (*current_id)++;
        vm_list[*current_id] = new_vm;

        // Check for reaching the maximum number of unique types
        if (unique_type_count >= max_types) {
            // Reuse instance types from the beginning of the list
            int i = 0;
            while (i < *current_id) {
                strcpy(vm_list[i]->type, vm_list[(*current_id)-1-i]->type);
                i++;
            }
        } else {
            unique_type_count++;
        }
    }
}

VM* create_vm_instance() {
    // Create a new VM instance
    static int type_index = 0;
    char types[MAX_TYPES][10] = {"c3.large", "m4.xlarge", "t2.micro"};
    strcpy(vm_list[type_index]->type, types[get_unique_type_index(types, unique_type_count)]);
    return vm_list[type_index];
}

int get_unique_type_index(int** types, int count) {
    // Get the next available type index
    for (int i = 0; i < count; i++) {
        if (strcmp(vm_list[i]->type, "") == 0) {
            return i;
        }
    }
}
