#define CRITICAL_CATEGORY_FLAG 0x02

typedef struct {
    char log_id[MAX_LOG_ID_LENGTH];
    time_t timestamp;
    int severity;
    char message[MESSAGE_LIMIT + 1];
    int metadata_flags;
} LogEntry;

pthread_mutex_t log_cache_mutex = PTHREAD_MUTEX_INITIALIZER;
pthread_mutex_t rolling_avg_mutex = PTHREAD_MUTEX_INITIALIZER;

// Cache of accepted logs
LogEntry *log_cache[LOG_CACHE_SIZE] = {0};
int log_cache_index = 0;

// Rolling average of message lengths over the last 60 seconds
double rolling_avg = 0.0;
int max_message_length = 0;
char *max_log_id = NULL;

void *handle_log_entry(void *arg) {
    LogEntry *entry = (LogEntry *) arg;

    // Check log age and ID
    time_t current_time = time(NULL);
    if ((current_time - entry->timestamp) >= 60 || pthread_mutex_trylock(&log_cache_mutex)) {
        return NULL; // Too old or concurrent access, skip this log entry
    }

    // Check message length and metadata flag
    if (strlen(entry->message) > MESSAGE_LIMIT || !(entry->metadata_flags & METADATA_FLAG_CACHED || entry->metadata_flags & CRITICAL_CATEGORY_FLAG)) {
        return NULL; // Invalid message or metadata, skip this log entry
    }

    // Update rolling average
    pthread_mutex_lock(&rolling_avg_mutex);
    int new_message_length = strlen(entry->message);
    if (new_message_length > max_message_length) {
        max_message_length = new_message_length;
        max_log_id = strdup(entry->log_id);
    }
    rolling_avg += (double)new_message_length;
    if (log_cache_index < LOG_CACHE_SIZE)
        log_cache[log_cache_index++] = *entry;

    pthread_mutex_unlock(&rolling_avg_mutex);

    // Check for unusual patterns
    if ((current_time - entry->timestamp) < 10) {
        // Unusual pattern detected, log it
        fprintf(stderr, "Unusual log frequency detected: %s\n", entry->log_id);
    }

    return NULL;
}

void *check_and_log(void *arg) {
    pthread_mutex_lock(&rolling_avg_mutex);
    double average = rolling_avg / (double)log_cache_index;
    pthread_mutex_unlock(&rolling_avg_mutex);
    // Return the rolling average, max message length, and corresponding log ID
    printf("Average message length: %.2f\nMax message length: %d\nLog ID: %s\n", average, max_message_length, max_log_id ? max_log_id : "None");
    return NULL;
}

void *manage_logs(void *arg) {
    pthread_t threads[10000]; // Handle up to 10,000 log entries per second
    int i = 0;

    while (1) {
        // Accept and process log entries concurrently
        pthread_create(&threads[i++], NULL, handle_log_entry, arg);
        if (i >= 10000) {
            for (int j = 0; j < i - 10000; j++)
                pthread_join(threads[j]);
            i = 0;
        }
    }

    return NULL;
}

int main() {
    // Start the log management thread
    pthread_t manage_logs_thread;
    pthread_create(&manage_logs_thread, NULL, manage_logs, NULL);

    // Periodically check and log statistics
    while (1) {
        pthread_join(manage_logs_thread, NULL);
        pthread_create(&manage_logs_thread, NULL, check_and_log, NULL);
    }

    return 0;
}
```']

