    NODE_INFO_T* new_node = (NODE_INFO_T*)malloc(sizeof(NODE_INFO_T));

    if (!new_node) return -1;  // Handle out-of-memory error

    // Check for duplicate node ID
    for (int i = 0; i < *size; i++) {
