            free(new_node);  // Deallocate memory and return error
            return -2;
        }
    }

    // Add the new element to the array
    (*arr) = (NODE_INFO_T**)realloc(*arr, (*size + 1) * sizeof(NODE_INFO_T*));
    if (!(*arr)) return -3;  // Handle out-of-memory error

    (*arr)[*size] = new_node;
    (*size)++;

    return 0;
}

// Function to serialize the node info array to file
int node_info_serialize(const NODE_INFO_T** arr, int size, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (!file) return -4;  // Handle I/O error

    for (int i = 0; i < size; i++) {
        fwrite(&((*arr)[i].node_id), sizeof(int), 1, file);
        fwrite((*arr)[i].location, sizeof(char), strlen((*arr)[i].location) + 1, file);
        fwrite(&((*arr)[i].status), sizeof(int), 1, file);
    }

    fclose(file);

    return 0;
}

// Function to deserialize the node info array from file
int node_info_deserialize(NODE_INFO_T** arr, int* size, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (!file) return -5;  // Handle I/O error

    int node_count;
    fread(&node_count, sizeof(int), 1, file);

    for (int i = 0; i < node_count; i++) {
        NODE_INFO_T* new_node = (NODE_INFO_T*)malloc(sizeof(NODE_INFO_T));
        if (!new_node) return -6;  // Handle out-of-memory error

        fread(&new_node->node_id, sizeof(int), 1, file);
        fread(new_node->location, sizeof(char), strlen(new_node->location) + 1, file);
        fread(&new_node->status, sizeof(int), 1, file);

        (*arr) = (NODE_INFO_T**)realloc(*arr, (*size + 1) * sizeof(NODE_INFO_T*));
        if (!(*arr)) return -7;  // Handle out-of-memory error

        (*arr)[*size] = new_node;
        (*size)++;

        free(new_node);
    }

    fclose(file);

    return 0;
}

// Function to update the status for a specific node ID
int node_info_update_status(NODE_INFO_T** arr, int size, int node_id, int new_status) {
    for (int i = 0; i < size; i++) {
