    uint16_t sample_per_pixel = TIFFGetFieldAsShort(tif, TIFF_FIELD_IMAGE_SAMPLESPERPIXEL);

    info->width = TIFFGetFieldAsLong(tif, TIFF_FIELD_IMAGE_WIDTH);
    info->height = TIFFGetFieldAsLong(tif, TIFF_FIELD_IMAGE_HEIGHT);

    if (bits_per_sample != 1 && bits_per_sample != 2 && bits_per_sample != 4 && bits_per_sample != 8 && bits_per_sample != 16) {
        free(info);
        TIFFClose(tif);
        return NULL;
    }

    info->bits_per_sample = bits_per_sample;
    info->sample_per_pixel = sample_per_pixel;

    int extra_samples = TIFFGetFieldAsShort(tif, TIFF_FIELD_IMAGE_EXTRASAMPLES);

    if (extra_samples > 0) {
        info->extra_samples = extra_samples;
        // handle extra samples
    }

    FILE* log_file = fopen("log.txt", "a");
    if (!log_file)
        return NULL;

    fprintf(log_file, "Parsing TIFF file: %s\n", filename);
    fprintf(log_file, "Width: %d, Height: %d, Bits per sample: %d, Sample per pixel: %d, Extra samples: %d\n", info->width, info->height, bits_per_sample, sample_per_pixel, extra_samples);

    fclose(log_file);

    int cipher_mode = 0;
    if (strcmp(option, "-symmetric") == 0)
        cipher_mode = AES_ENCRYPT;
    else if (strcmp(option, "-asymmetric") == 0)
