    EVP_CIPHER_CTX* ctx;
    if (cipher_mode == AES_ENCRYPT) {
        // initialize AES context
        ctx = EVP_CIPHER_CTX_new();
    } else if (cipher_mode == RSA_ENCRYPT) {
        // initialize RSA context
        ctx = RSA_CTX_new();
    } else {
