```c
#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <ctype.h>

const char* modify_filename(const char* filename) {
    int vowel_count = 0, last_char;
    const char* p = filename;

    // Count vowels in original filename (ignoring case)
    while (*p) {
        if (ispunct(*p) || isdigit(*p)) {
            break; // Stop counting vowels at the first non-alphabetic character
        }
        *p = tolower((unsigned char)*p);
        p++;
        vowel_count += strspn(p, "aeiou") == 0;
    }

    // Determine number of digits to append based on vowel count
    int num_digits = vowel_count ? (vowel_count % 10 + 1) : 1;

    // Extract the last character and file type from the original filename
    p = strrchr(filename, '.');
    if (!p || !*p) {
        last_char = '\0'; // Handle filenames with no extension
    } else {
        last_char = *p;
        p++; // Move to the start of the last extension
    }

    // Determine the new file type based on the last character
    char* new_type = (isalpha(last_char)) ? "txt" : ((isdigit(last_char)) ? "log" : "bin");

    // Construct the modified filename using sprintf and strcat
    size_t len = strlen(filename);
    char* new_filename = malloc((len + strlen(new_type) + 2) * sizeof(char));
    strcpy(new_filename, filename);
    sprintf(&new_filename[len], ".%s", new_type);

    return new_filename;
}
