#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

#define N 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfa_crc_indication_pdu = NULL;
pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
int crc_count = 0;
int max_crc_count = N;

void* allocate_and_populate_nfa_crc_indication_pdu(int n) {
    NFAPI_CRC_INDICATION_PDU_T *pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if(pdu != NULL) {
        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rand();
        pdu->CRC_INDICATION_REL8_TAG = rand();
        pdu->CRCFLAG = (rand() % 2);
        return pdu;
    } else {
        return NULL;
    }
}

void crc_indication_pdu_log(NFAPI_CRC_INDICATION_PDU_T *pdu, int verbosity) {
    if(verbosity >= 1) {
        printf("RX_UE_INFORMATION_TAG: %d\n", pdu->RX_UE_INFORMATION_TAG);
        printf("RNTI: %d\n", pdu->RNTI);
        printf("CRC_INDICATION_REL8_TAG: %d\n", pdu->CRC_INDICATION_REL8_TAG);
        printf("CRCFLAG: %d\n", pdu->CRCFLAG);
    }
}

void* crc_indication_pdu_update_and_validate(int n, int verbosity) {
    NFAPI_CRC_INDICATION_PDU_T *pdu;
    for(int i = 0; i < n; i++) {
        pthread_mutex_lock(&mutex);
        if(crc_count >= max_crc_count) {
            free(nfa_crc_indication_pdu);
            nfa_crc_indication_pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T)*max_crc_count*2);
            max_crc_count *= 2;
        }
        pdu = allocate_and_populate_nfa_crc_indication_pdu(1);
        if(pdu != NULL) {
            memcpy(&nfa_crc_indication_pdu[crc_count], pdu, sizeof(NFAPI_CRC_INDICATION_PDU_T));
            crc_indication_pdu_log(nfa_crc_indication_pdu+crc_count, verbosity);
            free(pdu);
            pthread_mutex_unlock(&mutex);
            crc_count++;
        }
    }
}

void* crc_indication_pdu_synchronize(int verbosity) {
