#define MAX_COMMANDS 1000
#define TIMEOUT 10 // seconds

typedef struct {
    char* command;
    int success;
} Command;

void signal_handler(int signum) {
    printf("Signal received: %d\n", signum);
}

int execute_commands(Command* commands, int num_commands) {
    int i;
    pid_t pid;
    int status;
    int timeout_count = 0;

    for (i = 0; i < num_commands; i++) {
        pid = fork();
        if (pid == 0) { // child process
            system(commands[i].command);
            exit(0);
        } else if (pid > 0) { // parent process
            if (timeout_count >= TIMEOUT) {
                kill(pid, SIGKILL);
                printf("Timeout exceeded for command %s\n", commands[i].command);
                return -1;
            }
            waitpid(pid, &status, WNOHANG);
            timeout_count++;
        } else { // fork failed
            perror("fork");
            return -1;
        }
    }

    return 0;
}

int main() {
    Command* commands = (Command*)malloc(MAX_COMMANDS * sizeof(Command));
    int num_commands = 5;

    for (int i = 0; i < num_commands; i++) {
        commands[i].command = "your_command_here"; // replace with actual command
        commands[i].success = -1;
    }

    signal(SIGCHLD, signal_handler);

    if (execute_commands(commands, num_commands) == -1) {
        printf("Command execution failed\n");
    } else {
        printf("Commands executed successfully\n");
    }

    free(commands);
    return 0;
}
