    RNTI rnti;
    CRC_INDICATION_REL8_TAG crc_indication;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *nfa_pi_crc_indications = NULL;
int num_structs = 0;

void nfa_pi_log(int log_level, char *fmt, ...) {
    va_list ap;
    va_start(ap, fmt);
    vprintf(fmt, ap);
    va_end(ap);
}

int nfa_pi_allocate_struct() {
    NFAPI_CRC_INDICATION_PDU_T *new_struct = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!new_struct) {
        return -1; // Out of memory
    }
    new_struct->rx_ue_info = malloc(sizeof(RX_UE_INFORMATION_TAG));
    new_struct->rnti = (RNTI)rand();
    new_struct->crc_indication.crcflag = rand() % 2;
    return 0;
}

void nfa_pi_free_struct(NFAPI_CRC_INDICATION_PDU_T *struct_to_free) {
    free(struct_to_free->rx_ue_info);
    free(struct_to_free);
}

int nfa_pi_merge_caches(int num_new_structs) {
    int i;
    for (i = 0; i < num_new_structs; i++) {
        // Merge cache into main array
        if (nfa_pi_crc_indications == NULL) {
            nfa_pi_crc_indications = (NFAPI_CRC_INDICATION_PDU_T *)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_STRUCTS);
            num_structs = 0;
        }
        // Check for contention and ensure data consistency
        if (nfa_pi_crc_indications[num_structs].rx_ue_info != struct_to_free->rx_ue_info) {
            // Handle race condition
            return -1; // Data inconsistency
        }
        nfa_pi_crc_indications[num_structs] = new_struct;
        num_structs++;
    }
}

int main() {
    int i;
    for (i = 0; i < MAX_STRUCTS; i++) {
        if (nfa_pi_allocate_struct()) {
            return -1; // Out of memory
        }
    }
    nfa_pi_merge_caches(MAX_STRUCTS);
    for (i = 0; i < num_structs; i++) {
        nfa_pi_free_struct(&nfa_pi_crc_indications[i]);
    }
