import java.io.*;
import java.lang.ProcessBuilder;
import java.net.URI;
import java.nio.file.Files;
import java.nio.file.Paths;
import java.util.ArrayList;
import java.util.List;
import java.util.concurrent.TimeUnit;

public class DynamicCommandExecutor {

    private static final int MAX_FILE_SIZE = 1024 * 1024; // 1MB
    private static final int COMMAND_TIMEOUT = 30000; // 30 seconds

    public void executeCommands(String[] commands, boolean interactive) throws IOException, InterruptedException {
        for (String command : commands) {
            String[] commandArray = command.split(" ");
            ProcessBuilder processBuilder = new ProcessBuilder(commandArray);

            if (interactive) {
                System.out.print("Enter command arguments: ");
                List<String> args = new ArrayList<>();
                while (!commandArray[0].equals("")) {
                    for (int i = 1; i < commandArray.length; i++) {
                        args.add(commandArray[i]);
                    }
                    String[] nextCommand = input.nextLine().split(" ");
                    commandArray = nextCommand;
                }
            }

            // Check and delete file if it exists
            File tempFile = new File("temp.txt");
            if (tempFile.exists() && Files.size(Paths.get(tempFile.getAbsolutePath())) <= MAX_FILE_SIZE) {
                Files.delete(Paths.get(tempFile.getAbsolutePath()));
            }

            // Execute command
            Process process = processBuilder.start();

            // Capture standard output and error streams
            ByteArrayOutputStream outputStream = new ByteArrayOutputStream();
            ByteArrayOutputStream errorStream = new ByteArrayOutputStream();
            new StreamGobbler(process.getInputStream(), outputStream).start();
            new StreamGobbler(process.getErrorStream(), errorStream).start();

            // Wait for command execution to complete or timeout
            if (!process.waitFor(COMMAND_TIMEOUT, TimeUnit.MILLISECONDS)) {
                System.out.println("Command timed out.");
            }

            // Log output and error streams
            String output = outputStream.toString();
            String error = errorStream.toString();
            logOutput(output);
            logError(error);

            // Close resources
            process.destroy();
            outputStream.close();
            errorStream.close();
        }
    }

    private void logOutput(String output) {
        try (PrintWriter writer = new PrintWriter(new FileWriter("output.log"))) {
            writer.println(output);
        } catch (IOException e) {
            // Handle logging failure
        }
    }

    private void logError(String error) {
        try (PrintWriter writer = new PrintWriter(new FileWriter("error.log"))) {
            writer.println(error);
        } catch (IOException e) {
            // Handle logging failure
        }
    }

    public static class StreamGobbler extends Thread {

        private InputStream inputStream;
        private ByteArrayOutputStream stream;

        public StreamGobbler(InputStream inputStream, ByteArrayOutputStream stream) {
            this.inputStream = inputStream;
            this.stream = stream;
        }

        @Override
        public void run() {
            try (InputStreamReader reader = new InputStreamReader(inputStream)) {
                char[] buffer = new char[1024];
                int bytesRead;
                while ((bytesRead = reader.read(buffer, 0, buffer.length)) > 0) {
                    stream.write(buffer, 0, bytesRead);
                }
            } catch (IOException e) {
                // Handle IO failure
            }
        }
    }
}
