#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char* access_token;
    int expires_in;
    char* token_type;
    char* refresh_token;
} Token;

int validate_json(char* json) {
    // Parse JSON into a linked list structure
    Token* token = (Token*)malloc(sizeof(Token));
    if (!token) return -1;  // Allocation failed

    token->access_token = NULL;
    token->expires_in = 0;
    token->token_type = NULL;
    token->refresh_token = NULL;

    int i = 0, j = 0;
    char quote = 0, level = 0;
    for (int c = 0; json[c]; c++) {
        if (json[c] == '{') level++;
        else if (json[c] == '}') level--;
        if (level > 1) continue;

        switch (json[c]) {
            case '"':
                quote ^= 1;
                break;
            case ',':
                token->refresh_token = NULL; // Reset refresh token for next item
                j = c + 1; i = 0;
                break;
            default: if (!quote) continue;

        }
        if (c == json[strlen(json) - 1]) break;

        if ((json[c] == 'a' || json[c] == 'A') && (json[c + 1] == 'c' || json[c + 1] == 'C') &&
            (json[c + 2] == 'c' || json[c + 2] == 'C) && (json[c + 3] == 'e' || json[c + 3] == 'E') &&
            (json[c + 4] == 's' || json[c + 4] == 'S') && (json[c + 5] == 's' || json[c + 5] == 'S) &&
            (json[c + 6] == '_' || json[c + 6] == '_')) {
            token->access_token = malloc((c - j + 1) * sizeof(char));
            memcpy(token->access_token, &json[j], c - j);
            token->access_token[c - j] = '\0';
        }

        if ((json[c] == 't' || json[c] == 'T') && (json[c + 1] == 'o' || json[c + 1] == 'O) &&
            (json[c + 2] == 'k' || json[c + 2] == 'K) && (json[c + 3] == 'e' || json[c + 3] == 'E) &&
            (json[c + 4] == 'n' || json[c + 4] == 'N) && (json[c + 5] == '_' || json[c + 5] == '_)) {
            token->token_type = malloc((c - j + 1) * sizeof(char));
            memcpy(token->token_type, &json[j], c - j);
            token->token_type[c - j] = '\0';
        }

        if ((json[c] == 'r' || json[c] == 'R') && (json[c + 1] == 'e' || json[c + 1] == 'E) &&
            (json[c + 2] == 'f' || json[c + 2] == 'F) && (json[c + 3] == 'r' || json[c + 3] == 'R) &&
            (json[c + 4] == 'e' || json[c + 4] == 'E) && (json[c + 5] == 's' || json[c + 5] == 'S)) {
            token->refresh_token = malloc((c - j + 1) * sizeof(char));
            memcpy(token->refresh_token, &json[j], c - j);
            token->refresh_token[c - j] = '\0';
        }

        if (json[c] >= '0' && json[c] <= '9') {
            token->expires_in = atoi(&json[j]);
        }
    }
    // Perform validation
    if (!token->access_token || !token->token_type || strlen(token->token_type) != 7 ||
        strcmp(token->token_type, "Bearer") != 0 || token->expires_in <= 0) {
        free(token);
        return -2;  // Validation failed
    }
    if (token->refresh_token && *token->refresh_token == '\0') {
        free(token->refresh_token); token->refresh_token = NULL;
    }
    free(token);
    return 1;  // Token is valid
}

int main() {
    char* json = "{\"access_token\":\"abc\",\"expires_in\":123,\"token_type\":\"Bearer\"}";
    int result = validate_json(json);
    if (result < 0) printf("Error: %d\n", -result);
    else printf("Token is valid.\n");
    return 0;
}
