using System;
using System.IO;
using System.Security.Cryptography;
using System.Text;

public class FileProcessor
{
    public static (string, string, int) ProcessFile(string encryptedMessage, string filePath)
    {
        byte[] decryptedBytes = TripleDESDecrypt(encryptedMessage);
        string decryptedMessage = Encoding.UTF8.GetString(decryptedBytes);

        byte[] fileBytes = ReadFileInChunks(filePath, 1024 * 1024); // 1 MB chunks
        MD5 hash = MD5.Create();
        byte[] fileHash = hash.ComputeHash(fileBytes);

        int retries = 0;
        DateTime start = DateTime.Now;

        while (true)
        {
            try
            {
                using (FileStream fs = new FileStream(filePath, FileMode.Open))
                {
                    long fileSize = fs.Length;
                    long processedSize = 0;
                    long lastUpdate = start.AddMilliseconds(10000).Ticks; // Update progress every 10 MB

                    string estimatedRemainingTime;
                    DateTime estimatedFinish;

                    while (processedSize < fileSize)
                    {
                        byte[] chunk = new byte[1024 * 1024]; // 1 MB chunks
                        int bytesRead = fs.Read(chunk, 0, chunk.Length);
                        processedSize += bytesRead;

                        if (processedSize >= lastUpdate)
                        {
                            long remainingSize = fileSize - processedSize;
                            TimeSpan elapsed = DateTime.Now.Subtract(start);
                            estimatedRemainingTime = $"{remainingSize / 1024 / 1024:###.00} MB ({elapsed.Seconds + (elapsed.Milliseconds / 1000f):#.# s})";
                            estimatedFinish = start.AddSeconds(elapsed.Seconds + remainingSize / (1024 * 1024) / elapsed.Seconds);
                        }

                        hash.TransformBlock(chunk, 0, bytesRead);
                    }

                    fileHash = hash.ComputeHash();
                }
            }
            catch (IOException ex)
            {
                retries++;
                if (retries >= 3)
                {
                    // Log error and return
                    return (decryptedMessage, Encoding.UTF8.GetString(fileHash), retries);
                }
                else
                {
                    // Wait for a short period before retrying
                    System.Threading.Thread.Sleep(1000);
                }
            }

            break;
        }

        return (decryptedMessage, Encoding.UTF8.GetString(fileHash), retries);
    }

    static byte[] TripleDESDecrypt(string encryptedMessage)
    {
        using (TripleDESCryptoServiceProvider tdes = new TripleDESCryptoServiceProvider())
        {
            tdes.Key = Encoding.ASCII.GetBytes("your-secret-key");
            tdes.IV = Encoding.ASCII.GetBytes("your-initialization-vector");

            using (MemoryStream ms = new MemoryStream(Encoding.UTF8.GetBytes(encryptedMessage)))
            {
                using (CryptoStream cs = new CryptoStream(ms, tdes.CreateDecryptor()))
                {
                    byte[] decryptedBytes = new byte[cs.Length];
                    cs.Read(decryptedBytes, 0, decryptedBytes.Length);
                    return decryptedBytes;
                }
            }
        }
    }

    static byte[] ReadFileInChunks(string filePath, int chunkSize)
    {
        using (FileStream fs = new FileStream(filePath, FileMode.Open))
        {
            byte[] buffer = new byte[chunkSize];
            long fileSize = fs.Length;

            byte[] fileBytes = new byte[(int)fileSize];
            int bytesRead = 0;
            int offset = 0;

            while (bytesRead < fileSize)
            {
                int bytesReadChunk = fs.Read(buffer, 0, chunkSize);
                Array.Copy(buffer, 0, fileBytes, offset, bytesReadChunk);
                bytesRead += bytesReadChunk;
                offset += bytesReadChunk;
            }

            return fileBytes;
        }
    }
}
