    // Initialize the array with NULL values
    NFAPI_CRC_INDICATION_PDU_T* arr = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize a log buffer to record CRCFLAG values
    char log_buffer[1024];

