            return NULL;
        }
    }

    // Wait for each thread to complete
    for(int i=0; i<num_requests; i++) {
        if(pthread_join(threads[i], NULL) != 0) {
            // Handle memory deallocation failure
            printf("Memory deallocation failed for request %d\n", i);
            return NULL;
        }
    }

    return NULL;
}

