    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

// Function to generate PDUs
void generate_PDUs(int numPDUs, int durationSecs, int* buffer, FILE** logFile) {
    int i, j, k;
    srand(time(NULL)); // Initialize random seed

    for (i = 0; i < numPDUs; i++) {
        LTE_PHY_STATS_PDU_T lte_stats;
        NFAPI_CRC_INDICATION_PDU_T nfa_pi_crc;

        // Generate LTE_PHY_STATS_PDU_T
        lte_stats.PHY_LAYER_STATUS = rand() % 256;
        lte_stats.CELL_ID = rand() % 65536;
        lte_stats.TX_POWER_LEVEL = rand() % 100 + 1;

        // Validate CELL_ID for uniqueness
        for (j = 0; j < i; j++) {
            if (lte_stats.CELL_ID == buffer[j].CELL_ID) {
                i--; // Reset the loop, duplicate found
                break;
            }
        }

        // Generate NFAPI_CRC_INDICATION_PDU_T
        nfa_pi_crc.RX_UE_INFORMATION_TAG = rand() % 256;
        nfa_pi_crc.RNTI = rand() % 65536;
        nfa_pi_crc.CRCFLAG = rand() % 2;

        if (*logFile) {
            fprintf(*logFile, "LTE_PHY_STATS_PDU_T:\n");
            fprintf(*logFile, "\tPHY_LAYER_STATUS: %d\n", lte_stats.PHY_LAYER_STATUS);
            fprintf(*logFile, "\tCELL_ID: %d\n", lte_stats.CELL_ID);
            fprintf(*logFile, "\tTX_POWER_LEVEL: %d\n", lte_stats.TX_POWER_LEVEL);

            fprintf(*logFile, "NFAPI_CRC_INDICATION_PDU_T:\n");
            fprintf(*logFile, "\tRX_UE_INFORMATION_TAG: %d\n", nfa_pi_crc.RX_UE_INFORMATION_TAG);
            fprintf(*logFile, "\tRNTI: %d\n", nfa_pi_crc.RNTI);
            fprintf(*logFile, "\tCRC_INDICATION_REL8_TAG: %d\n", nfa_pi_crc.CRC_INDICATION_REL8_TAG);
            fprintf(*logFile, "\tCRCFLAG: %d\n", nfa_pi_crc.CRCFLAG);

            fprintf(*logFile, "---------------------------\n");
        }

        // Validate CRC_INDICATION_REL8_TAG for correctness
        if (nfa_pi_crc.CRC_INDICATION_REL8_TAG > 0) {
            // Calculate the CRC value here using the CRC32 algorithm
