void* generate_packets(int num_packets, int delay_us, int random_seed, FILE* log_file) {
    srand(random_seed);

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    pthread_cond_t cond = PTHREAD_COND_INITIALIZER;

    DataPacket** packets = (DataPacket**)malloc(BUFFER_SIZE);
    size_t buffer_index = 0;
    time_t last_packet_time = 0;

    for (int i = 0; i < num_packets; i++) {
        int packet_id = rand();
        time_t timestamp = time(NULL);

        if ((timestamp - last_packet_time) * 1000000 > delay_us) {
            // New packet, check buffer size
            if (buffer_index >= MAX_PACKETS) {
                // Buffer full, remove oldest packets
                pthread_mutex_lock(&mutex);
                size_t j;
                for (j = buffer_index; j > 0; j--) {
                    memmove(packets, &packets[j - 1], sizeof(DataPacket*));
                }
                pthread_mutex_unlock(&mutex);

                // Update buffer index and last packet time
                buffer_index--;
                last_packet_time = packets[buffer_index]->timestamp;
            }

            DataPacket new_packet;
            new_packet.timestamp = timestamp;
            new_packet.id = packet_id;

            // Check payload integrity before adding to the buffer
            if (data_packet_checksum(&new_packet) == 0) {
                // Add packet to the buffer and update last packet time
                pthread_mutex_lock(&mutex);
                packets[buffer_index++] = &new_packet;
                pthread_mutex_unlock(&mutex);

                if (log_file) {
                    // Log packet generation
                    fprintf(log_file, "Packet ID: %d, Timestamp: %ld\n", new_packet.id, new_packet.timestamp);
                    fflush(log_file);
                }

                last_packet_time = timestamp;

                // Sleep for the specified delay to ensure rate limiting
                usleep(delay_us);
            } else {
                // Packet payload integrity check failed
                printf("Packet ID: %d, Payload integrity failure\n", packet_id);
            }
        }
    }

    return packets;
}
