} NFAPI_RX_INDICATION_PDU_T;

void* alloc_and_fill_phy_stat_pdu(int count, NR_PHY_STAT_PDU_T** phy_stat_pdus) {
    *phy_stat_pdus = (NR_PHY_STAT_PDU_T*)malloc(count * sizeof(NR_PHY_STAT_PDU_T));
    for (int i = 0; i < count; i++) {
        NR_PHY_STAT_PDU_T* p = &(*phy_stat_pdus)[i];
        p->phy_layer_status = rand() % 255;
        p->cell_id = rand() % 65535;
        p->mcs_level = rand() % 256;
    }
}

void* alloc_and_fill_rx_indication_pdu(int count, NFAPI_RX_INDICATION_PDU_T** rx_indication_pdus) {
    *rx_indication_pdus = (NFAPI_RX_INDICATION_PDU_T*)malloc(count * sizeof(NFAPI_RX_INDICATION_PDU_T));
    for (int i = 0; i < count; i++) {
        NFAPI_RX_INDICATION_PDU_T* p = &(*rx_indication_pdus)[i];
        p->rx_ue_information_tag = rand() % 65535;
        p->rnti = rand() % 2147483647;
        p->qcl_state = rand() % 255;
        p->qcl_tag = rand() % 255;
    }
}

void print_phy_stat_pdu(NR_PHY_STAT_PDU_T* phy_stat_pdu) {
    printf("PHY Layer Status: %d, Cell ID: %d, MCS Level: %d\n", phy_stat_pdu->phy_layer_status, phy_stat_pdu->cell_id, phy_stat_pdu->mcs_level);
}

void print_rx_indication_pdu(NFAPI_RX_INDICATION_PDU_T* rx_indication_pdu) {
    printf("RX UE Information Tag: %d, RNTI: %d, QCL State: %d, QCL Tag: %d\n", rx_indication_pdu->rx_ue_information_tag, rx_indication_pdu->rnti, rx_indication_pdu->qcl_state, rx_indication_pdu->qcl_tag);
}

void serialize_phy_stat_pdu_to_file(NR_PHY_STAT_PDU_T* phy_stat_pdu, int count, const char* filename) {
    FILE* file = fopen(filename, "wb");
    if (file == NULL) return;
    fwrite(phy_stat_pdu, sizeof(NR_PHY_STAT_PDU_T), count, file);
    fclose(file);
}

void deserialize_phy_stat_pdu_from_file(NR_PHY_STAT_PDU_T** phy_stat_pdu, int* count, const char* filename) {
    FILE* file = fopen(filename, "rb");
    if (file == NULL) return;
    fseek(file, 0, SEEK_END);
    long size = ftell(file);
    rewind(file);
    *phy_stat_pdu = (NR_PHY_STAT_PDU_T*)malloc(size / sizeof(NR_PHY_STAT_PDU_T));
    fread(*phy_stat_pdu, sizeof(NR_PHY_STAT_PDU_T), size / sizeof(NR_PHY_STAT_PDU_T), file);
    fclose(file);
}

void update_mcs_level_for_cell_id(NR_PHY_STAT_PDU_T* phy_stat_pdu, int cell_id) {
    for (int i = 0; i < NR_PHY_STAT_PDU_T; i++) {
        if (phy_stat_pdu[i].cell_id == cell_id) {
            phy_stat_pdu[i].mcs_level += rand() % 256;
            return;
        }
    }
}

void main() {
    srand(time(NULL));
    NR_PHY_STAT_PDU_T* phy_stat_pdus = NULL;
    NFAPI_RX_INDICATION_PDU_T* rx_indication_pdus = NULL;

    // Generate a specified number of PDUs within a given time frame
    alloc_and_fill_phy_stat_pdu(NR_PHY_STAT_PDU_T, &phy_stat_pdus);
    alloc_and_fill_rx_indication_pdu(NFAPI_RX_INDICATION_PDU_T, &rx_indication_pdus);

    // Validate the RX QCL TAG for correctness before adding it to the buffer and the final list
    for (int i = 0; i < NR_PHY_STAT_PDU_T; i++) {
        if (!validate_rx_qcl_tag(&phy_stat_pdus[i])) {
            printf("Invalid RX QCL TAG at index %d.\n", i);
            return;
        }
    }

    // Serialize the entire structure array to and from a file
    serialize_phy_stat_pdu_to_file(phy_stat_pdus, NR_PHY_STAT_PDU_T, "output.bin");
    deserialize_phy_stat_pdu_from_file(&phy_stat_pdus, &NR_PHY_STAT_PDU_T, "input.bin");

    // Update the MCS LEVEL for a specific CELL ID after deserialization
    update_mcs_level_for_cell_id(phy_stat_pdu, 123);

    // Handle out-of-memory conditions gracefully by releasing memory from the oldest entries in the buffer when space is needed
    free_buffer_memory();

    // Efficiently update the MCS LEVEL for a specific CELL ID after deserialization
    for (int i = 0; i < NR_PHY_STAT_PDU_T; i++) {
