std::unique_ptr<std::byte[]> processAndCacheComplexData(std::byte* data, size_t maxSizeLimit, IExternalCacheSystem& cache, const Config& config) {
    // Deserialize the byte array into a complex object using Boost serialization
    try {
        boost::archive::BinaryOArchive archive(data, std::strlen((char*)data));
        ComplexObject obj;
        archive >> obj;

        if (obj.getType() == ComplexType::Unknown) {
            // Log warning for unknown type and attempt to handle it gracefully
            LOG_WARNING("Unknown complex object type encountered");
        }

        // Process the nested data structure within the object based on configuration settings
        std::string processedData;
        processNestedData(obj, config, &processedData);

        // Validate if the total size of the processed data exceeds the specified size limit
        if (processedData.size() > maxSizeLimit) {
            return nullptr; // Return NULL if the processed data exceeds the size limit
        }

        // Format the data by replacing specific keywords with placeholders
        processedData = formatData(processedData, config);

        // Append a delimiter or prepend a summary prefix based on configuration settings
        if (config.appendDelimiter()) {
            processedData += "#";
        } else if (config.prependSummaryPrefix()) {
            processedData = config.getSummaryPrefix() + processedData;
        }

        return std::make_unique<std::byte[]>(processedData.size() + 1); // Allocate memory for the formatted data
    }
    catch (const boost::archive::ArchiveException& e) {
        throw std::runtime_error("Deserialization failed: " + e.what());
    }

    // Store intermediate results in the external cache system and ensure thread safety
    cache.storeIntermediateResults(processedData);
}
