use actix_web::http::{header, Request};
use actix_web::middleware::Logger;
use actix_web::{get, post, put, patch, delete, web, App, HttpRequest, HttpResponse, HttpServer};
use actix_cors::Cors;
use chrono::prelude::*;
use jsonwebtoken::{decode, verify_with_secret_key};
use log::Level;

#[actix_web(crate)]
async struct MyService {
    // Your configuration and data will go here
}

#[derive(Debug, Deserialize)]
struct LoginRequest {
    username: String,
    password: String,
}

async fn login(req: HttpRequest) -> HttpResponse {
    let token = generate_token(&req); // This function will be implemented later

    HttpResponse::Ok()
        .insert_header((header::SET_COOKIE, format!("token={}", token)).as_bytes())
        .finish()
}

fn main() {
    env_logger::init_from_env("RUST_LOG=info");

    HttpServer::new(|| {
        let cors = Cors::new()
            .allowed_origin("*")
            .allowed_methods(vec!["GET", "POST"])
            .allowed_headers(vec![header::AUTHORIZATION, header::CONTENT_TYPE])
            .max_age(3600)
            .finish();

        App::with_state(MyService {})
            .app_data(Logger::new("%a %A0: %T".parse().unwrap()))
            .wrap(cors)
            .service(web::resource("/login").route(post().to(login)))
            // Other routes will be implemented here
    })
    .bind("127.0.0.1:8080")
    .unwrap()
    .run();
}

fn generate_token(req: &HttpRequest) -> String {
    let user = req.match_info().get("username").unwrap();

    let now = Utc::now();
    let claims = jsonwebtoken::encode(&serde_json::json!({
        "exp": now.timestamp() + 3600,
        "user": user.to_string(),
    }), &"your_secret_key".to_string())
    .expect("Failed to generate token");

    claims
}

