```rust
use {
    std::env,
    std::fs::{create_dir_all, DirBuilder},
    std::io::{ErrorKind, Error},
    std::path::{Path, PathBuf},
    std::time::{SystemTime, UNIX_EPOCH},
};
struct Logger {
    log_dir: String,
}

impl Logger {
    fn new() -> Self {
        let current_time = SystemTime::now()
            .duration_since(UNIX_EPOCH)
            .unwrap()
            .as_secs();
        let mut log_dir = env::var("LOG_DIR").or_else(|_| {
            let now = chrono::Local::now().format("%Y-%m-%d");
            let service_name = env::var("SERVICE_NAME").expect("SERVICE_NAME environment variable is required.");
            let env_var = env::var("ENV_VAR").unwrap_or("default".to_string());
            let path = format!("{}/logs/{}/{}/{}/", now, &service_name, &env_var);
            create_dir_all(&path).map_err(|e| e.to_string()).ok(path.clone())
        });
        if log_dir.ends_with('/') {
            let time_path = format!("{}/{}", log_dir, current_time);
            create_dir_all(&time_path).map_err(|e| e.to_string()).ok(log_dir = time_path);
        }
        Logger { log_dir }
    }

    fn write_log(&self, message: &str) -> Result<(), Error> {
        let file_path = format!("{}/log.txt", self.log_dir.clone());
        let mut file = match std::fs::OpenOptions::new()
            .create(true)
            .append(true)
            .open(file_path)
        {
            Ok(f) => f,
            Err(e) => return Err(e.into()),
        };
        writeln!(file, "{}", message)?;
        Ok(())
    }

    fn archive_logs(&self) -> Result<(), Error> {
        let log_dir = &self.log_dir;
        if !log_dir.ends_with('/') {
            return Err(std::io::Error::new(ErrorKind::InvalidInput, "Not a directory").into());
        }
        let mut archive_dir = PathBuf::from(log_dir.clone());
        archive_dir.push("archive");
        create_dir_all(&archive_dir)?;
        let now = chrono::Local::now().format("%Y-%m-%d");
        if let Err(e) = self.move_logs_to_archive(now.as_str()) {
            return Err(e);
        }
        Ok(())
    }

    fn move_logs_to_archive(&self, archive_date: &str) -> Result<(), Error> {
        let log_dir = &self.log_dir;
        for entry in std::fs::read_dir(log_dir)? {
            if let Ok(entry) = entry {
                let path = entry.path();
                if path.is_file() && !path.file_name().unwrap().eq("log.txt") {
                    let mut dest_path = PathBuf::from(path.clone());
                    dest_path.push(archive_date);
                    std::fs::rename(&path, &dest_path)?;
                }
            }
        }
        Ok(())
    }
}

fn main() {
    let logger = Logger::new();
    logger.write_log("This is a log message");
    logger.archive_logs();
}
```']

