typedef struct {
    int rnti;
    char crcflag[3];
} NFAPI_CRC_INDICATION_PDU_T;

void* generate_pdu(void* arg) {
    int seed = *(int*)arg;
    srand(seed);
    // PDU generation logic goes here
    return NULL;
}

void* pdu_thread_function(void* thread_arg) {
    pthread_t thread_id = pthread_self();
    int seed = (int)(thread_id % 1000);
    generate_pdu(&seed);
    return NULL;
}

void manage_pdu_creation(int num_pdu, int time_frame) {
    // Throttle rate calculation
    int throttle_rate = THROTTLE_RATE / time_frame;

    // Create a buffer for the last 1000 PDUs
    NFAPI_CRC_INDICATION_PDU_T* pdu_buffer = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_PDU);
    int pdu_index = 0;
    pthread_t threads[100]; // Assuming no more than 100 concurrent threads

    for (int i = 0; i < num_pdu && clock() < time_frame * CLOCKS_PER_SEC; i++) {
        if (pdu_index >= MAX_PDU) {
            break; // Buffer full, stop generating PDUs
        }
        pthread_create(&threads[i], NULL, pdu_thread_function, &seed);
    }

    for (int i = 0; i < num_pdu && clock() < time_frame * CLOCKS_PER_SEC; i++) {
        pthread_join(threads[i], NULL);
    }

    // Log generation of each PDU to a file
    FILE* log_file = fopen("pdu_log.txt", "a");
    if (log_file) {
        for (int i = 0; i < pdu_index; i++) {
            fwrite(&pdu_buffer[i], sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, log_file);
        }
        fclose(log_file);
    }

    // Close the buffer
    free(pdu_buffer);
}

int main() {
    int num_pdu = 1000;
    int time_frame = 10; // seconds

    manage_pdu_creation(num_pdu, time_frame);

    return 0;
}
