int batch_process_media_files(char* directory_path) {
    DIR* dir = opendir(directory_path);
    HANDLE_ERROR(1);

    struct dirent* entry;
    int file_count = 0;

    while ((entry = readdir(dir)) != NULL) {
        if (strcmp(entry->d_name, ".") == 0 || strcmp(entry->d_name, "..") == 0)
            continue;

        char filepath[PATH_MAX];
        sprintf(filepath, "%s/%s", directory_path, entry->d_name);

        struct stat file_stat;
        HANDLE_ERROR(stat(filepath, &file_stat));

        if (S_ISDIR(file_stat.st_mode))
            continue; // Skip directories

        process_file(&file_stat);
        file_count++;

        if (file_count % BATCH_SIZE == 0) {
            printf("Processed %d files.\n", file_count);
        }

        if (file_count >= MAX_FILES_IN_MEMORY) {
            // Evict older files from the queue
            printf("Evicted older files to ensure optimal performance.\n");
        }
    }

    closedir(dir);

    return 0;
}

