    int num_pdus = cfg->n;
    int max_enb_id = cfg->e;
    int max_msg_len = cfg->l;
    size_t max_memory_usage = cfg->max_memory_usage * 1024; // Convert to bytes

    pdus = (LTE_ENB_INTERFACE_MME_PDU_T*)malloc(max_memory_usage);
    if (!pdus) {
        log_error("Failed to allocate memory for PDUs");
        return ENOMEM;
    }

