        pdu.ENB_ID = enb_id;

        // Initialize MESSAGE_TYPE and compute CRCFLAG
        pdu.MESSAGE_TYPE[0] = 'T'; // Set default message type
        pdu.CRCFLAG = compute_crc(&pdu, max_msg_len);

        if (pdu.CRCFLAG < 0) {
            log_error("Failed to compute CRC flag");
            err = E_CRC_ERROR;
            break;
        }

        pdus[i] = pdu;

        // Update PDU count and check for memory constraints
        pdu_count++;
        if (pdu_count > max_memory_usage / sizeof(LTE_ENB_INTERFACE_MME_PDU_T)) {
            log_error("Memory limit exceeded");
            err = ENOMEM;
            break;
        }
    }

    if (err) {
        free(pdus);
        return err;
    }

    // Validate and populate PDUs
    for (int i = 0; i < pdu_count; i++) {
        LTE_ENB_INTERFACE_MME_PDU_T* p = &pdus[i];

        // Initialize fields and compute CRC flag
        if (!validate_pdu(p, max_msg_len)) {
            log_error("Failed to validate PDU");
            err = E_INVALID_PDU;
            break;
        }
    }

    return err;

}

int generatePEMCertificate(oauth_request_t* req) {
    int err = 0;

    // Fetch private key and certificate from request
    char* priv_key_file = req->priv_key_file;
    char* cert_file = req->cert_file;

    if (!priv_key_file || !cert_file) {
        log_error("Missing private key or certificate");
        return EINVAL;
    }

    FILE* key_fd = fopen(priv_key_file, "r");
    if (!key_fd) {
        log_error("Failed to open private key file");
        err = ENOENT;
    } else {
        fclose(key_fd);
    }

    FILE* cert_fd = fopen(cert_file, "r");
    if (!cert_fd) {
        log_error("Failed to open certificate file");
        err = ENOENT;
    } else {
        fclose(cert_fd);

        // Combine private key and certificate into a single PEM file
        char* pem_file = req->pem_file;

        FILE* pem_fd = fopen(pem_file, "w");
        if (!pem_fd) {
            log_error("Failed to open PEM file for writing");
            err = ENOENT;
        } else {
            // Write private key and certificate to PEM file
            fwrite(priv_key_file, strlen(priv_key_file), 1, pem_fd);
            fwrite("\n", 1, 1, pem_fd);
            fwrite(cert_file, strlen(cert_file), 1, pem_fd);

            fclose(pem_fd);
        }
    }

    return err;
}
