#include <stdio.h>
#include <stdlib.h>
#include <time.h>

typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T* data;
    struct Node* next;
} Node;

void append(Node** head, NFAPI_CRC_INDICATION_PDU_T* new_data) {
    if (*head == NULL) {
        *head = (Node*)malloc(sizeof(Node));
        (*head)->data = new_data;
        (*head)->next = NULL;
    } else {
        Node* last = *head;
        while (last->next) {
            last = last->next;
        }
        Node* new_node = (Node*)malloc(sizeof(Node));
        new_node->data = new_data;
        new_node->next = NULL;
        last->next = new_node;
    }
}

NFAPI_CRC_INDICATION_PDU_T* create_pdu(int N) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    for (int i = 0; i < N; i++) {
        pdu_array[i].RX_UE_INFORMATION_TAG = i;
        pdu_array[i].RNTI = rand() % 100;
        pdu_array[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        if (rand() % 2) {
            pdu_array[i].CRCFLAG = 1;
        } else {
            pdu_array[i].CRCFLAG = 0;
        }
    }
    return pdu_array;
}

void log_operation(int success) {
    FILE* file = fopen("operation.log", "a");
    if (file == NULL) {
        printf("Failed to open log file\n");
    } else {
        fprintf(file, "%d\n", success);
        fclose(file);
    }
}

NFAPI_CRC_INDICATION_PDU_T** create_pdu_array(int N) {
    Node* head = NULL;
    for (int i = 0; i < N; i++) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = create_pdu(1);
        append(&head, pdu);
        log_operation(1);
    }
    int j = 0;
    NFAPI_CRC_INDICATION_PDU_T** pdu_array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T*) * N);
    Node* current = head;
    while (current) {
        pdu_array[j] = current->data;
        current = current->next;
        j++;
    }
    free(head);
    return pdu_array;
}
