#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define N 10 // Number of UE instances or lines in binary file
#define M 1000 // Limit on unique RNTI values

typedef struct {
    int RX_UE_INFORMATION_TAG;
    char RNTI[5];
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void initAndPopulateArray(int numUes, FILE* file) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    int rntiCount = 0;
    char* currentRNTI = "";
    for (int i = 0; i < numUes || file != NULL; i++) {
        NFAPI_CRC_INDICATION_PDU_T pdu;

        if (file) {
            // Process binary file line by line
            char line[1024];
            fgets(line, sizeof(line), file);
            int fields[3];
            sscanf(line, "%d,%d,%d", &fields[0], &fields[1], &fields[2]);
            pdu.RX_UE_INFORMATION_TAG = fields[0];
            sprintf(pdu.RNTI, "%04x", rand() % 0xFFFF);
            pdu.CRC_INDICATION_REL8_TAG = fields[2];
        } else {
            // Initialize with UE instances
            pdu.RX_UE_INFORMATION_TAG = i;
            sprintf(pdu.RNTI, "%04x", rand() % 0xFFFF);
            pdu.CRC_INDICATION_REL8_TAG = (rand() % 2) * 256 + rand() % 255;
        }

        if (rntiCount >= M && !strcmp(currentRNTI, pdu.RNTI)) {
            // Reuse RNTI values from the beginning of the list
            rntiCount = 0;
        } else if (rntiCount >= M) {
            // Increment RNTI count and reuse RNTI values from the beginning of the list
            for (int j = 0; j < i; j++) {
                array[j].RX_UE_INFORMATION_TAG = array[j + 1].RX_UE_INFORMATION_TAG;
                strcpy(array[j].RNTI, array[j + 1].RNTI);
                array[j].CRC_INDICATION_REL8_TAG = array[j + 1].CRC_INDICATION_REL8_TAG;
            }
            rntiCount = 0;
        }

        if (!strcmp(currentRNTI, pdu.RNTI)) {
            // Increment RNTI count
            rntiCount++;
        } else {
            currentRNTI = pdu.RNTI;
            rntiCount = 1;
        }

        array[i] = pdu;

        if (file) {
            printf("%d,%s,%d", fields[0], line, fields[2]);
            for (int j = i; j < N; j++) {
                array[j].RX_UE_INFORMATION_TAG = array[j + 1].RX_UE_INFORMATION_TAG;
                strcpy(array[j].RNTI, array[j + 1].RNTI);
                array[j].CRC_INDICATION_REL8_TAG = array[j + 1].CRC_INDICATION_REL8_TAG;
            }
        }

        if (i == N - 1 && file) {
            fclose(file);
            file = NULL;
        }
    }
}

int main(int argc, char* argv[]) {
    int numUes = atoi(argv[1]);
    FILE* file = fopen("binary_file.txt", "r");
    initAndPopulateArray(numUes, file);
    return 0;
}
