typedef struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void populateNfarecord(int N) {
    FILE *log_file = fopen("audit.log", "a");

    // Initialize linked list
    struct Node {
        NFAPI_CRC_INDICATION_PDU_T* data;
        struct Node* next;
    };
    struct Node* head = NULL;
    int allocated = 0;

    for (int i = 0; i < N; i++) {
        struct Node* newNode = (struct Node*)malloc(sizeof(struct Node));
        if (!newNode) {
            fprintf(log_file, "Error: Allocation failure at record %d.\n", i);
            continue;
        }
        allocated++;

        // Initialize data structure
        NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        if (!pdu) {
            fprintf(log_file, "Error: Allocation failure at record %d.\n", i);
            free(newNode);
            continue;
        }
        allocated++;

        pdu->RX_UE_INFORMATION_TAG = rand();
        pdu->RNTI = rand() % 100; // Random RNTI value
        pdu->CRCFLAG = rand();

        newNode->data = pdu;
        newNode->next = head;
        head = newNode;

        fprintf(log_file, "Record %d: RX_UE_INFORMATION_TAG=%d, RNTI=%d, CRCFLAG=%d.\n", i, pdu->RX_UE_INFORMATION_TAG, pdu->RNTI, pdu->CRCFLAG);
    }

    if (head) {
        struct Node* current = head;
        while (current->next) {
            current = current->next;
        }
        current->next = NULL;

        // Log last modified timestamp and clinic ID
        time_t now = time(NULL);
        fprintf(log_file, "Last modified: %s", ctime(&now));
        fprintf(log_file, "Clinic ID: 123456\n");

        fclose(log_file);
    } else {
        free(newNode);
        fclose(log_file);
    }
}
