void init_cell_info_table() {
    if (cell_info_table != NULL) {
        free(cell_info_table);
    }
    cell_info_table = (CELL_INFO_TABLE_T*)malloc(1 * sizeof(CELL_INFO_TABLE_T));
    table_size = 1;
}

int find_cell_id(uint32_t cell_id) {
    for (int i = 0; i < table_size; i++) {
        if (cell_info_table[i].cell_id == cell_id) {
            return i;
        }
