        info.rsrp = (float)(rand()) / RAND_MAX * 100.0f;
        info.rsrq = (float)(rand()) / RAND_MAX * 10.0f;
        info.sinr = (float)(rand()) / RAND_MAX * 20.0f;

        uint32_t cell_id = info.cell_id;
        int index = find_cell_id(cell_id);
        if (index == -1) {
            // Add new entry
            cell_info_table = (CELL_INFO_TABLE_T*)realloc(cell_info_table, (table_size + 1) * sizeof(CELL_INFO_TABLE_T));
            table_size++;
            info.unique_id = rand();
            strcpy(cell_info_table[table_size-1].cell_id, "Cell ID: ");
            strcat(cell_info_table[table_size-1].cell_id, itoa(info.cell_id));
            strcat(cell_info_table[table_size-1].cell_id, "\n");
        } else {
            // Update existing entry
            cell_info_table[index].info = info;
        }

        fprintf(log_file, "%s: Added Cell ID %u with unique ID %lu\n", asctime(localtime(&time(NULL))), cell_id, info.unique_id);
    }
}

void free_cell_info_table() {
    for (int i = 0; i < table_size; i++) {
        free(cell_info_table[i].info.cell_id);
    }
    free(cell_info_table);
}
