}

int resize_list(NFAPI_CRC_INDICATION_PDU_T** list, int* n, int new_max_entries) {
    NFAPI_CRC_INDICATION_PDU_T* temp = (NFAPI_CRC_INDICATION_PDU_T*)realloc(*list, new_max_entries * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (!temp) {
        return -1;
    }
    *list = temp;
    return 0;
