        (*list)[i].RNTI = rand() % 100;
        (*list)[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        (*list)[i].CRCFLAG = rand() % 2; // Randomly set CRCFLAG
    }
    *n = max_entries;
    return 0;
}

void flush_list(NFAPI_CRC_INDICATION_PDU_T** list, int* n) {
    free(*list);
    *n = 0;
}

