        if (newFreeMemoryIndex > MEMORY_POOL_SIZE) {
            return NULL; // Memory pool exhausted
        }
        freeMemoryIndex = newFreeMemoryIndex;

        // Simulate logging operation
        printf("Record %d created with timestamp: %f\n", i, time(NULL));
    }

    return memoryPool;
