typedef struct {
    int ue_id;
    int rnti;
    int srsPeriodicity;
    int srsBandwidth;
} UE_CONTEXT_T;

// Function to manage a pool of UE_CONTEXT_T structures for a specified number of user equipment (UE) instances
void configure_and_manage_ue_contexts(int num_ue_instances, int max_rntis) {
    int i;
    UE_CONTEXT_T *ue_contexts = NULL;
    int num_allocated = 0;

    // Initialize the list of NFAPI_CRC_INDICATION_PDU_T structures
    printf("Initializing...\n");
    FILE *file = fopen("ue_contexts.bin", "wb");
    if (file == NULL) {
        fprintf(stderr, "Error opening file for writing!\n");
        return;
    }

    // Initialize the rolling count of unique RNTI values used so far
    int rnti_count = 0;

    // Loop through the specified number of user equipment instances
    for (i = 0; i < num_ue_instances; i++) {
        UE_CONTEXT_T *ue_context = NULL;
        int rnti = -1;

        // Dynamically allocate memory for a new UE context structure
        ue_context = malloc(sizeof(UE_CONTEXT_T));
        if (ue_context == NULL) {
            fprintf(stderr, "Error allocating memory!\n");
            continue;  // Handle edge case: unable to allocate memory
        }

        // Initialize the RNTI value and increment the rolling count
        rnti = rand() % max_rntis;
        if (rnti_count < max_rntis) {
            rnti_count++;
        } else {
            rnti = 0;  // Reuse RNTI values from the beginning of the list
        }

        // Set the UE ID, RNTI, and SRS configuration parameters
        ue_context->ue_id = i;
        ue_context->rnti = rnti;
        ue_context->srsPeriodicity = rand() % 10 + 1;
        ue_context->srsBandwidth = rand() % 1000 + 1;

        // Add the newly allocated UE context structure to the list
        if (ue_contexts == NULL) {
            ue_contexts = malloc(sizeof(UE_CONTEXT_T *) * num_ue_instances);
            if (ue_contexts == NULL) {
                fprintf(stderr, "Error allocating memory!\n");
                free(ue_context);  // Release unallocated UE context structure
                return;
            }
        }

        // Store the RNTI value and increment the number of allocated UE contexts
        ue_contexts[num_allocated++] = ue_context;

        // Serialize the list to a binary file for later retrieval
        fwrite(&ue_context, sizeof(UE_CONTEXT_T), 1, file);

        printf("Allocated UE context %d with RNTI %d...\n", i, rnti);
    }

    fclose(file);
}
