NFAPI_CRC_INDICATION_PDU_T* init_crc_indications(int num_ue_instances, MYSQL *db) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_ue_instances * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    for(int i = 0; i < num_ue_instances; i++) {
        crc_indications[i].RX_UE_INFORMATION_TAG = rand() % RAND_MAX;
        crc_indications[i].RNTI = rand() % RAND_MAX;

        MYSQL_ROW row;
        char query[128];
        sprintf(query, "SELECT CRCFLAG FROM UE_INFO WHERE RNTI = %d", crc_indications[i].RNTI);
        if (mysql_query(db, query)) {
            // handle error
        } else {
            row = mysql_fetch_row(db, query);
            crc_indications[i].CRCFLAG = atoi(row[0]);
        }

        pthread_mutex_lock(&mutex);
        if (crc_indications[i].CRCFLAG > 50) {
            crc_indications[i].CRCFLAG = 1;
        } else if (crc_indications[i].CRCFLAG < 25) {
            crc_indications[i].CRCFLAG = 0;
        }
        pthread_mutex_unlock(&mutex);

        printf("UE Instance %d: RX_UE_INFORMATION_TAG = %d, RNTI = %d, CRCFLAG = %d\n", i+1, crc_indications[i].RX_UE_INFORMATION_TAG, crc_indications[i].RNTI, crc_indications[i].CRCFLAG);
    }

    return crc_indications;
}

void free_crc_indications(NFAPI_CRC_INDICATION_PDU_T* crc_indications, int num_ue_instances) {
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    for(int i = 0; i < num_ue_instances; i++) {
        pthread_mutex_lock(&mutex);
        free(crc_indications[i].CRCFLAG); // assuming CRCFLAG is dynamically allocated
        pthread_mutex_unlock(&mutex);
    }

    free(crc_indications);
}

