    db = mysql_init(NULL);
    mysql_real_connect(db, "localhost", "username", "password", "database", 0);

    NFAPI_CRC_INDICATION_PDU_T* crc_indications = init_crc_indications(MAX_UE_INSTANCES, db);

    free_crc_indications(crc_indications, MAX_UE_INSTANCES);

    mysql_close(db);
    return 0;
}
