int validate_crc_flags(NFAPI_CRC_INDICATION_PDU_T *ue, int num_ue) {
    for (int i = 0; i < num_ue; i++) {
        // Validate CRC flag against predefined thresholds
        if ((*ue)[i].crc_indication_rel8_tag.crcflag > THRESHOLD1 || (*ue)[i].crc_indication_rel8_tag.crcflag < THRESHOLD2) {
            return -1;
        }
    }

