int fetch_ue_info_from_db(int num_ue, NFAPI_CRC_INDICATION_PDU_T **ue_array) {
    // Asynchronously fetch UE information from database
    pthread_t threads[num_ue];

    for (int i = 0; i < num_ue; i++) {
        pthread_create(&threads[i], NULL, &fetch_ue_info_thread_func, (void *)((*ue_array)[i].rnti));
