// Define the linked list structure
typedef struct NFAPI_CRC_INDICATION_PDU_T {
    char RX_UE_INFORMATION_TAG[256];
    int RNTI;
    char CRC_INDICATION_REL8_TAG[256];
    unsigned int CRCFLAG; // CRC flag calculated using a pseudo-random algorithm
} NFAPI_CRC_INDICATION_PDU_T;

// Define the linked list node structure
typedef struct LinkedListNode {
    NFAPI_CRC_INDICATION_PDU_T *data;
    struct LinkedListNode *next;
} LinkedListNode;

// Function to dynamically allocate and populate a linked list of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T **create_crc_indication_pdu_list(int N, int threshold) {
    // Initialize the head pointer
    LinkedListNode *head = NULL;

    // Loop through each entry in the list
    for (int i = 0; i < N; i++) {
        // Allocate memory for a new linked list node
        LinkedListNode *new_node = malloc(sizeof(LinkedListNode));
        if (!new_node) {
            return NULL;
        }

        // Initialize the data structure and set CRC flag randomly using a pseudo-random algorithm
        NFAPI_CRC_INDICATION_PDU_T *data = malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
        strcpy(data->RX_UE_INFORMATION_TAG, "Rx UE Information Tag");
        data->RNTI = rand() % 256;
        strcpy(data->CRC_INDICATION_REL8_TAG, "Crc Indication Rel8 Tag");
        data->CRCFLAG = rand() % 2; // Randomly set CRC flag

        new_node->data = data;
        new_node->next = head;

        if (i < threshold) {
            head = new_node;
        }

        // If the number of entries surpasses the predefined threshold, flush the current list and initiate a new one
        if (i >= threshold) {
            // Flush the current list
            LinkedListNode *curr = head;
            while (curr->next != NULL) {
                curr = curr->next;
            }

            free(curr->data);
            free(curr);

            // Initialize a new head pointer
            head = NULL;

            threshold *= 2; // Adjust the threshold for the next iteration
        }
    }

    return NULL; // Return the linked list nodes (not implemented in this example)
}
