} NFAPI_CRC_INDICATION_PDU_T;

// Structure to manage the dynamic list of NFAPI_CRC_INDICATION_PDU_T structures
typedef struct {
    int size;
    int capacity;
    NFAPI_CRC_INDICATION_PDU_T* list;
    pthread_mutex_t mutex;
    pthread_cond_t cond;
} NFAPI_CRC_INDICATION_LIST_T;

// Function to initialize the list structure
NFAPI_CRC_INDICATION_LIST_T* nfa_pi_crc_indication_list_init(int initial_capacity) {
    NFAPI_CRC_INDICATION_LIST_T* list = (NFAPI_CRC_INDICATION_LIST_T*)malloc(sizeof(NFAPI_CRC_INDICATION_LIST_T));
    list->size = 0;
    list->capacity = initial_capacity;
    list->list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(initial_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));
    pthread_mutex_init(&list->mutex, NULL);
    pthread_cond_init(&list->cond, NULL);
    return list;
}

// Function to add an NFAPI_CRC_INDICATION_PDU_T structure to the list
int nfa_pi_crc_indication_list_add(NFAPI_CRC_INDICATION_LIST_T* list, NFAPI_CRC_INDICATION_PDU_T* pdu) {
    pthread_mutex_lock(&list->mutex);

    if (list->size >= list->capacity) {
        // Double the capacity and reallocate the list
        int new_capacity = list->capacity * 2;
        NFAPI_CRC_INDICATION_PDU_T* new_list = (NFAPI_CRC_INDICATION_PDU_T*)calloc(new_capacity, sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // Copy existing elements to the new list
        for (int i = 0; i < list->size; i++) {
            new_list[i] = list->list[i];
        }

        // Free the old list and update the capacity
        free(list->list);
        list->list = new_list;
        list->capacity = new_capacity;
    }

    // Add the new PDU to the end of the list
    list->list[list->size] = *pdu;
    list->size++;

    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Function to check for duplicate RNTI values in the list
int nfa_pi_crc_indication_list_validate_rnti(NFAPI_CRC_INDICATION_LIST_T* list) {
    pthread_mutex_lock(&list->mutex);

    // Create a set to keep track of unique RNTI values
    bool* rnti_set = (bool*)calloc(list->size, sizeof(bool));
    for (int i = 0; i < list->size; i++) {
        if (rnti_set[i]) {
            // Error: duplicate RNTI found
            fprintf(stderr, "Error: Duplicate RNTI value detected!\n");
            pthread_exit(NULL);
        }

        // Add the current RNTI to the set
        rnti_set[i] = true;
    }

    free(rnti_set);
    pthread_mutex_unlock(&list->mutex);
    return 0;
}

// Function to safely clear the list when no longer needed
void nfa_pi_crc_indication_list_clear(NFAPI_CRC_INDICATION_LIST_T* list) {
    pthread_mutex_lock(&list->mutex);

    // Iterate over the list and free each PDU structure
    for (int i = 0; i < list->size; i++) {
        free(&list->list[i]);
    }

    free(list->list);
    free(list);

    pthread_mutex_unlock(&list->mutex);
}

// Function to safely terminate the program when an error occurs
void nfa_pi_crc_indication_list_terminate(NFAPI_CRC_INDICATION_LIST_T* list) {
    pthread_mutex_lock(&list->mutex);

    // Clear the list before exiting
    nfa_pi_crc_indication_list_clear(list);

    pthread_cond_destroy(&list->cond);
    pthread_mutex_destroy(&list->mutex);

    pthread_exit(NULL);
}
