class AttackManager {
public:
    void selectAttack(int attackId) {
        switch (attackId) {
            case 1: {
                if (!cooldowns_[1] || cooldowns_[1]->expired()) {
                    std::cout << "Selected attack 1.\n";
                    *cooldowns_[1] = std::chrono::steady_clock::now() + std::chrono::seconds(8);
                } else {
                    std::cout << "Attack 1 on cooldown. Waiting for: " << (int)(*cooldowns_[1]->remainingTime()) << " seconds.\n";
                }
                break;
            }
            case 2: {
                if (!cooldowns_[2] || cooldowns_[2]->expired()) {
                    std::cout << "Selected attack 2.\n";
                    *cooldowns_[2] = std::chrono::steady_clock::now() + std::chrono::seconds(9);
                } else {
                    std::cout << "Attack 2 on cooldown. Waiting for: " << (int)(*cooldowns_[2]->remainingTime()) << " seconds.\n";
                }
                break;
            }
            case 3: {
                if (!cooldowns_[3] || cooldowns_[3]->expired()) {
                    std::cout << "Selected attack 3.\n";
                    *cooldowns_[3] = std::chrono::steady_clock::now() + std::chrono::seconds(10);
                } else {
                    std::cout << "Attack 3 on cooldown. Waiting for: " << (int)(*cooldowns_[3]->remainingTime()) << " seconds.\n";
                }
                break;
            }
        }
    }

private:
    struct CooldownTimer {
        std::chrono::steady_clock::time_point start;
        int duration;

        bool expired() const {
            return std::chrono::steady_clock::now() >= start + std::chrono::seconds(duration);
        }

        int remainingTime() const {
            auto now = std::chrono::steady_clock::now();
            return (int)((start + std::chrono::seconds(duration) - now).count());
        }
    };

    std::map<int, CooldownTimer*> cooldowns_ = {{1, nullptr}, {2, nullptr}, {3, nullptr}};
};
