// Custom error structure
typedef struct {
    int code;
    char* message;
} Error;

// MAC-CE structure
typedef struct {
    char* pdu;
    char* mac_identity;
    long timestamp;
} MAC_CE;

// Resource bundle item
typedef struct {
    int id;
    char* name;
    double value;
} Item;

// Dynamic list of MAC-CE structures
typedef struct {
    int size;
    MAC_CE** items;
} MAC_CE_List;

// Dynamic resource bundle
typedef struct {
    int size;
    Item** items;
} Resource_Bundle;

// Function to load a resource bundle from a file and manage the dynamic list of MAC-CE structures
Error* load_resource_bundle(char* file_path, MAC_CE_List* mac_ce_list, Resource_Bundle* resource_bundle) {
    // Initialize error structure
    Error* error = (Error*)malloc(sizeof(Error));
    error->code = 0;
    error->message = NULL;

    // Load resource bundle from file
    FILE* file = fopen(file_path, "r");
    if (file == NULL) {
        error->code = 1;
        error->message = "Failed to open file";
        return error;
    }

    // Initialize resource bundle and MAC-CE list
    resource_bundle->size = 0;
    resource_bundle->items = NULL;
    mac_ce_list->size = 0;
    mac_ce_list->items = NULL;

    // Load items from file and add to resource bundle
    Item* item = (Item*)malloc(sizeof(Item));
    while (fscanf(file, "%d %s %lf", &item->id, item->name, &item->value) == 3) {
        // Check for duplicate item identifiers
        int found = 0;
        for (int i = 0; i < resource_bundle->size; i++) {
            if (resource_bundle->items[i]->id == item->id) {
                error->code = 2;
                error->message = "Duplicate item identifier";
                return error;
            }
        }

        // Add item to resource bundle
        resource_bundle->items = (Item**)realloc(resource_bundle->items, sizeof(Item*) * (resource_bundle->size + 1));
        resource_bundle->items[resource_bundle->size++] = item;

        // Initialize MAC-CE list and item
        mac_ce_list->items = (MAC_CE*)malloc(sizeof(MAC_CE));
        mac_ce_list->items->pdu = NULL;
        mac_ce_list->items->mac_identity = NULL;
        mac_ce_list->items->timestamp = 0;

        // Check for duplicate MAC identities
        found = 0;
        for (int i = 0; i < mac_ce_list->size; i++) {
            if (strcmp(mac_ce_list->items[i]->mac_identity, item->name) == 0) {
                error->code = 3;
                error->message = "Duplicate MAC identity";
                return error;
            }
        }

        // Add MAC-CE to list
        mac_ce_list->items = (MAC_CE*)realloc(mac_ce_list->items, sizeof(MAC_CE) * (mac_ce_list->size + 1));
        mac_ce_list->items[mac_ce_list->size++] = mac_ce_list->items;
    }

    // Close file and free resources
    fclose(file);
    for (int i = 0; i < resource_bundle->size; i++) {
        free(resource_bundle->items[i]);
    }
    free(resource_bundle->items);
    free(mac_ce_list->items);
    free(error);

    return error;
}

// Function to clear the dynamic list of MAC-CE structures and the resource bundle
void clear_lists(MAC_CE_List* mac_ce_list, Resource_Bundle* resource_bundle) {
    // Clear MAC-CE list
    for (int i = 0; i < mac_ce_list->size; i++) {
        free(mac_ce_list->items[i]->pdu);
        free(mac_ce_list->items[i]->mac_identity);
        free(mac_ce_list->items[i]);
    }
    free(mac_ce_list->items);
    mac_ce_list->size = 0;
    mac_ce_list->items = NULL;

    // Clear resource bundle
    for (int i = 0; i < resource_bundle->size; i++) {
        free(resource_bundle->items[i]->name);
        free(resource_bundle->items[i]);
    }
    free(resource_bundle->items);
    resource_bundle->size = 0;
    resource_bundle->items = NULL;
}

// Function to safely clear both the MAC-CE list and the resource bundle when no longer needed
void* destructor(void* ptr) {
    if (ptr == NULL) return NULL;

    // Clear lists
    clear_lists((MAC_CE_List*)ptr, &((Resource_Bundle*)ptr)->resource_bundle);

    free(ptr);
}

// Function to create a new thread and initialize it with the destructor function
pthread_t start_thread(void* ptr) {
    pthread_t thread;
    pthread_create(&thread, NULL, (void(*)(void*))destructor, ptr);
    return thread;
}
