    HTTP_REQUEST_MESSAGE** queue = (HTTP_REQUEST_MESSAGE**)malloc(sizeof(HTTP_REQUEST_MESSAGE*) * M);
    for(int i = 0; i < M; i++) {
        queue[i] = (HTTP_REQUEST_MESSAGE*)malloc(sizeof(HTTP_REQUEST_MESSAGE));
