    // Flush the queue and initiate a new one when necessary
    flush_queue(queue);

    return 0;
}

void process_queue(HTTP_REQUEST_MESSAGE** queue, int size) {
    for(int i = 0; i < size; i++) {
        if(check_request(queue[i])) {
            // Process the request
            printf("Processing request %d...\n", queue[i]->request_id);
        } else {
            // Handle potential failures from an external HTTP server
            int retries = 0;
            while(retries < 3) {
                // Retry the operation
                if(check_request(queue[i])) {
                    break;
                }
                retries++;
            }
            if(retries == 3) {
                // Fallback mechanism to process partial data if possible
                printf("Failed to process request %d after 3 retries.\n", queue[i]->request_id);
            }
        }
    }
}

void flush_queue(HTTP_REQUEST_MESSAGE** queue) {
    int threshold = 10; // predefined threshold
    for(int i = 0; i < threshold; i++) {
        if(queue[i] != NULL) {
            free(queue[i]);
        }
    }
    // Reallocate the queue with a new size based on current usage
    int newSize = threshold * 2;
    queue = (HTTP_REQUEST_MESSAGE**)realloc(queue, sizeof(HTTP_REQUEST_MESSAGE*) * newSize);
