void initializeAndConfigureDynamicArray(int N, int M) {
    int i, j;
    MAC_CONTEXT_T* contexts = (MAC_CONTEXT_T*)malloc(N * sizeof(MAC_CONTEXT_T));
    if (!contexts) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Initialize cache size and eviction policies
    int cache_size = N / 2; // Initial cache size
    int eviction_count = 0; // Count of evictions

    for (i = 0; i < N; i++) {
        contexts[i].ue_id = i;
        contexts[i].retransmit_enabled = (i % 2 == 0);

        // Dynamically allocate list of packets
        int packet_count = (rand() % M) + 1;
        contexts[i].packets = (void**)malloc(packet_count * sizeof(void*));
        if (!contexts[i].packets) {
            printf("Memory allocation failed.\n");
            return;
        }

        // Initialize rolling count of unique RNTI values
        uint16_t rnti_count = 0;
        for (j = 0; j < packet_count; j++) {
            NFAPI_CRC_INDICATION_PDU_T* pdu = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));
            if (!pdu) {
                printf("Memory allocation failed.\n");
                return;
            }

            // Ensure no two consecutive structures have the same RNTI value
            uint16_t rnti = (rnti_count++) % M;
            pdu->rnti = rnti;

            contexts[i].packets[j] = pdu; // Store packet pointer

            // Check for maximum number of unique RNTI values reached
            if ((j + 1) == M) {
                rnti_count %= M; // Reuse RNTI values from the beginning
            }
        }

        contexts[i].packet_count = j;
    }

    // Serialize list to a binary file for later retrieval
    FILE* file = fopen("contexts.bin", "wb");
    if (file) {
        fwrite(contexts, sizeof(MAC_CONTEXT_T), N, file);
        fclose(file);
    } else {
        printf("File serialization failed.\n");
    }

    // Periodically evaluate and adjust cache size and eviction policies
    while (eviction_count < 5) { // Adjust cache size every 5 evictions
        cache_size = (cache_size * 3) / 2; // Adjust cache size based on performance metrics
        eviction_count++;

        printf("Cache size adjusted to %d.\n", cache_size);
    }

    // Cache mechanisms for frequently accessed contexts
    int* cache = (int*)malloc(cache_size * sizeof(int));
    if (!cache) {
        printf("Memory allocation failed.\n");
        return;
    }

    // Implement a logging mechanism for tracking allocations
    FILE* log_file = fopen("allocations.log", "a");
    if (log_file) {
        fwrite(&N, sizeof(int), 1, log_file);
        fclose(log_file);
    } else {
        printf("File logging failed.\n");
    }

    // Free memory to avoid leaks
    for (i = 0; i < N; i++) {
        for (j = 0; j < contexts[i].packet_count; j++) {
            free(contexts[i].packets[j]);
        }
        free(contexts[i].packets);
    }
    free(contexts);
    free(cache);
}
