    new_ctx = &state->contexts[state->count];
    new_ctx->ue_id = ue_id;
    new_ctx->packets = NULL;
    new_ctx->retransmit_enabled = retransmit_enabled;

    state->count++;
}

void add_packet(system_state *state, uint32_t ue_id) {
    pthread_mutex_lock(&state->lock);

    for (int i = 0; i < state->count; i++) {
