        crc_indication_rel8->rnti = rand() % 10000; // Randomly generated Resource Global Identifier (RNTI)

        int random_crcflag = rand() % 2; // Randomly set CRCFLAG
        crc_indication_rel8->crcflag = (uint8_t)random_crcflag;
