import java.util.*;

class UnionFind {
    int[] parent;
    int[] rank;

    public UnionFind(int n) {
        parent = new int[n];
        rank = new int[n];

        for (int i = 0; i < n; i++) {
            parent[i] = i;
            rank[i] = 0;
        }
    }

    public int find(int x) {
        if (parent[x] != x) {
            parent[x] = find(parent[x]);
        }
        return parent[x];
    }

    public void union(int x, int y) {
        int rootX = find(x);
        int rootY = find(y);

        if (rootX == rootY) return;

        if (rank[rootX] > rank[rootY]) {
            parent[rootY] = rootX;
        } else {
            parent[rootX] = rootY;
            if (rank[rootX] == rank[rootY]) {
                rank[rootY]++;
            }
        }
    }

    public void serialize() {
        for (int i = 0; i < parent.length; i++) {
            System.out.print(parent[i] + " ");
        }
        System.out.println();
    }

    public void deserialize(String[] states) {
        int n = states.length;
        this.parent = new int[n];
        this.rank = new int[n];

        for (int i = 0; i < n; i++) {
            this.parent[i] = Integer.parseInt(states[i]);
        }
    }
}

public class DisjointPairCounter {

    public static void main(String[] args) {
        // Initialize the Union-Find data structure
        int N = 100000; // Adjust according to input size constraints
        UnionFind uf = new UnionFind(N);

        // Read array elements from file in chunks (e.g., 10^5 at a time)
        int[][] arr = new int[1][];
        try (BufferedReader br = new BufferedReader(new FileReader("input.txt"))) {
            String line;
            while ((line = br.readLine()) != null) {
                String[] tempArr = line.split(","); // Adjust according to file format
                arr[arr.length - 1] = new int[tempArr.length];
                for (int i = 0; i < tempArr.length; i++) {
                    arr[arr.length - 1][i] = Integer.parseInt(tempArr[i]);
                }
                if (arr.length >= N / (10 * 100)) { // Check chunk size
                    processArray(arr);
                    arr = new int[1][];
                }
            }
        }

        // Handle remaining elements in the last chunk
        processArray(arr);

    }

    public static void processArray(int[][] arr) {
        // Initialize statistics for disjoint pair counting and Union-Find operations
        long startTime = System.nanoTime();
        int numDisjointPairs = 0;
        int numOperations = 0;

        try (BufferedReader br = new BufferedReader(new FileReader("input.txt"))) {
            String line;
            while ((line = br.readLine()) != null) {
                String[] tempArr = line.split(","); // Adjust according to file format
                for (int i = 0; i < tempArr.length - 1; i++) { // Handle remaining elements in the last chunk
                    int x = Integer.parseInt(tempArr[i]);
                    int y = Integer.parseInt(tempArr[i + 1]);

                    if (uf.find(x) != uf.find(y)) {
                        numDisjointPairs++;
                        long endTime = System.nanoTime();
                        System.out.println("Time taken for pair check: " + (endTime - startTime));
                        startTime = endTime;
                    }
                    uf.union(x, y);
                    numOperations++;

                    // Check for inconsistencies in the input data
                    if (!isValidIndex(x) || !isValidIndex(y)) {
                        throw new RuntimeException("Invalid indices detected!");
                    }
                }
            }
        }

        System.out.println("Number of disjoint pairs: " + numDisjointPairs);
        System.out.println("Total operations performed by Union-Find: " + numOperations);

    }

    private static boolean isValidIndex(int index) {
        // Implement your custom validation logic here
        return true; // Replace with actual validation checks
    }
}
