void* allocate_array(size_t size) {
    void* ptr = malloc(size);
    if (ptr == NULL) {
        printf("Memory allocation failed\n");
        return NULL;
    }
    memset(ptr, 0, size);
    return ptr;
}

int process_media_stream_frames(int num_tasks) {
    // Dynamically allocate array of structures
    MEDIA_STREAM_FRAME** frames = (MEDIA_STREAM_FRAME**)allocate_array(num_tasks * sizeof(MEDIA_STREAM_FRAME*));
    if (frames == NULL) {
        return -1;  // Handle memory allocation failure
    }

    // Initialize frame IDs and media stream channels
    for (int i = 0; i < num_tasks; i++) {
        frames[i] = allocate_array(sizeof(MEDIA_STREAM_FRAME));
        frames[i]->frame_id = i;
        strcpy(frames[i]->media_stream_channel, "Channel ");
        strcat(frames[i]->media_stream_channel, itoa(i));
    }

    // Periodic updates to video content
    for (int j = 0; j < num_tasks; j++) {
        // Validate existing video content before overwriting
        if (strlen(frames[j]->video_content) > 0) {
            // Update video content
            char* new_video_content = allocate_array(strlen(frames[j]->video_content) + 100);
            strcpy(new_video_content, frames[j]->video_content);
            strcat(new_video_content, " Updated ");
            free(frames[j]->video_content);
            frames[j]->video_content = new_video_content;
        }
    }

    // Handle out-of-memory conditions
    for (int k = 0; k < num_tasks; k++) {
        if (frames[k] == NULL) {
            printf("Out of memory\n");
            continue;
        }
        // Cache partially populated structures
        // Merge cache into main array periodically to minimize locking overhead
    }

    // Thread-safe handling of concurrent requests from multiple threads
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    void* thread_cache[num_tasks];
    for (int l = 0; l < num_tasks; l++) {
        thread_cache[l] = allocate_array(sizeof(MEDIA_STREAM_FRAME));
        pthread_mutex_lock(&mutex);
        // Merge cache into main array periodically to minimize locking overhead
        pthread_mutex_unlock(&mutex);
    }

    return 0;
}
