typedef struct Node {
    QoSConfig config;
    struct Node* prev;
    struct Node* next;
} Node;

void init_qos_queue(Node** queue, size_t initial_size) {
    *queue = (Node*)malloc(initial_size * sizeof(Node));
    for(size_t i = 0; i < initial_size; ++i) {
        (*queue)[i].prev = &((*queue)[i-1]);
        if(i > 0) {
            (*queue)[i-1].next = &((*queue)[i]);
        }
    }
    (*queue)[0].prev = NULL;
    (*queue)[initial_size - 1].next = NULL;
}

void serialize_config(QoSConfig* config, char* buffer) {
    *(int*)buffer = htonl(config->priority);
    *(int*)((char*)buffer + sizeof(int)) = htonl(config->bandwidth_limit);
    *(int*)((char*)buffer + 2 * sizeof(int)) = htonl(config->delay_constraint);
}

void deserialize_config(QoSConfig* config, char* buffer) {
    config->priority = ntohl(*(int*)buffer);
    config->bandwidth_limit = ntohl(*(int*)((char*)buffer + sizeof(int)));
    config->delay_constraint = ntohl(*(int*)((char*)buffer + 2 * sizeof(int)));
}

