void adjust_ue_contexts(int num_ue_contexts, int network_congestion_level) {
    // Adjust the number of UE contexts based on network congestion level (e.g., 0-5)
    if (network_congestion_level > 3) {
        num_ue_contexts = num_ue_contexts / 2;
