    for (int i = 0; i < num_ues; i++) {
        (*ue_ctx_pool)[i].ue_id = i + 1;

        int rnti = rand() % MAX_RNTI_VALUES;
        while (rnti == 0) {
            rnti = rand() % MAX_RNTI_VALUES;
        }
        (*ue_ctx_pool)[i].rnti = rnti;

        // dynamically set srsPeriodicity and srsBandwidth
        sprintf((*ue_ctx_pool)[i].srs_config, "srsPeriodicity=%d,srsBandwidth=1000", i);
    }

    printf("Number of successful allocations: %d\n", num_ues);
}

typedef struct {
    int rx_ue_info_tag;
    int rnti;
    char crc_ind_rel8_tag[4]; // CRCFLAG
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T *populate_crc_indication_pdu_list(int n, int m) {
    NFAPI_CRC_INDICATION_PDU_T *crc_list = (NFAPI_CRC_INDICATION_PDU_T *)malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (crc_list == NULL) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    int unique_rntis = 0;
    int current_rnti = rand() % MAX_RNTI_VALUES;

    for (int i = 0; i < n; i++) {
        crc_list[i].rx_ue_info_tag = i + 1;
        crc_list[i].rnti = current_rnti;

        if (++unique_rntis >= m) {
            current_rnti = rand() % MAX_RNTI_VALUES;
        }

        crc_list[i].crc_ind_rel8_tag[0] = (char)(rand() % 256);
        crc_list[i].crc_ind_rel8_tag[1] = (char)(rand() % 256);
        crc_list[i].crc_ind_rel8_tag[2] = (char)(rand() % 256);
        crc_list[i].crc_ind_rel8_tag[3] = '\0';

        if ((i + 1) < n && unique_rntis >= m) {
            current_rnti = rand() % MAX_RNTI_VALUES;
        }
    }

    printf("Number of successful allocations: %d\n", n);

    return crc_list;
}

void modify_filename(char *filename, char **new_filename) {
    int vowel_count = 0;

    for (int i = 0; filename[i]; i++) {
        if (!strchr("aeiouAEIOU", filename[i])) continue;
        vowel_count++;
    }

    char new_extension[10];
    sprintf(new_extension, ".txt%ds", vowel_count ? 1 : 0);

    int file_type = -1;

    if (filename[strlen(filename) - 1] >= 'a' && filename[strlen(filename) - 1] <= 'z') {
        file_type = 2; // letter
    } else if (filename[strlen(filename) - 1] >= '0' && filename[strlen(filename) - 1] <= '9') {
        file_type = 1; // digit
    }

    char *new_file_name = (char *)malloc(strlen(filename) + strlen(new_extension) + 2);

    if (file_type == 2)
        sprintf(new_file_name, "%s%s", filename, new_extension);
    else if (file_type == 1)
        sprintf(new_file_name, "%s.log%ds", filename, vowel_count ? 1 : 0);
    else
        sprintf(new_file_name, "%s.bin%ds", filename, vowel_count ? 1 : 0);

    *new_filename = new_file_name;
}
