        return -1; // invalid BS instance or frame number
    }

    NFAPI_L1_RX_FRAME_INFO_T* frame_info = (NFAPI_L1_RX_FRAME_INFO_T*)malloc(sizeof(NFAPI_L1_RX_FRAME_INFO_T));
