    for (int i = 0; i < FRAME_METADATA_CACHE_SIZE; i++) {
        if (!frame_cache[bs_instance_id]->frames[i]) {
            frame_cache[bs_instance_id]->frames[i] = frame_info;
            break;
        }
    }

    pthread_mutex_unlock(&frame_cache[bs_instance_id]->mutex);

