    if (config_profile_id > MAX_SUPPORTED_CONFIG_PROFILE_ID) {
        LOG_WARNING("Unsupported configuration profile");
        // Apply most similar available profile
        netif_cfg->CONFIG_PROFILE_ID = get_nearest_supported_config_profile(config_profile_id);
