    // Optimize memory usage during peak loads by reusing allocated memory
    void* reused_memory = realloc(ue_info_array, (num_ue_instances + 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    if (reused_memory != NULL) {
        ue_info_array = reused_memory;
    }

    // Integrate with external logging system
    log_configuration_setup_start();
    for (i = 0; i < num_ue_instances; i++) {
        log_configuration_setup_update(i, &ue_info_array[i]);
    }
    log_configuration_setup_end();

    free(ue_info_array);
    free(thread_cache);
}
