#define MAX_MESSAGES 1000
#define THRESHOLD 500
#define RETRIES 3

typedef struct {
    int order_id;
    char execution_report[32];
    time_t timestamp;
    int sequence_number;
} NFIXX_MESSAGE_T;

void* nfixx_message_array_init(int num_elements, unsigned seed) {
    if (num_elements > MAX_MESSAGES || seed < 0) {
        return NULL;
    }

    srand(seed);

    NFIXX_MESSAGE_T* messages = (NFIXX_MESSAGE_T*)malloc(num_elements * sizeof(NFIXX_MESSAGE_T));
    if (!messages) {
        return NULL;
    }

    int retries = RETRIES;
    while (retries--) {
        for (int i = 0; i < num_elements; i++) {
            NFIXX_MESSAGE_T* message = &messages[i];
            message->order_id = rand() % 10000;
            sprintf(message->execution_report, "EXECUTION_REPORT_%d", i);
            message->timestamp = time(NULL) + i;
            message->sequence_number = (i * seed) % 1000;
        }
    }

    if (!flush_list(messages, num_elements)) {
        free(messages);
        return NULL;
    }

    return messages;
}

int flush_list(NFIXX_MESSAGE_T* messages, int num_elements) {
    if (num_elements > THRESHOLD) {
        for (int i = 0; i < THRESHOLD; i++) {
            NFIXX_MESSAGE_T message = messages[i];
            // Process the message
        }
        return 1;
    }
    return 0;
}

void nfixx_message_array_deinit(void* array) {
    free(array);
}
