    for (int i = 0; i < numFrames; i++) {
        double sum = 0.0;
        for (int j = 0; j < 10; j++) { // calculate moving average of last 10 measurements
            if (j < frames[i].measurementCount) {
                sum += frames[i].measurements[j];
            } else {
                sum += frames[i].measurements[frames[i].measurementCount - 1] / 2.0;
            }
        }

        frames[i].signalStrength = sum / min(frames[i].measurementCount, 10);
    }
