#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

typedef struct {
    int frameNumber;
    struct MeasurementResult *measurementResults;
    double signalStrength;
    int successfulMeasurements;
} FrameStatistics;

typedef struct {
    double value1, value2;
} MeasurementResult;

void* initializeFrameStatisticsArray(int capacity) {
    FrameStatistics *frameStats = (FrameStatistics*)malloc(capacity * sizeof(FrameStatistics));
    for (int i = 0; i < capacity; i++) {
        frameStats[i].measurementResults = (MeasurementResult*)malloc(10 * sizeof(MeasurementResult)); // reserve memory for 10 measurements
        frameStats[i].signalStrength = 0.0;
        frameStats[i].successfulMeasurements = 0;
    }
    return frameStats;
}

void* processFrameStatisticsLine(char *line, int capacity, FrameStatistics **frameStats) {
    char *token = strtok(line, ",");
    if (token == NULL) return NULL;

    int frameNumber = atoi(token);
    token = strtok(NULL, ",");
    if (token == NULL) return NULL;

    MeasurementResult measurement;
    measurement.value1 = atof(token);
    measurement.value2 = atof(strtok(NULL, ","));

    FrameStatistics *frameStatsArray = *frameStats;
    for (int i = 0; i < capacity; i++) {
        if (frameStatsArray[i].frameNumber == frameNumber) {
            // add new measurement to the existing array
            frameStatsArray[i].measurementResults[frameStatsArray[i].successfulMeasurements] = measurement;
            frameStatsArray[i].signalStrength += measurement.value1 + measurement.value2;
            frameStatsArray[i].signalStrength /= 2.0; // calculate moving average
            frameStatsArray[i].successfulMeasurements++;
            break;
        }
    }

    return NULL;
}

void logStatistics(FrameStatistics *frameStats, int capacity) {
    FILE *fp = fopen("log.txt", "a");
    for (int i = 0; i < capacity; i++) {
        fprintf(fp, "%d,%f,%d\n", frameStats[i].frameNumber, frameStats[i].signalStrength, frameStats[i].successfulMeasurements);
    }
    fclose(fp);
}

void* resizeFrameStatisticsArray(int capacity, FrameStatistics **frameStats) {
    FrameStatistics *newFrameStats = (FrameStatistics*)realloc(*frameStats, 2 * capacity * sizeof(FrameStatistics));
    *frameStats = newFrameStats;
    return NULL;
}

int main() {
    int capacity = 10; // initial array capacity
    FrameStatistics *frameStats = initializeFrameStatisticsArray(capacity);
    FILE *fp = fopen("input.txt", "r");
    char line[1024];

    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    int linesProcessed = 0, errorsEncountered = 0;

    while (fgets(line, sizeof(line), fp)) {
        pthread_mutex_lock(&mutex);
        processFrameStatisticsLine(line, capacity, &frameStats);
        if (errno) {
            errorsEncountered++;
        }
        pthread_mutex_unlock(&mutex);

        linesProcessed++;

        // dynamically resize the array if exceeded
        if (linesProcessed >= capacity) {
            frameStats = resizeFrameStatisticsArray(capacity, &frameStats);
            capacity *= 2;
        }
    }

    logStatistics(frameStats, capacity);

    free(frameStats);
    fclose(fp);

    printf("Lines processed: %d\n", linesProcessed);
    printf("Errors encountered: %d\n", errorsEncountered);

    return 0;
}
