#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#define NFIXX_MESSAGE_T_MAX_SIZE 1024
#define MAX_ATTEMPTS 3
#define SEQUENCE_NUMBER_MAX_SIZE 16
#define MESSAGE_FORMAT_VERSION 1.0
#define MESSAGE_PACKET_THRESHOLD 10000

typedef struct {
    int order_id;
    char execution_report[NFIXX_MESSAGE_T_MAX_SIZE];
    time_t timestamp;
    unsigned long sequence_number;
} NFIXX_MESSAGE_T;

void* nfixx_message_alloc(int count) {
    return calloc(count, sizeof(NFIXX_MESSAGE_T));
}

void nfixx_message_free(void* messages) {
    free(messages);
}

int generate_sequence_number(const char* message_format, time_t timestamp) {
    // deterministic algorithm based on message type and timestamp
    int sequence = (int)(timestamp / 1000 + message_format[0]);
    return sequence;
}

void nfixx_message_initialize(void** messages, int count, const char* message_format, unsigned long seed) {
    *messages = nfixx_message_alloc(count);
    for (int i = 0; i < count; i++) {
        NFIXX_MESSAGE_T* msg = (*messages + i);
        msg->order_id = rand_r(&seed) % 10000;
        strcpy(msg->execution_report, "EXECUTION REPORT");
        msg->timestamp = time(NULL);
        msg->sequence_number = generate_sequence_number(message_format, msg->timestamp);
    }
}

void nfixx_message_flush(void** messages) {
    if (*messages != NULL) {
        free(*messages);
        *messages = NULL;
    }
}

int nfixx_message_insert(void** messages, NFIXX_MESSAGE_T* new_msg) {
    int count = 0;
    if (*messages == NULL) {
        *messages = malloc(sizeof(NFIXX_MESSAGE_T));
        **messages = *new_msg;
        return 1;
    } else {
        void* temp = realloc(*messages, sizeof(NFIXX_MESSAGE_T) * (count + 1));
        if (temp != NULL) {
            (*messages) = temp;
            memcpy((*messages) + count, new_msg, sizeof(NFIXX_MESSAGE_T));
            return count + 1;
        } else {
            printf("Memory allocation failed.\n");
            return -1;
        }
    }
}

int main() {
    // usage example
    void* messages = NULL;
    int count = 10;
    const char* message_format = "MESSAGE_FORMAT";
    unsigned long seed = time(NULL);

    nfixx_message_initialize(&messages, count, message_format, seed);

    NFIXX_MESSAGE_T new_msg;
    // populate new_msg...

    while (nfixx_message_insert(&messages, &new_msg) == 1 && *messages != NULL && count < MESSAGE_PACKET_THRESHOLD) {
        count++;
    }

    if (*messages != NULL) {
        printf("Messages inserted: %d\n", count);
    } else {
        printf("Error inserting messages.\n");
    }

    nfixx_message_flush(&messages);

    return 0;
}
