#include <stdio.h>
#include <stdlib.h>
#include <string.h>

#define HASH_TABLE_RESIZE_FACTOR 2
#define LOAD_FACTOR_THRESHOLD 0.7
#define INITIAL_HASH_TABLE_SIZE 16
#define LOG_LEVEL 1 // 0 - error, 1 - warning, 2 - info

typedef struct {
    char RX_UE_INFORMATION_TAG[32];
    uint32_t RNTI;
    char CRC_INDICATION_REL8_TAG[32];
    float signal_strength;
    time_t timestamp;
} NFAPI_RX_MESSAGE_PDU_T;

typedef struct {
    NFAPI_RX_MESSAGE_PDU_T* data;
    int size;
    int capacity;
    float load_factor;
} HashTable;

HashTable* create_hash_table(int initial_size, int seed) {
    HashTable* hash_table = (HashTable*)malloc(sizeof(HTable));
    if (!hash_table) {
        fprintf(stderr, "Error: unable to allocate memory for hash table.\n");
        return NULL;
    }
    hash_table->data = (NFAPI_RX_MESSAGE_PDU_T*)calloc(initial_size, sizeof(NFAPI_RX_MESSAGE_PDU_T));
    if (!hash_table->data) {
        free(hash_table);
        fprintf(stderr, "Error: unable to allocate memory for hash table data.\n");
        return NULL;
    }
    hash_table->size = 0;
    hash_table->capacity = initial_size;
    hash_table->load_factor = 0.0;
    srand(seed); // initialize random number generator with the given seed
    return hash_table;
}

void insert_hash_table(HashTable* hash_table, NFAPI_RX_MESSAGE_PDU_T message) {
    int index = message.RNTI % hash_table->capacity;
    if (hash_table->size == hash_table->capacity || 
        calculate_load_factor(hash_table) > LOAD_FACTOR_THRESHOLD) {
        resize_hash_table(hash_table);
        index = message.RNTI % hash_table->capacity;
    }
    // insert the message into the hash table
    hash_table->data[index] = message;
    hash_table->size++;
    hash_table->load_factor = (float)hash_table->size / hash_table->capacity;
}

int lookup_hash_table(HashTable* hash_table, NFAPI_RX_MESSAGE_PDU_T query_message) {
    int index = query_message.RNTI % hash_table->capacity;
    if (hash_table->data[index].RNTI == query_message.RNTI) {
        return 1; // found
    }
    for (int i = 0; i < hash_table->size; i++) {
        index = (index + 1) % hash_table->capacity;
        if (hash_table->data[index].RNTI == query_message.RNTI) {
            return 1; // found
        }
    }
    return 0; // not found
}

void delete_hash_table(HashTable* hash_table, NFAPI_RX_MESSAGE_PDU_T query_message) {
    int index = query_message.RNTI % hash_table->capacity;
    for (int i = 0; i < hash_table->size; i++) {
        if (hash_table->data[index].RNTI == query_message.RNTI) {
            // shift remaining elements down
            memmove(&hash_table->data[index], &hash_table->data[index + 1], 
                    (hash_table->size - i - 1) * sizeof(NFAPI_RX_MESSAGE_PDU_T));
            hash_table->size--;
            break;
        }
        index = (index + 1) % hash_table->capacity;
    }
}

float calculate_load_factor(HashTable* hash_table) {
    return (float)hash_table->size / hash_table->capacity;
}

void resize_hash_table(HashTable* hash_table) {
    int new_capacity = hash_table->capacity * HASH_TABLE_RESIZE_FACTOR;
    NFAPI_RX_MESSAGE_PDU_T* new_data = 
        (NFAPI_RX_MESSAGE_PDU_T*)realloc(hash_table->data, new_capacity * sizeof(NFAPI_RX_MESSAGE_PDU_T));
    if (!new_data) {
        fprintf(stderr, "Error: unable to allocate memory for resized hash table.\n");
        return;
    }
    hash_table->capacity = new_capacity;
    hash_table->data = new_data;
}

void log_hash_table_operation(int level, const char* message) {
    if (level <= LOG_LEVEL) {
        printf("Hash Table: %s\n", message);
    }
}
