#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <time.h>

#define MAX_SIZE 10000
#define MAX_RNTI_LENGTH 10

typedef struct {
    char RX_UE_INFORMATION_TAG[MAX_RNTI_LENGTH];
    int RNTI;
    uint16_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct Node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct Node* next;
} Node;

Node* create_node(NFAPI_CRC_INDICATION_PDU_T data) {
    Node* node = (Node*)malloc(sizeof(Node));
    node->data = data;
    node->next = NULL;
    return node;
}

void free_node(Node* node) {
    if(node == NULL)
        return;
    free_node(node->next);
    free(node);
}

int check_rnti_duplicate(Node* head, int rnti) {
    while(head != NULL) {
        if(head->data.RNTI == rnti)
            return 1;
        head = head->next;
    }
    return 0;
}

void add_node(Node** head_ref, NFAPI_CRC_INDICATION_PDU_T data) {
    Node* new_node = create_node(data);
    if(*head_ref == NULL || check_rnti_duplicate(*head_ref, data.RNTI)) {
        new_node->next = *head_ref;
        *head_ref = new_node;
    }
}

void serialize_list_to_file(Node* head, FILE* file) {
    while(head != NULL) {
        fwrite(&head->data, sizeof(NFAPI_CRC_INDICATION_PDU_T), 1, file);
        head = head->next;
    }
}

int count_unique_rnti(Node* head) {
    int unique_count = 0;
    Node* current = head;
    while(current != NULL) {
        if(!check_rnti_duplicate(head, current->data.RNTI))
            unique_count++;
        current = current->next;
    }
    return unique_count;
}

int main() {
    Node* head = NULL;

    // Add some sample data
    srand(time(NULL));
    for(int i = 0; i < MAX_SIZE; i++) {
        NFAPI_CRC_INDICATION_PDU_T data;
        data.RX_UE_INFORMATION_TAG[0] = 'A' + rand() % 26;
        data.RNTI = rand() % 10000;
        data.CRCFLAG = rand();
        add_node(&head, data);
    }

    FILE* file = fopen("data.bin", "wb");
    if(file != NULL) {
        serialize_list_to_file(head, file);
        fclose(file);
    }

    printf("Unique RNTI count: %d\n", count_unique_rnti(head));

    free_node(head);

    return 0;
}
