struct list_node {
    NFAPI_CRC_INDICATION_PDU_T data;
    struct list_node* next;
};

struct list {
    pthread_mutex_t mutex;
    int size;
    int max_size;
    int element_count;
    struct list_node* head;
    struct list_node* tail;
    FILE* log_file;
};

void init_list(struct list* lst, int max_size) {
    if (max_size > 10000)
        max_size = 10000;

    lst->head = NULL;
    lst->tail = NULL;
    lst->size = 0;
    lst->element_count = 0;
    lst->max_size = max_size;

    pthread_mutex_init(&lst->mutex, NULL);
}

void add_element(struct list* lst, NFAPI_CRC_INDICATION_PDU_T data) {
    struct list_node* node = (struct list_node*)malloc(sizeof(struct list_node));
    if (!node) {
        perror("Memory allocation failed");
        return;
    }

    node->data = data;

    pthread_mutex_lock(&lst->mutex);

    if (lst->size == lst->max_size) {
        struct list_node* temp = lst->tail;
        while (temp && temp->next)
            temp = temp->next;
        if (!temp)
            lst->tail = NULL;

        free(temp);
        lst->size--;
    }

    node->next = NULL;
    if (!lst->head) {
        lst->head = node;
        lst->tail = node;
    } else {
        lst->tail->next = node;
        lst->tail = node;
    }
    lst->size++;
    lst->element_count++;

    pthread_mutex_unlock(&lst->mutex);
}

