               current->data.RNTI,
               current->data.CRC_INDATION_REL8_TAG,
               current->data.CRCFLAG);

    pthread_mutex_unlock(&lst->mutex);
}

void clear_list(struct list* lst) {
    while (lst->head) {
        struct list_node* temp = lst->head;
        lst->head = lst->head->next;
        free(temp);
        lst->size--;
    }
    lst->tail = NULL;
    lst->element_count = 0;
}

