import xml.etree.ElementTree as ET
from logging import Logger
from typing import List, Dict

class LOG_ENTRY_T:
    def __init__(self, event_type: str, timestamp: int, source_ip: str, destination_port: int, message_content: str):
        self.event_type = event_type
        self.timestamp = timestamp
        self.source_ip = source_ip
        self.destination_port = destination_port
        self.message_content = message_content

def process_large_xml(xml_file: str, xml_schema: str, xpath_expression: str) -> List[LOG_ENTRY_T]:
    tree = ET.parse(xml_file)
    root = tree.getroot()

    log_entries = []
    for event in root.findall(xpath_expression):
        try:
            timestamp = int(event.find('timestamp').text)
            source_ip = event.find('source_ip').text
            destination_port = int(event.find('destination_port').text)
            message_content = event.find('message_content').text

            log_entry = LOG_ENTRY_T(event_type=event.tag, timestamp=timestamp, source_ip=source_ip, destination_port=destination_port, message_content=message_content)
            log_entries.append(log_entry)
        except ET.ParseError as e:
            raise ValueError(f"Invalid XML: {e}")

    return log_entries

def serialize_log_entries(log_entries: List[LOG_ENTRY_T], redis_key: str) -> None:
    serialized_log_entries = [entry.__dict__ for entry in log_entries]
    client = redis.Redis()
    client.set(redis_key, json.dumps(serialized_log_entries))
