using System;
using System.Xml.Linq;
using System.Collections.Generic;

public class XmlParser
{
    public List<HTTP_RESPONSE_PDU_T> ParseXml(string xml, string xpath, Dictionary<string, string> namespaces)
    {
        var responseList = new List<HTTP_RESPONSE_PDU_T>();
        try
        {
            XDocument doc = XDocument.Parse(xml);
            IEnumerable<XElement> elements = doc.XPathSelectElements(xpath);

            foreach (var element in elements)
            {
                var response = new HTTP_RESPONSE_PDU_T();
                response.TransactionId = Guid.NewGuid();
                response.HttpHeader = GetAttributeValue(element, "http-header");
                response.StatusCode = int.Parse(GetAttributeValue(element, "status-code"));
                response.Payload = GetAttributeValue(element, "payload");

                responseList.Add(response);
            }
        }
        catch (Exception ex)
        {
            throw new XmlParserException("Error parsing XML", ex);
        }

        return responseList;
    }

    private string GetAttributeValue(XElement element, string attributeName)
    {
        return (element.Attribute(attributeName) != null) ? element.Attribute(attributeName).Value : "";
    }
}

public class HTTP_RESPONSE_PDU_T
{
    public Guid TransactionId { get; set; }
    public string HttpHeader { get; set; }
    public int StatusCode { get; set; }
    public string Payload { get; set; }
}

public class XmlParserException : Exception
{
    public XmlParserException(string message, Exception innerException) : base(message, innerException)
    {
    }
}

