    for (size_t i = 0; i < newSize; i++) {
        pthread_mutex_lock(&((*deviceStates)[i].lock));
        (*deviceStates)[i].deviceId = -1;
        (*deviceStates)[i].eventLogCapacity = 10; // default event log capacity
        (*deviceStates)[i].activeEventCount = 0;
        (*deviceStates)[i].inactiveEventCount = 0;
        pthread_mutex_unlock(&((*deviceStates)[i].lock));
    }

    free(*deviceStates);
    *deviceStates = newDeviceStates;
}

