void* initAndPopulateFrames(int numFrames, pthread_mutex_t* lock) {
    FrameStatistics** frames = (FrameStatistics**)malloc(numFrames * sizeof(FrameStatistics*));

    for (int i = 0; i < numFrames; i++) {
