        frames[i]->frameNumber = i;
        frames[i]->measurementCount = 0;
        frames[i]->signalStrength = 0.0;
    }

    return frames;
}

// Function to add a new MeasurementResult to an existing FrameStatistics structure
void addMeasurement(FrameStatistics* frame, MeasurementResult result) {
    pthread_mutex_lock(frame);

    // Calculate the signal strength using moving average algorithm
    double newSignalStrength = (frame->signalStrength * (frame->measurementCount - 1) + result.value) / frame->measurementCount;

    // Update the signalStrength and measurementCount
    frame->signalStrength = newSignalStrength;
    frame->measurementCount++;

    pthread_mutex_unlock(frame);
}

// Function to detect anomalies in signal strength readings using a sliding window algorithm
int detectAnomalies(FrameStatistics* frame, int slidingWindow) {
    int anomalyCount = 0;

    // Compare the current signal strength against historical data within the sliding window
    for (int i = 0; i < slidingWindow; i++) {
        if (frame->signalStrength > (2 * frame->signalStrength - frame->signalStrength[i])) {
            anomalyCount++;
        }
    }

    return anomalyCount;
}

