void* allocate_array(size_t n) {
    void* array = NULL;

    if (n > MAX_ALLOCATIONS) {
        // handle error, log message
        printf("Error: Exceeding maximum allowed allocations\n");
        return NULL;
    }

    array = malloc(n * sizeof(NFAPI_CRC_INDICATION_PDU_T));

