    }
    return p;
}

void populate_crc_indications(NFAPI_CRC_INDICATION_PDU_T** p, int n, int log_level) {
    for (int i = 0; i < n; i++) {
        if (log_level >= 1)
            fprintf(stdout, "Populating CRC indication %d...\n", i);
        (*p)[i].rnti++;
        (*p)[i].crcflag ^= 1;
    }
}

int validate_crc_indications(NFAPI_CRC_INDICATION_PDU_T** p, int n, FILE* log_file) {
    for (int i = 0; i < n; i++) {
        if ((*p)[i].rnti > 0x7fffffff || (*p)[i].crcflag > 1)
            return -1;
        fprintf(log_file, "Valid CRC indication %d with RNTI %d and CRCFLAG %d\n", i, (*p)[i].rnti, (*p)[i].crcflag);
    }
    return 0;
}
