void* allocate_data_packet() {
    return malloc(sizeof(DATA_PACKET));
}

void free_data_packet(void* packet) {
    free(packet);
}

DATA_PACKET* populate_packets(int num_packets, char** data_sources) {
    DATA_PACKET* packets = NULL;
    for (int i = 0; i < num_packets; i++) {
        DATA_PACKET* packet = allocate_data_packet();
        if (packet == NULL) {
            printf("Error allocating memory for packet %d.\n", i);
            continue;
        }

        // Assign unique ID
        packet->id = i;

        // Parse timestamp from data source
        time_t timestamp = parse_timestamp(data_sources[i]);
        if (timestamp == -1) {
            printf("Error parsing timestamp for packet %d.\n", i);
            free_data_packet(packet);
            continue;
        }
        packet->timestamp = timestamp;

        // Determine payload length based on data source
        int payload_len = determine_payload_length(data_sources[i]);
        if (payload_len < 0) {
            printf("Error determining payload length for packet %d.\n", i);
            free_data_packet(packet);
            continue;
        }
        packet->payload_len = payload_len;

        // Add packet to array
        packets = realloc(packets, (i + 2) * sizeof(DATA_PACKET));
        if (packets == NULL) {
            printf("Error allocating memory for packet array.\n");
            free_data_packet(packet);
            return NULL;
        }
        packets[i] = *packet;
    }

    // Reallocate and add null terminator
    packets = realloc(packets, (num_packets + 1) * sizeof(DATA_PACKET));
    if (packets == NULL) {
        printf("Error allocating memory for packet array.\n");
        return NULL;
    }
    packets[num_packets] = (DATA_PACKET){0};

    return packets;
}

int main() {
    int num_packets = 10;
    char** data_sources = {"source1", "source2", ...}; // Replace with actual data sources
    DATA_PACKET* packets = populate_packets(num_packets, data_sources);
    if (packets == NULL) {
        printf("Error populating packet array.\n");
    } else {
        for (int i = 0; i < num_packets; i++) {
            printf("Packet %d: ID %d, Timestamp %lu, Payload Length %d\n", 
                   i, packets[i].id, packets[i].timestamp, packets[i].payload_len);
        }
        free(packets);
    }
    return 0;
}

