    // Validate CRC integrity
    for (int i = 0; i < num_connections; i++) {
        pthread_mutex_lock(mutex);
        if (crc_array[i].RX_UE_INFORMATION_TAG != crc_array[(i + 1) % num_connections].RX_UE_INFORMATION_TAG ||
            crc_array[i].RNTI != crc_array[(i + 1) % num_connections].RNTI) {
            printf("CRC integrity failed at index %d\n", i);
