    # Process the file contents and metadata
    with open(file_path, 'rb') as file:
        try:
            # Read file contents and calculate its hash
            file_hash = hashlib.md5(file.read()).hexdigest()
            file_size = os.path.getsize(file_path)
            return file_hash, file_size
        except Exception as e:
            print(f"Error processing file {file_path}: {e}")
            return None, None

def process_directory(dir_path):
    # Initialize a list to store processed files and their metadata
    files = []

    # Process each file in the directory
    for filename in os.listdir(dir_path):
        filepath = os.path.join(dir_path, filename)
        if os.path.isfile(filepath):
            try:
                file_hash, file_size = process_file(filepath)
                files.append((file_hash, file_size))
            except Exception as e:
                print(f"Error processing file {filename}: {e}")

    return files
