char* modify_filename(char* filename) {
    int vowel_count = 0;
    for (int i = strlen(filename) - 1; i >= 0 && vowel_count <= 5; --i) {
        char c = tolower(filename[i]);
        if (c == 'a' || c == 'e' || c == 'i' || c == 'o' || c == 'u') {
            ++vowel_count;
        }
    }

    char* new_filename = malloc(strlen(filename) + 7);
    strcpy(new_filename, filename);

    int last_dot_index = -1;
    for (int i = strlen(filename) - 1; i >= 0; --i) {
        if (filename[i] == '.') {
            last_dot_index = i;
            break;
        }
    }

    char* file_type = "";
    if (last_dot_index != -1 && isalpha(filename[last_dot_index + 1])) {
        strcpy(file_type, "txt");
    } else if (isdigit(filename[last_dot_index + 1])) {
        strcpy(file_type, "log");
    } else {
        strcpy(file_type, "bin");
    }

    sprintf(new_filename + last_dot_index + 1 + strlen(file_type), ".%s", file_type);

    new_filename = realloc(new_filename, strlen(new_filename) + vowel_count);
    for (int i = 0; i < vowel_count; ++i) {
        sprintf(new_filename + strlen(new_filename), "%d", i % 10);
    }

    if (strlen(new_filename) > 255) {
        free(new_filename);
        return NULL;
    }

    free(filename);
    return new_filename;
}
