#include <pthread.h>

#define MAX_STRUCTURES 1000
#define CRC_INDICATION_REL8_TAG_LENGTH 16

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint8_t CRC_INDICATION_REL8_TAG[CRC_INDICATION_REL8_TAG_LENGTH];
} NFAPI_CRC_INDICATION_PDU_T;

typedef struct {
    NFAPI_RLC_PDU_T* head;
    NFAPI_RLC_PDU_T* tail;
    int size;
} NFAPI_RLC_PDU_LIST_T;

NFAPI_RLC_PDU_T* nfapi_rlc_pdu_list_init() {
    NFAPI_RLC_PDU_LIST_T* list = (NFAPI_RLC_PDU_LIST_T*)malloc(sizeof(NFAPI_RLC_PDU_LIST_T));
    list->head = NULL;
    list->tail = NULL;
    list->size = 0;
    return list;
}

void nfapi_rlc_pdu_list_free(NFAPI_RLC_PDU_LIST_T* list) {
    NFAPI_RLC_PDU_T* current = list->head;
    NFAPI_RLC_PDU_T* next;
    while (current != NULL) {
        next = current->next;
        free(current);
        current = next;
    }
    free(list);
}

void nfapi_rlc_pdu_list_append(NFAPI_RLC_PDU_LIST_T* list, NFAPI_RLC_PDU_T* pdu) {
    if (list->tail == NULL || pdu != NULL) {
        if (list->size >= MAX_STRUCTURES) {
            // Resize the list
            NFAPI_RLC_PDU_LIST_T* new_list = nfaapi_rlc_pdu_list_init();
            *new_list = *list;
            free(list);
            list = new_list;
        }
        pdu->next = NULL;
        if (list->tail == NULL) {
            list->head = pdu;
            list->tail = pdu;
        } else {
            list->tail->next = pdu;
            list->tail = pdu;
        }
    }
}

void nfaapi_rlc_pdu_list_remove(NFAPI_RLC_PDU_LIST_T* list, NFAPI_RLC_PDU_T* pdu) {
    if (list->head == pdu || list->tail == pdu) {
        // Remove the head or tail
        if (pdu == list->head) {
            list->head = pdu->next;
        } else {
            list->tail = pdu->prev;
        }
    } else {
        // Find and remove the pdu
        NFAPI_RLC_PDU_T* current = list->head;
        while (current != NULL && current != pdu) {
            current = current->next;
        }
        if (current == NULL || current->next == pdu) {
            current->prev->next = current->next;
            current->next->prev = current->prev;
        } else {
            current->prev->next = current->next;
            current->next->prev = current->prev;
        }
    }
}

int main() {
    NFAPI_RLC_PDU_LIST_T* list = nfaapi_rlc_pdu_list_init();
    // Add and remove PDU structures as needed
    NFAPI_RLC_PDU_T* pdu1 = (NFAPI_RLC_PDU_T*)malloc(sizeof(NFAPI_RLC_PDU_T));
    NFAPI_RLC_PDU_T* pdu2 = (NFAPI_RLC_PDU_T*)malloc(sizeof(NFAPI_RLC_PDU_T));
    // Add PDU structures to the list
