// Define a function to generate random strings using the Fortuna PRNG
char* fortuna_prng(const int length, const char *set) {
    static char buffer[256];
    static uint32_t seed = 0;
    static int initialized = 0;

    if (!initialized) {
        srand((unsigned)time(NULL));
        initialized = 1;
    }

    for (int i = 0; i < length; ++i) {
        uint32_t random_value = rand() % 256;
        buffer[i] = set[random_value];
    }
    buffer[length] = '\0';

    return strdup(buffer);
}

// Define a function to generate NFAPI_CRC_INDICATION_PDU_T structures
