typedef struct {
    int client_id;
    int server_id;
    int conn_state;
    time_t last_active_time;
} TCP_CONNECTION_INFO;

void* alloc_tcp_connection(int fixed_seed) {
    // Initialize memory pool if not already initialized
    static void* memory_pool = NULL;
    static size_t total_memory = 0;

    // Calculate the required memory for a single structure
    size_t struct_size = sizeof(TCP_CONNECTION_INFO);
    size_t align_to = alignof(TCP_CONNECTION_INFO);

    // Calculate the number of structures that can fit in memory pool
    size_t num_structures = (total_memory / (struct_size + align_to - 1)) * (struct_size + align_to - 1) / align_to;

    if (num_structures < 500000) {
        printf("Insufficient memory, allocating more\n");
        total_memory *= 2; // Double the available memory
    }

    // Allocate a new block of memory
    void* new_block = malloc(total_memory);
    if (!new_block) {
        printf("Memory allocation failed\n");
        return NULL;
    }

    // Initialize the first structure in the new block with fixed seed for timestamp generation
    TCP_CONNECTION_INFO* connection = (TCP_CONNECTION_INFO*) (((size_t)new_block + align_to - 1) & ~(align_to - 1));
    if (fixed_seed) {
        time_t timestamp = time(NULL);
        for (int i = 0; i < num_structures; i++) {
            connection->client_id = rand();
            connection->server_id = rand();
            connection->conn_state = rand() % 2;
            connection->last_active_time = timestamp + i;
            connection++;
        }
    } else {
        // Initialize the first structure in the new block with system clock for timestamp generation
        time_t timestamp = time(NULL);
        for (int i = 0; i < num_structures; i++) {
            connection->client_id = rand();
            connection->server_id = rand();
            connection->conn_state = rand() % 2;
            connection->last_active_time = timestamp + i;
            connection++;
        }
    }

    return new_block;
}

void free_tcp_connection(void* memory_pool) {
    // Free the allocated structures
    TCP_CONNECTION_INFO* connection = (TCP_CONNECTION_INFO*)(((size_t)memory_pool + alignof(TCP_CONNECTION_INFO) - 1) & ~(alignof(TCP_CONNECTION_INFO) - 1));
    for (int i = 0; i < num_structures; i++) {
        free(connection);
        connection++;
    }

    // Free the memory pool
    free(memory_pool);
}
