void* tcp_connection_pool_alloc(int size) {
    static int initialized = 0;
    static int seed = 0;
    static TCP_CONNECTION_INFO* pool = NULL;
    static int pool_size = 0;
    static int total_allocated = 0;

    if (!initialized) {
        pool = (TCP_CONNECTION_INFO*)malloc(500000 * sizeof(TCP_CONNECTION_INFO));
        pool_size = 500000;
        initialized = 1;
    }

    for (int i = 0; i < pool_size; i++) {
        if (pool[i].client_id == 0) {
            total_allocated++;
            return &pool[i];
        }
    }

    // Resize the pool if necessary
    if (total_allocated > pool_size / 2) {
        int new_pool_size = pool_size * 2;
        TCP_CONNECTION_INFO* new_pool = (TCP_CONNECTION_INFO*)realloc(pool, new_pool_size * sizeof(TCP_CONNECTION_INFO));
        pool = new_pool;
        pool_size = new_pool_size;
    }

    return NULL; // No free slots available
}

void tcp_connection_pool_free(void* ptr) {
    static int initialized = 0;

    if (!initialized) {
        for (int i = 0; i < pool_size; i++) {
            if (&pool[i] == ptr) {
                pool[i].client_id = 0;
                return;
            }
        }

        printf("Attempt to free non-existent connection\n");
        exit(1);
    }

    // Evict older connections when freeing
    for (int i = 0; i < pool_size; i++) {
        if (pool[i].last_active_time + 3600 < time(NULL)) {
            pool[i].client_id = 0;
        }
