    // Initialize the random number generator
    srand(seed);

    // Generate a random string of the specified length using uppercase letters and digits
    char* subscription_id = (char*)malloc((length+1)*sizeof(char));
    for (int i=0; i<length; i++) {
        subscription_id[i] = (rand() % 2 == 0) ? 'A' + rand() % 26 : '0' + rand() % 10;
    }
    subscription_id[length] = '\0';

    return subscription_id;
}

