void log_error(const char* message) {
    printf("Error: %s\n", message);
}

InterfaceConfig** init_interfaces(int num_interfaces) {
    InterfaceConfig** interfaces = (InterfaceConfig**)calloc(num_interfaces, sizeof(InterfaceConfig*));

    for (int i = 0; i < num_interfaces; i++) {
        interfaces[i] = (InterfaceConfig*)malloc(sizeof(InterfaceConfig));

        // Initialize MAC address
        strcpy(interfaces[i]->mac, "00:11:22:33:44:55");

        // Initialize IP configuration
        interfaces[i]->ip[0] = '\0';
        interfaces[i]->subnet_mask[0] = '\0';
        interfaces[i]->gateway[0] = '\0';

        // Initialize DNS servers and MTU
        strcpy(interfaces[i]->dns, "8.8.8.8");
        interfaces[i]->mtu = 1500;
    }

    return interfaces;
}

int validate_ip(char* ip) {
    // IP validation logic goes here
    if (/* invalid IP */) {
        log_error("Invalid IP address");
        return 1;
    } else {
        return 0;
    }
}

int validate_subnet_mask(char* subnet_mask) {
    // Subnet mask validation logic goes here
    if (/* invalid subnet mask */) {
        log_error("Invalid subnet mask");
        return 1;
    } else {
        return 0;
    }
}

int validate_overlapping_subnets(InterfaceConfig** interfaces, int num_interfaces) {
    for (int i = 0; i < num_interfaces; i++) {
        for (int j = i + 1; j < num_interfaces; j++) {
            // Subnet mask comparison logic goes here
            if (/* overlapping subnets */) {
                log_error("Overlapping subnet masks");
                return 1;
            }
        }
    }

    return 0;
}

void add_interface(InterfaceConfig** interfaces, int* num_interfaces) {
    InterfaceConfig* new_interface = (InterfaceConfig*)malloc(sizeof(InterfaceConfig));

    // Validate IP configuration
    if (validate_ip(new_interface->ip)) {
        free(new_interface);
        log_error("Invalid IP address");
        return;
    }

    // Validate subnet mask
    if (validate_subnet_mask(new_interface->subnet_mask)) {
        free(new_interface);
        log_error("Invalid subnet mask");
        return;
    }

    // Validate overlapping subnets
    if (validate_overlapping_subnets(interfaces, *num_interfaces + 1)) {
        free(new_interface);
        log_error("Overlapping subnet masks");
        return;
    }

    interfaces[*num_interfaces] = new_interface;
    (*num_interfaces)++;
}

void iterate_interfaces(InterfaceConfig** interfaces, int num_interfaces) {
    for (int i = 0; i < num_interfaces; i++) {
        // Perform additional operations on each interface
        printf("MAC: %s, IP: %s, Subnet mask: %s, Gateway: %s, DNS: %s, MTU: %d\n",
               interfaces[i]->mac, interfaces[i]->ip, interfaces[i]->subnet_mask, interfaces[i]->gateway, interfaces[i]->dns, interfaces[i]->mtu);
    }
}

void free_interfaces(InterfaceConfig** interfaces, int num_interfaces) {
    for (int i = 0; i < num_interfaces; i++) {
        free(interfaces[i]);
    }

    free(interfaces);
}
