#define MAX_DEVICES 100
#define MAX_ECC_OPTIONS 10

typedef struct {
    int id;
    size_t capacity;
    double speed;
    char** ecc_options;
    size_t num_ecc_options;
    // Optional fields
    int power_management_enabled;
    int thermal_threshold;
} DeviceConfig;

DeviceConfig* devices = NULL;
size_t num_devices = 0;

void init_devices(size_t num_entries) {
    if (num_entries > MAX_DEVICES) {
        fprintf(stderr, "Error: Maximum number of devices exceeded.\n");
        return;
    }
    devices = (DeviceConfig*) realloc(devices, sizeof(DeviceConfig) * num_entries);
    num_devices = num_entries;
}

void add_device(int id, size_t capacity, double speed, char** ecc_options, size_t num_ecc_options) {
    if (num_devices >= MAX_DEVICES) {
        fprintf(stderr, "Error: Maximum number of devices reached. Cannot add more.\n");
        return;
    }
    DeviceConfig* device = &devices[num_devices];
    device->id = id;
    device->capacity = capacity;
    device->speed = speed;
    device->ecc_options = (char**) malloc(sizeof(char*) * num_ecc_options);
    for (size_t i = 0; i < num_ecc_options; i++) {
        device->ecc_options[i] = strdup(ecc_options[i]);
    }
    device->num_ecc_options = num_ecc_options;

    // Optional fields
    device->power_management_enabled = 0;
    device->thermal_threshold = -1;

    // Check for overlapping ECC capabilities
    for (size_t i = 0; i < num_devices; i++) {
        if (i != num_devices - 1 && strcmp(device->ecc_options[0], devices[i].ecc_options[0]) == 0) {
            fprintf(stderr, "Error: Overlapping ECC capabilities detected.\n");
            return;
        }
    }

    num_devices++;
}

void update_device(size_t index, int new_id, size_t new_capacity, double new_speed, char** new_ecc_options, size_t new_num_ecc_options) {
    if (index >= num_devices) {
        fprintf(stderr, "Error: Index out of range.\n");
        return;
    }
    DeviceConfig* device = &devices[index];
    device->id = new_id;
    device->capacity = new_capacity;
    device->speed = new_speed;
    free(device->ecc_options);
    device->ecc_options = (char**) malloc(sizeof(char*) * new_num_ecc_options);
    for (size_t i = 0; i < new_num_ecc_options; i++) {
        device->ecc_options[i] = strdup(new_ecc_options[i]);
    }
    device->num_ecc_options = new_num_ecc_options;
}

void iterate_devices(void (*callback)(DeviceConfig*)) {
    for (size_t i = 0; i < num_devices; i++) {
        callback(devices[i]);
    }
}
