void init_config_list(int num_entries) {
    int i;
    for(i=0;i<num_entries;i++){
        config_list[i] = (DeviceConfig*)malloc(sizeof(DeviceConfig));
        strcpy(config_list[i]->id,"default");
        config_list[i]->capacity=0;
        config_list[i]->speed=0.0;
        config_list[i]->num_ecc=0;
    }
}

void free_config_list() {
    int i;
    for(i=0;i<list_len;i++){
        free(config_list[i]);
    }
    free(config_list);
