int add_device(char* id, int capacity, double speed, char* ecc[] ,int num_ecc) {
    // Validate ECC options and ensure no overlap with existing entries
    DeviceConfig* new_entry = (DeviceConfig*)malloc(sizeof(DeviceConfig));
    strcpy(new_entry->id,id);
    new_entry->capacity=capacity;
    new_entry->speed=speed;
    new_entry->num_ecc=num_ecc;
    for(int i=0;i<num_ecc;i++){
        new_entry->ecc[i]=ecc[i];
    }

    // Check if the ECC options are already present in the list
