    for(int i=0;i<list_len;i++) {
        if(strcmp(new_entry->ecc[0], config_list[i]->ecc[0]) == 0) {
            free(new_entry);
            return -1; // error: ECC options already exist
        }
    }

    // If no error, add the new entry to the list
    list_len++;
    DeviceConfig** temp = (DeviceConfig**)malloc((list_len+1)*sizeof(DeviceConfig*));
    for(int i=0;i<list_len;i++) {
        temp[i] = config_list[i];
    }
    free(config_list);
    config_list = temp;
    config_list[list_len-1] = new_entry;

    return 0; // success
}

int update_ecc(int index, char* ecc[]) {
    if(index < 0 || index >= list_len) {
        return -1; // error: invalid index
    }

    DeviceConfig* current_config = config_list[index];
    for(int i=0;i<strlen(current_config->ecc);i++){
        free(current_config->ecc[i]);
    }
    int new_ecc_num = 0;
    while(ecc[new_ecc_num] != NULL){
        current_config->ecc[new_ecc_num] = ecc[new_ecc_num];
        new_ecc_num++;
    }

    return 0; // success
}

int update_thermal(int index, int thermal_thresholds[]) {
    if(index < 0 || index >= list_len) {
        return -1; // error: invalid index
    }

    DeviceConfig* current_config = config_list[index];
    for(int i=0;i<strlen(current_config->thermal_thresholds);i++){
        free(current_config->thermal_thresholds[i]);
    }
    int new_thermal_num = 0;
    while(thermal_thresholds[new_thermal_num] != NULL){
        current_config->thermal_thresholds[new_thermal_num] = thermal_thresholds[new_thermal_num];
        new_thermal_num++;
    }

    return 0; // success
}

