#include <stdio.h>
#include <stdlib.h>
#include <string.h>

typedef struct {
    char mac[17];
    char ip[16];
    int subnet;
    char gateway[16];
    int default_route;
} NetworkInterface;

typedef struct {
    NetworkInterface* interfaces;
    int count;
    int capacity;
} NetworkInterfaceList;

NetworkInterfaceList* create_list(int size) {
    NetworkInterfaceList* list = (NetworkInterfaceList*)malloc(sizeof(NetworkInterfaceList));
    if (!list) return NULL;
    list->interfaces = (NetworkInterface*)malloc(size * sizeof(NetworkInterface));
    list->count = 0;
    list->capacity = size;
    return list;
}

void destroy_list(NetworkInterfaceList* list) {
    if (!list) return;
    free(list->interfaces);
    free(list);
}

int validate_ip(char* ip) {
    // simple IP validation
    int i = 0, j = 0;
    while (ip[i]) {
        if (i == 3) break;
        if (ip[i] != '.') continue;
        j++;
        i++;
    }
    return j == 3;
}

int validate_subnet(int subnet) {
    // simple subnet validation
    return subnet > 0;
}

void add_interface(NetworkInterfaceList* list, NetworkInterface* interface) {
    if (!list || !interface) return;
    if (list->count >= list->capacity) {
        int new_capacity = list->capacity * 2;
        NetworkInterface* new_interfaces = (NetworkInterface*)realloc(list->interfaces, new_capacity * sizeof(NetworkInterface));
        if (!new_interfaces) return;
        list->interfaces = new_interfaces;
        list->capacity = new_capacity;
    }
    // validate IP and subnet
    if (!validate_ip(interface->ip) || !validate_subnet(interface->subnet)) {
        printf("Invalid IP or subnet!\n");
        return;
    }
    // check for overlapping subnets
    int i = 0;
    while (i < list->count) {
        NetworkInterface* existing_interface = &list->interfaces[i];
        if (existing_interface->subnet == interface->subnet && !strcmp(existing_interface->ip, interface->ip)) {
            printf("Subnet overlap detected!\n");
            return;
        }
        i++;
    }
    // add the new interface
    list->interfaces[list->count] = *interface;
    list->count++;
}

void remove_interface(NetworkInterfaceList* list, char* mac) {
    if (!list || !mac) return;
    int i = 0;
    while (i < list->count) {
        NetworkInterface* interface = &list->interfaces[i];
        if (!strcmp(interface->mac, mac)) {
            // shift all interfaces down
            memmove(&list->interfaces[i], &list->interfaces[i + 1], (list->count - i - 1) * sizeof(NetworkInterface));
            list->count--;
            return;
        }
        i++;
    }
}

NetworkInterface* find_interface_by_mac(NetworkInterfaceList* list, char* mac) {
    if (!list || !mac) return NULL;
    int i = 0;
    while (i < list->count) {
        NetworkInterface* interface = &list->interfaces[i];
        if (!strcmp(interface->mac, mac)) return interface;
        i++;
    }
    return NULL;
}

NetworkInterface* find_interface_by_ip(NetworkInterfaceList* list, char* ip) {
    if (!list || !ip) return NULL;
    int i = 0;
    while (i < list->count) {
        NetworkInterface* interface = &list->interfaces[i];
        if (!strcmp(interface->ip, ip)) return interface;
        i++;
    }
    return NULL;
}

void update_routing_table(NetworkInterfaceList* list) {
    // implement your routing table updating logic here
}

int main() {
    NetworkInterfaceList* list = create_list(5);
    // add interfaces
    add_interface(list, (NetworkInterface*)malloc(sizeof(NetworkInterface)));
    add_interface(list, (NetworkInterface*)malloc(sizeof(NetworkInterface)));
    // remove an interface
    remove_interface(list, "00:11:22:33:44:55");
    // find interfaces by MAC or IP
    NetworkInterface* found_interface = find_interface_by_mac(list, "00:11:22:33:44:56");
    if (found_interface) printf("Found interface with MAC %s!\n", found_interface->mac);
    // update the routing table
    update_routing_table(list);
    destroy_list(list);
    return 0;
}
