LOG_PROCESSOR_T* allocate_log_processors(int size) {
    LOG_PROCESSOR_T* log_processors = (LOG_PROCESSOR_T*)malloc(size * sizeof(LOG_PROCESSOR_T));
    if (!log_processors) {
        printf("Memory allocation failed: %s\n", strerror(errno));
        return NULL;
    }

    for (int i = 0; i < size; i++) {
        log_processors[i].log_id = i + OFFSET;
        char* source_name = concat_str("Source_", itoa(log_processors[i].log_id));
        log_processors[i].log_source_name = source_name;

        // Initialize log_level based on environmental variable
        const char* env_var = getenv("LOG_LEVEL");
        if (env_var && strcmp(env_var, "DEBUG") == 0) {
            log_processors[i].log_level = DEBUG;
        } else if (env_var && strcmp(env_var, "INFO") == 0) {
            log_processors[i].log_level = INFO;
        } else {
            log_processors[i].log_level = INFO; // Default to INFO
        }
    }

    return log_processors;
}

char* concat_str(char* prefix, char* suffix) {
    int len1 = strlen(prefix);
    int len2 = strlen(suffix);
    char* result = (char*)malloc(len1 + len2 + 1);
    memcpy(result, prefix, len1);
    memcpy(result + len1, suffix, len2);
    result[len1 + len2] = '\0';
    return result;
}

int main() {
    int size = MAX_ARRAY_SIZE;
    LOG_PROCESSOR_T* log_processors = allocate_log_processors(size);
