    // Get frame buffer and processing configuration from argument
    VideoFrame* frames = (VideoFrame*)arg;
    int num_frames = 10000; // Assuming maximum of 10,000 frames per second
    int max_concurrent_frames = 1000;

    // Initialize logging mechanism
    FILE* log_file = fopen("video_stream_processing.log", "w");
    if (!log_file) {
        fprintf(stderr, "Error opening log file\n");
        return NULL;
    }

