    uint64_t total_processing_time = 0;
    int num_errors = 0;

    // Start processing frames in parallel
    pthread_t threads[num_frames];
    for (int i = 0; i < num_frames; i++) {
        pthread_create(&threads[i], NULL, process_frame, &frames[i]);
    }

    // Wait for all frames to be processed
    for (int i = 0; i < num_frames; i++) {
        pthread_join(threads[i], NULL);
    }

    // Calculate and log total processing time and error count
    uint64_t end_time = gettimeofday(NULL, NULL);
    fprintf(log_file, "Total processing time: %llu\n", end_time - frames[0].timestamp);
