typedef struct NR_RACH_PREAMBLE_REQUEST_T {
    int PRACH_CONFIG_INDEX;
    char PREAMBLE_SEQUENCE[64];
    int CRCFLAG;
} NR_RACH_PREAMBLE_REQUEST_T;

typedef struct GTPv2_C_MESSAGE {
    uint16_t TEID;
    uint32_t PDP_Context_ID;
    EPS_Mobility_Header EPS_Header;
} GTPv2_C_MESSAGE;

NR_RACH_PREAMBLE_REQUEST_T* dynamic_list = NULL;
pthread_mutex_t list_lock = PTHREAD_MUTEX_INITIALIZER;
int list_size = 0;
int threshold = 100; // predefined threshold

void init_list() {
    pthread_mutex_init(&list_lock, NULL);
}

void add_to_list(NR_RACH_PREAMBLE_REQUEST_T* new_entry) {
    pthread_mutex_lock(&list_lock);
    if (list_size >= threshold) {
        flush_list();
    }
    dynamic_list = realloc(dynamic_list, sizeof(NR_RACH_PREAMBLE_REQUEST_T) * (list_size + 1));
    dynamic_list[list_size] = *new_entry;
    list_size++;
    pthread_mutex_unlock(&list_lock);
}

void flush_list() {
    NR_RACH_PREAMBLE_REQUEST_T* temp_list = dynamic_list;
    dynamic_list = NULL;
    free(temp_list);
    list_size = 0;
}

GTPv2_C_MESSAGE process_GTP_message(GTPv2_C_MESSAGE* message) {
    // deterministic algorithm for sequence number
    uint16_t seq_num = calculate_sequence_number(message->time, message->type);

    // handle potential failures from external network interface
    int retry_count = 0;
    while (retry_count < 5) {
        if (process_message(message)) {
            break;
        }
        retry_count++;
    }

    // detect and handle duplicate messages
    if (is_duplicate(message)) {
        return; // ignore duplicate message
    }

    // reassemble fragmented message
    GTPv2_C_MESSAGE* reassembled_message = reassemble_message(message);

    return *reassembled_message;
