    new_config->default_route = 1;

    // Initialize DNS server list and active connections
    new_config->dns_servers = (char*)malloc(256);
    sprintf(new_config->dns_servers, "8.8.8.8,8.8.4.4");
    new_config->num_dns_servers = 2;
    new_config->active_connections = 0;

    // Initialize bandwidth usage metric
    new_config->bandwidth_usage = 0.0f;

    // Update the list of network interface configurations
    napi_configs = (NAPI_Config*)realloc(napi_configs, (napi_count + 1) * sizeof(NAPI_Config));
    napi_configs[napi_count] = *new_config;
    free(new_config);

    // Validate IP configuration for each entry and ensure no overlapping subnets
    for (int i = 0; i < napi_count; i++) {
        if (strcmp(napi_configs[i].ip, new_config->ip) == 0) {
            printf("IP address conflict detected.\n");
            return;
        }

        // Check for subnet overlap
        int subnet1 = ip_to_subnet_mask(napi_configs[i].ip);
        int subnet2 = ip_to_subnet_mask(new_config->ip);
        if (subnet1 & subnet2) {
            printf("Subnet conflict detected.\n");
            return;
        }
    }

    napi_count++;
}

