NAPI_Config* napi_config_search(char* search_key) {
    // Search for the specified key in each network interface configuration
    for (int i = 0; i < napi_count; i++) {
        if (strcmp(napi_configs[i].mac, search_key) == 0 || strcmp(napi_configs[i].ip, search_key) == 0 || strstr(napi_configs[i].dns_servers, search_key)) {
            return &napi_configs[i];
        }
    }

    // Return NULL if the key is not found
    return NULL;
}

