NFAPI_CRC_INDICATION_PDU_T* create_crc_indication_pdu(int n) {
    int i;
    int num_allocations = 0;
    size_t total_size = 0;
    NFAPI_CRC_INDICATION_PDU_T* pdu_array = NULL;
    srand(time(NULL));

    while (n > 0) {
        size_t allocation_size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * 1024; // chunk size
        NFAPI_CRC_INDICATION_PDU_T* temp_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(allocation_size);

        if (!temp_array) {
            free(pdu_array);
            for (i = 0; i < num_allocations; i++) {
                free((pdu_array + i * allocation_size));
            }
            return NULL;
        }

        total_size += allocation_size;
        pdu_array = temp_array;

        for (i = 0; i < sizeof(NFAPI_CRC_INDICATION_PDU_T) / sizeof(NFAPI_CRC_INDICATION_PDU_T); i++) {
            pdu_array[i].RX_UE_INFORMATION_TAG = rand() % 256;
            pdu_array[i].RNTI = rand();
            pdu_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = rand() % 2;
        }

        num_allocations++;
        n -= sizeof(NFAPI_CRC_INDICATION_PDU_T) / allocation_size;
    }

    return pdu_array;
}
