typedef struct {
    int SEQUENCE_NUMBER;
    char AMCS[4];
    void* DATA; // Pointer to actual data, dynamically allocated
} MAC_DATA_ELEMENT;

typedef struct {
    int SEQUENCE_NUMBER;
    char MAC_CONTROL_ELEMENT[4]; // 3 bytes for the MAC control element
    MAC_DATA_ELEMENT* DATA; // Pointer to MAC data element
} MAC_PDU_T;

void process_MAC_PDU(MAC_PDU_T** pdus, int M) {
    for (int i = 0; i < M; i++) {
        (*pdus)[i].SEQUENCE_NUMBER = i;
        strcpy((*pdus)[i].MAC_CONTROL_ELEMENT, "MacControlElement");
        (*pdus)[i].DATA = malloc(8); // Allocate space for actual data
        sprintf((char*)(*pdus)[i].DATA, "DataElement-%d", i);
    }
}

void free_MAC_PDU(MAC_PDU_T** pdus, int M) {
    for (int i = 0; i < M; i++) {
        free((*pdus)[i].DATA); // Release memory allocated for actual data
    }
    free(*pdus); // Release memory allocated for array of MAC PDU structures
}

