LOG_PROCESSOR_T* allocate_and_init_log_processors(int initial_size, void (*custom_name_formatting_function)(int, const char*, char*)) {
    LOG_PROCESSOR_T* log_processors = (LOG_PROCESSOR_T*)malloc(initial_size * sizeof(LOG_PROCESSOR_T));
    if (!log_processors) return NULL; // Error: insufficient system resources

    for (int i = 0; i < initial_size; i++) {
        log_processors[i].log_id = i + LOG_ID_OFFSET;
        char source_name[32];
        sprintf(source_name, "Processor-%d", i);
        if (custom_name_formatting_function) {
            custom_name_formatting_function(i, source_name, log_processors[i].log_source_name = (char*)malloc(strlen(source_name) + 1));
        } else {
            log_processors[i].log_source_name = strdup(source_name);
        }
        char* env_log_level = getenv("LOG_LEVEL");
        int log_level = env_log_level ? atoi(env_log_level) : LOG_PROCESSOR_T_INFO;
        log_processors[i].log_level = log_level;

        // Check for duplicate source names
        for (int j = 0; j < i; j++) {
            if (strcmp(log_processors[j].log_source_name, log_processors[i].log_source_name) == 0) {
                printf("Error: Duplicate source name detected!\n");
                return NULL; // Error: duplicate source name found
            }
        }
    }

    int log_level = getenv("LOG_LEVEL") ? atoi(getenv("LOG_LEVEL")) : LOG_PROCESSOR_T_INFO;
    if (log_processors && log_level > 0) {
        printf("Info: Log level set to %d\n", log_level);
    } else {
        printf("Warning: Default log level: INFO\n");
    }

    return log_processors;
}

int main() {
    void custom_name_formatting_function(int index, const char* base_name, char* formatted_name) {
        sprintf(formatted_name, "%s-%d", base_name, index);
    }

    LOG_PROCESSOR_T* log_processors = allocate_and_init_log_processors(LOG_PROCESSOR_T_MAX_SIZE, custom_name_formatting_function);

    if (log_processors) {
        // Use the allocated log processors
        for (int i = 0; i < LOG_PROCESSOR_T_MAX_SIZE; i++) {
            printf("Log ID: %d\n", log_processors[i].log_id);
            printf("Source Name: %s\n", log_processors[i].log_source_name);
            printf("Log Level: %s\n", log_level_to_string(log_processors[i].log_level));
        }
    } else {
        // Error handling
        printf("Error: Unable to allocate memory for log processors.\n");
    }

    return 0;
}

