void generate_NFAPI_CRC_INDICATION_PDU_T_array(int N, int M, int* array_size) {
    *array_size = (N + M - 1) / M; // Calculate the size of the array based on user input and RNTI limit
    NFAPI_CRC_INDICATION_PDU_T** array = (NFAPI_CRC_INDICATION_PDU_T**)malloc(*array_size * sizeof(NFAPI_CRC_INDICATION_PDU_T*));

