        array[i] = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        int rnti = rand() % M;
        array[i]->RX_UE_INFORMATION_TAG = 1; // Set a valid RX_UE_INFORMATION_TAG
        array[i]->RNTI = rnti;
        array[i]->CRC_INDICATION_REL8_TAG = 2; // Set a valid CRC_INDICATION_REL8_TAG

        if(i > 0 && array[i-1]->RNTI == rnti) {
            i--; // Reuse RNTI values from the beginning of the list
        }
    }

    free(array);
}

void process_binary_file(char* filename, int N, int M) {
    FILE* file = fopen(filename, "r");

    if(file == NULL) {
        printf("Error opening file\n");
        return;
    }

    char line[1024];
    while(fgets(line, sizeof(line), file)) {
        float sum = 0;

        // Calculate the average of the last three fields for each line
        for(int i = 3; i < strlen(line); i++) {
            sum += (line[i] - '0') / 10.0f;
        }

        printf("%s,", line);
    }

    fclose(file);
}

int main(int argc, char* argv[]) {
    int N = 1000; // User input for the number of elements
    int M = 256; // RNTI value limit

