        M = atoi(argv[2]);
    }

    srand(time(NULL));

    int array_size;
    generate_NFAPI_CRC_INDICATION_PDU_T_array(N, M, &array_size);

    // Process binary file
    process_binary_file("data.bin", N, M);

    return 0;
}

