#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_CAPACITY 1000

typedef struct {
    int RX_UE_INFORMATION_TAG;
    unsigned int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* allocate_structures(int N) {
    static pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;
    static int capacity = 0, allocated = 0;
    static NFAPI_CRC_INDICATION_PDU_T* structures = NULL;

    if (N > MAX_CAPACITY || N <= 0) {
        return NULL;
    }

    if (pthread_mutex_lock(&mutex) != 0) {
        return NULL;
    }

    while (allocated >= MAX_CAPACITY) {
        // Enqueue new requests
        sleep(1);
    }

    int size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * N;
    void* mem = malloc(size);

    if (mem == NULL) {
        printf("Memory allocation failed.\n");
        pthread_mutex_unlock(&mutex);
        return NULL;
    }

    structures = mem;
    for (int i = 0; i < N; i++) {
        structures[i].RX_UE_INFORMATION_TAG = i;
        structures[i].RNTI = rand();
        structures[i].CRC_INDICATION_REL8_TAG = rand() % 2;

        // Record logging information
        time_t timestamp = time(NULL);
        printf("Allocated structure at timestamp %ld with RNTI %u and CRC flag %d.\n", timestamp, structures[i].RNTI, structures[i].CRC_INDICATION_REL8_TAG);
    }

    allocated += N;
    capacity = MAX_CAPACITY;

    pthread_mutex_unlock(&mutex);

    return structures;
}

void free_structures(NFAPI_CRC_INDICATION_PDU_T* structures) {
    if (structures == NULL) {
        return;
    }

    int size = sizeof(NFAPI_CRC_INDICATION_PDU_T) * (MAX_CAPACITY - allocated);
    void* mem = realloc(structures, size);

    if (mem != NULL) {
        free(mem);
    }
}

void* iter_structures(NFAPI_CRC_INDICATION_PDU_T* structures) {
    // Iterate over allocated structures
    for (int i = 0; i < MAX_CAPACITY; i++) {
        if (structures + i > &structures[allocated]) {
            break;
        }

        printf("Iterating structure with RNTI %u and CRC flag %d.\n", structures[i].RNTI, structures[i].CRC_INDICATION_REL8_TAG);
    }

    return NULL;
}

int main() {
    int N = 0;
    NFAPI_CRC_INDICATION_PDU_T* structures;

    printf("Enter the number of structures to allocate: ");
    scanf("%d", &N);

    structures = allocate_structures(N);

    if (structures == NULL) {
        return 1;
    }

    iter_structures(structures);
    free_structures(structures);

    return 0;
}

