#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <pthread.h>

#define MAX_CAPACITY 1000
#define MODULATION_SCHEMES 8
#define SNR_MAX 20
#define SNR_MIN 5

typedef struct {
    int RNTI;
    float modulationScheme;
    float SNR;
} RX_FRAME_INFO_T;

typedef struct {
    int RNTI;
    RX_FRAME_INFO_T *frames;
    int frameCount;
} NFAPI_RX_FRAME_INFO_T;

NFAPI_RX_FRAME_INFO_T* allocateRXFrames(int N) {
    pthread_mutex_lock(NULL);

    if (N > MAX_CAPACITY) {
        printf("Error: Maximum capacity reached. Enqueuing new request.\n");
        // enqueue new request
        return NULL;
    }

    NFAPI_RX_FRAME_INFO_T *rxFrames = (NFAPI_RX_FRAME_INFO_T*)malloc(sizeof(NFAPI_RX_FRAME_INFO_T));
    if (!rxFrames) {
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    rxFrames->frames = (RX_FRAME_INFO_T*)malloc(N * sizeof(RX_FRAME_INFO_T));
    if (!rxFrames->frames) {
        free(rxFrames);
        printf("Error: Memory allocation failed.\n");
        return NULL;
    }

    for (int i = 0; i < N; i++) {
        rxFrames->frames[i].RNTI = rand() % 10000;
        rxFrames->frames[i].modulationScheme = (float)rand() / RAND_MAX;
        rxFrames->frames[i].SNR = (float)(rand() % (SNR_MAX - SNR_MIN + 1)) / 10.0f;
    }

    rxFrames->frameCount = N;

    // Record allocation timestamp, RNTI, modulation scheme, and SNR
    time_t now = time(NULL);
    printf("Allocated frames for RNTI %d, modulation scheme %.2f, and SNR %.2f at time %ld.\n", 
           rxFrames->frames[0].RNTI, rxFrames->frames[0].modulationScheme, 
           rxFrames->frames[0].SNR, now);

    pthread_mutex_unlock(NULL);

    return rxFrames;
}

void retrieveStatistics(NFAPI_RX_FRAME_INFO_T* frames) {
    int totalAllocated = 0;
    float totalSNR = 0.0f;
    int modulationCounts[MODULATION_SCHEMES] = {0};

    pthread_mutex_lock(NULL);

    for (int i = 0; i < frames->frameCount; i++) {
        totalAllocated++;
        totalSNR += frames->frames[i].SNR;

        if (modulationCounts[(int)(frames->frames[i].modulationScheme * MODULATION_SCHEMES)]++ == 0) {
            modulationCounts[(int)(frames->frames[i].modulationScheme * MODULATION_SCHEMES)] = 1;
        }
    }

    printf("Total allocated frames: %d\n", totalAllocated);
    printf("Average SNR: %.2f dB\n", totalSNR / totalAllocated);
    int mostFrequentModulation = -1;
    for (int i = 0; i < MODULATION_SCHEMES; i++) {
        if (modulationCounts[i] > modulationCounts[mostFrequentModulation]) {
            mostFrequentModulation = i;
        }
    }
    printf("Most frequently used modulation scheme: %.2f\n", (float)mostFrequentModulation / MODULATION_SCHEMES);

    pthread_mutex_unlock(NULL);
}

int main() {
    int N = 5; // user input
    NFAPI_RX_FRAME_INFO_T* frames = allocateRXFrames(N);

    if (!frames) return -1;

    // iterate over allocated structures without causing memory leaks
    for (int i = 0; i < frames->frameCount; i++) {
        printf("Frame %d: RNTI = %d, modulation scheme = %.2f, SNR = %.2f\n", 
               i, frames->frames[i].RNTI, frames->frames[i].modulationScheme, frames->frames[i].SNR);
    }

    retrieveStatistics(frames);

    return 0;
}
