#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <time.h>

#define MAX_STRUCTURES 1000
#define MAX_QUEUED_REQUESTS 10

typedef struct {
    RX_FRAME_INFO_T frame_info;
    RNTI rnti;
    PHY_LAYER_INFO_T phy_layer_info;
} NFAPI_RX_FRAME_INFO_T;

NFAPI_RX_FRAME_INFO_T* init_rx_frame_info(int N) {
    int i, max_requests = 0;
    NFAPI_RX_FRAME_INFO_T *frame_info_array = NULL;
    struct timespec last_log_time;
    clock_gettime(CLOCK_REALTIME, &last_log_time);

    if (N > MAX_STRUCTURES || N < 1) {
        printf("Invalid number of structures. Maximum allowed: %d.\n", MAX_STRUCTURES);
        return NULL;
    }

    if (N > MAX_QUEUED_REQUESTS) {
        max_requests = N - MAX_QUEUED_REQUESTS + 1;
    } else {
        max_requests = MAX_QUEUED_REQUESTS;
    }

    frame_info_array = (NFAPI_RX_FRAME_INFO_T*) malloc(N * sizeof(NFAPI_RX_FRAME_INFO_T));

    if (!frame_info_array) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (i = 0; i < N; i++) {
        frame_info_array[i].frame_info.frame_id = rand() % 1000;
        frame_info_array[i].rnti = rand() % 1000;
        frame_info_array[i].phy_layer_info.modulation_scheme = (rand() % 2) ? MODULATION_QPSK : MODULATION_16QAM;
        frame_info_array[i].phy_layer_info.snr = (rand() % 20);

        clock_gettime(CLOCK_REALTIME, &last_log_time);
        if (last_log_time.tv_nsec >= 1000000) {
            last_log_time.tv_nsec -= 1000000;
            printf("Allocated structure %d with RNTI %d and modulation scheme %s.\n", i + 1, frame_info_array[i].rnti, get_modulation_scheme_string(frame_info_array[i].phy_layer_info.modulation_scheme));
        }
    }

    return frame_info_array;
}

// Function to retrieve current statistics
int get_statistics(NFAPI_RX_FRAME_INFO_T* frame_info_array, int N) {
    int i, total_allocated = 0;
    double avg_snr = 0.0;

    for (i = 0; i < N; i++) {
        total_allocated++;
        avg_snr += frame_info_array[i].phy_layer_info.snr;
    }

    if (total_allocated > 0) {
        avg_snr /= total_allocated;
    } else {
        avg_snr = 0.0;
    }

    // Most frequently used modulation scheme
    int most_used_modulation = -1, max_count = 0;

    for (i = 0; i < N; i++) {
        if (frame_info_array[i].phy_layer_info.modulation_scheme == MODULATION_QPSK) {
            if (max_count < 1) {
                most_used_modulation = MODULATION_QPSK;
                max_count = 1;
            } else if (most_used_modulation != MODULATION_QPSK) {
                most_used_modulation = -1;
                break;
            }
        } else if (frame_info_array[i].phy_layer_info.modulation_scheme == MODULATION_16QAM) {
            if (max_count < 2) {
                most_used_modulation = MODULATION_16QAM;
                max_count++;
            } else if (most_used_modulation != MODULATION_16QAM) {
                most_used_modulation = -1;
                break;
            }
        }
    }

    return total_allocated, avg_snr, most_used_modulation;
}

// Function to initialize an array of NFAPI_CRC_INDICATION_PDU_T structures
NFAPI_CRC_INDICATION_PDU_T* init_crc_indication_pdus(int N, uint16_t* ue_identifiers, int ue_identifier_count) {
    int i, max_pds = 0;

    if (ue_identifier_count > N || N < 1) {
        printf("Invalid number of PDUs. Maximum allowed: %d.\n", MAX_STRUCTURES);
        return NULL;
    }

    for (i = 0; i < ue_identifier_count; i++) {
        if (ue_identifiers[i] >= N) {
            printf("UE identifier %d exceeds the maximum allowed PDUs.\n", ue_identifiers[i]);
            return NULL;
        }
    }

    max_pds = N;

    // Initialize and populate array of CRC indication PDUs
    NFAPI_CRC_INDICATION_PDU_T* crc_indication_pdu_array = (NFAPI_CRC_INDICATION_PDU_T*) malloc(N * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!crc_indication_pdu_array) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (i = 0; i < N; i++) {
        crc_indication_pdu_array[i].rx_ue_information_tag = RX_UE_INFORMATION_TAG;
        crc_indication_pdu_array[i].rnti = ue_identifiers[i % ue_identifier_count];
        crc_indication_pdu_array[i].crc_indication_rel8_tag.crcflag = (rand() % 2) ? CRCFLAG_VALID : CRCFLAG_INVALID;
    }

    return crc_indication_pdu_array;
}
