#include <stdlib.h>
#include <stdio.h>
#include <string.h>
#include <pthread.h>

#define MIN_CHUNK_SIZE 16
#define MAX_CHUNK_SIZE 256
#define DEFAULT_CHUNK_SIZE 64

typedef struct {
    uint8_t RX_UE_INFORMATION_TAG;
    int32_t RNTI;
    uint16_t CRC_INDICATION_REL8_TAG;
    uint8_t CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

void* resize_array(int N, size_t chunk_size) {
    size_t initial_capacity = (N + MIN_CHUNK_SIZE - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T);
    size_t allocated_size = initial_capacity;
    NFAPI_CRC_INDICATION_PDU_T* array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(initial_capacity);

    if (!array) {
        // Handle memory allocation failure
        printf("Memory allocation failed for NFAPI CRC indication PDU array.\n");
        return NULL;
    }

    size_t current_size = initial_capacity;

    while (1) {
        size_t new_capacity = (current_size + chunk_size - 1) * sizeof(NFAPI_CRC_INDICATION_PDU_T);
        void* new_array = realloc(array, new_capacity);

        if (!new_array) {
            // Handle memory reallocation failure
            printf("Memory reallocation failed for NFAPI CRC indication PDU array.\n");
            free(array);
            return NULL;
        }

        array = (NFAPI_CRC_INDICATION_PDU_T*)new_array;

        size_t remaining_size = new_capacity - current_size * sizeof(NFAPI_CRC_INDICATION_PDU_T);

        if (remaining_size >= chunk_size) {
            current_size = new_capacity / sizeof(NFAPI_CRC_INDICATION_PDU_T);
        } else {
            // Adjust chunk size to avoid memory waste
            chunk_size = remaining_size / sizeof(NFAPI_CRC_INDICATION_PDU_T);
        }
    }
}
