#define MAX_LIST_SIZE 100
#define MIN_RNTI 1
#define MAX_RNTI 65535

typedef struct {
    uint16_t rx_ue_info_tag;
    uint16_t rnti;
    uint8_t crc_ind_rel8_tag;
    uint8_t crcflag;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generate_list(int n) {
    srand(time(NULL));
    NFAPI_CRC_INDICATION_PDU_T* list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * MAX_LIST_SIZE);
    int list_size = 0;
    uint16_t last_rnti = 0;

    while(list_size < n && list_size < MAX_LIST_SIZE) {
        NFAPI_CRC_INDICATION_PDU_T* pdu = &list[list_size];

        do {
            pdu->rx_ue_info_tag = rand() % 65535;
            pdu->rnti = (last_rnti + 1) % (MAX_RNTI - MIN_RNTI) + MIN_RNTI;
            pdu->crc_ind_rel8_tag = rand() % 255;
        } while(pdu->rnti == last_rnti);

        if(rand() & 1)
            pdu->crcflag = 0x80;
        else
            pdu->crcflag = 0;

        list_size++;

        if(list_size >= MAX_LIST_SIZE) {
            free(list);
            list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * n);
            list_size = 0;
        }

        last_rnti = pdu->rnti;
    }

    return list;
}
