TCP_CONNECTION_INFO_T* create_tcp_connections_array(size_t max_size) {
    if (max_size > MAX_ARRAY_SIZE || max_size == 0) {
        return NULL;
    }

    TCP_CONNECTION_INFO_T* connections = malloc(max_size * sizeof(TCP_CONNECTION_INFO_T));
    if (!connections) {
        return NULL; // handle memory allocation failure
    }

    for (size_t i = 0; i < max_size; i++) {
        TCP_CONNECTION_INFO_T* connection = &connections[i];
        uint16_t session_id = (i * CRC_SEED + SESSION_ID_OFFSET) % SESSION_ID_RANGE;
        if (session_id > SESSION_ID_RANGE / 2) {
            // ensure unique session ID values
            session_id = (session_id - SESSION_ID_RANGE / 2 + 1) % SESSION_ID_RANGE;
        }

        char* remote_ip_address = ip_address_conversion_function((i * CRC_SEED + IP_ADDRESS_OFFSET));
        if (!remote_ip_address) {
            // handle IP address conversion failure
            return NULL; // or retry with a different seed, if possible
        }

        int connection_state = (rand() % 2) ? ESTABLISHED : LISTENING;
        connection->session_id = session_id;
        connection->remote_ip_address = remote_ip_address;
        connection->connection_state = connection_state;

        // update CRC for integrity verification
        crc_t crc_value = crc_calculate(CRC_SEED, (char*)&connection, sizeof(TCP_CONNECTION_INFO_T));
        // log initialization details and capture errors
        printf("Session ID: %04x, Remote IP Address: %s, Connection State: %s\n", session_id, remote_ip_address, connection_state ? "ESTABLISHED" : "LISTENING");

        free(remote_ip_address); // cache previously converted addresses
    }

    return connections;
}
