#include <stdio.h>
#include <stdlib.h>
#include <time.h>
#include <string.h>
#include "ip_service.h"
#include "crc32.h"

#define MAX_CONNECTIONS 1000
#define SESSION_ID_OFF 256
#define ESTABLISHED 1
#define LISTENING 2
#define INVALID_SESSION -1

typedef struct {
    uint32_t session_id;
    char remote_ip_address[16];
    int connection_state;
} TCP_CONNECTION_INFO_T;

TCP_CONNECTION_INFO_T* populate_connections(int num_connections) {
    TCP_CONNECTION_INFO_T* connections = NULL;
    time_t current_time = time(NULL);
    srand(current_time);
    uint32_t ip_cache_size = 0;
    char* ip_cache = NULL;
    int cache_hits = 0;

    if (num_connections > MAX_CONNECTIONS) {
        return NULL; // Error: Exceeded maximum connections
    }

    connections = (TCP_CONNECTION_INFO_T*)malloc(num_connections * sizeof(TCP_CONNECTION_INFO_T));
    if (!connections) {
        return NULL; // Memory allocation failed
    }

    for (int i = 0; i < num_connections; i++) {
        TCP_CONNECTION_INFO_T* connection = &connections[i];

        uint32_t session_id = SESSION_ID_OFF + i;
        if (session_id > 4294967295) {
            return NULL; // Error: Invalid session ID
        }
        connection->session_id = session_id;

        char remote_ip_address[16];
        int cache_hit = get_cached_ip(session_id, &remote_ip_address);
        if (!cache_hit) {
            // Cache miss: Resolve IP address and store in cache
            if (ip_cache_size + strlen(remote_ip_address) > 1024 * 64) {
                free(ip_cache);
                ip_cache_size = 0;
                ip_cache = NULL;
            }
            char* new_ip_cache = (char*)realloc(ip_cache, ip_cache_size + strlen(remote_ip_address) + 1);
            if (!new_ip_cache) {
                return NULL; // Memory allocation failed
            }
            strcpy(new_ip_cache + ip_cache_size, remote_ip_address);
            ip_cache_size += strlen(remote_ip_address);
            ip_cache = new_ip_cache;
        } else {
            cache_hits++;
        }

        connection->remote_ip_address = remote_ip_address;

        if (rand() % 2) {
            connection->connection_state = ESTABLISHED;
        } else {
            connection->connection_state = LISTENING;
        }
    }

    // Verify CRC for allocated memory and structures
    crc32_t crc = crc32_checksum(connections, num_connections * sizeof(TCP_CONNECTION_INFO_T));
    if (crc != 0) {
        return NULL; // Error: Memory or structure corruption detected
    }

    free(ip_cache);
