TCP_CONNECTION_STATS* generate_tcp_connection_stats(int max_size, int** ip_ranges) {
    // Initialize list and current index
    TCP_CONNECTION_STATS* stats = (TCP_CONNECTION_STATS*)malloc(max_size * sizeof(TCP_CONNECTION_STATS));
    int curr_idx = 0;

    // Loop until max size is reached or all possible connections are generated
    while (curr_idx < max_size) {
        // Generate random source IP and destination IP
        char src_ip[16], dst_ip[16];
        for (int i = 0; i < 16; i++) {
            if (rand() % 2 == 0) {
                src_ip[i] = (char)(rand() % 128);
                dst_ip[i] = (char)(rand() % 128);
            } else {
                src_ip[i] = 'a' + rand() % 26;
                dst_ip[i] = 'a' + rand() % 26;
            }
        }
        src_ip[15] = '\0';
        dst_ip[15] = '\0';

        // Validate IP addresses and ports
        int port = rand() % 65535;
        for (int i = 0; i < 2; i++) {
            if (ip_ranges[i][1] - ip_ranges[i][0] <= rand() % (ip_ranges[i][1] - ip_ranges[i][0])) {
                break;
            }
        }

        // Validate duration
        double duration = (double)rand() / RAND_MAX;

        // Generate connection stats structure and add to list
        TCP_CONNECTION_STATS* stat = &stats[curr_idx];
        strcpy(stat->src_ip, src_ip);
        strcpy(stat->dst_ip, dst_ip);
        stat->port = port;
