typedef struct {
    const char* name;
    void (*function)(void*);
    void* parameters;
} Kernel;

// Function to create a pool of worker threads
WorkerThread* createThreadPool(int numThreads) {
    // Allocate memory for the thread pool
    WorkerThread* threadPool = (WorkerThread*)malloc(numThreads * sizeof(WorkerThread));

    // Initialize the thread pool
    for (int i = 0; i < numThreads; i++) {
        threadPool[i].taskId = -1;
        threadPool[i].taskData = NULL;
    }

    return threadPool;
}

// Function to start a worker thread
void startWorkerThread(WorkerThread* thread, int taskId, void* taskData) {
    // Set the task ID and data for the thread
    thread->taskId = taskId;
    thread->taskData = taskData;

    // Start the thread
    pthread_create(&thread->id, NULL, workerThreadFunction, (void*)thread);
}

// Function to manage the worker thread pool
