    int num_db_connections;
    DB_CONNECTION_POOL_T *db_connections;
} SERVICE_INSTANCE_T;

SERVICE_INSTANCE_T *service_instances[MAX_SERVICE_INSTANCES];
int service_instance_count = 0;

void db_connection_pool_init() {
    for (int i = 0; i < MAX_SERVICE_INSTANCES; i++) {
        service_instances[i] = NULL;
    }
}

void add_service_instance(char *name, int version) {
    if (service_instance_count >= MAX_SERVICE_INSTANCES) {
        printf("Error: maximum number of service instances reached.\n");
        return;
    }
    SERVICE_INSTANCE_T *new_instance = malloc(sizeof(SERVICE_INSTANCE_T));
    strcpy(new_instance->name, name);
    new_instance->version = version;
    new_instance->num_db_connections = 0;
    new_instance->db_connections = NULL;
    service_instances[service_instance_count++] = new_instance;
}

void remove_service_instance(int index) {
    if (index < 0 || index >= service_instance_count) {
        printf("Error: invalid service instance index.\n");
        return;
    }
    free(service_instances[index]->db_connections);
    free(service_instances[index]);
    for (int i = index; i < service_instance_count - 1; i++) {
        service_instances[i] = service_instances[i + 1];
    }
    service_instance_count--;
}

void db_connection_pool_destroy() {
    for (int i = 0; i < service_instance_count; i++) {
        remove_service_instance(i);
    }
    free(service_instances);
}
