} NFAPI_CRC_INDICATION_PDU_T;

// Forward declaration of the linked list node structure.
typedef struct _Node *NFAPI_CRC_INDICATION_LIST_T;

NFAPI_CRC_INDICATION_LIST_T nfaapi_crc_indication_list = NULL;
int list_length = 0;

// Function to create a new node with given data.
NFAPI_CRC_INDICATION_LIST_T create_node(NFAPI_CRC_INDICATION_PDU_T* data) {
    NFAPI_CRC_INDICATION_LIST_T node = (NFAPI_CRC_INDICATION_LIST_T)malloc(sizeof(struct _Node));
    if (!node) {
        return NULL;
    }
    node->data = *data;
    node->next = NULL;
    return node;
}

// Function to add a new node at the end of the list.
void add_node(NFAPI_CRC_INDICATION_PDU_T* data) {
    NFAPI_CRC_INDICATION_LIST_T new_node = create_node(data);
    if (!nfaapi_crc_indication_list) {
        nfaapi_crc_indication_list = new_node;
    } else {
        NFAPI_CRC_INDICATION_LIST_T last_node = nfaapi_crc_indication_list;
        while (last_node->next) {
            last_node = last_node->next;
        }
        last_node->next = new_node;
    }
    list_length++;
}

// Function to remove a node with given RNTI value.
void remove_node(int rnti) {
    if (!nfaapi_crc_indication_list) return;

    NFAPI_CRC_INDICATION_LIST_T current_node = nfaapi_crc_indication_list;
    NFAPI_CRC_INDICATION_LIST_T previous_node = NULL;
    while (current_node && current_node->data.RNTI != rnti) {
        previous_node = current_node;
        current_node = current_node->next;
    }
    if (!current_node) return;

    if (previous_node) {
        previous_node->next = current_node->next;
    } else {
        nfaapi_crc_indication_list = current_node->next;
    }

    free(current_node);
    list_length--;
}

// Function to reset all CRCFLAG bits in the list.
void reset_crc_flags() {
