['```cpp
#include <iostream>
#include <vector>
#include <algorithm>
#include <random>

class DynamicResourcePoolManager {
private:
    std::mutex mtx;
    int poolSize = 10; // initial pool size
    int blockSize = 1024; // block size in bytes
    int minID = 0, maxID = 10000; // ID range
    double minUsage = 0.0, maxUsage = 1.0; // usage percentage range

public:
    struct ResourceBlock {
        int blockID;
        long timestamp;
        double usagePercentage = 0.0;
    };

    DynamicResourcePoolManager() : pool(new std::vector<ResourceBlock>(poolSize)) {}

    ~DynamicResourcePoolManager() {
        delete[] pool.data();
    }

    // Generate a random integer within [minID, maxID]
    int generateRandomInt() {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        std::uniform_int_distribution<> dis(minID, maxID);
        return dis(gen);
    }

    // Generate a random double within [0.0, 1.0]
    double generateRandomDouble() {
        static std::random_device rd;
        static std::mt19937 gen(rd());
        std::uniform_real_distribution<double> dis(0.0, 1.0);
        return dis(gen);
    }

    // Create an array of ResourceBlock structures
    void createPool(int newSize) {
        if (newSize > 0) {
            delete[] pool.data();
            pool = new std::vector<ResourceBlock>(newSize);
            for (int i = 0; i < newSize; ++i)
                pool->emplace_back(generateRandomInt(), 0, 0.0);
        }
    }

    // Reset all usagePercentage fields
    void resetUsage() {
        for (auto& block : *pool) block.usagePercentage = 0.0;
    }

    // Remove specific entries from the array based on blockID values
    void removeBlocks(const std::vector<int>& IDsToRemove) {
        pool->erase(std::remove_if(pool->begin(), pool->end(),
            [&IDsToRemove](const ResourceBlock& block) {
                return std::find(IDsToRemove.begin(), IDsToRemove.end(), block.blockID) != IDsToRemove.end();
            }), pool->end());
    }

    // Serialize the internal state of the class
    void serialize(std::ostream& os) const {
        os << "Pool size: " << poolSize << "\n";
        os << "Block size: " << blockSize << "\n";
        os << "ID range: [" << minID << ", " << maxID << "]\n";
        os << "Usage percentage range: [" << minUsage << ", " << maxUsage << "]\n";

        for (const auto& block : *pool) {
            os << "Block ID: " << block.blockID << "\n";
            os << "Timestamp: " << block.timestamp << "\n";
            os << "Usage percentage: " << block.usagePercentage << "\n";
        }
    }

    // Deserialize the internal state of the class
    void deserialize(std::istream& is) {
        int poolSizeTemp, blockSizeTemp, minIDTemp, maxIDTemp;
        double minUsageTemp, maxUsageTemp;

        is >> poolSizeTemp >> blockSizeTemp >> minIDTemp >> maxIDTemp >> minUsageTemp >> maxUsageTemp;

        // Update internal state
        this->poolSize = poolSizeTemp;
        this->blockSize = blockSizeTemp;
        this->minID = minIDTemp;
        this->maxID = maxIDTemp;
        this->minUsage = minUsageTemp;
        this->maxUsage = maxUsageTemp;

        // Re-create the pool with the updated size
        createPool(poolSizeTemp);
    }

    // Override toString() method
    std::string toString() const {
        std::string output = "DynamicResourcePoolManager:\n";
        output += "Pool size: " + std::to_string(poolSize) + "\n";
        output += "Block size: " + std::to_string(blockSize) + "\n";
        output += "ID range: [" + std::to_string(minID) + ", " + std::to_string(maxID) + "]\n";
        output += "Usage percentage range: [" + std::to_string(minUsage) + ", " + std::to_string(maxUsage) + "]\n";

        for (const auto& block : *pool) {
            output += "Block ID: " + std::to_string(block.blockID) + "\n";
            output += "Timestamp: " + std::to_string(block.timestamp) + "\n";
            output += "Usage percentage: " + std::to_string(block.usagePercentage) + "\n";
        }

        return output;
    }
};

// Example usage:
int main() {
    DynamicResourcePoolManager pool;

    // Create an initial array of ResourceBlock structures
    pool.createPool(10);

    // Reset all usagePercentage fields
    pool.resetUsage();

    // Remove specific entries from the array based on blockID values
    std::vector<int> IDsToRemove = {1, 3, 5};
    pool.removeBlocks(IDsToRemove);

    // Serialize and deserialize the internal state of the class
    std::ofstream os("pool_state.txt");
    pool.serialize(os);
    os.close();

    std::ifstream is("pool_state.txt");
    pool.deserialize(is);
    is.close();

    // Display the current range, usage statistics, and pool size
    std::cout << pool.toString() << "\n";

    return 0;
}
```']

