import json
import csv
from kafka import KafkaProducer, KafkaConsumer
from pulsar import Producer, Consumer

class IoTDataProcessor:
    def __init__(self):
        self.kafka_producer = KafkaProducer(bootstrap_servers=['localhost:9092'])
        self.pulsar_producer = Producer('persistent://my-cluster/my-tenant/my-topic', 'my-topic')
        self.kafka_consumer = KafkaConsumer(bootstrap_servers=['localhost:9092'], group_id='iot_data_processor')
        self.pulsar_consumer = Consumer('persistent://my-cluster/my-tenant/my-topic', 'my-topic')

    def process_iot_data(self, data):
        # Process temperature, humidity, and motion data
        processed_data = {
            'temperature': data['temperature'],
            'humidity': data['humidity'],
            'motion': data['motion']
        }
        return json.dumps(processed_data)

    def ingest_data(self, data):
        # Send data to Kafka/Pulsar topics
        self.kafka_producer.send('iot_data', value=json.loads(data).encode('utf-8'))
        self.pulsar_producer.send(self.process_iot_data(data))

    def consume_data(self):
        # Consume data from Kafka/Pulsar topics
        for message in self.kafka_consumer:
            print(message.value.decode('utf-8'))
        for message in self.pulsar_consumer:
            print(message.value.decode('utf-8'))

if __name__ == '__main__':
    processor = IoTDataProcessor()
    processor.ingest_data('[{"temperature": 25, "humidity": 60, "motion": true}, {"temperature": 28, "humidity": 50, "motion": false}]')
    processor.consume_data()
```

