HTTP_REQUEST_STATS* generate_request_stats(int* max_list_size) {
    // Initialize the list and its size
    HTTP_REQUEST_STATS* request_stats = (HTTP_REQUEST_STATS*)malloc(*max_list_size * sizeof(HTTP_REQUEST_STATS));
    int current_list_size = 0;

    while (current_list_size < *max_list_size) {
        char client_ip[20];
        char server_ip[20];
        char requested_url[200];
        int response_status_code;
        double latency;

        // Generate unique client IP and server IP
        sprintf(client_ip, "192.168.%d.%d", rand() % 255, rand() % 255);
        sprintf(server_ip, "10.0.%d.%d", rand() % 254, rand() % 254);

        // Validate the generated IPs
        if (sscanf(client_ip, "%hhu.%hhu.%hhu.%hhu", &client_ip[0], &client_ip[1], &client_ip[2], &client_ip[3]) != 4 || sscanf(server_ip, "%hhu.%hhu.%hhu.%hhu", &server_ip[0], &server_ip[1], &server_ip[2], &server_ip[3]) != 4) {
            // If the IPs are invalid, generate new ones
            continue;
        }

        // Generate requested URL and response status code
        sprintf(requested_url, "http://example.com/page%d", rand() % 100);
        response_status_code = rand() % 200 + 1;

        // Validate the generated URL and response status code
        if (strlen(requested_url) > 190 || response_status_code < 100 || response_status_code > 299) {
            // If the URL or response status code is invalid, generate new ones
            continue;
        }

        // Generate latency
        latency = (double)rand() / RAND_MAX;

        // Add the generated request stats to the list
        request_stats[current_list_size].client_ip = client_ip;
        request_stats[current_list_size].server_ip = server_ip;
        strcpy(request_stats[current_list_size].requested_url, requested_url);
        request_stats[current_list_size].response_status_code = response_status_code;
        request_stats[current_list_size].latency = latency;

        current_list_size++;
    }

    // Set the actual list size
    *max_list_size = current_list_size;

    return request_stats;
}
