int init_aes_cipher(char* password, unsigned char** cipher_key, unsigned char** iv) {
    // Derive encryption key from password using PBKDF2-HMAC-SHA256
    const EVP_PBE_METHOD* pbe_method = EVP_pbkdf2_hmac_sha256();
    BIGNUM* salt = BN_new();
    int key_len = 32; // Set key length to 32 bytes (256 bits) for AES-256

    // Generate random initialization vector (IV)
    unsigned char* iv_data = OPENSSL_malloc(AES_BLOCK_SIZE);
    RAND_bytes(iv_data, AES_BLOCK_SIZE);

    *cipher_key = EVP_PBE_key(pbe_method, password, salt, key_len);
    *iv = iv_data;

    return 0;
}
