#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/mman.h>
#include <sys/stat.h>
#include <fcntl.h>

int main(int argc, char **argv) {
    int opt;
    char *input_file = NULL;
    char *delimiter = "\n";
    char *output_format = "%s\n";
    int skip_comments = 0;

    while ((opt = getopt(argc, argv, "d:f:vh")) != -1) {
        switch (opt) {
            case 'd':
                delimiter = optarg;
                break;
            case 'f':
                output_format = optarg;
                break;
            case 'v':
                printf("Version 1.0\n");
                exit(0);
            case 'h':
                printf("Usage: %s [-d DELIMITER] [-f FORMAT] [INPUT_FILE]\n", argv[0]);
                exit(0);
        }
    }

    if (argc < 2) {
        fprintf(stderr, "No input file specified. Please specify an input file.\n");
        return 1;
    }

    for (int i = 1; i < argc; i++) {
        if (!strcmp(argv[i], "-v")) {
            printf("Version 1.0\n");
            exit(0);
        } else if (!strcmp(argv[i], "-h")) {
            printf("Usage: %s [-d DELIMITER] [-f FORMAT] [INPUT_FILE]\n", argv[0]);
            exit(0);
        }
    }

    for (int i = 1; i < argc; i++) {
        if (strcmp(argv[i], "-d") == 0) {
            delimiter = argv[i + 1];
            i++;
        } else if (strcmp(argv[i], "-f") == 0) {
            output_format = argv[i + 1];
            i++;
        }
    }

    int fd, map_len;
    struct stat sb;

    for (int i = 1; i < argc; i++) {
        if (!strncmp(argv[i], "-", 1)) continue;
        char *temp_path = argv[i];
        if (*temp_path == '.') temp_path++;

        while ((fd = open(temp_path, O_RDONLY)) != -1) {
            fstat(fd, &sb);
            map_len = sb.st_size;

            // Map the file into memory
            void *map_start = mmap(NULL, map_len, PROT_READ, MAP_SHARED, fd, 0);

            if (map_start == (void *)-1) {
                perror("mmap");
                close(fd);
                continue;
            }

            char *line = map_start;

            int line_count = 0;
            while (*line != '\0') {
                if (!skip_comments && *line == '#') {
                    while (*++line != '\n');
                }
                if (*line == '\0') break;

                printf(output_format, line);
                line++;
                line_count++;

                // Check for end of file
                if (line >= map_start + map_len) {
                    char c;
                    while ((c = fgetc(fd)) != EOF && c != '\n');
                    if (c == EOF) break;
                }
            }

            munmap(map_start, map_len);
            close(fd);
        }
    }

    return 0;
}
