            nfa_pi_crc_indication_pdu_list.tail = new_node;
        } else {
            new_node->link.prev = nfa_pi_crc_indication_pdu_list.tail;
            nfa_pi_crc_indication_pdu_list.tail->link.next = new_node;
            nfa_pi_crc_indication_pdu_list.tail = new_node;
        }

        // Update the list size and age
        nfa_pi_crc_indication_pdu_list.size++;
        if (nfa_pi_crc_indication_pdu_list.size > max_size) {
            evict_least_recently_used();
        }
        nfa_pi_crc_indication_pdu_list.max_age = (int)(time(NULL));

    }

    // Function to remove an element from the list based on RNTI
    void remove_element(int rnti) {
