        node* previous_node;

        for (current_node = nfa_pi_crc_indication_pdu_list.head; current_node != NULL; current_node = current_node->link.next) {
            if (current_node->data.rnti == rnti) {
                // Remove the element from the list
                if (previous_node) {
                    previous_node->link.next = current_node->link.next;
                } else {
                    nfa_pi_crc_indication_pdu_list.head = current_node->link.next;
                }
                if (current_node->link.next == NULL) {
                    nfa_pi_crc_indication_pdu_list.tail = previous_node;
                }

                // Update the list size and age
                nfa_pi_crc_indication_pdu_list.size--;
                if (nfa_pi_crc_indication_pdu_list.size < max_size / 2) {
                    evict_least_recently_used();
                }
