    void reset_crcflags() {
        node* current_node;

        for (current_node = nfa_pi_crc_indication_pdu_list.head; current_node != NULL; current_node = current_node->link.next) {
            current_node->data.crcflag = 0;
        }
    }

    // Function to evict the least recently used elements
    void evict_least_recently_used() {
        node* current_node;
        node* previous_node;

        for (current_node = nfa_pi_crc_indication_pdu_list.head; current_node != NULL; current_node = current_node->link.next) {
