typedef struct {
    int frequencyBand;
    float channelWidth;
    struct modSchemes* modulationList;
} networkConfig;

typedef struct modScheme {
    char name[20];
    void (*callback)(struct modScheme*);
} modulationScheme;

void addModulation(networkConfig* config, const char* name, void (*callback)(struct modScheme*)) {
    modulationScheme* newMod = (modulationScheme*)malloc(sizeof(modulationScheme));
    strcpy(newMod->name, name);
    newMod->callback = callback;
    if(config->modulationList == NULL) {
        config->modulationList = newMod;
    } else {
        struct modSchemes* current = config->modulationList;
        while(current->next != NULL) {
            current = current->next;
        }
        current->next = newMod;
    }
}

void removeModulation(networkConfig* config, const char* name) {
    if(config->modulationList == NULL) return;

    struct modSchemes* current = config->modulationList;
    struct modSchemes* previous = NULL;

    while(current != NULL) {
        if(strcmp(current->name, name) == 0) {
            if(previous == NULL) {
                config->modulationList = current->next;
            } else {
                previous->next = current->next;
            }
            free(current);
            return;
        }
        previous = current;
        current = current->next;
    }
}

void iterateMods(networkConfig* config, void (*callback)(struct modSchemes*)) {
    struct modSchemes* current = config->modulationList;

    while(current != NULL) {
        callback(current);
        current = current->next;
    }
}

networkConfig* initializeNetworkConfig() {
    networkConfig* config = (networkConfig*)malloc(sizeof(networkConfig));
    config->frequencyBand = 0;
    config->channelWidth = 0.0f;
    config->modulationList = NULL;

    return config;
}']

