typedef struct {
    int frequencyBand;
    int channelWidth;
    float powerConsumption;
    float signalStrength;
} RadioModule;

typedef struct {
    char *modulationScheme;
    void (*callback)(void *);
} ModulationScheme;

RadioModule* radioModules = NULL;
int radioModuleCount = 0;
ModulationScheme* modulationSchemes = NULL;
int modulationSchemeCount = 0;

void initNetworkConfig() {
    radioModules = (RadioModule*)malloc(sizeof(RadioModule));
    radioModuleCount = 1;
}

void addRadioModule(int frequencyBand, int channelWidth, float powerConsumption, float signalStrength) {
    RadioModule* newModule = (RadioModule*)malloc(sizeof(RadioModule));
    newModule->frequencyBand = frequencyBand;
    newModule->channelWidth = channelWidth;
    newModule->powerConsumption = powerConsumption;
    newModule->signalStrength = signalStrength;

    radioModules = realloc(radioModules, (radioModuleCount + 1) * sizeof(RadioModule));
    radioModules[radioModuleCount] = newModule;
    radioModuleCount++;
}

void removeRadioModule(int index) {
    if(index < radioModuleCount) {
        for(int i = index; i < radioModuleCount - 1; i++) {
            radioModules[i] = radioModules[i + 1];
        }
        free(radioModules[radioModuleCount - 1]);
        radioModuleCount--;
    }
}

void addModulationScheme(char *modulationScheme, void (*callback)(void *)) {
    ModulationScheme* newScheme = (ModulationScheme*)malloc(sizeof(ModulationScheme));
    newScheme->modulationScheme = strdup(modulationScheme);
    newScheme->callback = callback;

    modulationSchemes = realloc(modulationSchemes, (modulationSchemeCount + 1) * sizeof(ModulationScheme));
    modulationSchemes[modulationSchemeCount] = newScheme;
    modulationSchemeCount++;
}

void removeModulationScheme(int index) {
    if(index < modulationSchemeCount) {
        for(int i = index; i < modulationSchemeCount - 1; i++) {
            modulationSchemes[i] = modulationSchemes[i + 1];
        }
        free(modulationSchemes[modulationSchemeCount - 1]->modulationScheme);
        free(modulationSchemes[modulationSchemeCount - 1]);
        modulationSchemeCount--;
    }
}

void iterateOverModulationSchemes(void (*callback)(void *)) {
    for(int i = 0; i < modulationSchemeCount; i++) {
        callback(modulationSchemes[i]->modulationScheme);
    }
}
