typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
    bool CRCFLAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generateNFAPDUList(int listSize, int* rntiRange) {
    // Initialize the list and a pointer to keep track of the current position
    NFAPI_CRC_INDICATION_PDU_T* pfapdu = (NFAPI_CRC_INDATION_PDU_T*)malloc(listSize * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int* pcurrentRnti = &MIN_RNTI;

    // Generate each PDU structure with a unique RNTI and validate the range
    for(int i=0; i<listSize; i++) {
        pfapdu[i].RX_UE_INFORMATION_TAG = rand() % 100;
        pfapdu[i].RNTI = *pcurrentRnti++;
        if(*pcurrentRnti > MAX_RNTI) {
            *pcurrentRnti = MIN_RNTI; // Reset the RNTI range
        }
        pfapdu[i].CRC_INDICATION_REL8_TAG = rand() % 100;
        pfapdu[i].CRCFLAG = (bool)(rand() & 1); // Randomly set CRCFLAG

        if(pfapdu[i].RNTI == pfapdu[i-1].RNTI) {
            printf("Error: Two consecutive structures have the same RNTI value.\n");
            return NULL; // Handle error and exit
        }
    }

    // Return the generated PDU list
    return pfapdu;
}

int main() {
    srand(time(NULL)); // Seed random number generator

    int listSize = 10; // Initial list size
    int rntiRange[MAX_RNTI-MIN_RNTI+1] = {0}; // Initialize RNTI range

    NFAPI_CRC_INDICATION_PDU_T* pfapduList = generateNFAPDUList(listSize, &rntiRange);

    if(pfapduList == NULL) {
        printf("Error: Unable to generate PDU list.\n");
