        // Print the generated PDU structures
        for(int i=0; i<listSize; i++) {
            printf("RX_UE_INFORMATION_TAG: %d, RNTI: %d, CRC_INDICATION_REL8_TAG: %d, CRCFLAG: %s\n", pfapduList[i].RX_UE_INFORMATION_TAG, pfapduList[i].RNTI, pfapduList[i].CRC_INDICATION_REL8_TAG, (pfapduList[i].CRCFLAG) ? "True" : "False");
        }
    }

    // Free dynamically allocated memory
    free(pfapduList);

    return 0;
}
