    if (num_ue_states == 0) {
        ue_states = malloc(sizeof(UEState));
    } else {
        UEState* temp = malloc((num_ue_states + 1) * sizeof(UEState));
        memcpy(temp, ue_states, num_ue_state * sizeof(UEState));
        free(ue_states);
        ue_states = temp;
    }
    ue_states[num_ue_states++] = *new_ue_state;
}

void update_ue_state(int RNTI, UEState* updated_ue_state) {
    for (int i = 0; i < num_ue_states; i++) {
        if (ue_states[i].RNTI == RNTI) {
            ue_states[i] = *updated_ue_state;
            return;
        }
    }
}

UEState* get_ue_state(int RNTI) {
    for (int i = 0; i < num_ue_states; i++) {
        if (ue_states[i].RNTI == RNTI) {
            UEState* ue_state = malloc(sizeof(UEState));
            *ue_state = ue_states[i];
            return ue_state;
