    void (**rnti_map)[3] = (void **)malloc((sizeof(void *) * 100));  // Assuming max 100 UEStates initially

    int rnti_count = 0;

    // Initialize the map with all NULLs to start with
    for (int i = 0; i < 100; i++) {
        rnti_map[i] = NULL;
    }

    while (1) {
        printf("Enter your choice:\n");
        printf("1. Add UEState\n");
        printf("2. Update UEState\n");
        printf("3. Retrieve UEState by RNTI\n");
        printf("4. Exit\n");

        int choice;
        scanf("%d", &choice);

        switch (choice) {
            case 1: {
                // Add new UEState
                UEState *new_ue_state = (UEState *)malloc(sizeof(UEState));
                printf("Enter UE_ID, RNTI, and CRC_STATUS for the new UEState:\n");
                scanf("%d %d %d", &new_ue_state->UE_ID, &new_ue_state->RNTI, &new_ue_state->CRC_STATUS);

                // Check if RNTI already exists in the map
                int rnti_index = -1;
                for (int i = 0; i < rnti_count; i++) {
                    if (rnti_map[i]->RNTI == new_ue_state->RNTI) {
                        rnti_index = i;
                        break;
                    }
                }

                // If RNTI exists, update the existing UEState
                if (rnti_index != -1) {
                    free(new_ue_state);
                    printf("UEState with RNTI %d already exists. Updating it.\n", new_ue_state->RNTI);
                    *rnti_map[rnti_index] = new_ue_state;
                } else {
                    // If RNTI doesn't exist, add the new UEState
                    rnti_map[rnti_count] = &new_ue_state;
                    rnti_count++;

                    printf("UEState added successfully.\n");
                }
                break;
            }

            case 2: {
                // Update existing UEState
                int update_rnti;
                printf("Enter the RNTI of the UEState you want to update:\n");
                scanf("%d", &update_rnti);

                for (int i = 0; i < rnti_count; i++) {
                    if (rnti_map[i]->RNTI == update_rnti) {
                        printf("Enter new UE_ID, RNTI, and CRC_STATUS for the updated UEState:\n");
                        scanf("%d %d %d", &rnti_map[i]->UE_ID, &rnti_map[i]->RNTI, &rnti_map[i]->CRC_STATUS);
                    }
                }

                printf("UEState updated successfully.\n");
                break;
            }

            case 3: {
                // Retrieve UEState by RNTI
                int retrieve_rnti;
                printf("Enter the RNTI of the UEState you want to retrieve:\n");
                scanf("%d", &retrieve_rnti);

                for (int i = 0; i < rnti_count; i++) {
                    if (rnti_map[i]->RNTI == retrieve_rnti) {
                        printf("UE_ID: %d, RNTI: %d, CRC_STATUS: %d\n", rnti_map[i]->UE_ID, rnti_map[i]->RNTI, rnti_map[i]->CRC_STATUS);
                    }
                }

                printf("Retrieved UEState successfully.\n");
                break;
            }

            case 4:
                // Exit the program
                free(rnti_map);
                return;

            default:
                printf("Invalid choice. Please try again.\n");
        }
    }
}
