// Function to manage a dynamically allocated list of DeviceContext objects
void *device_list = NULL;  // Initialize the device list as a linked list node

// Add a new DeviceContext entry with unique DeviceID, IP_Address and Status
int add_device(DeviceContext* new_device) {
    // Check if the device ID is already in use (simulate network service call)
    // Simulate network latency (1 second for simplicity)
    sleep(1);

    // Allocate memory for a new node
    DeviceContext* new_node = malloc(sizeof(DeviceContext));

    // Copy data from input to new_node
    memcpy(new_node, new_device, sizeof(DeviceContext));

    // Add the new node at the end of the linked list
    // If the list is empty, set device_list as the new node
    if (device_list == NULL) {
        device_list = new_node;
    } else {
        DeviceContext* current_node = device_list;

        // Traverse the linked list to find the last node and update its 'next' pointer
        while (current_node->next != NULL) {
            current_node = current_node->next;
        }

        current_node->next = new_node;
    }

    return 0;  // Successful addition
}

// Update an existing DeviceContext entry based on IP_Address
int update_device(char* ip_address) {
    DeviceContext* current_node = device_list;

    while (current_node != NULL) {
        if (strcmp(current_node->IP_Address, ip_address) == 0) {
            // Simulate updating the Status field of the found node
            current_node->Status = 1;  // Set status to '1' for simplicity

            return 0;  // Successful update
        }

        current_node = current_node->next;
    }

    return -1;  // Not found or list empty
}

// Retrieve a specific DeviceContext entry based on IP_Address
int get_device(char* ip_address) {
    DeviceContext* current_node = device_list;

    while (current_node != NULL) {
        if (strcmp(current_node->IP_Address, ip_address) == 0) {
            // Simulate returning the found node's data
            printf("DeviceID: %d, IP_Address: %s, Status: %d\n", current_node->DeviceID, current_node->IP_Address, current_node->Status);

            return 0;  // Successful retrieval
        }

        current_node = current_node->next;
    }

    return -1;  // Not found or list empty
}

// Free the device list when no longer needed
void free_device_list() {
    DeviceContext* current_node = device_list;
    DeviceContext* temp = NULL;

    while (current_node != NULL) {
        temp = current_node->next;

        free(current_node);
        current_node = temp;
    }

    device_list = NULL;  // Reset the list pointer
}

