    RRC_CONNECTION_RECONFIGURATION_TAG* tags;
    int num_tags;
} NFAPI_RX_FRAME_T;

int nfapi_rx_frame_init(NFAPI_RX_FRAME_T** frames, int capacity) {
    *frames = (NFAPI_RX_FRAME_T*)malloc(sizeof(NFAPI_RX_FRAME_T) * capacity);
    if (*frames == NULL) return -1;
    for (int i = 0; i < capacity; i++) {
        (*frames)[i].tags = (RRC_CONNECTION_RECONFIGURATION_TAG*)calloc(1, sizeof(RRC_CONNECTION_RECONFIGURATION_TAG));
        if ((*frames)[i].tags == NULL) return -2;
        (*frames)[i].num_tags = 0;
    }
    return 0;
}

int nfapi_rx_frame_add(NFAPI_RX_FRAME_T* frames, int capacity, int index, RRC_CONNECTION_RECONFIGURATION_TAG tag) {
    if (index < 0 || index >= capacity) return -1;
    frames[index].tags = realloc(frames[index].tags, (frames[index].num_tags + 1) * sizeof(RRC_CONNECTION_RECONFIGURATION_TAG));
    if (frames[index].tags == NULL) return -2;
    frames[index].tags[frames[index].num_tags] = tag;
    frames[index].num_tags++;
    return 0;
}

int nfapi_rx_frame_get(NFAPI_RX_FRAME_T* frames, int capacity, int index, RRC_CONNECTION_RECONFIGURATION_TAG** tag) {
    if (index < 0 || index >= capacity) return -1;
    *tag = &frames[index].tags[0];
    return 0;
}

void nfapi_rx_frame_free(NFAPI_RX_FRAME_T* frames, int capacity) {
    for (int i = 0; i < capacity; i++) {
        free(frames[i].tags);
    }
    free(frames);
}
