    size_t capacity;
    size_t size;
} NFAPIRXFrameList;

void nfapi_rx_frame_list_init(NFAPIRXFrameList* list, size_t initial_capacity) {
    list->frames = (NFAPI_RX_FRAME_T*)malloc(initial_capacity * sizeof(NFAPI_RX_FRAME_T));
    list->capacity = initial_capacity;
    list->size = 0;
}

int nfapi_rx_frame_list_add(NFAPIRXFrameList* list, NFAPI_RX_FRAME_T frame) {
    if (list->size >= list->capacity) {
        list->frames = (NFAPI_RX_FRAME_T*)realloc(list->frames, list->capacity * sizeof(NFAPI_RX_FRAME_T) * 2);
        list->capacity *= 2;
    }
    for (size_t i = 0; i < list->size; ++i) {
        if (memcmp(&list->frames[i], &frame, sizeof(NFAPI_RX_FRAME_T)) == 0) {
            return -1; // duplicate entry
        }
    }
    memcpy(&list->frames[list->size], &frame, sizeof(NFAPI_RX_FRAME_T));
    ++list->size;
    return 0;
}

NFAPI_RX_FRAME_T* nfapi_rx_frame_list_get(NFAPIRXFrameList* list, size_t index) {
    if (index >= list->size || !list->frames[index].info.rf_rx_frame_info_present) {
        return NULL; // invalid operation
    }
    return &list->frames[index];
}

void nfapi_rx_frame_list_free(NFAPIRXFrameList* list) {
    for (size_t i = 0; i < list->size; ++i) {
        if (list->frames[i].reconfigurations) {
            for (size_t j = 0; j < list->frames[i].num_reconfigurations; ++j) {
                free(list->frames[i].reconfigurations[j]);
            }
            free(list->frames[i].reconfigurations);
        }
    }
    free(list->frames);
}
