} DynamicList;

DynamicList* init_dynamic_list(int initial_capacity) {
    DynamicList* list = malloc(sizeof(DynamicList));
    list->capacity = initial_capacity;
    list->size = 0;
    list->messages = calloc(initial_capacity, sizeof(NFLOG_MESSAGE_T));
    return list;
}

void add_message(DynamicList* list, NFLOG_MESSAGE_T message) {
    if (list->size >= list->capacity) {
        resize_list(list);
    }
    memcpy(&list->messages[list->size], &message, sizeof(NFLOG_MESSAGE_T));
    list->size++;
}

NFLOG_MESSAGE_T* get_message_at_index(DynamicList* list, int index) {
    if (index < 0 || index >= list->size) {
        return NULL;
    }
    return &list->messages[index];
}

