    if (!ptr) {
        printf("Memory allocation failed!\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

// Implement the function to manage session states
int manage_session_states() {
    // Initialize the cache and memory pool
    SessionState *cache = (SessionState*)my_malloc(SESSION_CACHE_SIZE);
    pthread_mutex_t mutex = PTHREAD_MUTEX_INITIALIZER;

    // Initialize external user authentication service handle
    int auth_service_handle = -1;
    if (!init_auth_service(&auth_service_handle)) {
        printf("Error initializing authentication service!\n");
        return 1;
    }

    while (true) {
        // Process real-time updates from the external service
        update_session_states(auth_service_handle, cache);

        // Handle concurrent requests and maintain thread safety
        pthread_mutex_lock(&mutex);
        int current_sessions = 0;
        for (int i = 0; i < MAX_SESSIONS; i++) {
            if (cache[i].token != NULL) {
                current_sessions++;
                process_session(cache + i);
            }
        }
        pthread_mutex_unlock(&mutex);

        // Monitor and handle memory usage
        monitor_memory_usage();

        // Sleep for a short duration to allow other tasks to run
        usleep(10000); // 10ms delay
    }

    // Clean up resources before exit
