        if (allocations % logInterval == 0) {
            fclose(logFile);
            logFile = fopen("memory_pool.log", "a");
            if (!logFile) {
                printf("Failed to reopen logging.\n");
                return NULL;
            }
        }

        // Deallocate structures exceeding the maximum age
        if (allocations > 5000) { // Adjust based on system load and resource availability
            void* deallocateTarget = ((char*) memoryPool) + (allocations - logInterval) * structSize;
            int deallocationsToMake = allocations - logInterval;

            // Deallocate structures in batches to minimize disk I/O overhead
            for (int i = 0; i < deallocationsToMake; i++) {
                void* structure = ((char*) memoryPool) + (allocations - logInterval + i) * structSize;
                free(structure);
            }

            allocations -= deallocationsToMake;
            deallocations += deallocationsToMake;

            // Log deallocation event
            logEvent(logFile, "Deallocate", NULL);

            // Flush logs to disk or remote server
            fclose(logFile);
            logFile = fopen("memory_pool.log", "a");
            if (!logFile) {
                printf("Failed to reopen logging.\n");
                return NULL;
            }
        }
    }

    // Finalize performance monitoring and logging
    int totalAllocations = allocations + deallocations;
    int totalCorruptionEvents = corruptionEvents;

    // Close the log file
    fclose(logFile);

    // Log final statistics
    printf("Memory pool statistics: %d structures allocated, %d corrupted.\n", totalAllocations, totalCorruptionEvents);

    return memoryPool;
}

