typedef struct {
    int userId;
    char taskType[10];
    int priority;
} TASK_REQUEST;

// Worker thread function to process tasks
void* workerThread(void* arg) {
    // Get the task from the queue
    TASK_REQUEST* task = (TASK_REQUEST*)queue_dequeue();

    if (task == NULL) return NULL;  // Exit if queue is empty

    // Process the task here
    printf("Processing task %d with priority %d...\n", task->userId, task->priority);

    // Simulate processing time
    sleep(1);  // Replace with actual processing code

    free(task);  // Free allocated memory

    return NULL;
}

// Task queue structure and functions
typedef struct {
    TASK_REQUEST* tasks[MAX_TASKS];
    int front, rear, count;
} TaskQueue;

TaskQueue taskQueue = {{0}, 0, 0, 0};

void queue_enqueue(TASK_REQUEST* task) {
    if (taskQueue.count == MAX_TASKS) return;  // Queue full

    taskQueue.tasks[taskQueue.rear] = task;
    taskQueue.rear = (taskQueue.rear + 1) % MAX_TASKS;

    if (taskQueue.front == taskQueue.rear) taskQueue.front = taskQueue.rear;

    taskQueue.count++;
}

TASK_REQUEST* queue_dequeue() {
    TASK_REQUEST* task = NULL;

    if (taskQueue.count > 0) {
        task = taskQueue.tasks[taskQueue.front];

        taskQueue.front = (taskQueue.front + 1) % MAX_TASKS;

        if (taskQueue.front == taskQueue.rear) taskQueue.front = taskQueue.rear;

        taskQueue.count--;
    }

    return task;
}

// C function to manage asynchronous processing
void manageTasks(TASK_REQUEST* tasks, int numTasks) {
    // Initialize the task queue
    taskQueue.count = 0;
    taskQueue.front = taskQueue.rear = 0;

    pthread_t workerThreads[MAX_PRIORITY];  // Array of worker threads

    for (int i = 0; i < MAX_PRIORITY; i++) {
        pthread_create(&workerThreads[i], NULL, workerThread, NULL);
    }

    for (int i = 0; i < numTasks; i++) {
        TASK_REQUEST* task = &tasks[i];

        // Enqueue the task based on its priority
        int priorityIndex = task->priority - 1;

        queue_enqueue(task);  // Enqueue the task

        // Simulate processing time for demonstration purposes only
        sleep(1);  // Replace with actual processing code
    }

    // Wait for all worker threads to finish
    for (int i = 0; i < MAX_PRIORITY; i++) {
        pthread_join(workerThreads[i], NULL);
    }
}
