void initialize_ue_context_manager() {
    ue_context_manager.contexts = NULL;
    ue_context_manager.count = 0;
    pthread_mutex_init(&ue_context_manager.mutex, NULL);
}

UEContext* allocate_ue_context(int N) {
    UEContext* context;
    int i;

    if (N > MAX_UE_CONTEXTS) {
        // Handle integer overflow
        printf("Error: Maximum number of UE contexts exceeded.\n");
        return NULL;
    }

    context = (UEContext*)malloc(N * sizeof(UEContext));

    if (context == NULL) {
        // Handle memory allocation failure
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (i = 0; i < N; i++) {
        context[i].PCI = rand();
        context[i].RRC_STATE = 'A' + rand() % 26;
        context[i].MCG_TRACE = rand();
        context[i].CRS_INDICATION = rand();
    }

    // Record allocation timestamp and log details
    time_t now = time(NULL);
    logging_system_log("UEContext allocation successful at %s", ctime(&now));

    return context;
}

void deallocate_ue_context(UEContext* contexts, int N) {
    free(contexts);

    pthread_mutex_lock(&ue_context_manager.mutex);
    ue_context_manager.count -= N;
    pthread_mutex_unlock(&ue_context_manager.mutex);
}

int enqueue_ue_context_request(int N) {
    if (ue_context_manager.count >= MAX_UE_CONTEXTS) {
        // Handle queue overflow
        printf("Error: UE context queue is full.\n");
        return -1;
    }

    ue_context_manager.count += N;

    return 0;
}

