    UEContext* contexts = allocate_ue_context(N);

    if (contexts == NULL) {
        // Handle allocation failure
        printf("Error: UE context allocation failed.\n");
        return NULL;
    }

    // Process UE contexts concurrently
    for (int i = 0; i < N; i++) {
        pthread_mutex_lock(&ue_context_manager.mutex);
        // Access UEContext structures safely
        pthread_mutex_unlock(&ue_context_manager.mutex);

        // Perform operations on each UE context
    }

    deallocate_ue_context(contexts, N);

    return NULL;
}

