    initialize_ue_context_manager();

    while (1) {
        printf("Enter the number of UE contexts to allocate: ");
        scanf("%d", &N);

        if (enqueue_ue_context_request(N)) {
            // Handle error
            printf("Error: UE context request failed.\n");
            continue;
        }

        pthread_t thread;
        int* arg = malloc(sizeof(int));
        *arg = N;

        pthread_create(&thread, NULL, thread_function, arg);

        pthread_join(thread, NULL);
    }

    return 0;
}
