MAC_PDU* allocate_MAC_PDUs(int N) {
    srand(time(NULL));
    void* ptr = NULL;
    size_t size = sizeof(MAC_PDU) * N;

    if (size > SIZE_MAX || N <= 0) {
        printf("Invalid request: N must be a positive integer.\n");
        return NULL;
    }

    ptr = malloc(size);
    if (!ptr) {
        printf("Memory allocation failed.\n");
