        strcpy(pdu_array[i].payload, "Random Payload");
        pdu_array[i].checksum = rand();
        pdu_array[i].validity_flag = rand() % 2;

        // Handle potential memory allocation failures gracefully
        if (!pdu_array) {
            free(ptr);
            printf("Memory allocation failed.\n");
            return NULL;
