NFAPI_CRC_INDICATION_PDU_T* allocatePDUList(int N) {
    size_t totalBytes = (sizeof(NFAPI_CRC_INDICATION_PDU_T) + sizeof(int)) * N;

    // Check for potential integer overflow
    if ((size_t)(totalBytes) > SIZE_MAX - sizeof(NFAPI_CRC_INDICATION_PDU_T)) {
        printf("Error: Insufficient memory to allocate PDU list.\n");
        return NULL;
