    if (!pduList) {
        printf("Error: Unable to allocate memory for PDU list.\n");
        return NULL;
    }

    // Initialize each PDU with valid RX_UE_INFORMATION_TAG and RNTI
    int pduIndex = 0;
    while (pduIndex < N) {
        pduList[pduIndex].RX_UE_INFORMATION_TAG = pduIndex;
        pduList[pduIndex].RNTI = pduIndex * 2; // Ensure RNTI is unique for each PDU

        // Randomly set CRCFLAG
