typedef struct {
    int REQUEST_ID;
    char METHOD[20];
    char URL[100];
    json_object* BODY;
} HTTP_REQUEST_T;

void manageDynamicArraysAndNetworkRequests(int N) {
    if (N <= 0) return; // Handle invalid input

    LTE_PHY_STATS_PDU_T** lteStats = (LTE_PHY_STATS_PDU_T**)malloc(N * sizeof(LTE_PHY_STATS_PDU_T*));
    HTTP_REQUEST_T** httpRequests = (HTTP_REQUEST_T**)malloc(N * sizeof(HTTP_REQUEST_T*));

    for (int i = 0; i < N; i++) {
        lteStats[i] = (LTE_PHY_STATS_PDU_T*)malloc(sizeof(LTE_PHY_STATS_PDU_T));
        lteStats[i]->PHY_LAYER_STATUS = rand() % 100;
        lteStats[i]->CELL_ID = rand() % 10000;
        lteStats[i]->TX_POWER_LEVEL = (double)rand() / RAND_MAX;

        httpRequests[i] = (HTTP_REQUEST_T*)malloc(sizeof(HTTP_REQUEST_T));
        httpRequests[i]->REQUEST_ID = i;
        strcpy(httpRequests[i]->METHOD, "GET");
        strcpy(httpRequests[i]->URL, "/api/v1/data");
        httpRequests[i]->BODY = json_object_new_object();
    }

    // Validate and process CELL_ID values
    for (int i = 0; i < N; i++) {
        if (lteStats[i]->CELL_ID > 9999) continue;
        printf("Valid CELL_ID: %d\n", lteStats[i]->CELL_ID);
    }

    // Serialize arrays to file
    FILE* file = fopen("data.json", "wb");
    json_object* root = json_object_new_object();
    for (int i = 0; i < N; i++) {
        json_object* lteStatObj = json_object_new_object();
        json_object_object_add(lteStatObj, "PHY_LAYER_STATUS", json_real(json_real_to_double(lteStats[i]->TX_POWER_LEVEL)));
        json_object_object_add(lteStatObj, "CELL_ID", json_integer(lteStats[i]->CELL_ID));
        json_object_object_add(lteStatObj, "TX_POWER_LEVEL", json_real(json_real_to_double(lteStats[i]->TX_POWER_LEVEL)));

        json_object* httpRequestObj = json_object_new_object();
        json_object_object_add(httpRequestObj, "REQUEST_ID", json_integer(httpRequests[i]->REQUEST_ID));
        json_object_object_add(httpRequestObj, "METHOD", json_string(httpRequests[i]->METHOD));
        json_object_object_add(httpRequestObj, "URL", json_string(httpRequests[i]->URL));
        json_object_object_add(httpRequestObj, "BODY", httpRequests[i]->BODY);

        json_object_object_add(root, (char*)json_object_get_string(json_object_get_array(file)), lteStatObj);
    }
    fwrite(&root, sizeof(json_object*), 1, file);
    fclose(file);

    // Deserialize arrays from file
    file = fopen("data.json", "rb");
    root = json_object_from_file(file);
    for (int i = 0; i < N; i++) {
        lteStats[i]->TX_POWER_LEVEL = json_real(json_object_get_real(root, (char*)json_object_get_string(json_object_object_get(root, "lteStatObj"))));
        httpRequests[i]->REQUEST_ID = json_integer(json_object_get_integer(root, (char*)json_object_get_string(json_object_object_get(root, "httpRequestObj"))));
    }
    fclose(file);

    // Clean up
    for (int i = 0; i < N; i++) {
        free(lteStats[i]);
        free(httpRequests[i]->BODY);
        free(httpRequests[i]);
    }
    free(httpRequests);
    free(lteStats);
}
