        return NULL;
    }

    // Iterate over arrays and serialize data
    for (int i = 0; i < 10; i++) {
        fprintf(xml_file, "<ORDER ORDER_ID=\"%d\" CUSTOMER_NAME=\"%s\" TOTAL_AMOUNT=\"%lf\">\n", 
               customer_orders[i]->ORDER_ID, customer_orders[i]->CUSTOMER_NAME, customer_orders[i]->TOTAL_AMOUNT);

        for (int j = 0; j < 10; j++) {
            fprintf(xml_file, "<PRODUCT PRODUCT_ID=\"%d\" PRODUCT_NAME=\"%s\" QUANTITY=\"%d\" PRICE=\"%lf\">\n", 
                   products[j]->PRODUCT_ID, products[j]->PRODUCT_NAME, products[j]->QUANTITY, products[j]->PRICE);
        }
    }

    // Deserialize data from XML file (handle I/O errors)
    FILE* xml_file = fopen("data.xml", "r+");
    if (!xml_file) {
        printf("I/O error. Cannot read from file.\n");
        return NULL;
    }

    // Iterate over arrays and deserialize data
    for (int i = 0; i < 10; i++) {
        fscanf(xml_file, "<ORDER ORDER_ID=\"%d\" CUSTOMER_NAME=\"%s\" TOTAL_AMOUNT=\"%lf\">\n", 
               &customer_orders[i]->ORDER_ID, customer_orders[i]->CUSTOMER_NAME, &customer_orders[i]->TOTAL_AMOUNT);

        for (int j = 0; j < 10; j++) {
            fscanf(xml_file, "<PRODUCT PRODUCT_ID=\"%d\" PRODUCT_NAME=\"%s\" QUANTITY=\"%d\" PRICE=\"%lf\">\n", 
                   &products[j]->PRODUCT_ID, products[j]->PRODUCT_NAME, &products[j]->QUANTITY, &products[j]->PRICE);
        }
    }

    // Print memory usage metrics and log retry/fallback counts
    printf("Peak memory consumption: %d bytes.\n", peak_memory_consumption);
    printf("Average memory consumption: %f bytes.\n", average_memory_consumption);
    printf("Number of retries: %d.\n", num_retries);
    printf("Number of fallbacks: %d.\n", num_fallbacks);

    // Free allocated memory
    for (int i = 0; i < 10; i++) {
        free(customer_orders[i]);
        free(products[i]);
    }
    free(customer_orders);
    free(products);

    return NULL;
}

int main() {
    handleComplexDataProcessing();
    return 0;
}
