#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_UE 10000
#define RNTI_RANGE 0x7FFF

struct NFAPI_CRC_INDICATION_PDU_T {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    struct CRC_INDICATION_REL8_TAG {
        int CRCFLAG;
    } CRC_INDICATION_REL8_TAG;
};

int total_allocated = 0;

void* my_calloc(size_t size) {
    void* ptr = calloc(1, size);
    if (ptr == NULL) {
        fprintf(stderr, "Memory allocation failed.\n");
        exit(EXIT_FAILURE);
    }
    return ptr;
}

NFAPI_CRC_INDICATION_PDU_T* allocate_UEs(int num_ue) {
    NFAPI_CRC_INDICATION_PDU_T* ue_array = my_calloc(sizeof(NFAPI_CRC_INDICATION_PDU_T) * num_ue);
    int retries = 0;

    for (int i = 0; i < num_ue; i++) {
        int rnti;
        do {
            rnti = rand() & RNTI_RANGE;
            ue_array[i].RX_UE_INFORMATION_TAG = i;
            ue_array[i].RNTI = rnti;
            ue_array[i].CRC_INDICATION_REL8_TAG.CRCFLAG = (rand() & 1);
            retries = 0;
        } while (retries < 5 && find_rnti(ue_array, num_ue, rnti));
    }

    total_allocated += num_ue;

    if (total_allocated > MAX_UE) {
        free(ue_array);
        total_allocated -= num_ue;
        return NULL;
    }
    return ue_array;
}

int find_rnti(NFAPI_CRC_INDICATION_PDU_T* ue_array, int num_ue, int rnti) {
    for (int i = 0; i < num_ue; i++) {
        if (ue_array[i].RNTI == rnti)
            return 1;
    }
    return 0;
}
