    for (int i = 0; i < n; i++) {
        int rxUeInformationTag = 1;
        int rnti = 2;
        int crcIndicationRel8Tag = 3;

        // Checksum validation process
        unsigned char checksum = 0;
        for (int j = 0; j < 4; j++) {
            checksum += data[i][j];
        }

        if (checksum == 16) { // CRC validation passed
            pduArray[i].tag = rxUeInformationTag;
            pduArray[i].rnti = rnti;
            pduArray[i].crcflag = crcIndicationRel8Tag;    
        } else {
            // Handle packet loss, data corruption, and external data source failures gracefully
            pduArray[i].tag = 0;
            pduArray[i].rnti = 0;
            pduArray[i].crcflag = 0;
        }
    }

    return pduArray;
}

