#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <sys/types.h>
#include <netinet/in.h>
#include "http_request_stats.h"
#include "nfaapi_crc_indication_pdu_t.h"

#define MAX_REQUESTS 1000
#define MIN_CLIENT_IP 0x01000000
#define MAX_CLIENT_IP 0x0AFFFFFF
#define MIN_SERVER_IP 0x02000000
#define MAX_SERVER_IP 0x0BFFFFFF
#define MIN_URL_LENGTH 1
#define MAX_URL_LENGTH 255

// Function to generate request statistics dynamically
void* generate_request_stats(int num_requests) {
    int i;
    HttpRequestStats** requests = (HttpRequestStats**)malloc(sizeof(HttpRequestStats*) * num_requests);

    // Initialize CRC indication PDU tag and UE information tag
    NfaapiCrcIndicationPduT* crc_pdu_tags = (NfaapiCrcIndicationPduT*)malloc(sizeof(NfaapiCrcIndicationPduT) * num_requests);
    RxUeInformationTag* ue_info_tags = (RxUeInformationTag*)malloc(sizeof(RxUeInformationTag) * num_requests);

    for (i = 0; i < num_requests; i++) {
        HttpRequestStats* request_stats;

        // Generate unique client and server IP addresses
        uint32_t client_ip = (rand() % (MAX_CLIENT_IP - MIN_CLIENT_IP)) + MIN_CLIENT_IP;
        uint32_t server_ip = (rand() % (MAX_SERVER_IP - MIN_SERVER_IP)) + MIN_SERVER_IP;

        // Validate IP addresses within specified valid ranges
        if (client_ip < MIN_CLIENT_IP || client_ip > MAX_CLIENT_IP || server_ip < MIN_SERVER_IP || server_ip > MAX_SERVER_IP) {
            continue;
        }

        // Generate requested URL with length between MIN_URL_LENGTH and MAX_URL_LENGTH
        uint16_t url_length = rand() % (MAX_URL_LENGTH - MIN_URL_LENGTH + 1) + MIN_URL_LENGTH;
        char* requested_url = (char*)malloc(url_length * sizeof(char));
        for (uint8_t j = 0; j < url_length; j++) {
            requested_url[j] = (char)(rand() % 256);
        }
        requested_url[url_length - 1] = '\0';

        // Generate response status code between 100 and 599
        uint16_t response_status_code = rand() % 499 + 101;

        // Calculate latency as random number between 10ms and 1000ms
        uint16_t latency = (rand() % 990) + 10;

        request_stats = (HttpRequestStats*)malloc(sizeof(HttpRequestStats));
        request_stats->client_ip = client_ip;
        request_stats->server_ip = server_ip;
        strcpy(request_stats->requested_url, requested_url);
        request_stats->response_status_code = response_status_code;
        request_stats->latency = latency;

        // Generate CRC indication PDU tag and UE information tag
        crc_pdu_tags[i].crcflag = 0;
        ue_info_tags[i].rnti = (rand() % 65536);

        requests[i] = request_stats;
    }

    // Handle cases where the list approaches the maximum size constraint
    if (num_requests > MAX_REQUESTS) {
        int num_requests_to_adjust = num_requests - MAX_REQUESTS;
        for (i = 0; i < num_requests_to_adjust; i++) {
            free(requests[i]->requested_url);
            free(requests[i]);
        }
        num_requests -= num_requests_to_adjust;
    }

    // Perform CRC validation and populate request statistics
    for (i = 0; i < num_requests; i++) {
        if (!validate_crc(requests[i]->response_status_code, requests[i]->latency)) {
            free(requests[i]->requested_url);
            free(requests[i]);
            continue;
        }

        crc_pdu_tags[i].crcflag = calculate_crc(requests[i]->client_ip, requests[i]->server_ip, requests[i]->requested_url);
