void generate_requests(HTTP_REQUEST_STATS **stats, int *num_requests, int max_packets) {
    // Initialize stats array
    *stats = (HTTP_REQUEST_STATS *)malloc(sizeof(HTTP_REQUEST_STATS) * MAX_REQUESTS);
