#include <string.h>
#include <sys/types.h>
#include <netinet/in.h>

// Define structure for HTTP_REQUEST_STATS
typedef struct {
    char client_ip[16];
    char server_ip[16];
    char requested_url[256];
    int response_status_code;
    double latency;
} HTTP_REQUEST_STATS;

// Define structure for NFAPI_CRC_INDICATION_PDU_T
typedef struct {
    int RX_UE_INFORMATION_TAG;
    int RNTI;
    int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

void generate_request_stats_list(int max_size, int* n_packets) {
    // Initialize request stats list and NFAPI_crc_indication_pdu_t list
    HTTP_REQUEST_STATS* request_stats = (HTTP_REQUEST_STATS*)malloc(max_size * sizeof(HTTP_REQUEST_STATS));
    NFAPI_CRC_INDICATION_PDU_T* crc_indications = (NFAPI_CRC_INDICATION_PDU_T*)malloc(max_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    // Initialize packet count
    int packets = 0;

    while (packets < *n_packets) {
        char client_ip[16];
        char server_ip[16];

        // Generate unique client and server IPs
        sprintf(client_ip, "192.168.%d.%d", rand() % 255, rand() % 255);
        sprintf(server_ip, "10.0.%d.%d", rand() % 255, rand() % 255);

        // Validate IP addresses within valid range
        if (strlen(client_ip) > 15 || strlen(server_ip) > 15) {
            printf("Invalid client or server IP address.\n");
            continue;
        }

        // Generate requested URL
        char url[256];
        sprintf(url, "http://example.com/page%d", rand() % 100);

        // Validate URL within valid range
        if (strlen(url) > 255) {
            printf("Invalid URL length.\n");
            continue;
        }

        // Generate response status code and latency
        int status_code = rand() % 500 + 200;
        double latency = ((double)rand()) / RAND_MAX;

        // Validate response status code within valid range
        if (status_code < 100 || status_code > 599) {
            printf("Invalid response status code.\n");
            continue;
        }

        // Update request stats list and NFAPI_crc_indication_pdu_t list
        strcpy(request_stats[packets].client_ip, client_ip);
        strcpy(request_stats[packets].server_ip, server_ip);
        strcpy(request_stats[packets].requested_url, url);
        request_stats[packets].response_status_code = status_code;
        request_stats[packets].latency = latency;

        // Generate NFAPI_CRC_INDICATION_PDU_T structure
        crc_indications[packets].RX_UE_INFORMATION_TAG = rand() % 1000 + 1;
        crc_indications[packets].RNTI = rand() % 1000 + 1;
        crc_indications[packets].CRC_INDICATION_REL8_TAG = rand() % 1000 + 1;

        // Validate CRC flag
        if (crc_indications[packets].RX_UE_INFORMATION_TAG > 999 || 
            crc_indications[packets].RNTI > 999 || 
            crc_indications[packets].CRC_INDICATION_REL8_TAG > 999) {
            printf("Invalid CRC flags.\n");
            continue;
        }

        packets++;
    }

    // Update request stats list and NFAPI_crc_indication_pdu_t list
    for (int i = 0; i < packets; i++) {
        // Apply checksum validation process to the received data packets
        int crc_flag = rand() % 2;

        if (crc_flag == 1) {
            printf("CRC flag valid.\n");
        } else {
            printf("CRC flag invalid.\n");
            continue;
        }
    }

    free(request_stats);
    free(crc_indications);

    return;
}

int main(int argc, char* argv[]) {
    int max_size = atoi(argv[1]);
    int n_packets = atoi(argv[2]);

    generate_request_stats_list(max_size, &n_packets);

    return 0;
}
