import os
import hashlib
from shutil import copyfile

def rename_files_based_on_content(directory_path):
    for filename in os.listdir(directory_path):
        file_path = os.path.join(directory_path, filename)

        if os.path.isfile(file_path):
            try:
                with open(file_path, 'rb') as f:
                    file_hash = hashlib.md5(f.read()).hexdigest()
                    new_filename = f"{file_hash}.txt"
                    os.rename(file_path, os.path.join(directory_path, new_filename))
            except Exception as e:
                print(f"Error renaming file {filename}: {str(e)}")

        elif os.path.isdir(file_path):
            rename_files_based_on_content(file_path)
