#include <string.h>
#include <rand.h>

#define SYSTEM_LIMIT 10000
#define RNTI_RANGE_MIN 0
#define RNTI_RANGE_MAX 65535
#define MAX_RETRIES 5
#define MEMORY_COMPACTION_THRESHOLD 500

typedef struct {
    // your structure definition here
} NFAPI_CRC_INDICATION_PDU_T;

int global_allocation_counter = 0;
int system_limit = SYSTEM_LIMIT;
int retries = 0;

NFAPI_CRC_INDICATION_PDU_T* allocate_and_populate(int num_ue) {
    if (num_ue <= 0 || !system_limit) return NULL; // handle non-positive UE count and system limit

    NFAPI_CRC_INDICATION_PDU_T* allocated_array = NULL;
    int retry_count = 0;

    while ((allocated_array = (NFAPI_CRC_INDICATION_PDU_T*)malloc(num_ue * sizeof(NFAPI_CRC_INDICATION_PDU_T))) == NULL) {
        if (global_allocation_counter >= system_limit) {
            // handle exceeded system limit
            free(allocated_array);
            return NULL;
        }
    }

    for (int i = 0; i < num_ue; i++) {
        int rnti = rand() % (RNTI_RANGE_MAX - RNTI_RANGE_MIN + 1) + RNTI_RANGE_MIN;

        while ((retries > MAX_RETRIES || allocated_array[i].RNTI == rnti)) {
            retries++;
            rnti = rand() % (RNTI_RANGE_MAX - RNTI_RANGE_MIN + 1) + RNTI_RANGE_MIN;
        }

        allocated_array[i].RX_UE_INFORMATION_TAG = ...; // populate your structure here
        allocated_array[i].RNTI = rnti;
        allocated_array[i].CRC_INDICATION_REL8_TAG.crcflag = rand() % 2;

        if (i >= MEMORY_COMPACTION_THRESHOLD) {
            // periodically check and compact memory allocations
            void* temp = malloc(get_size());
            memcpy(temp, allocated_array, get_size());
            free(allocated_array);
            allocated_array = temp;
            global_allocation_counter--;
        }
    }

    retries = 0;

    if (global_allocation_counter >= system_limit) {
        // handle exceeded system limit
        free(allocated_array);
        return NULL;
    }

    for (int i = 0; i < num_ue; i++) {
        printf("RNTI: %d\n", allocated_array[i].RNTI); // log RNTI values
    }

    global_allocation_counter += num_ue;

    return allocated_array;
}

