int create_and_init_cipher(const uint8_t* key, int key_len, int operation_type, AES_KEY** cipher) {
    if (AES_new_key(&key[0], &(*cipher)->key)) {
        ERR_error_fp(stderr, NULL);
        return 1;
    }

    if (operation_type == 0) {
        // Initialize for encryption
        AES_set_encrypt_key(&key[0], key_len, (*cipher));
    } else {
        // Initialize for decryption
        AES_set_decrypt_key(&key[0], key_len, (*cipher));
    }

    return 0;
}

void securely_disable_cipher(AES_KEY* cipher) {
    if (AES_free(&cipher->key)) {
        ERR_error_fp(stderr, NULL);
    }
}

