#include <stdio.h>
#include <stdlib.h>
#include <string.h>
#include <pthread.h>

// Define a structure for UE information
typedef struct {
    char id[10];
    int signal_strength;
    long timestamp;
} UE_info;

// Define a structure to hold the dynamic list of UEs
typedef struct {
    UE_info* ue_list;
    int size;
    pthread_mutex_t lock; // Thread-safe mutex for concurrent access
} UE_manager;

// Function to initialize and manage a dynamic list of UEs
UE_manager* init_ue_manager() {
    UE_manager* manager = (UE_manager*) malloc(sizeof(UE_manager));
    if (!manager) return NULL;

    manager->ue_list = NULL;
    manager->size = 0;
    pthread_mutex_init(&manager->lock, NULL);
    return manager;
}

// Function to add a new UE to the dynamic list
int ue_add(UE_manager* manager, const char* id, int signal_strength) {
    UE_info* new_ue = (UE_info*) malloc(sizeof(UE_info));
    if (!new_ue) return -1;

    strcpy(new_ue->id, id);
    new_ue->signal_strength = signal_strength;
    new_ue->timestamp = time(NULL);

    pthread_mutex_lock(&manager->lock); // Lock for thread-safe access
    manager->ue_list = (UE_info**) realloc(manager->ue_list, sizeof(UE_info*) * ++manager->size);
    if (!manager->ue_list) {
        free(new_ue);
        return -1;
    }
    manager->ue_list[manager->size-1] = new_ue;
    pthread_mutex_unlock(&manager->lock); // Unlock for thread-safe access
    return 0;
}

// Function to update the status of a UE based on network conditions
int ue_update(UE_manager* manager, const char* id, int signal_strength) {
    pthread_mutex_lock(&manager->lock); // Lock for thread-safe access
    for (int i = 0; i < manager->size; i++) {
        if (strcmp(manager->ue_list[i]->id, id) == 0) {
            manager->ue_list[i]->signal_strength = signal_strength;
            manager->ue_list[i]->timestamp = time(NULL);
            pthread_mutex_unlock(&manager->lock); // Unlock for thread-safe access
            return 0;
        }
    }
    pthread_mutex_unlock(&manager->lock); // Unlock for thread-safe access
    return -1; // UE not found in the list
}

// Function to free dynamically allocated memory for UEs and manager
void free_ue_manager(UE_manager* manager) {
    for (int i = 0; i < manager->size; i++) {
        free(manager->ue_list[i]);
    }
    free(manager->ue_list);
    pthread_mutex_destroy(&manager->lock);
    free(manager);
}
