#include <stdlib.h>
#include <time.h>

#define MAX_LIST_SIZE 1000
#define RNTI_VALID_RANGE 1, 256
#define CRC_INDICATION_REL8_TAG 0x12345678
#define TIMESTAMP_UPDATE_INTERVAL 10 // seconds

typedef struct {
    uint32_t RX_UE_INFORMATION_TAG;
    uint16_t RNTI;
    uint32_t CRC_INDICATION_REL8_TAG;
    time_t timestamp;
} NFAPI_CRC_INDICATION_PDU_T;

void generate_crc_indication_pdu_list(int* list_size, int* rnti_range_start, int* rnti_range_end, struct timespec* load_info) {
    NFAPI_CRC_INDICATION_PDU_T* pdu_list = (NFAPI_CRC_INDICATION_PDU_T*)malloc(*list_size * sizeof(NFAPI_CRC_INDICATION_PDU_T));
    int current_rnti = 1;
    time_t last_timestamp = time(NULL);

    for(int i = 0; i < *list_size; i++) {
        pdu_list[i].RX_UE_INFORMATION_TAG = i % RNTI_VALID_RANGE[1];
        pdu_list[i].RNTI = current_rnti++;

        if(current_rnti > RNTI_VALID_RANGE[1]) {
            current_rnti = 1;
        }

        pdu_list[i].CRC_INDICATION_REL8_TAG = CRC_INDICATION_REL8_TAG;
        pdu_list[i].timestamp = last_timestamp + i * TIMESTAMP_UPDATE_INTERVAL;

        // Monitor system load and adjust generation rate if necessary
        clock_gettime(CLOCK_REALTIME, &load_info);
        int load_level = (int)load_info.tv_nsec / 1000000; // Adjust this formula to suit your load calculation method

        if(load_level > 80) {
            *list_size /= 2;
            printf("System load high. Reducing list size.\n");
        } else if(load_level < 20) {
            *list_size *= 2;
            printf("System load low. Increasing list size.\n");
        }
    }

    // Validate RNTI values and ensure no two consecutive structures have the same RNTI value
    for(int i = 0; i < *list_size - 1; i++) {
        if(pdu_list[i].RNTI == pdu_list[i+1].RNTI) {
            printf("Error: Consecutive RNTIs must be distinct.\n");
            return;
        }

        if(pdu_list[i].RNTI < *rnti_range_start || pdu_list[i].RNTI > *rnti_range_end) {
            printf("Error: RNTI %u is outside valid range [%d, %d].\n", pdu_list[i].RNTI, *rnti_range_start, *rnti_range_end);
            return;
        }
    }

    free(pdu_list);
}
