// Define structure for NRUEContext
typedef struct NRUEContext {
    int PCI;
    int RRC_STATE;
    int MCG_TRACE;
} NRUEContext;

// Define structure for UE
typedef struct UE {
    char ID[16];
    int signal_strength;
    long timestamp;
    NRUEContext context;
} UE;

// Define structure for the dynamic list of UEs
typedef struct DynamicList {
    UE* head;
    int size;
} DynamicList;

// Function to initialize a new UE
void init_ue(UE* ue, char* ID, int signal_strength, long timestamp) {
    strcpy(ue->ID, ID);
    ue->signal_strength = signal_strength;
    ue->timestamp = timestamp;
}

// Function to initialize the dynamic list
DynamicList* init_dynamic_list() {
    DynamicList* dl = (DynamicList*)malloc(sizeof(DynamicList));
    dl->head = NULL;
    dl->size = 0;
    return dl;
}

// Function to add a UE to the dynamic list
void add_ue_to_list(DynamicList* dl, UE* ue) {
    if(dl->head == NULL) {
        dl->head = ue;
    } else {
        UE* current = dl->head;
        while(current->next != NULL) {
            current = current->next;
        }
        current->next = ue;
    }
    dl->size++;
}

// Function to print the dynamic list
void print_dynamic_list(DynamicList* dl) {
    UE* current = dl->head;
    while(current != NULL) {
        printf("ID: %s, signal_strength: %d, timestamp: %ld\n", current->ID, current->signal_strength, current->timestamp);
        current = current->next;
    }
}

int main(int argc, char** argv) {
    DynamicList* dl = init_dynamic_list();

    // Initialize UEs and add them to the dynamic list
    UE ue1, ue2, ue3;
    init_ue(&ue1, "UE1", 10, 1643723400);
    init_ue(&ue2, "UE2", 20, 1643723410);
    init_ue(&ue3, "UE3", 30, 1643723420);
    add_ue_to_list(dl, &ue1);
    add_ue_to_list(dl, &ue2);
    add_ue_to_list(dl, &ue3);

    print_dynamic_list(dl);

    return 0;
}
