// Function to dynamically allocate and populate an array of LTE_PHY_RX_FRAME_INFO structures
LTE_PHY_RX_FRAME_INFO** allocate_and_populate_frames(int N, int* total_frames_allocated, int* compression_enabled) {
    int i;
    LTE_PHY_RX_FRAME_INFO **frames = NULL;
    int frames_allocated = 0;

    // Check if the total number of frames is known in advance
    if (N > 0) {
        frames = (LTE_PHY_RX_FRAME_INFO**)malloc(N * sizeof(LTE_PHY_RX_FRAME_INFO*));

        for (i = 0; i < N; i++) {
            frames[i] = (LTE_PHY_RX_FRAME_INFO*)malloc(sizeof(LTE_PHY_RX_FRAME_INFO));

            // Ensure each FRAME_NUMBER is unique within the array
            frames[i]->frame_number = i;

            strcpy(frames[i]->phy_frame_info, "Valid PHY Frame Info");
            strcpy(frames[i]->channel_state_info, "Valid Channel State Info");
        }

        *total_frames_allocated = N;
    } else {
        // If the total number of frames is not known in advance, use a pool allocation strategy
        int pool_size = 10; // Define a default pool size
        int* frame_pool = (int*)malloc(pool_size * sizeof(int));
        int free_frames = pool_size;

        for (i = 0; i < N; i++) {
            if (free_frames > 0) {
                frames[i] = (LTE_PHY_RX_FRAME_INFO*)malloc(sizeof(LTE_PHY_RX_FRAME_INFO));

                // Ensure each FRAME_NUMBER is unique within the array
                frames[i]->frame_number = i;

                strcpy(frames[i]->phy_frame_info, "Valid PHY Frame Info");
                strcpy(frames[i]->channel_state_info, "Valid Channel State Info");

                free_frames--;
            } else {
                // Reallocate the frame pool if it's exhausted
                int new_pool_size = pool_size * 2; // Double the pool size

                for (int j = 0; j < N; j++) {
                    if (j >= free_frames) {
                        // Allocate a new frame
                        frames[j] = (LTE_PHY_RX_FRAME_INFO*)malloc(sizeof(LTE_PHY_RX_FRAME_INFO));

                        // Ensure each FRAME_NUMBER is unique within the array
                        frames[j]->frame_number = j;

                        strcpy(frames[j]->phy_frame_info, "Valid PHY Frame Info");
                        strcpy(frames[j]->channel_state_info, "Valid Channel State Info");
                    }
                }

                free_frames = new_pool_size - N; // Update the number of free frames

                *total_frames_allocated += (new_pool_size - pool_size);
                pool_size = new_pool_size;
            }
        }

        *compression_enabled = 1; // Compression is enabled by default
    }

    return frames;
}

// Function to free allocated memory and handle potential memory allocation failures gracefully
void deallocate_frames(LTE_PHY_RX_FRAME_INFO** frames, int N) {
    if (frames != NULL) {
        for (int i = 0; i < N; i++) {
            if (frames[i] != NULL) {
                free(frames[i]);
                frames[i] = NULL;
            }
        }

        free(frames);
    }
}

// Example usage of the function
int main() {
    int N = 5; // Define the total number of frames
    LTE_PHY_RX_FRAME_INFO** frames;

    int total_frames_allocated = 0;
    int compression_enabled = 0;

    frames = allocate_and_populate_frames(N, &total_frames_allocated, &compression_enabled);

    // Perform operations with the allocated frames

    deallocate_frames(frames, N); // Deallocate memory after usage

    return 0;
}

