#include <stdio.h>
#include <stdlib.h>
#include <time.h>

#define MAX_PDU 1000
#define MIN_RNTI 1
#define MAX_RNTI 255
#define CRC_FLAG 0x01

typedef struct {
    unsigned char RX_UE_INFORMATION_TAG;
    int RNTI;
    unsigned int CRC_INDICATION_REL8_TAG;
} NFAPI_CRC_INDICATION_PDU_T;

NFAPI_CRC_INDICATION_PDU_T* generateDynamicPduSequence(int N) {
    int i, rnti = MIN_RNTI, pdu_size = 0;
    NFAPI_CRC_INDICATION_PDU_T *pdus = (NFAPI_CRC_INDICATION_PDU_T*)malloc(MAX_PDU * sizeof(NFAPI_CRC_INDICATION_PDU_T));

    if (!pdus) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (i = 0; i < N && pdu_size < MAX_PDU; i++) {
        pdus[pdu_size].RX_UE_INFORMATION_TAG = 'A' + rnti % ('Z' - 'A' + 1);
        pdus[pdu_size].RNTI = rnti;
        pdus[pdu_size].CRC_INDICATION_REL8_TAG = (unsigned int)rnti * 2;

        if (rnti == MAX_RNTI) {
            rnti = MIN_RNTI;
        } else {
            rnti++;
        }

        pdu_size++;
    }

    for (int j = 0; j < pdu_size; j++) {
        pdus[j].CRC_INDICATION_REL8_TAG &= ~(1 << 31);
        pdus[j].CRC_INDICATION_REL8_TAG |= CRC_FLAG;
    }

    if (pdu_size > 0) {
        printf("Created %d PDUs.\n", pdu_size);
    } else {
        printf("Failed to create any PDUs.\n");
    }

    return pdus;
}
