import os
import hashlib
import time
from shutil import copy2
from stat import S_IMODE

# Function to rename files based on content hash
def rename_files_based_on_content_hash(directory):
    try:
        for filename in os.listdir(directory):
            filepath = os.path.join(directory, filename)
            if os.path.isfile(filepath):
                # Calculate MD5 hash of file contents
                md5hash = hashlib.md5()
                with open(filepath, 'rb') as f:
                    while chunk := f.read(4096):
                        md5hash.update(chunk)

                # Generate unique identifier from content hash
                newname = f"{md5hash.hexdigest()}_{os.path.splitext(filename)[0]}{os.path.splitext(filename)[1]}"

                # Rename file with unique identifier
                copy2(filepath, os.path.join(directory, newname))

            elif os.path.isdir(filepath):
                # Recursively process subdirectories
                rename_files_based_on_content_hash(filepath)

    except Exception as e:
        print(f"Error: {str(e)}")

    finally:
        time.sleep(0.5)  # Wait before retrying

# Example usage
directory = '/path/to/files'
rename_files_based_on_content_hash(directory)
