NFAPI_CRC_INDICATION_PDU_T *allocate_structures(int max_structures) {
    NFAPI_CRC_INDICATION_PDU_T *structures = NULL;
    size_t allocated_size = 0, current_size = 0;
    int i, rnti_count[1024] = {0};

    for (i = 0; i < max_structures; i++) {
        if ((current_size + sizeof(NFAPI_CRC_INDICATION_PDU_T)) > MAX_MEMORY) {
            // reallocate to avoid memory exhaustion
            structures = realloc(structures, current_size + sizeof(NFAPI_CRC_INDICATION_PDU_T));
            allocated_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);
        }

        NFAPI_CRC_INDICATION_PDU_T* structure = (NFAPI_CRC_INDICATION_PDU_T*)malloc(sizeof(NFAPI_CRC_INDICATION_PDU_T));

        // set random CRCFLAG
        uint16_t crcflag = rand() % 0xFFFF;
        *structure = (NFAPI_CRC_INDICATION_PDU_T){i, i, i, crcflag};

        if (!structures) {
            structures = structure;
            current_size = sizeof(NFAPI_CRC_INDICATION_PDU_T);
        } else {
            structures[current_size / sizeof(NFAPI_CRC_INDICATION_PDU_T)] = *structure;
            current_size += sizeof(NFAPI_CRC_INDICATION_PDU_T);

            // count and check for duplicate RNTI
            if (rnti_count[structure->RNTI] > 0) {
                printf("Error: Duplicate RNTI\n");
                free(structure);
                return NULL;
            } else {
                rnti_count[structure->RNTI]++;
            }
        }
    }

    // validate each structure's RX_UE_INFORMATION_TAG corresponds to a valid RNTI
    for (i = 0; i < current_size / sizeof(NFAPI_CRC_INDICATION_PDU_T); i++) {
        if (rnti_count[structures[i].RNTI] > 1) {
            printf("Error: Duplicate RNTI\n");
            free(structures);
            return NULL;
        }
    }

    return structures;
}

void* thread_function(void* arg) {
    // allocate structures
    int max_structures = MAX_STRUCTURES;
    NFAPI_CRC_INDICATION_PDU_T *structures = allocate_structures(max_structures);

    // monitor memory usage and performance metrics
    size_t allocated_size = current_size;
    int reallocation_count = 0;

    return NULL;
}

int main() {
    pthread_t threads[100];

    for (int i = 0; i < 100; i++) {
        pthread_create(&threads[i], NULL, thread_function, NULL);
    }

    // handle potential issues
    pthread_join(threads[0], NULL);

    return 0;
}

