    NFAPI_SRB_BUFFER_T* buffers = (NFAPI_SRB_BUFFER_T*)malloc(size);

    if (!buffers) {
        printf("Memory allocation failed.\n");
        return NULL;
    }

    for (i = 0; i < N; i++) {
        buffers[i].SRB_ID = i;
        srand(time(NULL));
        sprintf(buffers[i].PREAMBLE, "Preamble_%d", rand() % 100);
        buffers[i].SRB_STATE = rand() % 10;
        buffers[i].SRB_VALIDITY = (rand() % 2) ? 1 : 0;

        // Check for duplicate PREAMBLE
        int j;
        for (j = 0; j < i; j++) {
            if (!strcmp(buffers[j].PREAMBLE, buffers[i].PREAMBLE)) {
                printf("Error: Duplicate preamble detected.\n");
                free(buffers);
                return NULL;
            }
        }
    }

    // Perform optimization using Union-Find
    int* parent = (int*)malloc(N * sizeof(int));
    int* rank = (int*)malloc(N * sizeof(int));

    for (i = 0; i < N; i++) {
        parent[i] = i;
        rank[i] = 0;
    }

    for (i = 0; i < N; i++) {
        printf("Checking for disjointness...\n");
        // Measure time taken
        clock_t start = clock();
        int j;
        for (j = 0; j < N; j++) {
            if (find(parent, rank, buffers[i].SRB_ID, buffers[j].PREAMBLE)) {
                printf("Disjoint found.\n");
                break;
            }
        }
        printf("Time taken: %d milliseconds\n", (int)(clock() - start) * 1000 / CLOCKS_PER_SEC);
    }

    free(parent);
    free(rank);

    return buffers;
}

// Helper function for Union-Find
int find(int* parent, int* rank, int x, char y[]) {
    if (!strcmp(y, buffers[x].PREAMBLE)) {
        return x;
    }

    int y_parent = find(parent, rank, x, y);
    if (rank[y_parent] > 0) {
        return y_parent;
    }

    for (int i = 0; i < N; i++) {
        if (!strcmp(y, buffers[i].PREAMBLE)) {
            if (parent[x] == parent[i]) {
                rank[parent[x]]++;
                return parent[x];
            }
        }
    }

    printf("Error: Preamble not found.\n");
    return -1;
}
