        arr[i].CRCFLAG = (rand() & 1) ? true : false; // Randomly set CRCFLAG

        if (i > 0 && arr[i-1].RNTI == arr[i].RNTI) {
            printf("Error: Duplicate RNTI detected.\n");
            free(arr);
            return NULL;
        }
    }

    return arr;
}

int main() {
    int n = 10000; // Default maximum number of structures to allocate
    int max_n = 1000000; // Maximum allowed memory usage in bytes (1 MB)

    NFAPI_CRC_INDICATION_PDU_T* arr = create_array(n, max_n);

    if (arr != NULL) {
        printf("Array created with %d elements.\n", n);
    } else {
        printf("Error: Array creation failed.\n");
    }

    return 0;
}
