#include <stdlib.h>
#include <stdio.h>
#include <string.h>

#define MAX_CONNECTIONS 1000
#define POOL_INITIAL_SIZE 10

typedef struct {
    int session_id;
    char client_address[16];
    int status; // 0: idle, 1: connected, 2: closed
} CONNECTION_OBJECT_T;

// Function to manage connection pool
CONNECTION_OBJECT_T* connection_pool_create(int max_connections) {
    if (max_connections > MAX_CONNECTIONS || max_connections < POOL_INITIAL_SIZE) {
        fprintf(stderr, "Invalid maximum connections: %d\n", max_connections);
        return NULL;
    }

    CONNECTION_OBJECT_T* pool = malloc(max_connections * sizeof(CONNECTION_OBJECT_T));
    if (!pool) {
        perror("Memory allocation failed");
        return NULL;
    }

    for (int i = 0; i < max_connections; i++) {
        pool[i].session_id = -1;
        strcpy(pool[i].client_address, "");
        pool[i].status = 0;
    }

    return pool;
}

// Function to add a new connection to the pool
void connection_pool_add(CONNECTION_OBJECT_T** pool, int* size, int session_id, char client_address[]) {
    if (*size >= *max_connections) {
        fprintf(stderr, "Pool is full. Connection not added.\n");
        return;
    }

    for (int i = 0; i < *size; i++) {
        if (pool[i]->session_id == -1) {
            pool[i]->session_id = session_id;
            strcpy(pool[i]->client_address, client_address);
            pool[i]->status = 1;
            return;
        }
    }

    // If no idle connection found, allocate a new one
    *size += 10; // Increase size to accommodate the newly added connection

    if (*size > *max_connections) {
        fprintf(stderr, "Pool exceeded maximum capacity. Connection not added.\n");
        return;
    }

    pool[*size - 1]->session_id = session_id;
    strcpy(pool[*size - 1].client_address, client_address);
    pool[*size - 1]->status = 1;
}

// Function to remove a connection from the pool
void connection_pool_remove(CONNECTION_OBJECT_T** pool, int* size, int session_id) {
    for (int i = 0; i < *size; i++) {
        if (pool[i]->session_id == session_id) {
            strcpy(pool[i].client_address, "");
            pool[i]->status = 2;
            // If the removed connection is not idle, decrement size
            if (pool[i]->status != 0) {
                (*size)--;
            }
            return;
        }
    }
}

// Function to retrieve a connection from the pool
CONNECTION_OBJECT_T* connection_pool_get(CONNECTION_OBJECT_T** pool, int* size) {
    for (int i = 0; i < *size; i++) {
        if (pool[i]->status == 0) {
            return &pool[i];
        }
    }
    return NULL;
}

// Function to check the status of a connection
int connection_pool_get_status(CONNECTION_OBJECT_T* connection) {
    return connection->status;
}
