#include <stdlib.h>
#include <stdio.h>
#include <string.h>

typedef struct {
    int session_id;
    char client_address[16];
    enum {CONNECTED, DISCONNECTED} status;
} CONNECTION_OBJECT_T;

void *connection_pool_create(int max_connections);
void connection_pool_destroy(void **pool_ptr);
int connection_pool_add(void **pool_ptr, int session_id, const char *client_address);
int connection_pool_remove(void **pool_ptr, int session_id);
int connection_pool_status(void **pool_ptr, int session_id);

void *connection_pool_create(int max_connections) {
    void *pool = malloc(sizeof(CONNECTION_OBJECT_T) * max_connections);
    if (!pool) {
        fprintf(stderr, "Failed to allocate memory for pool.\n");
        return NULL;
    }

    // Initialize pool with disconnected status
    for (int i = 0; i < max_connections; i++) {
        ((CONNECTION_OBJECT_T *) pool)[i].status = DISCONNECTED;
    }

    return pool;
}

void connection_pool_destroy(void **pool_ptr) {
    free(*pool_ptr);
    *pool_ptr = NULL;
}

int connection_pool_add(void **pool_ptr, int session_id, const char *client_address) {
    void *pool = *pool_ptr;

    // Find an idle connection or create a new one
    for (int i = 0; i < sizeof(CONNECTION_OBJECT_T) / sizeof(*((CONNECTION_OBJECT_T *) pool)); i++) {
        if (((CONNECTION_OBJECT_T *) pool)[i].status == DISCONNECTED) {
            ((CONNECTION_OBJECT_T *) pool)[i].session_id = session_id;
            strcpy(((CONNECTION_OBJECT_T *) pool)[i].client_address, client_address);
            ((CONNECTION_OBJECT_T *) pool)[i].status = CONNECTED;
            return 0; // Connection added successfully
        }
    }

    // Pool is full or no idle connection found
    fprintf(stderr, "Pool is full or no idle connection available.\n");
    return -1;
}

int connection_pool_remove(void **pool_ptr, int session_id) {
    void *pool = *pool_ptr;

    for (int i = 0; i < sizeof(CONNECTION_OBJECT_T) / sizeof(*((CONNECTION_OBJECT_T *) pool)); i++) {
        if (((CONNECTION_OBJECT_T *) pool)[i].session_id == session_id) {
            ((CONNECTION_OBJECT_T *) pool)[i].status = DISCONNECTED;
            return 0; // Connection removed successfully
        }
    }

    // Session ID not found in the pool
    fprintf(stderr, "Session ID not found in the connection pool.\n");
    return -1;
}

int connection_pool_status(void **pool_ptr, int session_id) {
    void *pool = *pool_ptr;

    for (int i = 0; i < sizeof(CONNECTION_OBJECT_T) / sizeof(*((CONNECTION_OBJECT_T *) pool)); i++) {
        if (((CONNECTION_OBJECT_T *) pool)[i].session_id == session_id) {
            return ((CONNECTION_OBJECT_T *) pool)[i].status;
        }
    }

    // Session ID not found in the pool
    fprintf(stderr, "Session ID not found in the connection pool.\n");
    return -1;
}
